/* CCAR-F Exam Simulation question bank.
 *
 * Hand-maintained. This file was originally generated by an importer from
 * JSON drops in ccar-f-handoff/; both were retired once the question sets
 * were final, so this file is now the source of truth — edit it directly.
 * Section 12 of tests/sim-test.js enforces the integrity the importer used
 * to check on every run: run it after editing.
 *
 * These are a separate pool from QUESTIONS in data-questions*.js. They come
 * from a real sitting of the exam: long plain-prose stems, four options of
 * which often two would work, and one best answer. They are never mixed into
 * the fact-recall drills.
 *
 * Shape:
 *   id           unique across every imported set
 *   scn          scenario id matching EXAMS['CCAR-F'].scenarios
 *   domains      domain ids matching EXAMS['CCAR-F'].domains
 *   objectives   score-report objective ids (O01-O37), may be empty
 *   family       optional; questions that teach the same lesson share one.
 *                buildSitting keeps a family to one question per paper,
 *                because the first would give the second away. A new
 *                question that restates an existing one should join its
 *                family rather than be left to land in the same block.
 *   options      exactly four, keyed A-D, each with its own explanation
 *   correct      the key of the single correct option
 *   tiebreaker   what separates the best answer from the runner-up
 *   note         current_state_note: where the product has moved since the
 *                guide. The answer still follows the guide.
 */
const SIM_QUESTIONS = [
{"id":"BAL-001","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d2"],"taskStatements":["2.5"],"objectives":["O32"],"stem":"An engineer joining a 4,000-file service needs to find every file whose name ends in .migration.sql, anywhere in the tree. They do not yet care what is inside the files, only which ones exist and where. Which built-in tool does this in one step?","options":[{"key":"A","text":"Glob with the pattern **/*.migration.sql, which matches file paths regardless of their contents.","explanation":"Glob matches paths by pattern, which is exactly a filename question."},{"key":"B","text":"Grep for the string \"migration\", which will surface the files that mention it.","explanation":"Grep searches contents, so it would match any file discussing migrations and miss ones whose names match but whose bodies never say the word."},{"key":"C","text":"Read on each directory in turn, listing what each one holds.","explanation":"Walking 4,000 files by hand is what the pattern tools exist to avoid."},{"key":"D","text":"Bash with a find command piped through grep.","explanation":"It works, but a built-in tool covers this directly — reach for the shell when nothing built in fits."}],"correct":"A","tiebreaker":"Match the tool to the requirement","rationale":"Glob matches file paths by pattern; Grep searches file contents. Selecting the wrong one wastes the exploration step.","sources":[{"title":"Task 2.5 — O32","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code tools reference","url":"https://code.claude.com/docs/en/tools-reference","type":"docs"}],"note":"Answer per the exam guide. In current Claude Code on macOS, Linux and WSL, Glob and Grep are left out of the default tool set and Claude searches with find and grep through Bash; the two tools are available when named in --tools or --allowedTools, or in a subagent's tools list.","corroborated":[]},
{"id":"BAL-002","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d2"],"taskStatements":["2.5"],"objectives":["O32"],"stem":"A security reviewer must find every place in a repository where the deprecated helper signRequestV1 is still called. The callers live in files with no shared naming convention, spread across several directories. Which tool finds them?","options":[{"key":"A","text":"Grep for signRequestV1, which searches file contents across the tree.","explanation":"Call sites are content, and content search is what Grep does."},{"key":"B","text":"Glob for **/*sign*, matching files whose names mention signing.","explanation":"Glob matches names, and the stem says the callers share no naming convention."},{"key":"C","text":"Read the files in the directory where the helper is defined.","explanation":"Callers are elsewhere by definition; reading the definition site finds none of them."},{"key":"D","text":"Bash running a recursive listing of the repository.","explanation":"A listing shows paths, not which files contain the call."}],"correct":"A","tiebreaker":"Match the tool to the requirement","rationale":"Grep searches file contents for a pattern; Glob cannot inspect what is inside a file.","sources":[{"title":"Task 2.5 — O32","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code tools reference","url":"https://code.claude.com/docs/en/tools-reference","type":"docs"}],"note":"Answer per the exam guide. In current Claude Code on macOS, Linux and WSL, Glob and Grep are left out of the default tool set and Claude searches with find and grep through Bash; the two tools are available when named in --tools or --allowedTools, or in a subagent's tools list.","corroborated":[]},
{"id":"BAL-003","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d2"],"taskStatements":["2.5"],"objectives":["O32"],"stem":"An agent has already located the single file that defines a service's retry policy and now needs its full contents, including the comments explaining each threshold. What is the right call?","options":[{"key":"A","text":"Read on that file path, which returns the file.","explanation":"The file is known, so retrieving it is a read, not a search."},{"key":"B","text":"Grep the file for \"retry\" to pull out the relevant lines.","explanation":"Returns matching lines and drops the surrounding comments the task needs."},{"key":"C","text":"Glob the directory to confirm the file is there first.","explanation":"The path is already known; confirming it adds a step and returns no contents."},{"key":"D","text":"Bash with cat on the path.","explanation":"Equivalent output, but the built-in Read is the documented way to read a file."}],"correct":"A","tiebreaker":"Match the tool to the requirement","rationale":"Read retrieves a known file whole; the search tools are for discovery, not for fetching a file already located.","sources":[{"title":"Task 2.5 — O32","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code tools reference","url":"https://code.claude.com/docs/en/tools-reference","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-004","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d2"],"taskStatements":["2.5"],"objectives":["O32"],"stem":"A team's agent runs every file lookup through Bash — find for filenames, grep for contents, cat to read. It works, but reviewers note the agent's permission configuration must now allow broad shell access. What should the team change?","options":[{"key":"A","text":"Use Glob, Grep and Read for those three jobs, keeping Bash for operations that have no built-in equivalent.","explanation":"The built-ins cover exactly these cases, so the broad shell permission stops being necessary."},{"key":"B","text":"Keep Bash but constrain it with a wrapper script that only permits find, grep and cat.","explanation":"Rebuilds the built-in tools in shell and still needs shell access to run."},{"key":"C","text":"Keep Bash and tighten the review process around what the agent is asked to do.","explanation":"Process around a capability is weaker than not granting the capability."},{"key":"D","text":"Keep Bash because one tool is simpler for the model to choose between than four.","explanation":"Fewer tools, but each call is now an arbitrary command rather than a scoped operation."}],"correct":"A","tiebreaker":"Built-in feature over workaround","rationale":"Prefer a built-in tool where one fits; the shell is for operations the built-ins do not cover.","sources":[{"title":"Task 2.5 — O32","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code tools reference","url":"https://code.claude.com/docs/en/tools-reference","type":"docs"}],"note":"Answer per the exam guide. In current Claude Code on macOS, Linux and WSL, Glob and Grep are left out of the default tool set and Claude searches with find and grep through Bash; the two tools are available when named in --tools or --allowedTools, or in a subagent's tools list.","corroborated":[]},
{"id":"BAL-005","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d2"],"taskStatements":["2.5"],"objectives":["O32"],"family":"glob-then-grep","stem":"An agent must find which of a monorepo's test files assert on the status field. Test files all end in .test.ts, but they are scattered, and the repository also contains many non-test files that mention status. What sequence is most efficient?","options":[{"key":"A","text":"Glob **/*.test.ts to get the test files, then Grep those for status.","explanation":"Narrow by path first, then search contents within that set — each tool doing what it is for."},{"key":"B","text":"Grep the whole repository for status, then filter the results down to test files.","explanation":"Works, but searches the entire tree when the path pattern could have excluded most of it first."},{"key":"C","text":"Glob **/*status*, assuming the assertions live in files named for the field.","explanation":"Assumes a naming convention the stem does not give."},{"key":"D","text":"Read every .test.ts file and scan them.","explanation":"Loads whole files into context when a content search would return just the matches."}],"correct":"A","tiebreaker":"Match the tool to the requirement","rationale":"Glob narrows by path, Grep then searches within that narrowed set — a two-step discovery neither tool does alone.","sources":[{"title":"Task 2.5 — O32","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code tools reference","url":"https://code.claude.com/docs/en/tools-reference","type":"docs"}],"note":"Answer per the exam guide. In current Claude Code on macOS, Linux and WSL, Glob and Grep are left out of the default tool set and Claude searches with find and grep through Bash; the two tools are available when named in --tools or --allowedTools, or in a subagent's tools list.","corroborated":[]},
{"id":"BAL-006","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d2"],"taskStatements":["2.5"],"objectives":["O32"],"stem":"Partway through a refactor an agent needs to know whether the project's test suite currently passes, before it changes anything further. Which tool fits?","options":[{"key":"A","text":"Bash, running the project's test command.","explanation":"Running a command is an action, and Bash is the tool that executes."},{"key":"B","text":"Grep the test files for assertions that look like they would fail.","explanation":"Reading assertions cannot tell you the runtime result."},{"key":"C","text":"Read the most recent CI log committed to the repository.","explanation":"Tells you about an earlier state, not the working tree as it stands now."},{"key":"D","text":"Glob the test directory to confirm the suite is complete.","explanation":"Confirms files exist; says nothing about whether they pass."}],"correct":"A","tiebreaker":"Match the tool to the requirement","rationale":"Bash is the right tool when the task is to execute something rather than to find or read it.","sources":[{"title":"Task 2.5 — O32","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code tools reference","url":"https://code.claude.com/docs/en/tools-reference","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-007","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d1"],"taskStatements":["1.7"],"objectives":["O02"],"stem":"An agent spent 40 minutes mapping a service's data layer and wrote its findings to a file. Overnight, three of the ninety files it examined changed. The team wants the agent to continue from where it stopped the next morning. What should the resumption do?","options":[{"key":"A","text":"Load the stored findings as context and re-analyse only the three changed files.","explanation":"Targeted re-analysis of what changed, with prior findings injected — state restored without repeating work."},{"key":"B","text":"Re-run the full ninety-file analysis so the picture is guaranteed current.","explanation":"Correct but wasteful: it repeats 87 files of work that is still valid."},{"key":"C","text":"Load the stored findings and continue, treating them as current.","explanation":"Cheapest, but three files have moved on and the stale entries are now wrong."},{"key":"D","text":"Ask the engineer to summarise what changed and work from that summary.","explanation":"Puts a manual step in the loop when the changed files are discoverable."}],"correct":"A","tiebreaker":"Smallest thing that works","rationale":"On resumption, re-analyse only what changed and inject prior findings as context, rather than repeating the whole analysis.","sources":[{"title":"Task 1.7 — O02","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Agent SDK: sessions (resume and fork)","url":"https://code.claude.com/docs/en/agent-sdk/sessions","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-008","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.7"],"objectives":["O02"],"stem":"A long-running exploration agent is occasionally killed by the deployment platform. Today, recovery means replaying the whole conversation transcript into a fresh session and hoping the agent re-reaches the same conclusions. The team wants reliable resumption. What should they add?","options":[{"key":"A","text":"Have the agent write structured findings to a state file as it goes, and load that file on resume.","explanation":"Explicit durable state restores conclusions directly instead of asking the model to re-derive them from a replay."},{"key":"B","text":"Increase the context window so the full transcript always fits on replay.","explanation":"A longer replay still asks the model to re-derive everything, and costs the same tokens each restart."},{"key":"C","text":"Checkpoint the raw transcript more often so less is lost at the moment of the kill.","explanation":"Keeps more of the conversation but still stores narration rather than conclusions."},{"key":"D","text":"Retry the failed run from the beginning automatically.","explanation":"Automates repetition; the work is still done twice."}],"correct":"A","tiebreaker":"Guaranteed beats likely","rationale":"Durable state written as the run proceeds is what makes resumption possible; a transcript alone leaves the agent to re-derive its conclusions.","sources":[{"title":"Task 1.7 — O02","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Agent SDK: sessions (resume and fork)","url":"https://code.claude.com/docs/en/agent-sdk/sessions","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-009","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.7"],"objectives":["O02"],"stem":"On resume, an agent is given its previous session's findings by replaying them as prior user turns. It immediately re-executes the actions those turns describe, duplicating several writes. What is the fix?","options":[{"key":"A","text":"Inject the prior findings as context saying what is done, not as turns that read like fresh instructions.","explanation":"The duplication comes from the shape of the injected history: as instructions it acts again, as state it does not."},{"key":"B","text":"Add an instruction at the end of the replay telling the agent not to repeat any completed work.","explanation":"An instruction competing with a transcript that looks like live instructions; probabilistic at best."},{"key":"C","text":"Make the write operations idempotent, so that repeating one of them does no harm.","explanation":"Contains the damage and is good practice, but the agent still redoes the work."},{"key":"D","text":"Replay only the final turn of the prior session, so there is less history to act on.","explanation":"Loses the findings that made resumption worth doing."}],"correct":"A","tiebreaker":"Root cause","rationale":"Resumed context must be injected as context, not replayed as instructions the agent will act on again.","sources":[{"title":"Task 1.7 — O02","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Agent SDK: sessions (resume and fork)","url":"https://code.claude.com/docs/en/agent-sdk/sessions","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-010","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d1"],"taskStatements":["1.7"],"objectives":["O02"],"stem":"A dependency-upgrade agent paused mid-run three weeks ago. Since then the lockfile, the CI configuration and about a fifth of the source files have changed. An engineer wants to pick the run back up. What is the best approach?","options":[{"key":"A","text":"Start a fresh session seeded with a summary of the old run's conclusions, and re-examine the tree.","explanation":"Three weeks of drift makes most of the stored state stale; the summary keeps the intent without carrying stale findings."},{"key":"B","text":"Resume the session as it is, since resumption exists precisely for runs that were interrupted.","explanation":"Resumption assumes the stored state still describes reality, which three weeks of changes have broken."},{"key":"C","text":"Resume and re-analyse only the files known to have changed since the run was paused.","explanation":"Right technique for a short gap; here the changed set is so large that the untouched findings are also suspect."},{"key":"D","text":"Discard the old run entirely and start again from nothing, with no context carried over.","explanation":"Throws away the conclusions and the reasoning about intent, which are still useful."}],"correct":"A","tiebreaker":"Eliminate what the scenario rules out","rationale":"Resuming a session whose stored results are stale is worse than starting fresh from a summary of them.","sources":[{"title":"Task 1.7 — O02","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Agent SDK: sessions (resume and fork)","url":"https://code.claude.com/docs/en/agent-sdk/sessions","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-011","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d1"],"taskStatements":["1.7"],"objectives":["O02"],"stem":"A team is deciding what their agent should write to its resumption file at the end of each work block. Context budget on resume is tight. What content serves resumption best?","options":[{"key":"A","text":"The conclusions reached, the files they rest on, and the questions still open.","explanation":"Conclusions plus provenance plus open threads is what the next session needs to continue."},{"key":"B","text":"The full tool-call log, so the next session can see exactly what was done.","explanation":"Complete but mostly narration; it spends the resume budget on how rather than what."},{"key":"C","text":"The final assistant message from the block.","explanation":"Usually a summary written for a human, missing the provenance and the open questions."},{"key":"D","text":"A list of every file read, so the next session knows what was covered.","explanation":"Coverage without findings — the next session knows where it looked but not what it learned."}],"correct":"A","tiebreaker":"Signal beats volume","rationale":"What gets persisted for resumption should be conclusions and open questions, not the full narration of how they were reached.","sources":[{"title":"Task 1.7 — O02","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Agent SDK: sessions (resume and fork)","url":"https://code.claude.com/docs/en/agent-sdk/sessions","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-012","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.6"],"objectives":["O07"],"stem":"A research agent is asked to assess a company's exposure to a new regulation. The orchestrator plans five subtasks up front and runs them in order. Subtask two discovers the company has three subsidiaries in scope, a fact the plan did not anticipate, and the remaining subtasks never examine them. What should change?","options":[{"key":"A","text":"Generate the next subtasks from what each step returns, so the subsidiaries become tasks of their own.","explanation":"The discovery should change the plan; dynamic decomposition is what lets it."},{"key":"B","text":"Expand the initial plan to twelve subtasks, so that more ground is covered before anything runs.","explanation":"A longer fixed plan is still fixed — it only moves the line at which an unanticipated finding falls outside it."},{"key":"C","text":"Run the same five subtasks again after the first pass, now that more about the company is known.","explanation":"A second fixed pass; it may still not have a subsidiary step."},{"key":"D","text":"Have subtask two report the subsidiaries in its summary so the final report mentions them.","explanation":"Mentions them without examining them, which is the gap."}],"correct":"A","tiebreaker":"Who decides the units of work","rationale":"Dynamic decomposition generates subtasks from what has been discovered so far, rather than committing to a fixed list up front.","sources":[{"title":"Task 1.6 — O07","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-013","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.6"],"objectives":["O07"],"stem":"A nightly job converts yesterday's uploaded invoices to a normalised schema, validates them, and writes them to a warehouse. Every invoice goes through the same three steps regardless of content. An architect proposes making the decomposition dynamic. Is that the right call?","options":[{"key":"A","text":"No — the steps are known in advance and do not depend on findings, so a fixed sequence is correct.","explanation":"Dynamic decomposition earns its complexity only when discoveries should change the plan; here nothing does."},{"key":"B","text":"Yes — dynamic decomposition adapts better and should be the default for agent pipelines.","explanation":"Treats a technique as a default rather than matching it to whether the work varies."},{"key":"C","text":"Yes, but only for the validation step, which can fail in varied ways.","explanation":"Varied failures call for error handling, not for generating new subtasks."},{"key":"D","text":"No — but only because the volume is low; it should become dynamic as volume grows.","explanation":"Volume is not what decides this; whether findings change the plan is."}],"correct":"A","tiebreaker":"Match the tool to the requirement","rationale":"A fixed sequence is right when the steps are known in advance and independent of what earlier steps find.","sources":[{"title":"Task 1.6 — O07","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-014","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d1"],"taskStatements":["1.6"],"objectives":["O07"],"family":"loop-termination","stem":"An agent that generates its own subtasks from what it discovers has started running for hours on broad questions, each finding spawning two or three more investigations. The outputs are good but the runs never settle. What should be added?","options":[{"key":"A","text":"A termination condition: a depth limit, a budget, or a test for when the question is answered.","explanation":"Dynamically generated work needs a bound; without one, discovery can expand indefinitely."},{"key":"B","text":"A fixed subtask list written up front, since the dynamic approach has proven to be unbounded.","explanation":"Throws away the adaptiveness to solve a problem a bound would solve."},{"key":"C","text":"A faster model, so that the same expansion of subtasks finishes in less time than it does now.","explanation":"Reduces the wait without bounding the expansion."},{"key":"D","text":"A rule that each subtask may spawn at most one more, so the tree can never branch outwards.","explanation":"A bound of a kind, but it also forbids a finding that genuinely opens two threads."}],"correct":"A","tiebreaker":"Bound what cannot be guaranteed to converge","rationale":"When subtasks are generated from findings, the loop needs a termination condition, or discovery can keep spawning work.","sources":[{"title":"Task 1.6 — O07","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-015","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d1"],"taskStatements":["1.6"],"objectives":["O07"],"stem":"A document-processing agent must handle a batch where some files are simple forms and others are long contracts with attachments it cannot know about until it opens them. Compliance requires a record of why each processing step ran. What design fits?","options":[{"key":"A","text":"Generate each document's steps from what opening it reveals, with the coordinator logging each step and why.","explanation":"Adapts to what is discovered and keeps the audit trail compliance needs."},{"key":"B","text":"Run the full contract pipeline on every document, so the handling is uniform and fully auditable.","explanation":"Uniform and auditable, but spends contract-level processing on simple forms."},{"key":"C","text":"Let each document's agent decide its own steps and report only its final output to the coordinator.","explanation":"Adapts, but the coordinator loses the visibility compliance requires."},{"key":"D","text":"Sort the documents into two fixed pipelines by file size before any of them are processed.","explanation":"A proxy that gets the easy cases right and misses a short contract with attachments."}],"correct":"A","tiebreaker":"The option that meets every stated goal","rationale":"Dynamic decomposition adapts the plan to intermediate findings while the coordinator keeps visibility of what was generated and why.","sources":[{"title":"Task 1.6 — O07","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-016","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.6"],"objectives":["O07"],"family":"decomposition-gap","stem":"A multi-agent review consistently misses issues that span two services. Each subagent's report on its own service is accurate and thorough. The coordinator splits the work one service per agent. Where is the problem?","options":[{"key":"A","text":"In the decomposition: splitting strictly by service means no subtask ever owns the interactions between them.","explanation":"The gap is structural — the agents answer their questions well, but no agent is asked the cross-service question."},{"key":"B","text":"In the subagent prompts, which should tell each agent to consider other services.","explanation":"Each agent would speculate about services it was not given; the cross-cutting task still belongs to no one."},{"key":"C","text":"In the synthesis step, which should infer the cross-service issues from the individual reports.","explanation":"Asks synthesis to find what was never investigated."},{"key":"D","text":"In the model choice for the subagents, which lack the capability for cross-cutting analysis.","explanation":"Capability is not the constraint; scope of the assigned task is."}],"correct":"A","tiebreaker":"Root cause","rationale":"Coverage gaps in multi-agent output trace back to how the coordinator decomposed the task.","sources":[{"title":"Task 1.6 — O07","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-017","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.5"],"objectives":["O12"],"stem":"A team has written nine paragraphs of prose rules describing the commit-message format they want. The agent still produces a different shape every few commits — sometimes a body, sometimes not, sometimes a scope prefix. What should they do next?","options":[{"key":"A","text":"Add three or four concrete examples of a correct commit message alongside the rules.","explanation":"Examples pin the shape in a way prose does not, and this is the documented first move for inconsistent output."},{"key":"B","text":"Rewrite the nine paragraphs so that every rule is stated more clearly and precisely.","explanation":"More prose addressing a problem prose has already failed at."},{"key":"C","text":"Add a rule stating that the format must be followed exactly, with no deviations.","explanation":"Emphasis, not specification — it does not show what the format is."},{"key":"D","text":"Lower the temperature so the output varies less from one commit to the next.","explanation":"Reduces variation around whatever shape the model picks; it does not fix which shape."}],"correct":"A","tiebreaker":"First Step Trap: Output inconsistency → add few-shot examples.","rationale":"Concrete input-output examples are the most effective fix when prose instructions alone produce varied output.","sources":[{"title":"Task 3.5 — O12","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Prompting best practices","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-018","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.5"],"objectives":["O12"],"stem":"An agent's generated API client is correct except that it swallows HTTP 429 instead of retrying. An engineer is about to send feedback. Which form of feedback is most likely to fix it in one round?","options":[{"key":"A","text":"Point at the 429 handling specifically and state what it should do instead.","explanation":"Targeted feedback on the actual failure is what iterative refinement calls for."},{"key":"B","text":"Re-send the original requirements with a note that the output was not right.","explanation":"Makes the agent search for the defect it has already failed to see."},{"key":"C","text":"Ask the agent to review its own output and find the problem.","explanation":"Sometimes works, but it already produced this output believing it correct."},{"key":"D","text":"Send the full HTTP specification for status code semantics.","explanation":"Volume around the issue rather than the issue; the fix is one behaviour."}],"correct":"A","tiebreaker":"Signal beats volume","rationale":"Targeted feedback naming the specific failure beats restating the whole requirement.","sources":[{"title":"Task 3.5 — O12","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-019","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.5"],"objectives":["O12"],"stem":"A reviewer has found eleven problems in a generated migration script. They could send each one as it is found, or collect them. The agent re-runs the whole script generation on each round of feedback. What should the reviewer do?","options":[{"key":"A","text":"Send all eleven in one consolidated round of feedback.","explanation":"One round with the full set; eleven rounds would each regenerate the script and risk reintroducing earlier fixes."},{"key":"B","text":"Send them one at a time so each fix can be verified before the next.","explanation":"Eleven regenerations, and a later round can undo an earlier fix."},{"key":"C","text":"Send the three most severe and leave the rest for a later pass.","explanation":"Two passes where one would do, and the minor issues ship in the interim."},{"key":"D","text":"Fix them by hand, since eleven is too many to delegate.","explanation":"Abandons the loop over a quantity that batching handles."}],"correct":"A","tiebreaker":"Signal beats volume","rationale":"When every round of feedback regenerates the whole artefact, or the fixes interact, send the issues in one consolidated round; a stream of single-issue corrections risks each round undoing an earlier fix. Independent issues in separate places can be handled one at a time.","sources":[{"title":"Task 3.5 — O12","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-020","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d3"],"taskStatements":["3.5"],"objectives":["O12"],"stem":"A team wants an agent to normalise messy supplier names into a canonical form. They plan to give it examples. Which form of example teaches the transformation?","options":[{"key":"A","text":"Pairs showing a raw input and the canonical output it should become.","explanation":"The task is a mapping, so each example must show both sides of it."},{"key":"B","text":"A list of correctly formatted canonical names.","explanation":"Shows the target shape but not which inputs map to which output."},{"key":"C","text":"A list of the messy inputs the agent will encounter.","explanation":"Shows the problem without showing the answer."},{"key":"D","text":"A prose description of the canonicalisation rules, with one worked example at the end.","explanation":"Better than rules alone, but one example against a varied input space is thin."}],"correct":"A","tiebreaker":"Match the tool to the requirement","rationale":"Examples that pair an input with its expected output teach a transformation; output samples alone leave the mapping unstated.","sources":[{"title":"Task 3.5 — O12","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Prompting best practices","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-021","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.5"],"objectives":["O12"],"stem":"Despite six correct examples, an agent keeps wrapping its JSON output in a markdown code fence. The examples all show bare JSON. What addition is most likely to stop it?","options":[{"key":"A","text":"A counter-example showing a fenced response marked wrong, beside the correct bare-JSON form.","explanation":"The specific wrong move persists despite positive examples; naming it as wrong is what displaces it."},{"key":"B","text":"Six more correct examples of bare JSON, so the pattern carries more weight in the prompt.","explanation":"More of what has already not worked."},{"key":"C","text":"A rule in the system prompt stating that the output must always be valid JSON.","explanation":"A fenced block can still contain valid JSON, so the rule does not exclude the behaviour."},{"key":"D","text":"Post-processing that strips any code fence from the response before it is parsed.","explanation":"Hides the behaviour rather than correcting it, and the fence may not always be where expected."}],"correct":"A","tiebreaker":"Counter-examples reinforce what to avoid","rationale":"Counter-examples help when the model keeps making one specific wrong move that positive examples have not displaced.","sources":[{"title":"Task 3.5 — O12","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-022","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.6"],"objectives":["O15"],"stem":"An agent writes tests that pass but look nothing like the rest of the suite: it builds objects inline where the project has factory helpers, and uses a different assertion library. The prompt describes the conventions in prose. What is the most effective change?","options":[{"key":"A","text":"Include two or three existing test files from the suite as context in the prompt.","explanation":"Existing tests show the fixture helpers and assertion style concretely, which prose descriptions have already failed to convey."},{"key":"B","text":"Expand the prose description to name every helper and the assertion library.","explanation":"More prose where prose has not worked; naming a helper does not show how it is used."},{"key":"C","text":"Add a lint rule that rejects tests not using the factories.","explanation":"Catches the problem after the fact and does not teach the agent the convention."},{"key":"D","text":"Ask the agent to read the whole test directory before writing.","explanation":"Spends a lot of context on discovery when a couple of representative files would do."}],"correct":"A","tiebreaker":"First Step Trap: Output inconsistency → add few-shot examples.","rationale":"Existing test files given as context are what teach an agent the project’s fixture conventions and assertion style.","sources":[{"title":"Task 3.6 — O15","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-023","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.6"],"objectives":["O15"],"stem":"An agent asked to raise coverage on a pricing module produces forty new tests. Coverage goes from 61% to 94%, but most tests call a function and assert only that the result is not null. What criterion was missing from the prompt?","options":[{"key":"A","text":"A requirement that each test assert the specific expected result for a stated input.","explanation":"Not-null assertions execute the code without checking it; the criterion that distinguishes a meaningful test is what the prompt lacked."},{"key":"B","text":"A higher coverage target, so that the agent is pushed to exercise more of the module's paths.","explanation":"A higher target met the same trivial way produces more trivial tests."},{"key":"C","text":"A limit on how many tests the agent may write, so that each one gets more attention.","explanation":"Fewer trivial tests are still trivial."},{"key":"D","text":"A requirement to test the module's private functions as well as its public ones.","explanation":"Widens the surface without changing the quality of the assertions."}],"correct":"A","tiebreaker":"Signal beats volume","rationale":"Meaningful tests assert on behaviour; coverage counts can be satisfied by trivial assertions that prove nothing.","sources":[{"title":"Task 3.6 — O15","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-024","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.6"],"objectives":["O15"],"stem":"A project seeds its test database through a shared fixture module with a strict teardown order. Generated tests keep creating their own records directly and leaving rows behind, which makes later tests flaky. What should the team add to the agent's instructions?","options":[{"key":"A","text":"The fixture conventions: which module to seed through, and the teardown contract tests must follow.","explanation":"Stating the convention is what stops the agent inventing its own setup; the flakiness is a direct consequence of the gap."},{"key":"B","text":"A rule that every test must clean up whatever records it creates once it has finished.","explanation":"States the goal without the mechanism, so each test invents its own cleanup."},{"key":"C","text":"A retry wrapper around the flaky tests, so an intermittent failure is run again before it is reported.","explanation":"Hides a correctness problem in the test setup."},{"key":"D","text":"A requirement that the suite runs in a fixed order, so leftover rows are always the same ones.","explanation":"Masks the leakage by relying on ordering, which is itself fragile."}],"correct":"A","tiebreaker":"The option that meets every stated goal","rationale":"Fixture conventions must be stated explicitly, or generated tests invent their own setup and drift from the suite.","sources":[{"title":"Task 3.6 — O15","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-025","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"ci","scenario":"Claude Code for Continuous Integration","scenarioContext":null,"domains":["d3"],"taskStatements":["3.6"],"objectives":["O15"],"stem":"A team reviews two generated test files for the same module. File A asserts on the module's public outputs for a set of inputs. File B asserts on the values of internal variables mid-computation. Both pass. Which should the team prefer, and why?","options":[{"key":"A","text":"File A, because it tests the contract and survives a refactor that changes the internals.","explanation":"Behavioural tests on the public surface are what remain meaningful when implementation changes."},{"key":"B","text":"File B, because it localises failures more precisely to the line that broke.","explanation":"Precise, but it fails on every refactor and passes even when the public behaviour is wrong."},{"key":"C","text":"Both, since more assertions mean more confidence.","explanation":"File B's assertions add maintenance cost and false failures without adding behavioural coverage."},{"key":"D","text":"Neither, until a coverage report shows which lines each one reaches.","explanation":"Coverage says which lines ran, not whether the assertions are meaningful."}],"correct":"A","tiebreaker":"Measured beats intuitive","rationale":"Behavioural tests exercise the contract through its public surface; tests coupled to internals break on refactors without catching defects.","sources":[{"title":"Task 3.6 — O15","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-026","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.6"],"objectives":["O19"],"family":"conflict-attribution","stem":"Three sources give a market's size as $4.2bn, $5.1bn and $6.8bn. The synthesis agent's report states the market is approximately $5.4bn. An analyst asks where that figure came from. What should the agent have done instead?","options":[{"key":"A","text":"Reported all three figures with their sources, noting that the estimates differ materially.","explanation":"The disagreement is itself a finding; averaging it away produces a number no source supports."},{"key":"B","text":"Reported the median figure instead, since the median is less sensitive to an outlier.","explanation":"Still a single number no source states, and it hides that the range is wide."},{"key":"C","text":"Reported only the figure from the most recent source, as the most up-to-date estimate.","explanation":"Defensible if recency were the stated criterion, but it discards the disagreement without saying so."},{"key":"D","text":"Reported the average, but shown the calculation behind it in a footnote to the report.","explanation":"Transparent about the arithmetic while still presenting a synthetic figure as the finding."}],"correct":"A","tiebreaker":"Presence is not shape","rationale":"A synthesis agent should attribute conflicting figures to their sources rather than resolving them silently into one number.","sources":[{"title":"Task 5.6 — O19","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-027","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.6"],"objectives":["O19"],"stem":"A research agent's report reads with the same confident tone throughout. Some statements rest on several independent sources; others come from a single blog post. A reader cannot tell which is which. What should the synthesis design change?","options":[{"key":"A","text":"Mark each finding with how well supported it is, so solid and contested claims read differently.","explanation":"Preserving source-level uncertainty means the reader can see which claims are solid."},{"key":"B","text":"Drop any finding that rests on only one source, so that only corroborated claims remain.","explanation":"Discards real information; a single-source finding is worth reporting as such."},{"key":"C","text":"Add a disclaimer at the top of the report saying that confidence varies across it.","explanation":"Tells the reader uncertainty exists without saying where."},{"key":"D","text":"Have a second agent re-verify every claim in the report before it is published to readers.","explanation":"Improves accuracy and costs a second pass, but the report still reads uniformly confident."}],"correct":"A","tiebreaker":"Signal beats volume","rationale":"Well-established findings and contested claims should be distinguishable in the output, not flattened into uniform prose.","sources":[{"title":"Task 5.6 — O19","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-028","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.6"],"objectives":["O19"],"family":"dated-figures","stem":"Two sources give a company's headcount as 1,200 and 1,900. The synthesis agent flags them as conflicting. An analyst points out they may not conflict at all. What does the agent need to resolve this?","options":[{"key":"A","text":"The date each figure describes, since a company can hold both numbers at different times.","explanation":"Without dates, a temporal difference is indistinguishable from a genuine conflict."},{"key":"B","text":"A third independent source, so the agent can see which of the two figures it agrees with.","explanation":"A third undated figure adds another point without resolving what the dates would."},{"key":"C","text":"The methodology each source used to count employees, such as whether contractors are included.","explanation":"Relevant, and a real source of discrepancy, but the temporal question comes first here."},{"key":"D","text":"The relative authority of the two sources, so the more reliable figure can be preferred.","explanation":"Picks a winner between figures that may both be correct."}],"correct":"A","tiebreaker":"The mechanism’s own contract","rationale":"Publication and collection dates are needed to interpret whether two sources genuinely conflict or merely describe different periods.","sources":[{"title":"Task 5.6 — O19","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-029","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.6"],"objectives":["O19"],"stem":"Subagents return findings carefully hedged — \"one source suggests\", \"disputed by\". The coordinator's final summary step compresses these into short declarative bullets and the hedges disappear. Where should the fix go?","options":[{"key":"A","text":"In the summarisation step, which must be told to carry the qualifiers into the compressed form.","explanation":"The loss happens at compression, so that is where uncertainty has to be preserved."},{"key":"B","text":"In the subagents, which should hedge more strongly so that some of it survives compression.","explanation":"Stronger hedging compressed by the same step loses the same information."},{"key":"C","text":"In the final report template, which should include a separate section on uncertainty.","explanation":"A separate section detaches the caveat from the claim it qualifies."},{"key":"D","text":"In the model used for summarisation, which should be swapped for a more capable one.","explanation":"A capable model still does what it was asked; the instruction is what omits the qualifiers."}],"correct":"A","tiebreaker":"Guaranteed beats likely","rationale":"Uncertainty must survive the summarisation step; a compression that drops qualifiers produces false confidence.","sources":[{"title":"Task 5.6 — O19","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-030","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O03"],"stem":"A coordinator dispatches a subagent to write a section of a report. The subagent comes back twice asking which of two figures to use and where a statistic came from. What was wrong with the dispatch?","options":[{"key":"A","text":"The prompt omitted the findings and their source metadata, so the subagent could not complete the task alone.","explanation":"A complete handoff carries the data and its provenance; these round trips are the symptom of an incomplete one."},{"key":"B","text":"The subagent should have been told to pick a figure and note the ambiguity.","explanation":"Produces an answer without the information needed to make it correct."},{"key":"C","text":"The coordinator should allow the subagent to query the source documents itself.","explanation":"Replaces the round trips with rediscovery of what the coordinator already held."},{"key":"D","text":"The subagent's model is too cautious and should be instructed to proceed without asking.","explanation":"Suppresses the question without supplying the answer."}],"correct":"A","tiebreaker":"The option that meets every stated goal","rationale":"A subagent prompt must carry every finding, datum and piece of source metadata the task needs, so the subagent never has to return for context.","sources":[{"title":"Task 1.3 — O03","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-031","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O03"],"stem":"Correcting a problem with incomplete handoffs, a team now passes the coordinator's full conversation history to every subagent. Subagent quality drops and costs rise. What is the right middle ground?","options":[{"key":"A","text":"Pass the findings, data and source metadata the specific task requires, and nothing else.","explanation":"Completeness is measured against the task, not against the coordinator's whole context."},{"key":"B","text":"Pass the full history but instruct each subagent to ignore irrelevant parts.","explanation":"The tokens are still spent and the irrelevant material still competes for attention."},{"key":"C","text":"Return to short prompts and accept the occasional clarifying round trip.","explanation":"Swaps one failure mode back for the other."},{"key":"D","text":"Pass a summary of the full history to each subagent.","explanation":"Compresses uniformly, so a detail one subagent needs may be summarised away."}],"correct":"A","tiebreaker":"Signal beats volume","rationale":"A complete handoff means everything the task needs, not the coordinator’s entire context.","sources":[{"title":"Task 1.3 — O03","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-032","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O03"],"stem":"Subagents extract figures from a document set and return them as plain numbers. The report assembled from them is accurate, but compliance rejects it because no figure can be traced to a document. What must the handoff include?","options":[{"key":"A","text":"The source identifier and location for each figure, carried alongside the value.","explanation":"Provenance has to travel with the data; it cannot be reconstructed afterwards."},{"key":"B","text":"A list of the documents each subagent examined, attached to its report.","explanation":"Says which documents were seen, not which figure came from which."},{"key":"C","text":"A final verification pass that re-finds each figure in the source set.","explanation":"Re-derives what the first pass could have recorded, and may match the wrong occurrence."},{"key":"D","text":"A requirement that subagents quote the surrounding sentence for each figure.","explanation":"Helpful context, but a quotation without a document identifier is still untraceable."}],"correct":"A","tiebreaker":"Guaranteed beats likely","rationale":"Source metadata must travel with the data, or downstream work cannot cite or verify it.","sources":[{"title":"Task 1.3 — O03","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-033","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O06"],"family":"coordinator-spawn-tool","stem":"A coordinator agent is configured with three subagent definitions but never spawns any of them. It completes the work itself, slowly. Its allowed tools are Read, Grep, Glob and Write. What is the cause?","options":[{"key":"A","text":"The Task tool is missing from its allowed tools, so it has no way to spawn a subagent.","explanation":"Subagent definitions do nothing without the tool that invokes them."},{"key":"B","text":"The subagent definitions are malformed and are being silently skipped.","explanation":"Possible in general, but the tool list here plainly lacks the spawn capability."},{"key":"C","text":"The coordinator's model is not capable of delegation.","explanation":"Delegation is a tool call, not a model capability that switches off."},{"key":"D","text":"The prompt does not instruct it strongly enough to delegate.","explanation":"No instruction can invoke a tool the agent was not given."}],"correct":"A","tiebreaker":"Root cause","rationale":"A coordinator that cannot spawn subagents at all usually lacks the Task tool in its allowed tools.","sources":[{"title":"Task 1.3 — O06","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code subagents","url":"https://code.claude.com/docs/en/sub-agents","type":"docs"},{"title":"Agent SDK: subagents (AgentDefinition)","url":"https://code.claude.com/docs/en/agent-sdk/subagents","type":"docs"}],"note":"Claude Code renamed the Task tool to Agent in version 2.1.63. Existing Task(...) references still work as aliases, so the mechanism this question tests is unchanged; the current name is Agent. In the current Agent SDK, allowedTools is the list of auto-approved tools, and its examples include Agent there so the coordinator can delegate.","corroborated":[]},
{"id":"BAL-034","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O06"],"stem":"A coordinator successfully spawns a research subagent, which returns almost immediately saying it could not find the information. Logs show the subagent made no search or read calls at all. Its definition restricts it to a tools list that contains only Write. What should be fixed?","options":[{"key":"A","text":"Give the subagent the tools its role needs, such as Read and Grep.","explanation":"It spawned correctly but had no capability to search; a tools list without Read or Grep explains the immediate return."},{"key":"B","text":"Instruct the subagent to try harder before reporting failure.","explanation":"It cannot try at all without tools."},{"key":"C","text":"Have the coordinator pass the file contents in the prompt instead.","explanation":"A workaround that removes the subagent's purpose."},{"key":"D","text":"Increase the subagent's turn limit so it has room to search.","explanation":"More turns of nothing, since it has no search capability."}],"correct":"A","tiebreaker":"Root cause","rationale":"A subagent that spawns but cannot act is usually restricted to a tools list that lacks what its role requires, not misinstructed.","sources":[{"title":"Task 1.3 — O06","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code subagents","url":"https://code.claude.com/docs/en/sub-agents","type":"docs"},{"title":"Agent SDK: subagents (AgentDefinition)","url":"https://code.claude.com/docs/en/agent-sdk/subagents","type":"docs"}],"note":"In current Claude Code, a subagent whose definition omits the tools field inherits every tool available to subagents; only an explicit list restricts it.","corroborated":[]},
{"id":"BAL-035","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O06"],"stem":"A team defines a specialist subagent for database migrations. The coordinator has the Task tool and the subagent has the right tools, but the coordinator keeps handling migration work itself. The subagent's description field reads \"helper agent\". What should change?","options":[{"key":"A","text":"Write a description stating what the subagent is for, so the coordinator can match work to it.","explanation":"The description is the coordinator's basis for selecting a subagent; a vague one gives it nothing to match on."},{"key":"B","text":"Add an instruction to the coordinator naming this subagent as the one for migration work.","explanation":"Hardcodes one case and leaves every other subagent selection equally blind."},{"key":"C","text":"Remove the coordinator's own file-editing tools, so that it has no choice but to delegate.","explanation":"Forces delegation by removing capability, which breaks the work it should still do itself."},{"key":"D","text":"Rename the subagent to migration-specialist, so its purpose is clear from the name alone.","explanation":"A better name helps a little, but the description is the field that carries the selection signal."}],"correct":"A","tiebreaker":"Root cause","rationale":"A subagent definition’s description is what the coordinator matches against when choosing whether to invoke it.","sources":[{"title":"Task 1.3 — O06","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code subagents","url":"https://code.claude.com/docs/en/sub-agents","type":"docs"},{"title":"Agent SDK: subagents (AgentDefinition)","url":"https://code.claude.com/docs/en/agent-sdk/subagents","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-036","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d3"],"taskStatements":["3.2"],"objectives":["O14"],"family":"skill-fork-verbose","stem":"A skill that audits dependency licences reads about 200 files and prints its working as it goes. Engineers complain that running it leaves the main session cluttered and that later answers degrade. What frontmatter option fixes this?","options":[{"key":"A","text":"context: fork, so the skill runs in an isolated context and returns only its result.","explanation":"Isolation at the skill level is what keeps the verbose working out of the main conversation."},{"key":"B","text":"allowed-tools, restricted to Read, so the skill does less work.","explanation":"Restricts capability rather than isolating output, and the reads are the point of the skill."},{"key":"C","text":"argument-hint, so the skill can be scoped to fewer files per run.","explanation":"Addresses parameter prompting, not context pollution."},{"key":"D","text":"A line in the skill asking it to summarise rather than print its working.","explanation":"Probabilistic; the tool output still lands in the main context regardless of what the skill says."}],"correct":"A","tiebreaker":"Built-in feature over workaround","rationale":"context: fork runs a skill in an isolated context so only its result returns to the main conversation.","sources":[{"title":"Task 3.2 — O14","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code skills","url":"https://code.claude.com/docs/en/skills","type":"docs"}],"note":"The exam guide describes allowed-tools as restricting a skill's tools. In current Claude Code it pre-approves the listed tools for the turn and does not remove any others.","corroborated":[]},
{"id":"BAL-037","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d3"],"taskStatements":["3.2"],"objectives":["O14"],"stem":"A team adds context: fork to every skill as a standing policy. One skill, which continues an in-progress refactor the engineer has been discussing all session, immediately stops working correctly. Why?","options":[{"key":"A","text":"It runs in an isolated context and no longer sees the session state the refactor depends on.","explanation":"Isolation is the point of fork, which makes it wrong for a skill that must build on the conversation."},{"key":"B","text":"Forked skills must finish within a single turn, so a multi-step refactor is cut off early.","explanation":"A forked skill runs as a subagent with turns of its own; the problem is what it can see, not how long it runs."},{"key":"C","text":"Forked skills can only be started by typing their name, so Claude never invokes this one itself.","explanation":"Forking changes the context a skill runs in, not who can invoke it."},{"key":"D","text":"Forked skills run with a smaller context window, so the refactor no longer fits in it.","explanation":"The problem is what is in the context, not how large it is."}],"correct":"A","tiebreaker":"Match the tool to the requirement","rationale":"Forking isolates a skill’s execution; it is the wrong choice when the skill must build on the session’s state.","sources":[{"title":"Task 3.2 — O14","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code skills","url":"https://code.claude.com/docs/en/skills","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-038","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d3"],"taskStatements":["3.2"],"objectives":["O14"],"stem":"Four skills are candidates for context: fork. Which profile benefits most?","options":[{"key":"A","text":"A skill that greps a large codebase for pages of matches in order to give a one-line answer.","explanation":"Large intermediate work, small useful result — exactly what isolation is for."},{"key":"B","text":"A skill that renames a single variable in one file and reports the change.","explanation":"Almost no intermediate output to isolate."},{"key":"C","text":"A skill that asks the engineer a clarifying question and waits for the answer.","explanation":"Interaction with the session is its purpose, which isolation would cut off."},{"key":"D","text":"A skill that appends an entry to a changelog using facts from the current conversation.","explanation":"Depends on session state, so isolating it would remove what it needs."}],"correct":"A","tiebreaker":"The option that meets every stated goal","rationale":"context: fork suits a skill whose intermediate work is large and whose useful output is small.","sources":[{"title":"Task 3.2 — O14","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code skills","url":"https://code.claude.com/docs/en/skills","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-039","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.4"],"objectives":["O20"],"family":"exploration-drift","stem":"An agent exploring a large unfamiliar codebase degrades after about an hour: it starts re-reading files it has already seen and contradicts its earlier conclusions. The context window is not full. What combination addresses this?","options":[{"key":"A","text":"Subagents for discovery that return summaries, plus a scratchpad file of findings the main agent re-reads.","explanation":"Isolation keeps the verbose reading out of the main context, and the scratchpad gives conclusions a durable home."},{"key":"B","text":"Move to a model with a larger context window so that nothing has to be dropped.","explanation":"The window is not full; attention over a long context is the problem, and a bigger one does not fix it."},{"key":"C","text":"Restart the session every forty minutes so the agent always works from a fresh context.","explanation":"Stops the degradation and loses the accumulated understanding with it."},{"key":"D","text":"Instruct the agent to keep a running summary of its conclusions in each of its replies.","explanation":"Better than nothing, but the summary lives in the same degrading context."}],"correct":"A","tiebreaker":"Built-in technique that targets the problem","rationale":"Subagent isolation and scratchpad files sustain exploration past what a single context can hold.","sources":[{"title":"Task 5.4 — O20","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-040","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.4"],"objectives":["O20"],"stem":"An exploration agent answers each question by reading entire files, several of them over 3,000 lines. It runs out of context budget about a third of the way through a survey of twelve services. What practice would extend its reach most?","options":[{"key":"A","text":"Grep for the relevant symbols first and read only the regions that matter.","explanation":"Targeted reading is the documented way to keep exploration within a context budget."},{"key":"B","text":"Read the files but ask the agent to forget them once summarised.","explanation":"Content already in the context cannot be unread by instruction."},{"key":"C","text":"Survey six services instead of twelve.","explanation":"Fits the budget by reducing the task rather than by exploring more efficiently."},{"key":"D","text":"Increase the per-file read limit so fewer calls are needed.","explanation":"Fewer calls carrying the same volume; the context cost is unchanged."}],"correct":"A","tiebreaker":"Signal beats volume","rationale":"Targeted file reading keeps exploration within budget; reading whole files to answer narrow questions exhausts it.","sources":[{"title":"Task 5.4 — O20","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code tools reference","url":"https://code.claude.com/docs/en/tools-reference","type":"docs"}],"note":"Answer per the exam guide. In current Claude Code on macOS, Linux and WSL, Glob and Grep are left out of the default tool set and Claude searches with find and grep through Bash; the two tools are available when named in --tools or --allowedTools, or in a subagent's tools list.","corroborated":[]},
{"id":"BAL-041","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.4"],"objectives":["O20"],"stem":"A codebase survey will take longer than any single session. The team wants each day's work to build on the last. Where should the accumulated understanding live?","options":[{"key":"A","text":"In a file on disk that each session reads at the start and appends to as it works.","explanation":"Durable storage outside the conversation is what makes the work survive the session boundary."},{"key":"B","text":"In the conversation history, replayed at the start of each session.","explanation":"Replay costs the full history in tokens each day and grows without bound."},{"key":"C","text":"In the agent's system prompt, updated between sessions.","explanation":"Possible, but a system prompt rewritten daily is awkward and is loaded in full every turn."},{"key":"D","text":"In the final message of each session, read back the next day.","explanation":"One message is a thin record of a day's exploration."}],"correct":"A","tiebreaker":"Guaranteed beats likely","rationale":"A scratchpad that persists outside the conversation is what lets exploration survive a session boundary.","sources":[{"title":"Task 5.4 — O20","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-042","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d5"],"taskStatements":["5.1"],"objectives":["O21"],"family":"case-facts-block","stem":"In long support conversations, progressive summarisation keeps the gist but loses exact values — an order number becomes \"the customer's order\", a date becomes \"last week\". Later steps need the exact values. What preserves them?","options":[{"key":"A","text":"Keep a structured block of case facts — order number, dates, amounts — outside the summarised history.","explanation":"Structured state holds exact values verbatim; prose summarisation is what blurs them."},{"key":"B","text":"Summarise less aggressively, so that more of the original detail survives each compression pass.","explanation":"Delays the loss rather than preventing it, and spends more context throughout."},{"key":"C","text":"Instruct the summariser to always retain every number, date and identifier it comes across.","explanation":"Better, but still probabilistic compression of facts that could be stored exactly."},{"key":"D","text":"Re-read the original ticket from the start whenever a later step needs one of the exact values.","explanation":"Works if the ticket holds them all, and costs a retrieval on every use."}],"correct":"A","tiebreaker":"Guaranteed beats likely","rationale":"A structured state object preserves exact facts through compression better than prose summarisation.","sources":[{"title":"Task 5.1 — O21","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-043","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d5"],"taskStatements":["5.1"],"objectives":["O21"],"stem":"A team is choosing a context strategy for an agent that debugs production incidents over long sessions. The initial description of the symptom stays relevant throughout. Which strategy is a poor fit?","options":[{"key":"A","text":"A sliding window that keeps only the most recent turns.","explanation":"It will eventually drop the symptom description, which the stem says stays relevant throughout."},{"key":"B","text":"Summarisation that compresses older turns while keeping their substance.","explanation":"Keeps older material in reduced form, so the symptom survives."},{"key":"C","text":"A structured state object holding the symptom and findings so far.","explanation":"Holds exactly the durable facts the session needs."},{"key":"D","text":"Selective retention that keeps the opening description and recent turns.","explanation":"Explicitly designed to keep the material the stem identifies as important."}],"correct":"A","tiebreaker":"Match the tool to the requirement","rationale":"A sliding window suits conversations where only recent turns matter; it is wrong where early context stays relevant.","sources":[{"title":"Task 5.1 — O21","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-044","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.1"],"objectives":["O21"],"stem":"To stay within budget, a pipeline truncates the oldest third of the conversation whenever it approaches the limit. Quality drops sharply at each truncation. What should replace it?","options":[{"key":"A","text":"Compaction that summarises the older material instead of discarding it.","explanation":"Truncation drops content by age, with no regard for value; compaction keeps the substance in less space."},{"key":"B","text":"Truncating a smaller fraction, more often.","explanation":"Same mechanism applied in smaller steps, with the same losses accumulating."},{"key":"C","text":"Truncating the middle of the conversation instead of the start.","explanation":"Still discards by position rather than by value."},{"key":"D","text":"Raising the budget threshold at which truncation triggers.","explanation":"Postpones the first truncation without changing what happens then."}],"correct":"A","tiebreaker":"Root cause","rationale":"Compaction preserves key context better than truncation, which drops the oldest material regardless of value.","sources":[{"title":"Task 5.1 — O21","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-045","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d5"],"taskStatements":["5.5"],"objectives":["O22"],"stem":"An extraction pipeline sends 10% of documents to human review, chosen at random. Reviewers report that most of what they see is obviously correct, while errors keep reaching production. What should the routing use instead?","options":[{"key":"A","text":"Field-level confidence calibrated on labelled data, routing documents with low-confidence fields.","explanation":"Routing on the signal that correlates with error puts review where errors actually are."},{"key":"B","text":"A higher random sample, such as 25% of documents, so more errors are caught overall.","explanation":"More reviewer time spent in the same uninformed proportion."},{"key":"C","text":"Review of every document above a certain monetary value, where an error costs the most.","explanation":"A reasonable risk filter, but value does not track extraction difficulty."},{"key":"D","text":"Review of documents from the sources that have produced errors in the past.","explanation":"Useful as one input, but it misses a new error in a previously clean source."}],"correct":"A","tiebreaker":"Signal beats volume","rationale":"Route extractions to human review by validated confidence and field-level ambiguity, not by random sampling.","sources":[{"title":"Task 5.5 — O22","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-046","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d5"],"taskStatements":["5.5"],"objectives":["O22"],"stem":"A team plans to route documents to review when the model states it is less than 80% confident. A reviewer warns this will not work well. Why?","options":[{"key":"A","text":"Self-reported confidence is poorly calibrated, so the threshold won't track the actual error rate.","explanation":"Asking the model how sure it is produces numbers that do not reliably correspond to correctness."},{"key":"B","text":"80% is too high a threshold, so it will send most of the documents to human review.","explanation":"The threshold could be tuned; the problem is the signal it is applied to."},{"key":"C","text":"Confidence cannot be obtained from the model at all, so the threshold has nothing to act on.","explanation":"It can be asked for; the issue is how well it corresponds to accuracy."},{"key":"D","text":"Routing should be based on document type rather than on any measure of confidence.","explanation":"Document type is a coarse proxy that ignores the per-field ambiguity the task names."}],"correct":"A","tiebreaker":"Usually Wrong: self-reported confidence — poorly calibrated.","rationale":"Model self-reported confidence is poorly calibrated; validated field-level scoring is what routing should use.","sources":[{"title":"Task 5.5 — O22","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-047","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d5"],"taskStatements":["5.5"],"objectives":["O22"],"stem":"After six months of clean results, a team wants to stop reviewing invoices from its three largest suppliers entirely. What should they do first?","options":[{"key":"A","text":"Measure accuracy on a stratified sample across those suppliers' document types and fields.","explanation":"Verifying real accuracy per document type and field is what justifies removing review."},{"key":"B","text":"Remove review now and monitor the volume of downstream complaints for problems.","explanation":"Uses production as the test, with errors reaching customers as the signal."},{"key":"C","text":"Keep review in place but reduce it to a random 1% of those suppliers' documents.","explanation":"A cautious step, but 1% random sampling gives a weak estimate of a low error rate."},{"key":"D","text":"Treat the six months of clean results as sufficient evidence to remove review.","explanation":"Those results came from reviewed documents, so they describe the pipeline with review in place."}],"correct":"A","tiebreaker":"Measured beats intuitive","rationale":"Before removing human review from a class of documents, verify real accuracy on a stratified sample.","sources":[{"title":"Task 5.5 — O22","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-048","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.6"],"objectives":["O28"],"family":"truncation-split","stem":"A review pass over an 80-file changeset returns JSON that is cut off mid-object. The team has already raised max_tokens twice; each rise works until the changeset grows again. What is the durable fix?","options":[{"key":"A","text":"Split the review into smaller scoped calls and merge the resulting structures.","explanation":"Scoping the work to the output budget scales with the changeset; raising the ceiling only moves the failure point."},{"key":"B","text":"Raise max_tokens to the model's maximum and leave it there for every review.","explanation":"A fixed ceiling against unbounded input fails again at the next size increase."},{"key":"C","text":"Ask the model to keep its findings more concise so the output stays shorter.","explanation":"Trades review quality for output size and still fails on a large enough changeset."},{"key":"D","text":"Retry the call whenever the output comes back truncated, until one completes.","explanation":"The same call producing the same oversized output."}],"correct":"A","tiebreaker":"Root cause","rationale":"Resolve truncation by splitting into smaller scoped calls and merging the results, not by raising max_tokens indefinitely.","sources":[{"title":"Task 4.6 — O28","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-049","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.6"],"objectives":["O28"],"family":"stop-reason-truncation","stem":"A pipeline decides whether a response was cut off by checking whether the JSON parses. Some truncated responses happen to parse, because the cut fell after a closing brace, and incomplete results are accepted as whole. What should it check?","options":[{"key":"A","text":"The response's stop_reason, which is max_tokens when the output hit the ceiling.","explanation":"The API states why generation stopped; inferring it from the text shape is what produced the false accepts."},{"key":"B","text":"Whether the JSON contains the expected number of top-level entries.","explanation":"Needs to know the expected count in advance, which varies by input."},{"key":"C","text":"Whether the response ends with a newline, as a complete response usually does.","explanation":"Another shape heuristic with the same class of failure."},{"key":"D","text":"The response length measured against the max_tokens value set on the request.","explanation":"Close to the signal, but the API reports it directly rather than requiring a comparison."}],"correct":"A","tiebreaker":"The mechanism’s own contract","rationale":"Truncated output is detected from stop_reason, not by inspecting whether the text looks complete.","sources":[{"title":"Task 4.6 — O28","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Handling stop reasons","url":"https://platform.claude.com/docs/en/build-with-claude/handling-stop-reasons","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-050","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.6"],"objectives":["O28"],"stem":"A team splits a large document-extraction call into smaller ones. They are choosing where to divide. The document is a contract whose clauses cross-reference each other. What split is safest?","options":[{"key":"A","text":"By clause group, with the cross-referenced clauses kept in the same call.","explanation":"Each call stays independently answerable, which is what makes the merged result correct."},{"key":"B","text":"By an equal character count, so each call has a similar output size.","explanation":"Predictable sizes, but it can cut a clause away from the clause it depends on."},{"key":"C","text":"By page, since pages are a natural document boundary.","explanation":"A layout boundary that has no relation to where the meaning divides."},{"key":"D","text":"By field type, with one call per field across the whole document.","explanation":"Reasonable for independent fields, but each call still reads the whole contract."}],"correct":"A","tiebreaker":"Match the tool to the requirement","rationale":"Splitting for truncation must divide along boundaries that keep each call independently answerable.","sources":[{"title":"Task 4.6 — O28","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-051","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"ci","scenario":"Claude Code for Continuous Integration","scenarioContext":null,"domains":["d3"],"taskStatements":["3.6"],"objectives":["O11"],"stem":"A nightly Claude Code job in CI normally finishes in about nine turns. Last week one run entered a loop and ran for four hours before the pipeline timeout killed it, at significant cost. The job already uses -p. What should be added?","options":[{"key":"A","text":"--max-turns sized from successful runs, plus --max-budget-usd as a spend ceiling.","explanation":"Both are print-mode flags that bound the run at the agent layer rather than waiting for a wall-clock timeout. --max-budget-usd stops the run once estimated spend reaches the cap."},{"key":"B","text":"A shorter pipeline timeout, so that a runaway job is killed sooner than four hours.","explanation":"Caps the damage in time only, and the run still burns its budget until the cut."},{"key":"C","text":"A nightly budget alert so the team is notified of expensive runs.","explanation":"Tells you after the money is spent."},{"key":"D","text":"A retry limit, so that a failing job does not get re-run over and over.","explanation":"Addresses repeated runs, not one run that will not stop."}],"correct":"A","tiebreaker":"Guaranteed beats likely","rationale":"Non-interactive CI runs need turn and cost limits sized from real runs, so a pathological run cannot bill indefinitely.","sources":[{"title":"Task 3.6 — O11","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Run Claude Code programmatically (headless)","url":"https://code.claude.com/docs/en/headless","type":"docs"},{"title":"Claude Code CLI reference","url":"https://code.claude.com/docs/en/cli-reference","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-052","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"ci","scenario":"Claude Code for Continuous Integration","scenarioContext":null,"domains":["d3"],"taskStatements":["3.6"],"objectives":["O11"],"stem":"A CI job asks Claude Code to review a pull request and comment. The prompt says \"do not modify any files\". A reviewer objects that this is not a real guarantee, since the PR branch itself can contain instructions. What should the job do instead?","options":[{"key":"A","text":"Limit the run with --tools to read-only tools, so modification is not available at all.","explanation":"--tools is what restricts the available set, so the capability is absent rather than merely discouraged. A prompt is advisory; a tool the run does not have cannot be talked into being used."},{"key":"B","text":"Strengthen the prompt wording and repeat the restriction at the end.","explanation":"Still an instruction, competing with whatever the branch contents say."},{"key":"C","text":"Run the job and revert any file changes afterwards.","explanation":"Allows the change to happen and relies on cleanup being complete."},{"key":"D","text":"Run on a copy of the branch so modifications do not reach the original.","explanation":"Protects the repository but still lets the run take actions it should not have."}],"correct":"A","tiebreaker":"Enforce at the layer the adversary cannot edit","rationale":"Scope a CI run with --tools, which restricts the available set. --allowedTools is a different flag: it marks tools that run without a permission prompt.","sources":[{"title":"Task 3.6 — O11","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Run Claude Code programmatically (headless)","url":"https://code.claude.com/docs/en/headless","type":"docs"},{"title":"Claude Code CLI reference","url":"https://code.claude.com/docs/en/cli-reference","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-053","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d2"],"taskStatements":["2.3"],"objectives":["O33"],"stem":"Every subagent in a research system is given the same 22-tool set for simplicity. The summarising subagent, whose only job is to condense findings it is handed, occasionally makes web search calls and returns material no other agent gathered. What is the fix?","options":[{"key":"A","text":"Give the summariser only the tools its role needs, which for condensing text is none.","explanation":"An out-of-role call is only possible because the tool was in range; scoping the set removes both the temptation and the choice."},{"key":"B","text":"Instruct the summariser in its prompt that it must not search for new material.","explanation":"An instruction against an available capability, which is what already failed."},{"key":"C","text":"Have the coordinator discard any summary containing unsourced material.","explanation":"Detects the symptom after a wasted call and loses the whole summary."},{"key":"D","text":"Reduce the shared set to the twelve most commonly used tools for every subagent.","explanation":"Fewer tools for everyone, still not matched to any agent's role."}],"correct":"A","tiebreaker":"Smallest thing that works","rationale":"Each subagent should hold only the tools its role requires, which reduces decision complexity and prevents out-of-role calls.","sources":[{"title":"Task 2.3 — O33","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-054","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d2"],"taskStatements":["2.3"],"objectives":["O33"],"stem":"As a multi-agent system grew to 30 tools shared by all agents, tool-selection mistakes rose sharply — agents picking a plausible but wrong tool for the job. Tool descriptions were reviewed and are clear. What structural change helps most?","options":[{"key":"A","text":"Scope each agent's tools to its role, so each chooses among a handful of relevant ones.","explanation":"Selection error grows with the number of candidates; narrowing the set per role is the structural fix."},{"key":"B","text":"Merge similar tools together, so that the total number of tools falls well below 30.","explanation":"Merging genuinely distinct tools makes each one vaguer and harder to use correctly."},{"key":"C","text":"Add a routing agent that picks the tool and tells the others which to call.","explanation":"Moves the same 30-way choice to one agent and adds a hop."},{"key":"D","text":"Rewrite the tool descriptions again, this time with more detail on each one.","explanation":"Descriptions are already clear by the stem; the count is the remaining variable."}],"correct":"A","tiebreaker":"Root cause","rationale":"A large undifferentiated tool set raises selection errors; scoping per role is the documented remedy.","sources":[{"title":"Task 2.3 — O33","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-055","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d2"],"taskStatements":["2.4"],"objectives":["O34"],"stem":"An MCP server for a ticketing system must let an agent see the list of projects and their workflow states, which change rarely, and also transition a ticket from one state to another. How should these map onto MCP primitives?","options":[{"key":"A","text":"Projects and workflow states as resources; the state transition as a tool.","explanation":"Stable content to read is a resource; an action taken with inputs is a tool."},{"key":"B","text":"Both as tools, since both involve the ticketing system.","explanation":"Works, but turns reading a rarely-changing catalogue into repeated exploratory calls."},{"key":"C","text":"Both as resources, with each transition published as a new resource.","explanation":"A transition takes input and causes a change, which is what tools are for."},{"key":"D","text":"Projects as a tool and transitions as a resource.","explanation":"Exactly inverted: it makes reading an action and acting a read."}],"correct":"A","tiebreaker":"Match the tool to the requirement","rationale":"Resources expose content for the agent to read; tools perform actions that take input and run on demand.","sources":[{"title":"Task 2.4 — O34","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code MCP documentation (scopes, .mcp.json, ${VAR} expansion, @ resources, /mcp)","url":"https://code.claude.com/docs/en/mcp","type":"docs"}],"note":"Answer per the exam guide. How a resource reaches the model depends on the client: in Claude Code, resources are attached when referenced with an @ mention, and Claude can otherwise list and read them through built-in resource tools.","corroborated":[]},
{"id":"BAL-056","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d2"],"taskStatements":["2.4"],"objectives":["O34"],"stem":"An agent using an MCP server for an internal data warehouse spends the first several calls of every session asking which datasets exist before it can do anything useful. The dataset list changes about once a month. What change removes those calls?","options":[{"key":"A","text":"Expose the dataset catalogue as a resource the agent can see without calling anything.","explanation":"Resources make content visible upfront, which is precisely what removes the discovery round trips."},{"key":"B","text":"Cache the discovery call's result so repeat calls within a session are fast.","explanation":"Makes the exploration cheaper rather than unnecessary, and the first call still happens."},{"key":"C","text":"Add a single list_everything tool that returns the full catalogue in one call.","explanation":"One call instead of several, but still a call the agent must know to make."},{"key":"D","text":"Paste the dataset list into the system prompt of every session.","explanation":"Visible upfront, but it goes stale between updates and costs tokens every session."}],"correct":"A","tiebreaker":"Built-in feature over workaround","rationale":"Exposing catalogues as resources gives upfront visibility and removes exploratory discovery calls.","sources":[{"title":"Task 2.4 — O34","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code MCP documentation (scopes, .mcp.json, ${VAR} expansion, @ resources, /mcp)","url":"https://code.claude.com/docs/en/mcp","type":"docs"}],"note":"Answer per the exam guide. How a resource reaches the model depends on the client: in Claude Code, resources are attached when referenced with an @ mention, and Claude can otherwise list and read them through built-in resource tools.","corroborated":[]},
{"id":"BAL-057","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d2"],"taskStatements":["2.4"],"objectives":["O35"],"stem":"A developer has added an MCP server to the project's .mcp.json, and the file is correct and committed. The agent behaves as though the server's tools do not exist. What is the first diagnostic step?","options":[{"key":"A","text":"Run /mcp to see whether the server is connected and which tools it is advertising.","explanation":"It separates a connection or discovery failure from a configuration error, which the correct file has already ruled out."},{"key":"B","text":"Re-write the .mcp.json entry from the documentation example.","explanation":"The stem says the file is correct, so rewriting it tests nothing."},{"key":"C","text":"Restart the machine to clear any cached configuration.","explanation":"A broad action taken before knowing what failed."},{"key":"D","text":"Move the server definition to user scope so it applies everywhere.","explanation":"Changes where the config lives without finding out why the current one is not working."}],"correct":"A","tiebreaker":"Root cause","rationale":"Verify tool discovery with /mcp when a configured server’s tools are not reaching the agent.","sources":[{"title":"Task 2.4 — O35","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code MCP documentation (scopes, .mcp.json, ${VAR} expansion, @ resources, /mcp)","url":"https://code.claude.com/docs/en/mcp","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-058","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d2"],"taskStatements":["2.4"],"objectives":["O35"],"stem":"A team wants one MCP server configuration that everyone gets on clone, where each developer authenticates with their own API token and no token is ever committed. Which configuration meets all three requirements?","options":[{"key":"A","text":"A project-scoped .mcp.json referencing the token as an environment variable each developer sets locally.","explanation":"Project scope shares it on clone; variable expansion keeps the per-person secret out of the repo."},{"key":"B","text":"A project-scoped .mcp.json with a shared service token committed to the repository.","explanation":"Shared on clone, but it commits a secret and gives everyone one identity."},{"key":"C","text":"Each developer adding the server to their own user-scope configuration with their own token.","explanation":"Keeps tokens out of the repo but shares nothing, so setups drift."},{"key":"D","text":"A project-scoped .mcp.json with the token left blank for each developer to fill in locally.","explanation":"An edited tracked file turns up in everyone's diffs and invites an accidental commit."}],"correct":"A","tiebreaker":"The option that meets every stated goal","rationale":"Project scope shares a server through version control; environment variable expansion keeps each person’s credential out of the repository.","sources":[{"title":"Task 2.4 — O35","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code MCP documentation (scopes, .mcp.json, ${VAR} expansion, @ resources, /mcp)","url":"https://code.claude.com/docs/en/mcp","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-059","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d2"],"taskStatements":["2.5","5.4"],"objectives":["O17"],"stem":"Asked how authentication works in an unfamiliar 200,000-line codebase, an agent begins by reading the twelve largest files in src/. Half an hour later it has used most of its context and still cannot describe the flow. What approach should it have taken?","options":[{"key":"A","text":"Grep for the authentication entry points, read those regions, and follow calls outward.","explanation":"Targeted discovery followed by incremental reading builds the picture without spending context on unrelated code."},{"key":"B","text":"Read the README and architecture documentation first, then stop and answer from them.","explanation":"A sensible opening move, but documentation alone rarely answers how the code actually behaves."},{"key":"C","text":"Glob for files with auth in their names and read every one of those files in full.","explanation":"Better targeted than the largest files, but still reads whole files and misses auth code named otherwise."},{"key":"D","text":"Read every file in src/ in dependency order, so nothing relevant is missed.","explanation":"Systematic and far beyond any context budget at this size."}],"correct":"A","tiebreaker":"Signal beats volume","rationale":"Incremental exploration builds understanding while keeping context spend proportional to what each step needs.","sources":[{"title":"Task 2.5, 5.4 — O17","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code tools reference","url":"https://code.claude.com/docs/en/tools-reference","type":"docs"}],"note":"Answer per the exam guide. In current Claude Code on macOS, Linux and WSL, Glob and Grep are left out of the default tool set and Claude searches with find and grep through Bash; the two tools are available when named in --tools or --allowedTools, or in a subagent's tools list.","corroborated":[]},
{"id":"BAL-060","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.6","5.1"],"objectives":["O18"],"stem":"Subagents each return a single prose paragraph summarising their findings, including numbers and the sources behind them. The coordinator must aggregate the numbers across agents into a comparison table, and it frequently misparses them. How should the output schema change?","options":[{"key":"A","text":"Return the figures as structured fields with their citations, alongside the prose summary.","explanation":"The numbers are aggregated, so they should arrive as data; the prose still serves the parts a reader needs."},{"key":"B","text":"Require the prose to state each number in a fixed sentence format the coordinator can parse.","explanation":"A parsing convention over free text, which is fragile compared to returning the field."},{"key":"C","text":"Have the coordinator ask a model to extract the numbers from each paragraph.","explanation":"Adds a lossy extraction step over data the subagent already had in hand."},{"key":"D","text":"Drop the prose and return only structured fields.","explanation":"Fixes the parsing and loses the reasoning that the final report needs."}],"correct":"A","tiebreaker":"Match the tool to the requirement","rationale":"Subagent output should render each part in the form downstream synthesis needs: structured data where it is aggregated, prose where it is read, citations alongside both.","sources":[{"title":"Task 5.6, 5.1 — O18","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-061","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.5"],"objectives":["O23"],"family":"batch-vs-sync","stem":"A product team must classify support tickets in two places: as each ticket is submitted, where the result decides what the customer sees next, and in a nightly pass over the previous day's tickets for reporting. Which processing modes fit?","options":[{"key":"A","text":"Messages API for the submission-time path, Batches for the nightly pass.","explanation":"A blocking, user-facing decision needs the synchronous path; the nightly reporting pass is latency-tolerant."},{"key":"B","text":"Batches for both, since the work is identical and batching is cheaper.","explanation":"The submission path blocks a customer, which rules out an asynchronous processing window."},{"key":"C","text":"Messages API for both, for consistent behaviour between the paths.","explanation":"Correct but forgoes the cost advantage on the pass that has no latency requirement."},{"key":"D","text":"Batches for the submission path with a short poll interval, Messages for the nightly pass.","explanation":"Inverted: it makes the user wait on a batch and runs the tolerant job synchronously."}],"correct":"A","tiebreaker":"Always Wrong: Batch API for blocking tasks.","rationale":"The Batch API suits latency-tolerant, non-blocking work; anything a user waits on belongs on the synchronous Messages API.","sources":[{"title":"Task 4.5 — O23","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Batch processing","url":"https://platform.claude.com/docs/en/build-with-claude/batch-processing","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-062","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.1"],"objectives":["O31"],"stem":"A contract-analysis prompt asks the model to flag risks. It reliably identifies payment and termination risks, but its attempts at jurisdiction-specific regulatory risk are frequently wrong, and legal review cannot tell the good flags from the bad. What should the prompt change?","options":[{"key":"A","text":"State explicitly that regulatory risk is out of scope and must not be flagged.","explanation":"An exclusion boundary stops output in the category where performance is unreliable, so what remains can be trusted."},{"key":"B","text":"Ask the model to mark each of its regulatory flags as low confidence.","explanation":"Self-assessed confidence is poorly calibrated, and the unreliable flags still arrive."},{"key":"C","text":"Add examples of correct regulatory risk analysis to the prompt for it to follow.","explanation":"May help, but it keeps the model working in a category the stem says it handles badly."},{"key":"D","text":"Have a second model review the regulatory flags before they reach legal.","explanation":"A second pass over output that should not be produced at all."}],"correct":"A","tiebreaker":"Eliminate what the scenario rules out","rationale":"Explicit exclusion boundaries stop the model producing findings in categories where its performance is unreliable.","sources":[{"title":"Task 4.1 — O31","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"BAL-063","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O03"],"stem":"A coordinator spends twenty turns with a user narrowing a market study to three named competitors and the years 2024 to 2026. It then dispatches a research subagent with the prompt \"Research the competitors we agreed on for the period discussed.\" The subagent returns a survey of the whole industry since 2015. What went wrong?","options":[{"key":"A","text":"The subagent had too few turns to narrow its own search, so it settled on the broadest scope it could find.","explanation":"More turns would not reveal names that were never passed; the scope was missing, not the time to find it."},{"key":"B","text":"The subagent receives only the prompt string, so the competitor names and years had to be written into it.","explanation":"Correct. A subagent starts without the coordinator's conversation, and the prompt is the only thing passed to it, so \"the competitors we agreed on\" refers to nothing it can see."},{"key":"C","text":"The coordinator should have let the subagent read the user conversation so it could recover the agreed scope.","explanation":"Passing the whole conversation spends context on twenty turns of negotiation to recover two facts that fit in one sentence."},{"key":"D","text":"The subagent's system prompt should tell it to ask the coordinator whenever a prompt mentions earlier talks.","explanation":"Round trips back to the coordinator are what a complete prompt avoids, and they add latency to every dispatch."}],"correct":"B","tiebreaker":"Sharing the conversation also recovers the scope, but costs the whole history when two facts would do.","rationale":"A subagent's context starts fresh: it does not see the coordinator's conversation, and the only thing passed to it is the prompt. Every finding, constraint and identifier the task needs has to be written into that prompt.","sources":[{"title":"Task 1.3 — O03","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Agent SDK: subagents (what subagents inherit)","url":"https://code.claude.com/docs/en/agent-sdk/subagents","type":"docs"},{"title":"Claude Code subagents","url":"https://code.claude.com/docs/en/sub-agents","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-064","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O03"],"stem":"A synthesis step hands a fact-checking subagent 14 claims to verify, as plain sentences. The subagent searches for each one afresh, finds newer figures for several, and marks those claims wrong, although each was correct for the dated source the research subagents cited. What should each claim carry in the handoff?","options":[{"key":"A","text":"Its source, with URL and publication date, so the check is made against the version actually cited.","explanation":"Correct. Without provenance the checker can only compare against whatever it finds today; with the source and its date, a newer figure reads as a later figure rather than a contradiction."},{"key":"B","text":"A confidence score from the research subagent, so the checker knows where to spend its search effort.","explanation":"Self-reported confidence says nothing about where a claim came from, so the checker still compares against the wrong version."},{"key":"C","text":"An instruction to treat newer figures as corrections, so the report always reflects the latest data.","explanation":"Overwriting dated, correctly cited figures changes what the report says its sources say."},{"key":"D","text":"The full text of every page the research subagents read, so the checker never needs to search at all.","explanation":"Whole pages flood the checker's context; the source and date are the parts of them the check needs."}],"correct":"A","tiebreaker":"Passing the full pages also carries the provenance, but buries the two fields that matter under everything else.","rationale":"A handoff must carry source metadata with each finding. Without it the receiving agent re-derives the claim from scratch and cannot tell a later figure from a contradiction.","sources":[{"title":"Task 1.3 — O03","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Agent SDK: subagents (what subagents inherit)","url":"https://code.claude.com/docs/en/agent-sdk/subagents","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-065","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O03"],"stem":"A support coordinator delegates refund-eligibility checks to a subagent, passing only the order ID. For every case the subagent calls the order, customer and policy tools to rebuild facts the coordinator already gathered with the customer, and about one case in ten it reaches a different total because the order was partly refunded in between. What should the coordinator pass instead?","options":[{"key":"A","text":"The order ID plus an instruction to call each tool only once, to cut down the duplicate lookups.","explanation":"Fewer calls are still calls: the subagent rebuilds facts it was never given, and the timing mismatch stays."},{"key":"B","text":"Its full transcript with the customer, so the subagent sees every fact exactly as it was gathered.","explanation":"The facts are in there, but mixed through a conversation the subagent must re-read; a structured handoff carries only what the check needs."},{"key":"C","text":"The items, amounts, prior refunds and policy clause the check rests on, each with when it was read.","explanation":"Correct. Passing the gathered facts with their timestamps lets the subagent decide on the same evidence the coordinator holds, and makes a stale reading visible instead of silently different."},{"key":"D","text":"A cache of the coordinator's recent tool results, so the repeated lookups return faster than before.","explanation":"A cache makes the rediscovery cheaper without making it unnecessary, and stale cached data hides the timing difference."}],"correct":"C","tiebreaker":"The transcript also contains the facts, but leaves the subagent to dig them out instead of handing them over.","rationale":"A subagent prompt should carry the findings and structured data the task depends on, with enough metadata (here, when each value was read) that the subagent never has to rebuild the coordinator's work.","sources":[{"title":"Task 1.3 — O03","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Agent SDK: subagents (what subagents inherit)","url":"https://code.claude.com/docs/en/agent-sdk/subagents","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-066","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O03"],"stem":"A support coordinator's system prompt says no refund amount may be quoted to a customer until the policy check has passed. Its drafting subagents' replies quote refund amounts throughout. The coordinator's prompts to them describe only the customer's question. What should change?","options":[{"key":"A","text":"Restate the refund rule in the coordinator's system prompt in stronger terms, since the subagents work under it.","explanation":"Strengthening a prompt the subagents never see changes nothing about what they do."},{"key":"B","text":"Have the coordinator discard any draft that quotes an amount and dispatch the same subagent again.","explanation":"Rejecting and redispatching with the same prompt reproduces the same drafts at twice the cost."},{"key":"C","text":"Put the refund rule in each subagent's own prompt, since subagents don't receive the coordinator's system prompt.","explanation":"Correct. A subagent's context holds its own system prompt and the prompt it was given, not the parent's system prompt, so a rule the task depends on has to travel in the handoff or the subagent's definition."},{"key":"D","text":"Switch the subagents to a more capable model so they apply stricter refund standards on their own.","explanation":"A stronger model still can't follow a rule it was never given."}],"correct":"C","tiebreaker":"Redispatching looks like enforcement, but the second run gets the same incomplete prompt as the first.","rationale":"Subagents don't inherit the coordinator's system prompt. Constraints that govern the task, such as when an amount may be quoted, must be written into the subagent's prompt or definition.","sources":[{"title":"Task 1.3 — O03","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Agent SDK: subagents (what subagents inherit)","url":"https://code.claude.com/docs/en/agent-sdk/subagents","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-067","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O03"],"stem":"A coordinator asks a subagent to write the Risks section of a report, passing the section title and a word limit. The research findings, including two flagged as low-confidence and one contradicted by another source, sit in the coordinator's context. The section comes back confident and generic. What did the dispatch leave out?","options":[{"key":"A","text":"A firmer instruction to be specific, with an example of a well-written risks section from an earlier report.","explanation":"Specific about what? An instruction can't supply findings the subagent never received."},{"key":"B","text":"The findings themselves, with their sources and the confidence and conflict flags attached to each one.","explanation":"Correct. The section can only reflect findings it is given. Passing them with sources and uncertainty flags lets it name specific risks and keep the low-confidence and contested ones marked as such."},{"key":"C","text":"Permission to run its own searches, so the subagent can find risk material on the topic independently.","explanation":"Fresh searches rediscover what the coordinator already holds and lose the confidence and conflict judgements already made."},{"key":"D","text":"A higher word limit, so the subagent has room to cover the risks in more depth than the limit allowed.","explanation":"More words of generic content; length is not what was missing."}],"correct":"B","tiebreaker":"Letting it search would produce specifics, but not the ones the research established, and not their uncertainty.","rationale":"A subagent prompt must include the findings, structured data and metadata (sources, confidence, conflicts) the task needs. Otherwise the subagent fills the gap with generic content or redoes the coordinator's work.","sources":[{"title":"Task 1.3 — O03","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Agent SDK: subagents (what subagents inherit)","url":"https://code.claude.com/docs/en/agent-sdk/subagents","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-068","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O06"],"stem":"Midway through a session, an engineer creates a .claude/agents/ folder in a project that had none and adds a reviewer.md subagent with valid frontmatter. Asked to use the reviewer agent, Claude says no such agent exists. A new session opened in the same directory can use it straight away. What explains this?","options":[{"key":"A","text":"The file needs a matching entry in settings.json before Claude Code will register the subagent it defines.","explanation":"Subagents are discovered from the folder; there is no settings registration step, and the new session shows none is needed."},{"key":"B","text":"Project subagents only load once the file is committed, so the engineer must commit it before using it.","explanation":"The new session in the same directory loads it uncommitted, which rules out a commit requirement."},{"key":"C","text":"The subagent's description is too vague for Claude to match the request to it, so it reports no agent.","explanation":"A vague description affects whether Claude picks an agent on its own; here it was named outright and still not found."},{"key":"D","text":"Agent folders are only watched if they existed at session start, so this session needs a restart.","explanation":"Correct. Claude Code picks up new or edited agent files within seconds, but only in directories it was already watching. The first file in a new directory needs a restart, which is why the new session sees it."}],"correct":"D","tiebreaker":"A vague description is the usual delegation fault, but the agent was named outright and Claude still didn't know it existed.","rationale":"When a subagent definition doesn't appear, check whether its directory existed when the session started, whether its frontmatter is valid, and whether its name collides with another definition.","sources":[{"title":"Task 1.3 — O06","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Agent SDK: subagents (what subagents inherit)","url":"https://code.claude.com/docs/en/agent-sdk/subagents","type":"docs"},{"title":"Claude Code subagents","url":"https://code.claude.com/docs/en/sub-agents","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-069","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O06"],"stem":"An internal developer tool built on the Agent SDK passes a reviewer agent in the agents option of query(). The team has since refined a .claude/agents/reviewer.md file with a narrower tools list and better instructions, but the subagent keeps behaving as it did before. Both definitions are valid. What is happening?","options":[{"key":"A","text":"The programmatic definition passed to query() takes precedence over a filesystem agent with the same name.","explanation":"Correct. Agents passed to query() override a filesystem agent with the same name, so the refined file never takes effect. Remove one definition or give them different names."},{"key":"B","text":"Tool lists in Markdown agent files are advisory, so the narrower list is ignored when the subagent runs.","explanation":"A tools list does restrict the subagent: a tool left out is not in its session at all."},{"key":"C","text":"The Markdown file must be referenced from CLAUDE.md before the SDK will prefer it over the coded one.","explanation":"CLAUDE.md plays no part in choosing between agent definitions."},{"key":"D","text":"Edits to an agent file take effect only after the subagent's earlier transcripts have been cleared.","explanation":"Old transcripts don't pin a definition; the coded agent of the same name is what wins."}],"correct":"A","tiebreaker":"Each wrong option invents a loading rule; the documented rule is that the programmatic definition wins on a name clash.","rationale":"Diagnosing a subagent that ignores its definition starts with which definition is actually loaded. A programmatic agent passed to query() overrides a filesystem agent of the same name.","sources":[{"title":"Task 1.3 — O06","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Agent SDK: subagents (what subagents inherit)","url":"https://code.claude.com/docs/en/agent-sdk/subagents","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-070","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O06"],"stem":"A repository-audit tool spawns one subagent per service, and each service subagent is meant to spawn its own file-reader subagents. The service subagents have the Agent tool in their tools lists, but they always read every file themselves and never spawn anything. The environment sets CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH=1. What is the cause?","options":[{"key":"A","text":"Nested spawning is unsupported, so only the top-level coordinator can ever create subagents of its own.","explanation":"Nesting is supported, up to three layers below the main agent by default; the configured limit is what prevents it here."},{"key":"B","text":"The depth limit of 1 stops subagents spawning their own, so they do the delegated work themselves.","explanation":"Correct. The variable sets how many layers of subagents may sit below the main agent. At 1, a subagent can't spawn its own and does its delegated work itself, which is exactly what the logs show."},{"key":"C","text":"The service subagents need the coordinator's permission mode copied into their definitions before spawning.","explanation":"Permission modes govern approval of tool calls, not whether a subagent may spawn; the depth setting does."},{"key":"D","text":"The file-reader definitions have vague descriptions, so the service subagents can't find any to call.","explanation":"Vague descriptions affect which subagent is chosen, not whether any can be spawned; at depth 1, none can."}],"correct":"B","tiebreaker":"Calling nesting unsupported gets the symptom right but the mechanism wrong: the default allows three layers and this run set it to one.","rationale":"When spawning silently doesn't happen, check the wiring as well as the definitions: the tool to spawn with, and any limit on how deep subagents may nest.","sources":[{"title":"Task 1.3 — O06","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Agent SDK: subagents (what subagents inherit)","url":"https://code.claude.com/docs/en/agent-sdk/subagents","type":"docs"},{"title":"Claude Code subagents","url":"https://code.claude.com/docs/en/sub-agents","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-071","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O06"],"stem":"A team keeps twelve subagent files in .claude/agents/. A teammate adds security-review.md, made by copying code-review.md and editing the instructions. The new agent never appears among the available agents, although the file sits in the folder with the others and the session was started after the folder existed. What should they check first?","options":[{"key":"A","text":"Whether the copied file still carries code-review's name field, so the two definitions collide.","explanation":"Correct. Subagents are identified by the name in their frontmatter, not the filename. A copy that keeps the original name duplicates an existing agent, a documented reason a new definition never appears."},{"key":"B","text":"Whether the folder has reached a cap on how many subagent definitions Claude Code will load.","explanation":"Twelve is nowhere near a documented limit, and the fault is in the new file, which is where to look first."},{"key":"C","text":"Whether the new file needs a reference in CLAUDE.md before Claude Code will load it.","explanation":"Agent files are discovered from the folder; CLAUDE.md doesn't register them."},{"key":"D","text":"Whether the new agent's tools list repeats tools that are already given to another subagent.","explanation":"Several subagents can share tools; overlapping tool lists don't stop a definition loading."}],"correct":"A","tiebreaker":"A loading cap would also hide an agent, but nothing suggests one; a copied name field is the documented cause and the cheaper check.","rationale":"A subagent definition that never appears usually has invalid frontmatter or a name that another definition already uses. Check the new file before looking for limits elsewhere.","sources":[{"title":"Task 1.3 — O06","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Agent SDK: subagents (what subagents inherit)","url":"https://code.claude.com/docs/en/agent-sdk/subagents","type":"docs"},{"title":"Claude Code subagents","url":"https://code.claude.com/docs/en/sub-agents","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-072","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d3"],"taskStatements":["3.2"],"objectives":["O14"],"stem":"Engineers run a /triage skill several times a session. Each run reads logs and stack traces and leaves its full investigation in the conversation, and later runs start echoing conclusions from earlier, unrelated incidents. The skill's steps are explicit and need nothing from the conversation. What should the skill's frontmatter add?","options":[{"key":"A","text":"context: fork, so each run starts in a fresh subagent without the session history and returns only its result.","explanation":"Correct. A forked skill runs in a new subagent that doesn't see the conversation history, and its result returns to the main conversation when it finishes. Each run starts clean and its investigation stays out of the session."},{"key":"B","text":"allowed-tools listing only Read and Grep, so the skill can no longer pull earlier incidents into the session.","explanation":"allowed-tools pre-approves the listed tools; it doesn't remove others or separate the run from the conversation it shares."},{"key":"C","text":"disable-model-invocation: true, so the skill runs only when an engineer types its name, never automatically.","explanation":"This controls who can trigger the skill, not what each run can see."},{"key":"D","text":"An argument-hint for the incident ID, so each run is told clearly which incident it should investigate.","explanation":"Naming the incident doesn't stop the run reading, and being swayed by, earlier investigations still in context."}],"correct":"A","tiebreaker":"An incident argument helps each run aim, but only isolation stops earlier investigations leaking into it.","rationale":"context: fork suits a task-style skill with explicit steps that doesn't depend on the conversation: each run starts without session history, so earlier runs can't contaminate it, and only the result comes back.","sources":[{"title":"Task 3.2 — O14","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code skills (run skills in a subagent)","url":"https://code.claude.com/docs/en/skills","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-073","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"ci","scenario":"Claude Code for Continuous Integration","scenarioContext":null,"domains":["d4"],"taskStatements":["4.1"],"objectives":["O31"],"stem":"A CI review step is prompted to \"report anything that might be a problem\". It posts about 40 comments per pull request. On a labelled sample, its findings on injection, hard-coded secrets and missing auth checks are almost always right, while its comments on naming, formatting and possible performance issues are mostly wrong or ignored. What should change in the prompt?","options":[{"key":"A","text":"Ask it to report only findings it is highly confident about, so the weaker comments drop out on their own.","explanation":"Self-assessed confidence is poorly calibrated, so findings from the unreliable categories still come through."},{"key":"B","text":"List what to report (injection, secrets, missing auth) and state that style and performance guesses are out.","explanation":"Correct. Explicit inclusion and exclusion boundaries keep the model out of the categories where its findings are unreliable, so what it does post can be trusted."},{"key":"C","text":"Cap the output at five comments per pull request, so reviewers only ever see the most important findings.","explanation":"A cap selects some comments, not the reliable ones; it can drop a real injection finding to keep a naming nit."},{"key":"D","text":"Open the prompt with a senior security reviewer persona, so the model focuses on the issues that matter.","explanation":"A persona shifts tone but doesn't define what is in or out of scope."}],"correct":"B","tiebreaker":"Asking for high confidence sounds like a boundary, but it leaves the model to judge its own reliability, which is the weak point.","rationale":"Explicit inclusion and exclusion criteria stop the model producing findings in categories where its performance is unreliable, so the output that remains is worth acting on.","sources":[{"title":"Task 4.1 — O31","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Prompting best practices: be clear and direct","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-074","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.1"],"objectives":["O31"],"stem":"A contract pipeline is asked to extract \"all relevant dates\". Dates written in the contract come out accurately, but the model also returns dates it computed, such as renewal deadlines and notice cut-offs, and about a third of those are wrong because they depend on business-day rules it doesn't have. What should the prompt say?","options":[{"key":"A","text":"Show the arithmetic for every computed date, so reviewers can check each derived deadline before use.","explanation":"Visible arithmetic makes errors easier to spot but still produces them, and moves the checking onto reviewers."},{"key":"B","text":"Mark every computed date with a confidence level, so the pipeline can discard the ones it is unsure of.","explanation":"Self-reported confidence is poorly calibrated, so wrong derived dates still get through."},{"key":"C","text":"Include the business-day rules for each jurisdiction, so every derived date can be computed in-prompt.","explanation":"Closer, but it keeps the model doing calendar arithmetic it gets wrong; deterministic code is the reliable place for derived dates."},{"key":"D","text":"Extract only dates stated in the text, and leave derived deadlines, which need business-day rules, to code.","explanation":"Correct. An inclusion boundary limits extraction to what the model does reliably, reading stated dates, and takes the unreliable category, computed deadlines, out of the prompt entirely."}],"correct":"D","tiebreaker":"Supplying the business-day rules is the runner-up, but it keeps the model in the category it handles badly instead of drawing the line around it.","rationale":"Define what the extraction includes and excludes so the model works only where it is reliable. Values that need rules the model lacks belong in deterministic code downstream.","sources":[{"title":"Task 4.1 — O31","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Prompting best practices: be clear and direct","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"BAL-075","exam":"CCAR-F","set":"objective_balance","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d1"],"taskStatements":["1.1"],"objectives":["O01"],"stem":"A support agent answers order questions that need three independent lookups: order status, shipment tracking and refund history. Logs show exactly one tool call per response, so each answer takes three round trips. Results go back correctly, all in one user message, and the system prompt already asks for independent calls to be made together. The request sets tool_choice to {\"type\": \"auto\", \"disable_parallel_tool_use\": true}. What should change?","options":[{"key":"A","text":"Set tool_choice to any, so the model is required to call all of the available tools in each response.","explanation":"any requires some tool call, not every tool, and it doesn't lift the one-call limit the flag imposes."},{"key":"B","text":"Combine the three lookups into one tool, since the model can only call a single tool per response.","explanation":"Claude can call several tools in one response by default; merging tools works around a setting that should simply be removed."},{"key":"C","text":"Remove disable_parallel_tool_use, which limits Claude to at most one tool call in each response.","explanation":"Correct. With tool_choice auto, disable_parallel_tool_use: true means Claude calls at most one tool per response. Parallel tool use is on by default, so removing the flag lets the three lookups happen in one turn."},{"key":"D","text":"Raise max_tokens, since several tool_use blocks in one response need more output room than one.","explanation":"Output length isn't what limits the calls; the flag caps them at one per response."}],"correct":"C","tiebreaker":"Merging the tools would also cut round trips, but it rewrites the tool surface to dodge a flag that can just be removed.","rationale":"Independent tool calls can be emitted together in one response, which is on by default. A one-call-per-turn pattern with correctly formatted results points at configuration: disable_parallel_tool_use inside tool_choice.","sources":[{"title":"Task 1.1 — O01","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Parallel tool use","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/parallel-tool-use","type":"docs"}],"note":null,"corroborated":[]},
{"id":"HARD-001","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":[],"objectives":[],"stem":"An agent loop checks stop_reason and handles tool_use and end_turn. Anything else falls through to a branch that returns the accumulated text to the user. A nightly job using it produces a complete-looking report most nights and a truncated one roughly once a week. What is the defect?","options":[{"key":"A","text":"The loop is not retrying on transient failures, so an occasional network error ends the run early with whatever text had accumulated.","explanation":"A dropped network call leaves a trace — an exception, a failed request in the logs — and would not produce a cleanly formatted report that simply stops early."},{"key":"B","text":"The job runs without an iteration cap, so on heavy nights the agent exhausts its budget partway through and returns early.","explanation":"A hit iteration cap is observable and would bite on the longest runs for a reason you could see; nothing here records a budget being exhausted."},{"key":"C","text":"Tool results are being appended in the wrong order on nights when several tools are called, so the model loses the thread.","explanation":"Misordered tool results produce confused or contradictory content, not content that is correct up to a point and then stops."},{"key":"D","text":"The fall-through treats every other stop reason as success, so a max_tokens stop returns partial output as though it were finished.","explanation":"Correct. The catch-all branch returns accumulated text for every stop reason it does not name, so a max_tokens stop — which only happens when the report runs long — is reported as a finished job."}],"correct":"D","tiebreaker":"Root cause","rationale":"A catch-all branch that returns accumulated text turns every unhandled stop reason into a silent success. max_tokens is the one that bites here: generation halts wherever it happened to be, so the text reads as plausible and is incomplete, and it only appears on nights when the report runs long. The other options describe real failures that would look different — a network error or a hit iteration cap leaves a trace, and reordered tool results produce confused content rather than truncated content. Branch on every value explicitly and treat an unknown one as an error, not as done.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Agentic Architecture & Orchestration. Verified against a primary source; see docs/VERIFICATION.md (hd-d1-01).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Handling stop reasons","url":"https://platform.claude.com/docs/en/build-with-claude/handling-stop-reasons","type":"docs"}],"note":null,"corroborated":[]},
{"id":"HARD-002","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d1"],"taskStatements":[],"objectives":[],"stem":"A support agent calls issue_refund. The tool succeeds, the network drops before the result reaches the orchestrator, and the orchestrator's retry logic calls it again. The team proposes moving the refund call later in the sequence so there is less time for a drop. Assess the proposal.","options":[{"key":"A","text":"It does not address the failure: the window is smaller but still open, and a repeat charge is prevented by an idempotency key at the tool, not by timing.","explanation":"Correct. Moving the call narrows the window without closing it; the retry can still fire against a completed refund. Only an idempotency key at the tool makes the second call return the first result instead of charging again."},{"key":"B","text":"It is sound, because the shorter the gap between the call and the confirmation, the lower the probability that a retry fires against a completed action.","explanation":"Lowering the probability of a race is not the same as removing it, and a refund issued twice is not a risk you manage by making it rarer."},{"key":"C","text":"It is unnecessary, because an orchestrator should never retry a tool call that has side effects, and the retry policy is the thing to change.","explanation":"Too absolute. A lost response is exactly the case where a side-effecting call does need retrying — the work may never have happened. The fix is to make the retry safe, not to forbid it."},{"key":"D","text":"It helps but is incomplete: it should be paired with a confirmation step that asks the user whether the refund arrived before any retry.","explanation":"Asking the customer whether a refund arrived is slow, often unanswerable, and moves a correctness problem onto the person least able to resolve it."}],"correct":"A","tiebreaker":"Guaranteed beats likely","rationale":"Reordering changes how often the race is lost, not whether it can be. The guarantee has to come from the tool: an idempotency key means the second call recognizes the first and returns the original result instead of refunding twice. The third option is tempting and too absolute — side-effecting calls do need retrying when the failure is genuinely a lost response, which is exactly this case. Asking the user is slow, unreliable, and pushes a correctness problem onto them.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Agentic Architecture & Orchestration. Verified against a primary source; see docs/VERIFICATION.md (hd-d1-02).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"HARD-003","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":[],"objectives":[],"stem":"A design review covers two systems. System A summarizes five named documents, concurrently. System B reads a request, works out which checks apply, and dispatches those. Both run work in parallel. Which patterns are these?","options":[{"key":"A","text":"Both are parallelization: concurrency is the defining property, and the difference is only in how the work is enumerated.","explanation":"Concurrency is what the two share, so it cannot be what distinguishes them. The question is who determines the units of work."},{"key":"B","text":"A is parallelization, B is prompt chaining, because B's steps run in a sequence decided before any of them start.","explanation":"B's checks are not a fixed sequence decided in advance — that is the point of the example. It reads the request first and then decides which checks apply."},{"key":"C","text":"A is parallelization, B is orchestrator–worker, because B decides the subtasks at runtime after seeing the request.","explanation":"Correct. A's five documents are known before the run; B examines the request at runtime and determines the breakdown, which is the defining move of orchestrator-worker."},{"key":"D","text":"A is orchestrator–worker and B is routing, because A has a coordinator combining results and B classifies before dispatching.","explanation":"Combining results does not make A an orchestrator, and B does more than classify-and-dispatch: it decides how many checks and which."}],"correct":"C","tiebreaker":"Who decides the units of work","rationale":"Concurrency is shared by both, which is exactly why questions pair them: the distinction is who decides the units of work. In A they are known before the run — five named documents. In B a coordinator examines the request and determines the breakdown, which is orchestrator–worker. The fourth option misreads both: combining results does not make A an orchestrator, and B does more than classify-and-dispatch because it decides how many checks and which.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Agentic Architecture & Orchestration. Verified against a primary source; see docs/VERIFICATION.md (hd-d1-03).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"HARD-004","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d1"],"taskStatements":[],"objectives":[],"stem":"An agent must never send an email without human approval. Three designs are proposed: a system-prompt rule stating it, a PreToolUse hook on the send tool, and removing the send tool so the agent writes a draft another system picks up. Which satisfies \"never\"?","options":[{"key":"A","text":"All three, because each one prevents the send in normal operation and the differences are about convenience rather than correctness.","explanation":"The three differ on whether the send can happen at all, which is correctness, not convenience."},{"key":"B","text":"The hook and the draft design both do, while the system-prompt rule shifts probability rather than enforcing anything.","explanation":"Correct. The hook blocks the call before it executes and the draft design makes sending unreachable; the system-prompt rule is text competing with other text, which shifts the odds without closing the path."},{"key":"C","text":"Only the draft design, because a hook is configuration that a developer can edit and so cannot carry a guarantee.","explanation":"A hook is editable by anyone with repository access, but that is a question about which adversary you are defending against — against the model, it enforces absolutely."},{"key":"D","text":"The hook alone, because the draft design still lets the agent compose the message and a downstream system may dispatch it unreviewed.","explanation":"Composing a draft is not sending. The approval step lives in the downstream system, which is precisely where the design puts it."}],"correct":"B","tiebreaker":"Enforcement beats instruction","rationale":"\"Never\" is an enforcement word, and enforcement runs in code regardless of what the model decides. The hook blocks the call before it executes; removing the tool makes the action unreachable. The prompt is text competing with other text. The third option over-corrects: a hook is editable by whoever can edit the repo, which is a question of who you are defending against, and it still enforces against the model. The fourth misreads the draft design — composing a draft is not sending, and the approval sits in the downstream system.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Agentic Architecture & Orchestration. Verified against a primary source; see docs/VERIFICATION.md (hd-d1-04).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"HARD-005","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":[],"objectives":[],"stem":"A subagent crashes mid-task. The orchestrator catches the exception and returns an empty string as the tool result so the loop can continue. The run completes and the final answer omits that subagent's section without mentioning it. What is the fix?","options":[{"key":"A","text":"Let the exception propagate, so the run fails loudly rather than producing an answer with a silent hole in it.","explanation":"Failing the entire run discards every step that succeeded, which is too blunt a response to one subagent failing."},{"key":"B","text":"Retry the subagent until it succeeds, since an empty result is never a useful input to the next step.","explanation":"Unbounded retry hammers a dependency that may be permanently down, and still never tells the user anything is missing."},{"key":"C","text":"Return a structured result saying the step failed and why, so the model can report the gap or route around it.","explanation":"Correct. A structured failure says what broke and why, so the model can report the gap, route around it, or stop — instead of treating an empty string as a section with nothing in it."},{"key":"D","text":"Cache the last successful output from that subagent and substitute it, so the section is populated with the best available content.","explanation":"Substituting a cached result produces a confident section built from data that was never fetched for this run — the worst of the four outcomes."}],"correct":"C","tiebreaker":"Actionable beats silent","rationale":"An empty string is indistinguishable from a step that genuinely found nothing, which is why the gap went unmentioned. A structured failure gives the model something to reason about: it can say the section is missing, try another route, or stop. Failing the whole run discards work that succeeded and is too blunt for a partial failure. Unbounded retry hammers a dependency that may be permanently down. Substituting stale output is the worst of the four — it produces a confident answer from data that was never fetched.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Agentic Architecture & Orchestration. Verified against a primary source; see docs/VERIFICATION.md (hd-d1-05).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"HARD-006","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":[],"objectives":[],"family":"loop-termination","stem":"An evaluator–optimizer loop has run 40 iterations on one document without the critic passing it. Cost is mounting. Where does the design need changing?","options":[{"key":"A","text":"It needs a cap with a defined outcome at the limit, because a loop whose exit depends on a judgment may never reach it.","explanation":"Correct. The loop exits only when two components agree, and nothing guarantees they ever will. A cap with a defined outcome at the limit bounds the cost regardless of how the critic behaves."},{"key":"B","text":"The critic is too strict, because a bar no document has cleared in 40 attempts is set above what the generator can produce.","explanation":"Relaxing the critic may raise the convergence rate, but a loop with no bound can still run away on the next document."},{"key":"C","text":"The generator is too weak, because a more capable tier would satisfy the existing critic in far fewer iterations.","explanation":"A stronger generator has the same property: better odds of converging, no guarantee, and no limit on what one document can cost."},{"key":"D","text":"The pattern is wrong, because a single-pass chain with one final review would suit this work at a fraction of the cost.","explanation":"Evaluator-optimizer is the right pattern for iterative refinement; the defect is the missing bound, not the choice of pattern."}],"correct":"A","tiebreaker":"Bound what cannot be guaranteed to converge","rationale":"The structural fault is that nothing bounds the loop: convergence depends on two components agreeing, and no amount of tuning guarantees they will. A cap plus a defined behavior at it — ship the best attempt, escalate, fail — makes the cost bounded whatever the critic does. The second and third options may both improve the convergence rate and neither removes the possibility of a run that never ends. The fourth throws away a pattern that is right for the task.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Agentic Architecture & Orchestration. Verified against a primary source; see docs/VERIFICATION.md (hd-d1-06).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"HARD-007","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":[],"objectives":[],"stem":"Two tools exist: search_orders (\"Search orders\") and lookup_order (\"Look up an order\"). The model picks the wrong one about a third of the time. A developer proposes listing the preferred tool first in the array. Assess.","options":[{"key":"A","text":"Reasonable as a first attempt, since the model reads the tool array in order and earlier definitions carry more weight in selection.","explanation":"Selection is driven by the name, description and input schema, not by position in the tool array, so reordering cannot change the outcome."},{"key":"B","text":"Wrong approach: the two should be merged into one tool with a mode parameter, because any two tools this similar are one tool.","explanation":"Merging is sometimes right, but nothing here shows the two are one job, and it is a far larger change than the defect warrants: neither description says when its tool applies."},{"key":"C","text":"Reasonable, but it should be paired with a system-prompt instruction naming which tool to prefer for which kind of request.","explanation":"A system-prompt instruction is a probabilistic patch over a description that could simply say when the tool applies."},{"key":"D","text":"Ordering has no effect on selection. The descriptions do not say when each applies, and that is what has to change.","explanation":"Correct. Both descriptions restate the tool's own name and neither says when it applies or when it does not, which is exactly what the model needs at selection time."}],"correct":"D","tiebreaker":"Root cause","rationale":"Selection is driven by the name, description and input schema — not by position in the array, so the proposal cannot work. Both descriptions restate the tool name and neither says when it applies or when it does not, which is the actual defect: one presumably takes a query and returns many, the other takes an id and returns one. Merging is sometimes right and is a larger change than the problem warrants. A system-prompt instruction is a probabilistic patch over a description that could simply be correct.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Tool Design & MCP Integration. Verified against a primary source; see docs/VERIFICATION.md (hd-d2-01).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Define tools (descriptions, tool_choice)","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools","type":"docs"}],"note":null,"corroborated":[]},
{"id":"HARD-008","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d2"],"taskStatements":[],"objectives":[],"stem":"An MCP server exposes delete_event as a Tool. A team building a read-only calendar assistant against that server asks how to prevent deletions. What is the right answer?","options":[{"key":"A","text":"Declare delete_event as a Resource in the client configuration, since Resources are read-only by definition.","explanation":"Tool versus Resource is the server's design decision about what an operation is. A consuming client cannot reclassify someone else's side-effecting tool as read-only."},{"key":"B","text":"Configure the client to expose only the tools the assistant needs, so delete_event is never offered to the model.","explanation":"Correct. The client controls which tools it surfaces, and a tool that is never offered cannot be called — enforcement on your own side, with no dependency on the model or the server team."},{"key":"C","text":"Add a system-prompt instruction that the assistant is read-only and must not call any tool that modifies the calendar.","explanation":"An instruction not to call a tool that is sitting in front of the model is the usual probabilistic non-answer to a question about prevention."},{"key":"D","text":"Ask the server's maintainers to split it into a read-only server and a separate one carrying the write operations.","explanation":"Splitting the server would work, but it asks another team for a change you do not need when the client can already solve it."}],"correct":"B","tiebreaker":"Enforcement beats instruction","rationale":"The Tool/Resource distinction is a server-side design decision about the nature of an operation, and a consuming client cannot reclassify someone else's side-effecting tool — which rules out the first option. What a client does control is which tools it surfaces, and a tool never offered cannot be called. The prompt instruction is the usual probabilistic non-answer. Splitting the server works and asks another team for a change you do not need: you can already solve it on your side.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Tool Design & MCP Integration. Verified against a primary source; see docs/VERIFICATION.md (hd-d2-02).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"HARD-009","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":[],"objectives":[],"stem":"An agent's tool returns, on failure, the full 400-line stack trace from the underlying service. The team argues it gives the model maximum information to recover with. What is wrong with that reasoning?","options":[{"key":"A","text":"Stack traces leak internal detail about the service, so the real objection here is disclosure rather than anything about the model's reasoning.","explanation":"Disclosure is a real secondary concern, but the question asks what is wrong with the reasoning about the model's recovery, not about who can read the trace."},{"key":"B","text":"The model cannot parse a 400-line trace reliably, so the tokens are spent on material it will not extract the failure from in any case.","explanation":"A stack trace is perfectly parseable. The problem is not that the model cannot read it but that almost none of it bears on what to do next."},{"key":"C","text":"A tool result is the input to the next decision, and 400 lines of trace crowds out the part that says what failed and what to try.","explanation":"Correct. A tool result is the input to the next decision, and 400 lines of trace crowd out the one or two lines saying what failed and what might work instead."},{"key":"D","text":"A 400-line trace risks exceeding what a single tool result may return, so the part naming the failure may be the part that gets truncated.","explanation":"Nothing here is being truncated; the full trace arrives intact. That is the problem rather than the limit."}],"correct":"C","tiebreaker":"Signal beats volume","rationale":"More information is not automatically more useful when it competes for the same context. What the next decision needs is the outcome and an actionable reason; the trace buries both and spends window that the rest of the task needs. The first option names a real secondary concern. The second is wrong on the facts — a trace is readable, it is just mostly irrelevant. Keep the trace in your logs, where a human debugging the service will actually want it.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Tool Design & MCP Integration. Verified against a primary source; see docs/VERIFICATION.md (hd-d2-03).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"HARD-010","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d3"],"taskStatements":[],"objectives":[],"stem":"A PreToolUse hook is meant to block commits to main. It detects the branch correctly, logs \"blocked: commit to main\", and exits with code 1. Commits to main are still going through. What is wrong?","options":[{"key":"A","text":"Exit code 1 is a non-blocking error. Only exit code 2 blocks the call, so the hook detects correctly and stops nothing.","explanation":"Correct. Exit 1 signals a non-blocking error: the hook runs, the message is logged, and the call proceeds. Exit 2 is the code that denies it, which is why every visible part of this hook works and nothing is stopped."},{"key":"B","text":"The hook is registered on the wrong event. Blocking has to happen in PostToolUse, where exit code 1 is read as a veto.","explanation":"PostToolUse fires after the tool has already run, so it cannot prevent anything — the opposite of what a block needs."},{"key":"C","text":"Hooks cannot block git operations. Git runs as a subprocess outside the tool lifecycle, so the exit code goes nowhere.","explanation":"Hooks do gate git operations; this one is firing and detecting the branch correctly, which disproves the claim."},{"key":"D","text":"The hook must write its decision as JSON. An exit code of 1 is advisory on its own and the runner continues regardless.","explanation":"A JSON decision is an alternative way to express the outcome, not the reason this hook fails. The exit code it already returns simply means the wrong thing."}],"correct":"A","tiebreaker":"The mechanism's own contract","rationale":"This is a bug that ships easily because every observable part of it works: the hook fires, the condition matches, the message appears in the log, and the commit proceeds. Exit 1 signals a non-blocking error; exit 2 is what denies the call. PostToolUse runs after the tool has already executed and cannot prevent anything, which is the opposite of the fix. The third option is simply false, and the fourth describes an alternative decision format rather than the reason this hook fails.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Claude Code Configuration & Workflows. Verified against a primary source; see docs/VERIFICATION.md (hd-d3-01).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code hooks reference","url":"https://code.claude.com/docs/en/hooks","type":"docs"}],"note":null,"corroborated":[]},
{"id":"HARD-011","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"ci","scenario":"Claude Code for Continuous Integration","scenarioContext":null,"domains":["d3"],"taskStatements":[],"objectives":[],"stem":"A CI job runs a code review on every pull request. It already passes a non-interactive flag and a structured output format. About one run in five still comes back with an incomplete review, always on pull requests that touch more files than usual. What is the most likely cause?","options":[{"key":"A","text":"The timeout is too short for large diffs, so the job is being killed partway and the pipeline keeps whatever had been written.","explanation":"A job killed on timeout reports a kill, with a duration that matches the limit. The scenario describes runs that finish normally with part of the review missing."},{"key":"B","text":"Output is being buffered rather than streamed, so the end of a long review is lost when the pipeline reads the buffer.","explanation":"Buffering would affect every run, not only the ones touching more files, and it delays output rather than dropping it."},{"key":"C","text":"A tool the run needs on larger diffs is not pre-authorized, so the call is denied with nobody to approve it and that part is skipped.","explanation":"Correct. In a non-interactive run, a call that needs approval is denied unless a rule, hook or permission tool approves it. A larger diff reaches a tool the smaller runs never needed, the call is denied, and the review comes back incomplete."},{"key":"D","text":"The structured format is being emitted only at the end, so the pipeline reads the result before the output is complete.","explanation":"Emitting at the end is normal for a structured format and would affect every run equally."}],"correct":"C","tiebreaker":"Eliminate what the scenario rules out","rationale":"The scenario deliberately rules out the two facts people reach for first: non-interactive mode is set and the output format is structured. What is left is authorization, and the correlation with larger diffs is the clue — a bigger change set reaches a tool the smaller ones never needed. In a non-interactive run there is nobody to approve that call, so it is denied and the run carries on without it. The first option describes a kill rather than a completed run, and the others would affect every run rather than the large ones.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Claude Code Configuration & Workflows. Verified against a primary source; see docs/VERIFICATION.md (hd-d3-02).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Run Claude Code programmatically (headless)","url":"https://code.claude.com/docs/en/headless","type":"docs"},{"title":"Claude Code CLI reference","url":"https://code.claude.com/docs/en/cli-reference","type":"docs"}],"note":null,"corroborated":[]},
{"id":"HARD-012","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d3"],"taskStatements":[],"objectives":[],"stem":"An organization needs a rule that engineers cannot disable: no AI-assisted commit may skip the pre-commit hooks. Where does it go, and why not the other layers?","options":[{"key":"A","text":"Committed project settings, because they live with the repository and anyone cloning it picks them up without being told at all.","explanation":"Committed settings travel with the repository, and anyone with commit access can edit them — which is exactly the person the rule constrains."},{"key":"B","text":"A hook in the repository, because hooks run in code, and enforcement in code is exactly what a non-negotiable rule requires.","explanation":"Right about the mechanism and wrong about the threat: a committed hook does enforce in code, but it lives in the repository the engineer can edit."},{"key":"C","text":"Project memory, because it loads into every single session, which is where the model will read the rule and then act on it.","explanation":"Project memory is read by the model as guidance, so it does not enforce anything, and it sits in the repository besides."},{"key":"D","text":"Managed settings, because every repository-level layer is editable by anyone with commit access, which is who the rule constrains.","explanation":"Correct. Managed settings sit outside the repository and cannot be edited locally, which is the only one of the four that holds against someone with commit access."}],"correct":"D","tiebreaker":"Enforce at the layer the adversary cannot edit","rationale":"The question names the adversary: an engineer in a hurry who can edit the repository. That eliminates the three repo-level answers, however well they enforce against the model. A committed hook does run in code — the second option is right about the mechanism and wrong about the threat, which is what makes it the hardest distractor here. Managed settings sit outside the repository and cannot be edited locally. Reserve that layer for the genuine non-negotiables; putting ordinary conventions there makes the configuration rigid and invites workarounds.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Claude Code Configuration & Workflows. Verified against a primary source; see docs/VERIFICATION.md (hd-d3-03).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code permissions","url":"https://code.claude.com/docs/en/permissions","type":"docs"}],"note":null,"corroborated":[]},
{"id":"HARD-013","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":[],"objectives":[],"stem":"A pipeline needs every response to match one JSON schema. A developer sets tool_choice to any with three tools declared, and still sees responses in two different shapes. Why?","options":[{"key":"A","text":"any permits a text answer when no tool fits, so the responses that differ are the ones where the model declined to call anything.","explanation":"This contradicts what any does: it requires that some tool is called, so a plain text answer is not among the outcomes."},{"key":"B","text":"any guarantees that some tool is called, not which one, so with three tools declared the output can match any of three schemas.","explanation":"Correct. any guarantees presence, not shape. With three tools declared the model still chooses which one, so the response can match any of three schemas; naming the tool pins it to one."},{"key":"C","text":"any applies only to the first turn of a conversation, so later turns revert to the default, where prose is a valid response.","explanation":"There is no first-turn restriction on tool_choice; it applies to the request it is set on."},{"key":"D","text":"any is advisory rather than binding, so a schema guarantee needs validation on the response, whatever the setting says.","explanation":"Validating the response is sound advice generally, but it does not explain the two shapes, which is what the question asks."}],"correct":"B","tiebreaker":"Presence is not shape","rationale":"The distinction between presence and shape is the whole question. any forces a tool call, so every response is a tool call — and with three tools available, which schema you get is still the model's choice. Naming the specific tool pins it to one. The first option contradicts what any means, and the third invents a turn restriction. The fourth is reasonable advice that does not explain the observed behavior, which is what was asked.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Prompt Engineering & Structured Output. Verified against a primary source; see docs/VERIFICATION.md (hd-d4-01).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Define tools (descriptions, tool_choice)","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools","type":"docs"}],"note":"Answer per the exam guide. The current docs list several newer models that reject tool_choice any and named-tool with a 400 error; the documented alternative there is auto with strict: true.","corroborated":[]},
{"id":"HARD-014","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":[],"objectives":[],"stem":"Cost is dominated by a 12,000-token system prompt sent on every request. Caching is enabled and the usage data shows cache_read_input_tokens at zero across requests that look identical. What should you check first?","options":[{"key":"A","text":"Whether the prompt clears the minimum cacheable length for the model in use, since a short prompt is silently not cached.","explanation":"A real cause of silent non-caching, but 12,000 tokens clears the minimum for every model, so the scenario rules it out."},{"key":"B","text":"Whether the five-minute lifetime is expiring between requests, since traffic that arrives in bursts can fall outside the window.","explanation":"Expiry produces intermittent reads — some hits, some misses — not zero across the board."},{"key":"C","text":"Whether anything before the breakpoint varies between requests, because the cache matches on an exact prefix hash.","explanation":"Correct. A cache entry is keyed on a hash of everything up to the breakpoint, so a timestamp, request id or reordered field anywhere in that span yields a new hash every time and nothing is ever reused."},{"key":"D","text":"Whether the requests are hitting different model versions, since a cache entry written by one version cannot be read by another.","explanation":"Possible in principle, but the scenario describes requests that look identical, and a version split would be visible in the request itself."}],"correct":"C","tiebreaker":"Root cause","rationale":"Zero reads across requests that look identical points at the prefix rather than the timing: a cache entry is a hash of everything up to the breakpoint, so a timestamp, a request id, or a reordered field anywhere in that span produces a different hash every time. The first option is a real cause of silent non-caching and 12,000 tokens clears every model's minimum, so the scenario rules it out. Expiry would show intermittent reads rather than none. Fix it by moving the breakpoint to the last genuinely identical block.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Prompt Engineering & Structured Output. Verified against a primary source; see docs/VERIFICATION.md (hd-d4-02).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Prompt caching","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-caching","type":"docs"}],"note":null,"corroborated":[]},
{"id":"HARD-015","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":[],"objectives":[],"stem":"A prompt places a 30,000-token document first, then the instruction, then the specific question. A reviewer argues the instruction should come first so the model knows what it is looking for while it reads. Assess.","options":[{"key":"A","text":"The current order is what the guidance recommends: long inputs near the top, with the query after them, which measurably improves quality on multidocument inputs.","explanation":"Correct. The documented guidance puts long-form data at the top with the query after it, and queries at the end measurably improve response quality on complex multidocument inputs."},{"key":"B","text":"The reviewer is right about this: an instruction read before the document frames what to extract, and that avoids a wasted second pass back over the same material.","explanation":"It is the intuitive reading, and the measured result goes the other way — which is why this is worth knowing rather than reasoning out."},{"key":"C","text":"Neither ordering matters much at this length, because the whole prompt is processed in a single pass rather than sequentially in the way that a human reader works.","explanation":"The prompt is processed in one pass, but position still affects how strongly content is weighted, so ordering is not neutral."},{"key":"D","text":"Both positions are wrong: at 30,000 tokens the document should be chunked and summarized before the question is put, whatever ordering is then settled on for the parts.","explanation":"Chunking solves a problem the scenario has not reported: 30,000 tokens fits comfortably, and the question is about ordering."}],"correct":"A","tiebreaker":"Measured beats intuitive","rationale":"This is a case where the intuitive answer and the measured one differ, which is why it is worth knowing rather than reasoning out. The documented guidance is to put long-form data at the top, above the query and instructions, and queries at the end have been found to improve response quality substantially on complex multidocument inputs. The third option is wrong in a subtle way — the prompt is processed at once, and position still affects how strongly content is weighted. The fourth solves a problem the scenario has not reported.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Prompt Engineering & Structured Output. Verified against a primary source; see docs/VERIFICATION.md (hd-d4-03).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Prompting best practices","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"HARD-016","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d5"],"taskStatements":[],"objectives":[],"stem":"A client retries on every failure with exponential backoff. Traffic is healthy but a tenth of requests now return 400 invalid_request_error after three retries each. What is wrong with the policy?","options":[{"key":"A","text":"Backoff is too aggressive: three retries with exponential delay takes long enough that later requests pile up behind the failing ones.","explanation":"The delay is not the issue; the request is rejected on its contents, so no amount of waiting changes the outcome."},{"key":"B","text":"The retries are hiding a capacity problem, and the 400s are the API's way of shedding load once the organization's limits are reached.","explanation":"Load shedding is a 429 or a 529. A 400 here is invalid_request_error on a tenth of requests, which points at the request contents; a spend limit can also return a 400, but it would reject every request, not one in ten."},{"key":"C","text":"Nothing is wrong with the policy; a 10% failure rate points at malformed requests from one caller and the policy is behaving correctly.","explanation":"Half right about the source and wrong about the policy: a malformed request from one caller is a bug to surface immediately, not to retry three times in silence."},{"key":"D","text":"A 400 here means the request itself is invalid, so retrying changes nothing: the same request fails identically three more times.","explanation":"Correct. A 400 means the request itself is wrong, so the same request fails identically on every retry — spending quota and delay to receive the same answer."}],"correct":"D","tiebreaker":"Retry only what can succeed","rationale":"Retry policy has to distinguish failures that may succeed later from failures that cannot. A 400 is the latter — the request is wrong, and sending it again spends quota and delay to receive the same answer. Transient codes such as 429 and 529 are what backoff is for. The second option confuses a 400 with a 429; a spend limit you set can also return a 400, but it would reject every request, not one in ten. The third is half-right about the source and draws the wrong conclusion: a malformed request from one caller is a bug to surface immediately, not something to retry quietly.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Context Management & Reliability. Verified against a primary source; see docs/VERIFICATION.md (hd-d5-01).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"API errors","url":"https://platform.claude.com/docs/en/api/errors","type":"docs"}],"note":null,"corroborated":[]},
{"id":"HARD-017","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":[],"objectives":[],"stem":"A synthesis step over a long aggregated input reliably reports findings from the first and last documents and misses the middle ones. The input fits the context window with room to spare. What is happening?","options":[{"key":"A","text":"The aggregation is silently truncating the middle documents, since the total is near enough to the limit that a boundary is being hit.","explanation":"Truncation would remove the middle documents entirely, and the scenario states the input fits with room to spare."},{"key":"B","text":"Material in the middle of a long prompt competes with everything around it, so content there carries less weight than at either end.","explanation":"Correct. Fitting the window is not the same as being weighted evenly across it: attention is uneven over a long prompt and the ends dominate, which is precisely the first-and-last pattern described."},{"key":"C","text":"The documents in the middle are being deduplicated against the first and last, so their distinct findings never reach the model.","explanation":"Deduplication would have to find the middle documents near-identical to the ends, and it would remove them rather than under-weight them."},{"key":"D","text":"The synthesis instruction is at the end, so the model has already formed its summary by the time it reads what to look for.","explanation":"The instruction at the end is the recommended placement, and the model does not form a summary before reading the rest of the prompt."}],"correct":"B","tiebreaker":"Root cause","rationale":"Fitting in the window is not the same as being weighted evenly within it: attention across a long prompt is uneven, and the ends dominate. The symptom here — first and last reported, middle dropped — is that effect almost exactly, which is why the scenario states the input fits. The first and third options propose mechanisms that would lose the content entirely rather than under-weight it. The fourth has the ordering backwards: the instruction at the end is the recommended placement.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Context Management & Reliability. Verified against a primary source; see docs/VERIFICATION.md (hd-d5-02).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"HARD-018","exam":"CCAR-F","set":"hard_tier","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d5"],"taskStatements":[],"objectives":[],"stem":"A long-running assistant is approaching its context limit. Three options are on the table: summarize the oldest turns, drop superseded tool results, or start a fresh session carrying forward the conclusions. How do you choose?","options":[{"key":"A","text":"Summarize, because it is the only one of the three that preserves the whole history in some form and so cannot lose anything that later turns out to matter.","explanation":"Summarizing everything spends effort preserving material that is genuinely superseded, and a summary degrades detail that pruning would have cost nothing to drop."},{"key":"B","text":"Start fresh, because every form of compaction degrades the material, and a clean session with the constraints restated is the most predictable state to be in.","explanation":"Restarting is right when the task has moved on, but applied to every case it throws away context the current work still depends on."},{"key":"C","text":"By what the remaining work needs: prune what is genuinely superseded first, summarize what must survive in outline and restart when the task itself has moved on.","explanation":"Correct. The three are not interchangeable: prune what is genuinely superseded, summarize what must survive in outline, and restart when the task itself has changed — the choice follows what the remaining work needs."},{"key":"D","text":"Drop the superseded tool results, because they are the largest consumer of window and removing them is lossless where the other two options are not.","explanation":"Right that pruning is the cheapest move and wrong to treat it as the whole answer; it only helps while something superseded remains to remove."}],"correct":"C","tiebreaker":"Fit the remedy to the need","rationale":"All three are legitimate and they are not interchangeable: superseded tool results can go at no cost, an argument you may need to revisit should be summarized rather than deleted, and a session whose task has genuinely changed is better restarted than compacted. The fourth option is right that pruning is the cheapest move and wrong to treat it as the whole answer, because it only helps while there is something genuinely superseded to remove. Choosing by what the remaining work needs is the judgment the question is testing.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026) — Context Management & Reliability. Verified against a primary source; see docs/VERIFICATION.md (hd-d5-03).","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-001","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.1"],"objectives":["O01"],"stem":"A developer builds an agentic loop that processes insurance claims. The loop exits when response.content[0].type == \"text\" is detected. In production, roughly 30% of claims stop prematurely — the agent returns a partial text summary without completing the required update_record and send_confirmation tool calls. The remaining 70% process correctly. What is the most likely root cause?","options":[{"key":"A","text":"The agent's system prompt lacks explicit instructions to keep processing once tool calls return a result.","explanation":"System prompts shape behaviour but don't control loop termination — the exit condition is in your code, and no wording change fixes a bad check."},{"key":"B","text":"The model is hitting its context limit on complex claims, truncating the tool_use block partway.","explanation":"A truncated response would come back with stop_reason max_tokens and would affect the largest claims, not a clean 30% that returns a well-formed partial summary."},{"key":"C","text":"Tool results aren't being appended to conversation history before the next turn, breaking the loop's state.","explanation":"If tool results were never appended, the loop would break on every tool-using claim, not 70% succeed; this is intermittent, not total."},{"key":"D","text":"The termination check compares content[0].type to \"text\" instead of stop_reason, exiting early when both appear together.","explanation":"Correct. Claude can emit text AND tool_use in the same response. Checking content[0].type catches the text block and exits while tool calls are still pending; stop_reason == \"end_turn\" is the only reliable signal."}],"correct":"D","tiebreaker":"Same stop_reason-vs-content[0] bug — if you see this setup, you barely need to read all four options.","rationale":"Claude can return text AND tool_use blocks in the same response — checking position, not stop_reason, causes false-positive exits. The correct check is stop_reason == \"end_turn\", which only fires when there are truly no pending tool calls. System prompts don't control loop logic; a context-limit issue would cause different symptoms; broken history would break ALL tool-using claims, not 30%.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.1 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Handling stop reasons","url":"https://platform.claude.com/docs/en/build-with-claude/handling-stop-reasons","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-002","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d5"],"taskStatements":["5.2"],"objectives":[],"stem":"An agent handling claims is supposed to escalate to a human when it can't resolve an issue. In practice it escalates inconsistently: some clearly-resolvable cases get escalated, and some genuinely stuck ones don't. The current logic asks the model to \"escalate if you sense the customer is frustrated or the issue seems complex.\" What's the correct fix?","options":[{"key":"A","text":"Add a second model call that re-evaluates whether escalation was correct once the conversation has already ended.","explanation":"Reviewing after the conversation has ended can't prevent the bad escalation — it diagnoses after the damage, and still leans on the same vague judgement."},{"key":"B","text":"Replace the vague guidance with explicit, concrete escalation criteria plus few-shot examples of borderline cases.","explanation":"Correct. Replacing \"sense the customer is frustrated\" with concrete criteria plus few-shot borderline examples gives the model a decidable test instead of a feeling."},{"key":"C","text":"Lower the threshold across the board so the agent escalates more often, treating caution as the safer default.","explanation":"Escalating more often trades one error for another: clearly-resolvable cases get escalated too, which is already half the reported problem."},{"key":"D","text":"Train a separate sentiment-analysis model to detect customer frustration more accurately before escalating.","explanation":"A better frustration detector still routes on sentiment. The defect is that escalation is keyed to mood rather than to stated, checkable conditions."}],"correct":"B","tiebreaker":"First Step Trap: Escalation calibration wrong → explicit criteria + few-shot. Always Wrong: sentiment-based escalation.","rationale":"Sentiment-based escalation is Always Wrong — \"sensing frustration\" is exactly that pattern, however it's implemented. The fix is always explicit criteria plus examples for ambiguous cases, not a better frustration detector or a blanket policy shift.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.2 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-003","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.2"],"objectives":["O04","O10"],"family":"decomposition-gap","stem":"An orchestrator agent splits a market research task across three subagents by topic. The final report is missing coverage of one entire sub-topic, even though all three subagents \"completed successfully.\" What's the most likely root cause?","options":[{"key":"A","text":"One subagent silently failed partway through and its output should simply be retried automatically.","explanation":"The subagents all reported success, and a silent partial failure would usually leave a truncated or empty section rather than a sub-topic nobody was assigned."},{"key":"B","text":"The orchestrator's task decomposition never assigned that sub-topic to any subagent, or left overlapping gaps.","explanation":"Correct. If no subagent was given that sub-topic, every one of them can succeed and the topic still never appears — the gap is in the orchestrator's decomposition."},{"key":"C","text":"The model needs a larger context window to hold all three subagents' outputs without losing detail.","explanation":"A context limit would truncate or degrade content that was gathered; it doesn't explain a sub-topic that was never researched at all."},{"key":"D","text":"Add a fourth subagent as a general safety net to catch whatever the first three might miss.","explanation":"A fourth subagent papers over the symptom without telling you why coverage was missed — and the same decomposition step would have to assign its work too."}],"correct":"B","tiebreaker":"First Step Trap: Coverage gaps in multi-agent → fix the coordinator's task decomposition.","rationale":"Coverage gaps in multi-agent systems are almost always a decomposition problem at the coordinator level, not an execution failure by any individual subagent. Adding a subagent (D) doesn't diagnose the gap; a bigger window (C) is unrelated to this symptom.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.2 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-004","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.6"],"objectives":["O07","O10"],"stem":"A team needs Claude to research three unrelated competitor products at once, with no subtopic depending on another's output, and results simply need to be combined into one report at the end. Which orchestration pattern is the best fit?","options":[{"key":"A","text":"Prompt chaining","explanation":"Chaining passes output forward through stages, which implies a dependency the stem explicitly rules out: no subtopic needs another's output."},{"key":"B","text":"Parallelization","explanation":"Correct. Three independent subtasks that run concurrently and are combined at the end is the definition of parallelization."},{"key":"C","text":"Evaluator-optimizer","explanation":"Evaluator-optimizer is a generate-then-critique loop on one piece of work, not a way to cover three unrelated products."},{"key":"D","text":"Routing","explanation":"Routing picks ONE path for a request. Here all three competitors must be covered, not chosen between."}],"correct":"B","tiebreaker":"Domain 1 core concept: parallelization vs chaining vs routing.","rationale":"Parallelization is the right fit whenever subtasks are independent and can run concurrently, with results combined at the end. Chaining implies sequential dependency that doesn't exist here; routing implies choosing ONE path, not covering all three.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.6 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-005","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.2"],"objectives":["O04","O10"],"stem":"You want Claude to draft marketing copy, then have a second pass critique and refine it before it goes out, repeating a couple of times if needed. Which pattern is this?","options":[{"key":"A","text":"Orchestrator-workers — a lead agent decomposes one task and delegates parts to workers.","explanation":"Orchestrator-workers splits one task into parts handled by different workers; here a single piece of copy is repeatedly refined, not decomposed."},{"key":"B","text":"Evaluator-optimizer — one agent generates output, another critiques it, repeating in a loop.","explanation":"Correct. One pass generates, a second critiques, and the cycle repeats — a genuine feedback loop is what defines evaluator-optimizer."},{"key":"C","text":"Parallelization — several subagents run concurrently and their results are aggregated.","explanation":"Nothing runs concurrently: the critique can only act on copy that already exists, so the steps are inherently ordered."},{"key":"D","text":"Prompt chaining — output passes forward through fixed stages with no feedback loop.","explanation":"Chaining is the closest distractor, but it is a one-way pass through fixed stages. The repeating critique here is the feedback loop chaining lacks."}],"correct":"B","tiebreaker":"Domain 1 core concept: evaluator-optimizer pattern.","rationale":"Evaluator-optimizer is exactly this: one agent generates, another critiques, and the loop repeats until quality is acceptable. Plain chaining (D) is close but misses the defining feature — a genuine feedback loop, not a one-way pass.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.2 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-006","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d1"],"taskStatements":["1.2"],"objectives":["O04","O10"],"stem":"A support system receives requests that fall into clearly distinct categories (billing, technical, legal), each best handled by a differently-configured agent. What pattern classifies the request and sends it to the right specialized agent?","options":[{"key":"A","text":"Routing — the request is classified and sent to a single specialized agent.","explanation":"Correct. Classifying a request into billing, technical or legal and sending it to one specialized agent is exactly routing."},{"key":"B","text":"Parallelization — several subagents run concurrently and their results are aggregated.","explanation":"Parallelization would run every specialist on every request and aggregate the results — wasteful when the categories are already distinct."},{"key":"C","text":"Evaluator-optimizer — one agent generates output, another critiques it in a loop.","explanation":"Evaluator-optimizer refines one output through critique; it offers no mechanism for choosing between specialized handlers."},{"key":"D","text":"Orchestrator-workers — a lead agent decomposes one task across multiple workers.","explanation":"Orchestrator-workers decomposes a single task across several workers at once. Here one request needs one specialist, not a split."}],"correct":"A","tiebreaker":"Domain 1 core concept: routing pattern.","rationale":"Routing is specifically the pattern of classifying input and directing it to one of several specialized downstream paths. Orchestrator-workers implies a lead agent decomposing ONE task across MULTIPLE subagents at once — different from choosing a single path.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.2 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-007","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.5"],"objectives":[],"stem":"You've instructed your loan underwriting agent in its system prompt to always run a validation tool before marking an application complete. Audit logs show it skips validation roughly 8% of the time. What is the most reliable fix?","options":[{"key":"A","text":"Repeat the validation instruction more emphatically and earlier in the system prompt.","explanation":"Emphasis and placement still leave the instruction probabilistic — an 8% skip rate is what \"usually follows instructions\" looks like in production."},{"key":"B","text":"Add a PreToolUse hook on the completion step that blocks it until validation has run.","explanation":"Correct. \"Must always happen\" calls for deterministic enforcement: a PreToolUse hook on the completion call blocks it until validation has actually run, regardless of what the model decides."},{"key":"C","text":"Increase temperature so the model attends more broadly to the full set of instructions.","explanation":"Raising temperature makes sampling more random, not more obedient; if anything it increases the skip rate."},{"key":"D","text":"Add a second reminder message immediately before the final step of the task.","explanation":"A second reminder is still a prompt. It lowers the failure rate without removing it, and the requirement here is a guarantee."}],"correct":"B","tiebreaker":"First Step Trap: Workflow compliance needed → programmatic enforcement (hooks).","rationale":"'Must always happen' is the signal for hooks, not stronger prompting — instructions are probabilistic, hooks are deterministic. The other options are all still prompt-based and will still fail some percentage of the time.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.5 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code hooks reference","url":"https://code.claude.com/docs/en/hooks","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-008","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.1"],"objectives":["O01"],"stem":"An agent calls a lookup tool, receives a valid result, but the model's next response acts as if the tool was never called — it asks the same question again. The tool itself works fine in isolation. What's the most likely cause?","options":[{"key":"A","text":"The tool result was never appended to conversation history before the next API call, so the model never saw it.","explanation":"Correct. The loop only works if each tool_result is appended to the conversation before the next call — without that, the model genuinely never saw the result and asks again."},{"key":"B","text":"The model's context window is already full from earlier turns, pushing the tool result out of scope.","explanation":"A full context window would surface as errors or degraded recall across the whole conversation, not one tool result vanishing while the tool works fine."},{"key":"C","text":"The tool's description is unclear about when to call it, so the model discounts the result it gets back.","explanation":"A vague description affects whether the tool gets called, not whether a returned result is visible — and the model did call it."},{"key":"D","text":"The system prompt has grown too long to process reliably, crowding out the returned tool result.","explanation":"A long system prompt doesn't selectively erase a tool result; the result was never in the request to begin with."}],"correct":"A","tiebreaker":"Domain 1 core concept: tool_result must be appended to history before the next turn.","rationale":"The agentic loop only works if each tool_result is appended to the conversation before the next turn — skip that, and the model has no memory the call ever happened. The other options would produce different symptoms — this is specifically a loop-plumbing bug.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.1 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Tool use with Claude","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/overview","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-009","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.5"],"objectives":[],"stem":"Your e-commerce returns agent has access to a delete_record tool. Rarely, it calls it inappropriately — for example, when a return request should have been flagged for review instead of removed. What's the most reliable safeguard?","options":[{"key":"A","text":"Remove the delete_record tool entirely and require every deletion to be done manually instead.","explanation":"Removing the tool removes the capability the agent needs. The goal is to make deletion safe, not impossible."},{"key":"B","text":"Add a PreToolUse hook that requires explicit confirmation criteria before delete_record can execute.","explanation":"Correct. A PreToolUse hook gates the call before it executes, turning \"should rarely do this\" into a checkable precondition the model cannot bypass."},{"key":"C","text":"Add a stronger warning sentence to the tool's description explaining the risk of misuse.","explanation":"A warning in the description is advice the model weighs probabilistically — the same mechanism that already failed."},{"key":"D","text":"Lower the model's temperature so it behaves more conservatively around destructive operations.","explanation":"Lower temperature narrows sampling but offers no guarantee about a destructive call; \"more conservative on average\" is not a safeguard."}],"correct":"B","tiebreaker":"Domain 1 core concept: PreToolUse hooks gate risky actions before execution.","rationale":"A PreToolUse hook can gate a risky action deterministically before it runs — exactly right for 'sometimes does something destructive it shouldn't.' The description/temperature options are still probabilistic; removing the tool removes needed capability instead of adding safe control.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.5 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code hooks reference","url":"https://code.claude.com/docs/en/hooks","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-010","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d1"],"taskStatements":["1.7"],"objectives":["O02","O09"],"stem":"You want to explore three different strategies for solving the same coding problem, without any of the three conversations' context bleeding into the others, then compare results side by side. What capability is designed for this?","options":[{"key":"A","text":"Prompt caching — repeated context prefixes are cached to cut cost and latency across the attempts.","explanation":"Caching reuses a shared prefix to cut cost and latency. It says nothing about keeping three lines of work isolated."},{"key":"B","text":"Session forking — the conversation branches into isolated paths that can't contaminate each other.","explanation":"Correct. Forking branches the conversation into separate paths, which is precisely the isolation needed to compare three strategies without cross-contamination."},{"key":"C","text":"A larger context window — more room so all three attempts fit in one conversation.","explanation":"A bigger window lets the attempts coexist — which is the problem. They would still see each other and bleed context."},{"key":"D","text":"Sectioned prompting — all three attempts share one conversation, separated by clear headers.","explanation":"Headers are a convention inside one shared context; the model can still read across them, so the attempts are not independent."}],"correct":"B","tiebreaker":"Domain 1 core concept: session forking for isolated parallel exploration.","rationale":"Session forking exists exactly for this: branching into isolated paths so different approaches don't contaminate each other's context. Running all three in one conversation (D) would let context bleed between attempts, defeating the purpose.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.7 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Agent SDK: sessions (resume and fork)","url":"https://code.claude.com/docs/en/agent-sdk/sessions","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-011","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.7"],"objectives":["O02","O09"],"stem":"A long-running agent task completes 40 of 50 steps successfully before failing. Restarting the entire task from step 1 is expensive and slow. What capability would have avoided losing that progress?","options":[{"key":"A","text":"Prompt caching — repeated context prefixes are cached to cut cost and latency on each step.","explanation":"Caching reduces the cost of re-sending a prefix but stores no task state, so a restart still redoes all 40 steps of work."},{"key":"B","text":"Checkpointing — task state is saved at intervals so a failure doesn't lose prior progress.","explanation":"Correct. Checkpointing persists state at intervals, so a failure at step 41 resumes from the last checkpoint instead of step 1."},{"key":"C","text":"A shorter system prompt — less per-step overhead, leaving more budget for the task itself.","explanation":"A shorter prompt trims per-step overhead; it does nothing to preserve progress when the run fails."},{"key":"D","text":"Parallelization — the fifty steps are split across concurrent subagents to shorten the run.","explanation":"Parallelization may shorten the run, but a failure still loses whatever wasn't saved — the gap is persistence, not speed."}],"correct":"B","tiebreaker":"Domain 1 core concept: checkpointing preserves progress across long-running tasks.","rationale":"Checkpointing is specifically for saving/restoring state at points in time, so failures don't cost all prior progress. Prompt caching reduces cost/latency on repeated prefixes but doesn't preserve task progress state.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.7 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-012","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.2"],"objectives":["O04","O10"],"stem":"A complex intake form needs a legal check, a financial check, and a compliance check all performed on it before it can proceed. What's the best-fit architecture?","options":[{"key":"A","text":"A single agent with a very long system prompt covering all three areas.","explanation":"One prompt covering legal, financial and compliance dilutes attention across three specialities and tends to do all three less well."},{"key":"B","text":"A hub-and-spoke design, with a coordinator over three specialized checks.","explanation":"Correct. Hub-and-spoke puts a coordinator over three specialized checks, which is the shape of one item needing several areas of expertise brought back together."},{"key":"C","text":"Three completely separate, unconnected pipelines.","explanation":"Unconnected pipelines produce three results with nothing reconciling them, and no single place decides whether the item may proceed."},{"key":"D","text":"Prompt chaining, running the checks strictly one after another.","explanation":"Chaining forces an order the problem doesn't have: the three checks are independent, so making each wait on the last adds latency for nothing."}],"correct":"B","tiebreaker":"Domain 1 core concept: hub-and-spoke / orchestrator-workers pattern.","rationale":"Hub-and-spoke (orchestrator-workers) is the right shape when one task genuinely needs multiple areas of specialized handling coordinated together. A single long prompt tends to dilute quality across all three areas; forcing strict sequential chaining adds an artificial dependency that doesn't need to exist.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.2 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-013","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.2"],"objectives":["O04","O10"],"stem":"A single long-running conversation handles a main task plus several unrelated side-lookups, and overall response quality is degrading as the conversation grows. What's the most likely fix?","options":[{"key":"A","text":"Increase max_tokens so the conversation has more room before quality starts to degrade.","explanation":"max_tokens caps the length of a reply. It has no bearing on quality degrading as unrelated content accumulates."},{"key":"B","text":"Delegate the side-lookups to isolated subagents so their context doesn't pollute the main conversation.","explanation":"Correct. Moving side-lookups into isolated subagents keeps their content out of the main thread, which is what's diluting attention."},{"key":"C","text":"Ask the model to periodically summarize itself, with no other structural change to the setup.","explanation":"Periodic self-summarizing shortens the transcript but keeps the unrelated material in the same context, so the pollution remains."},{"key":"D","text":"Switch to a model with a larger context window so the accumulated side content fits comfortably.","explanation":"A larger window lets more clutter fit. The problem is attention spread across irrelevant content, not a hard capacity limit."}],"correct":"B","tiebreaker":"Always/Usually Wrong: larger context window doesn't fix attention dilution.","rationale":"Context isolation — pushing side-tasks into their own subagent context — keeps the main conversation focused and avoids degradation from accumulated unrelated content. A bigger window repeats the Usually Wrong pattern: it doesn't fix attention dilution from clutter.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.2 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-014","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.1"],"objectives":["O01"],"stem":"A developer makes one Messages API call with tools attached, gets back a tool_use block, and calls that the finished feature — no code executes the tool or sends the result back. Is this an agent?","options":[{"key":"A","text":"Yes — attaching tools to a call is what makes it agentic, no matter what happens next.","explanation":"Attaching tools only makes tool use possible. Nothing has executed and nothing has been returned, so no agentic step occurred."},{"key":"B","text":"No — a single call with no loop that executes the tool and returns the result isn't agentic.","explanation":"Correct. The agentic part is the loop — execute the tool, return a tool_result, let the model continue. One call that stops at tool_use is a request for action nobody carried out."},{"key":"C","text":"Yes — provided tool_choice is explicitly set to \"auto\" so the model retains the decision.","explanation":"tool_choice governs whether the model may pick a tool; it doesn't execute anything or close the loop."},{"key":"D","text":"No — it would only count as agentic if the work were delegated to a subagent somewhere.","explanation":"Subagents are one pattern built on agentic loops, not a requirement. A single-agent loop is still an agent."}],"correct":"B","tiebreaker":"Domain 1 core concept: the agentic loop, not tool attachment alone, defines an agent.","rationale":"What makes something 'agentic' is the loop — execute the tool, return the result, let the model continue — not merely the presence of tool definitions in one call. Requiring a subagent (D) overstates the bar; subagents are one pattern within agentic systems, not a requirement for the basic definition.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.1 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Tool use with Claude","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/overview","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-015","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.5"],"objectives":[],"stem":"A lookup tool in your IT helpdesk pipeline sometimes returns dates as \"2024-01-05\" and sometimes as \"Jan 5, 2024\" depending on the source system, and downstream steps that expect one format keep failing. Where should the fix go?","options":[{"key":"A","text":"A PostToolUse hook that normalizes the tool's output into one consistent format before it re-enters context.","explanation":"Correct. PostToolUse runs on the tool's output, so it can normalize both date shapes into one format deterministically before anything downstream sees it."},{"key":"B","text":"A stronger prompt asking the model to reformat the dates itself before responding.","explanation":"Asking the model to reformat makes a data contract depend on model behaviour — it will mostly work, which is why the failures are intermittent."},{"key":"C","text":"A PreToolUse hook that blocks the lookup tool from running until its output contract has been validated.","explanation":"PreToolUse fires before execution, when no output exists yet, so it cannot fix the shape of a result."},{"key":"D","text":"Increase the model's max_tokens so it has enough room to restate and reformat the fields consistently.","explanation":"max_tokens is about response length. The two formats are both short; nothing is being truncated."}],"correct":"A","tiebreaker":"Domain 1 core concept: PostToolUse hooks normalize inconsistent tool output.","rationale":"PostToolUse hooks are exactly for normalizing/validating a tool's raw output before it flows further — deterministic cleanup, not relying on the model to notice and fix formatting. PreToolUse runs before execution and can't fix output shape; asking the model to reformat is probabilistic and unreliable for a formatting guarantee.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.5 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code hooks reference","url":"https://code.claude.com/docs/en/hooks","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-016","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.2"],"objectives":["O04","O10"],"stem":"Three subagents each independently review the same contract clause for risk and return different risk ratings. What should the architecture include to handle this well?","options":[{"key":"A","text":"Take the first subagent's rating as authoritative and discard the two that disagreed with it.","explanation":"Taking the first rating treats arrival order as authority and throws away two genuine signals, including possibly the correct one."},{"key":"B","text":"An aggregation/reconciliation step that reviews the disagreement and produces a final decision.","explanation":"Correct. Independent reviewers can legitimately disagree, so parallel work needs an explicit step that reconciles conflicting ratings into one decision."},{"key":"C","text":"Re-run all three subagents on the same document until their independent ratings happen to converge.","explanation":"Re-running until three independent reviews happen to agree burns cost waiting on chance, and convergence wouldn't mean correctness."},{"key":"D","text":"Reduce to a single reviewing subagent, so conflicting ratings can no longer arise in the first place.","explanation":"Dropping to one reviewer hides the disagreement rather than resolving it, losing the cross-check that made three reviews worthwhile."}],"correct":"B","tiebreaker":"Domain 1 core concept: parallelization requires a real aggregation step.","rationale":"Parallelization needs an explicit aggregation step for exactly this reason — independent runs can disagree, and silently picking one discards signal. Removing subagents avoids the problem rather than resolving it; blind re-running just adds cost without addressing the disagreement.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.2 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-017","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d5"],"taskStatements":["5.2"],"objectives":[],"stem":"A tool call in your HR onboarding pipeline fails validation repeatedly. The agent retries the same failing step indefinitely rather than escalating to a human. What's missing?","options":[{"key":"A","text":"A retry limit is fine as-is; the real fix is a faster tool.","explanation":"A faster tool fails faster. The loop still retries forever, because nothing defines when to stop trying."},{"key":"B","text":"An explicit escalation trigger","explanation":"Correct. Retries need a ceiling plus a defined handoff: without an escalation trigger, a permanently failing step loops indefinitely and no human ever sees it."},{"key":"C","text":"A longer system prompt asking it to \"try harder.\"","explanation":"\"Try harder\" is a prompt change against a deterministic validation failure — the retry will fail identically."},{"key":"D","text":"A bigger context window so it remembers more failed attempts.","explanation":"Remembering more failed attempts doesn't create a rule for abandoning them; the missing piece is the exit condition."}],"correct":"B","tiebreaker":"Domain 5 core concept: explicit escalation criteria, not open-ended retry.","rationale":"Retries need a ceiling paired with an explicit escalation trigger — infinite retry with no handoff path is a reliability failure by itself. Neither a longer prompt nor a bigger window addresses the missing escalation logic.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.2 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-018","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O05"],"stem":"A subagent is meant to do private intermediate work and only return a final summary to the orchestrator. Instead, its raw intermediate reasoning ends up quoted in the user-facing final answer. What's the most likely architectural gap?","options":[{"key":"A","text":"The subagent's full output is being passed into the orchestrator's context instead of just its final result.","explanation":"Correct. Isolation only holds if the boundary is enforced when results are passed back — handing the orchestrator the subagent's full output puts its private reasoning in scope to be quoted."},{"key":"B","text":"The subagent needs a larger context window so its private reasoning never spills past its own boundary.","explanation":"A larger window changes how much the subagent can hold, not what it returns. The leak is in what crosses the boundary."},{"key":"C","text":"The orchestrator's system prompt needs more detail about which parts of a subagent reply to ignore.","explanation":"Telling the orchestrator which parts to ignore is probabilistic filtering of content that should never have been passed in."},{"key":"D","text":"Subagents can never be trusted with private reasoning, so this whole pattern is flawed.","explanation":"The pattern is sound and widely used; this is an implementation gap in how results are returned, not a flaw in context isolation."}],"correct":"A","tiebreaker":"Domain 1 core concept: enforce the boundary on what a subagent actually returns.","rationale":"Context isolation only works if the boundary between a subagent's private work and its returned output is actually enforced when passing results back — otherwise everything leaks through. Throwing out the pattern (D) overreacts to an implementation gap, not a flaw in the pattern itself.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.3 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-019","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.6"],"objectives":["O07","O10"],"stem":"A single prompt asks Claude to research a topic, draft a report, and then edit that same draft, all in one response. Output quality is noticeably worse than when these were tested as separate steps. What's the likely fix?","options":[{"key":"A","text":"Prompt chaining — the three stages run as separate, sequential calls.","explanation":"Correct. Research, drafting and editing are three different cognitive modes; splitting them into sequential calls lets each run with its own focus and the previous stage's output as clean input."},{"key":"B","text":"A longer single prompt — far more detail supplied about all three steps at once.","explanation":"More detail in one prompt still asks for all three modes in a single response — the usual result is that each gets less attention, not more."},{"key":"C","text":"A bigger context window — more room for research, draft, and edit in one response.","explanation":"A bigger window addresses room, and the stem reports a quality problem, not truncation."},{"key":"D","text":"Best-of sampling — the same three-in-one request is run twice and the better result kept.","explanation":"Best-of sampling picks the better of two flawed attempts. It raises cost without fixing the structure that caused the quality drop."}],"correct":"A","tiebreaker":"Domain 1 core concept: prompt chaining for sequential, dependent steps.","rationale":"Prompt chaining exists exactly for this: sequential, dependent steps often perform better broken apart than crammed into one response. Neither a longer prompt nor a bigger window addresses asking for three distinct cognitive modes at once.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.6 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-020","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.1"],"objectives":["O01"],"family":"stop-reason-truncation","stem":"An agent's response is cut off mid-sentence because it hit the token limit, but the calling code proceeds as if the response were complete. What should the code have checked?","options":[{"key":"A","text":"Whether stop_reason equals \"max_tokens\", signalling the response was truncated.","explanation":"Correct. stop_reason == \"max_tokens\" is the explicit signal that generation was cut short, so the code can continue, retry with more room, or surface the truncation."},{"key":"B","text":"Whether the returned text string exceeds an expected character length.","explanation":"A character-length threshold is a guess about where the limit fell; tokens and characters don't correspond, so it misclassifies both ways."},{"key":"C","text":"Whether the response text happens to end with sentence-ending punctuation.","explanation":"Trailing punctuation is a heuristic a truncated response can satisfy by chance, and a complete response can fail — it's unreliable in both directions."},{"key":"D","text":"Whether the content array contains more than one block of any type.","explanation":"Block count says what kinds of content came back, not whether generation finished."}],"correct":"A","tiebreaker":"Domain 1 core concept: check stop_reason, don't infer completion from text shape.","rationale":"stop_reason == \"max_tokens\" is the explicit signal that the response was cut off, not finished — code should branch on this rather than assuming completion. Character counts, trailing punctuation and block counts are all guesses from the shape of the text.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.1 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Handling stop reasons","url":"https://platform.claude.com/docs/en/build-with-claude/handling-stop-reasons","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-021","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.2"],"objectives":["O04","O10"],"stem":"A subagent given the broad goal \"improve code quality\" starts making unrelated architectural changes far outside what the orchestrator intended for that task. What's the most likely fix?","options":[{"key":"A","text":"Give the subagent a much larger context window so it \"understands the full picture\" before acting.","explanation":"A larger window gives more room to roam. Nothing about extra capacity narrows a goal that was stated too broadly."},{"key":"B","text":"Scope the subagent's task more narrowly and explicitly, rather than delegating a broad, vague goal.","explanation":"Correct. \"Improve code quality\" permits almost any change, so the subagent isn't misbehaving — it's doing what it was asked. Narrowing the brief is the direct fix."},{"key":"C","text":"Remove the subagent's tool access so it is structurally unable to act outside its intended area.","explanation":"Removing tool access stops the subagent doing its job at all, trading scope creep for no capability."},{"key":"D","text":"Add further subagents so the work is spread out and no single one drifts far from its brief.","explanation":"More subagents sharing the same vague goal multiplies the drift rather than containing it."}],"correct":"B","tiebreaker":"Domain 1 core concept: narrow, explicit task scoping prevents subagent scope creep.","rationale":"Broad, underspecified goals invite scope creep — narrowing and specifying the actual task is the direct fix, not adding capacity or removing tools. Neither a bigger window nor more subagents addresses the actual root cause: task specification.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.2 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-022","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.1"],"objectives":["O36"],"stem":"A customer support agent has two tools: search_kb(query), described as \"Search the knowledge base,\" and search_orders(query), described as \"Search order records.\" When users ask about order status, the model frequently calls search_kb instead. What should be fixed first?","options":[{"key":"A","text":"Add a routing layer that inspects the request and pre-selects the correct tool before the agent runs.","explanation":"A routing layer adds a component to work around unclear descriptions. Fix the descriptions first — the layer then has nothing left to correct."},{"key":"B","text":"Rewrite the tool descriptions with concrete trigger conditions and examples, so each tool's scope is unambiguous.","explanation":"Correct. Tool misrouting is nearly always a description problem — unambiguous scopes with examples fix the model's choice at the source."},{"key":"C","text":"Increase the model's temperature so it explores tool options more broadly instead of fixating on one.","explanation":"Higher temperature adds randomness to an already-wrong choice; it doesn't teach the model which tool fits."},{"key":"D","text":"Force both tools via tool_choice so the model cannot skip the one it should have been calling.","explanation":"Forcing both tools runs the wrong one too, and the task is to choose correctly between them, not to call everything."}],"correct":"B","tiebreaker":"First Step Trap: Tool misrouting → improve tool descriptions.","rationale":"Tool misrouting is a description problem in the overwhelming majority of cases — vague or overlapping descriptions leave the model guessing. Adding a routing layer is infrastructure-before-descriptions; forcing tool_choice doesn't even make sense when the model must choose between two tools based on the query.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.1 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Define tools (descriptions, tool_choice)","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-023","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d2"],"taskStatements":["2.4"],"objectives":["O34","O35"],"stem":"An MCP server exposes a company style guide as a Resource, and a submit_ticket function as a Tool. A developer is confused: the model references the style guide content in its answers, but there's no tool_use block for it, while submit_ticket clearly generates one. Why?","options":[{"key":"A","text":"The style guide's content is too brief to meet the threshold that would trigger a tool invocation.","explanation":"There is no length threshold governing invocation. Resources are never invoked regardless of size."},{"key":"B","text":"Resources are context for the model to read; only Tools are actively invoked via a tool_use block.","explanation":"Correct. In MCP, Resources are context the model reads and Tools are actions it invokes — so only submit_ticket produces a tool_use block."},{"key":"C","text":"The MCP server is misconfigured, and the style guide should instead be redefined as a Tool.","explanation":"Nothing is misconfigured: a style guide is reference material, which is exactly what a Resource is for."},{"key":"D","text":"The model is limited to using only one type, Resource or Tool, per conversation.","explanation":"MCP places no such limit; a conversation can use Resources and Tools together, as this one does."}],"correct":"B","tiebreaker":"Domain 2 core concept: Resources vs. Tools.","rationale":"This is the core Resource vs. Tool distinction in MCP: Resources are context, Tools are actions the model actively invokes. The other options all describe non-issues — nothing here is misconfigured or limited; it's working exactly as designed.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.4 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code MCP documentation (scopes, .mcp.json, ${VAR} expansion, @ resources, /mcp)","url":"https://code.claude.com/docs/en/mcp","type":"docs"}],"note":"Answer per the exam guide. How a resource reaches the model depends on the client: in Claude Code, resources are attached when referenced with an @ mention, and Claude can otherwise list and read them through built-in resource tools.","corroborated":[]},
{"id":"REF-024","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.1"],"objectives":["O36"],"stem":"Which sequence correctly describes the tool-call flow in the Messages API?","options":[{"key":"A","text":"The model calls the tool directly → the tool executes on the model's behalf → the response is returned straight through to the user.","explanation":"The model cannot execute anything. It can only ask, by returning a tool_use block for your code to act on."},{"key":"B","text":"Define tools, send the request → model returns a tool_use block → your code executes it and returns a tool_result → model continues.","explanation":"Correct. Define tools, the model returns tool_use, your code executes it and sends back a tool_result, and the model continues from there."},{"key":"C","text":"Send the request → the model returns final text → your code optionally calls tools afterward and appends the results if needed.","explanation":"Tools called after the model has already produced final text can't inform that text — the loop exists so results feed back before the answer."},{"key":"D","text":"Define the tools → the API executes them server-side automatically → you receive only the final text.","explanation":"The Messages API does not run the tools you define; your code executes them. (Anthropic's own server tools, such as web search, are the exception and are not what this flow describes.)"}],"correct":"B","tiebreaker":"Domain 2 core concept: the 5-step tool call flow.","rationale":"For the tools you define, the API never executes anything — your code runs the tool and returns a tool_result block for the model to continue from. Options A and D imply the tool runs without your code; option C calls tools only after the answer is already written.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.1 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Tool use with Claude","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/overview","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-025","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.3"],"objectives":["O05","O27","O33","O37"],"stem":"You want to guarantee the model calls at least one of several available tools, but you don't want to force a specific one. Which tool_choice setting fits?","options":[{"key":"A","text":"tool_choice: auto — the model decides freely whether to call a tool at all.","explanation":"auto permits the model to answer with no tool at all, which fails the \"at least one\" requirement."},{"key":"B","text":"tool_choice: any — the model must call some tool, but chooses which one.","explanation":"Correct. any compels some tool call while leaving the choice of which to the model — exactly the stated requirement."},{"key":"C","text":"tool_choice: tool — the model is forced to call one specific named tool.","explanation":"Naming a specific tool over-constrains it: the requirement is that some tool runs, not a particular one."},{"key":"D","text":"tool_choice: none — the model is prevented from calling any tool.","explanation":"none forbids tool use outright, the opposite of what's wanted."}],"correct":"B","tiebreaker":"Domain 2 core concept: tool_choice modes — auto / any / tool / none.","rationale":"any forces some tool use without pinning down which specific tool — exactly this requirement. tool forces one named tool specifically; auto leaves it fully up to the model, including not using a tool at all.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.3 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Define tools (descriptions, tool_choice)","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools","type":"docs"}],"note":"Answer per the exam guide. The current docs list several newer models that reject tool_choice any and named-tool with a 400 error; the documented alternative there is auto with strict: true.","corroborated":[]},
{"id":"REF-026","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.2"],"objectives":[],"stem":"A payment-lookup tool fails due to a timeout. What should the tool_result returned to the model include, at minimum, so it can make a good decision about what to do next?","options":[{"key":"A","text":"An empty result, so the model is left to infer that something went wrong.","explanation":"An empty result is ambiguous — the model can read it as \"no records found\" and answer confidently that there are no payments."},{"key":"B","text":"A structured error (is_error: true) with a clear, specific message describing what failed and why.","explanation":"Correct. is_error: true with a specific message tells the model what failed, so it can retry, escalate or explain rather than guess."},{"key":"C","text":"A generic \"error\" string, signalling failure without committing to a specific cause the model might misread.","explanation":"A bare \"error\" string signals failure but withholds the cause, so the model can't tell a timeout worth retrying from a permanent one."},{"key":"D","text":"The last successful result from a previous call, so the conversation isn't visibly interrupted.","explanation":"Returning a previous call's result feeds the model stale data as if current — a wrong answer presented confidently."}],"correct":"B","tiebreaker":"Always Wrong: return empty as success — applies equally to vague/empty error handling.","rationale":"A specific, structured error gives the model something to actually reason about — retry, escalate, or ask for clarification. An empty result is Always Wrong (empty ≠ success, and it's ambiguous here too); returning stale data actively feeds the model false information.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.2 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Tool use with Claude","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/overview","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-027","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.4"],"objectives":["O34","O35"],"stem":"You're integrating an MCP server that runs as a local process alongside your CLI tool, and separately, one that's a remote hosted service you connect to over the network. Which transports fit each, respectively?","options":[{"key":"A","text":"Streamable HTTP for the local one, stdio for the remote one.","explanation":"This inverts the two: stdio has no network layer for reaching a remote host, and HTTP adds a needless hop for a local child process."},{"key":"B","text":"stdio for the local one, Streamable HTTP for the remote one.","explanation":"Correct. stdio suits a local process communicating over standard streams; Streamable HTTP is MCP's transport for servers reached over a network."},{"key":"C","text":"Both should always use stdio, regardless of where the server actually runs.","explanation":"stdio can't reach a remote hosted service — there is no process on the local machine to pipe to."},{"key":"D","text":"Both should always use Streamable HTTP, regardless of where the server actually runs.","explanation":"HTTP for a local co-process adds network setup and overhead where a direct pipe already works."}],"correct":"B","tiebreaker":"Domain 2 core concept: MCP transports — stdio (local) vs HTTP/SSE (remote).","rationale":"stdio suits a local process with no network hop; Streamable HTTP (MCP's current remote transport, superseding the older HTTP+SSE naming) suits a server reached over the network. Using the same transport for both regardless of deployment location ignores the actual constraint each one solves.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.4 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code MCP documentation (scopes, .mcp.json, ${VAR} expansion, @ resources, /mcp)","url":"https://code.claude.com/docs/en/mcp","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-028","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.1"],"objectives":["O36"],"stem":"A team has get_customer_profile and get_customer_orders as two distinct tools, each doing one clearly different thing well. A developer proposes merging them into a single get_customer_data tool to \"reduce tool count.\" Is this the right move?","options":[{"key":"A","text":"Yes — fewer tools is reliably better, so distinct tools should be merged wherever possible.","explanation":"\"Fewer tools is reliably better\" overstates it. Merging genuinely distinct tools creates one vague tool the model must disambiguate at call time."},{"key":"B","text":"Not necessarily — merging helps for genuinely overlapping tools, but these have clear separate purposes.","explanation":"Correct. Consolidation helps when tools overlap or have fuzzy boundaries; these two have clear separate purposes, so merging trades clarity for a smaller count."},{"key":"C","text":"Yes — models handle only a small number of tools well, so tool count should always be minimized.","explanation":"Modern models handle sizeable tool sets; two well-described tools are not the problem this fix imagines."},{"key":"D","text":"No — tools should never be merged, since every capability belongs in its own separate definition.","explanation":"\"Never merge\" is equally absolute — merging is the right call precisely when boundaries are genuinely blurred."}],"correct":"B","tiebreaker":"Usually Wrong: consolidating tools that are actually distinct.","rationale":"Consolidating tools that are actually distinct is on the Usually Wrong list — it's only a good move for genuinely overlapping/fuzzy-boundary tools. The blanket 'always' and 'never' framings in the other options both overstate a rule that doesn't hold universally.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.1 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-029","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.3"],"objectives":["O05","O27","O33","O37"],"stem":"A compliance workflow requires that every request result in a call to log_compliance_event, with no other tool called instead. What's the most reliable way to guarantee this in a single turn?","options":[{"key":"A","text":"Ask nicely in the system prompt to \"always call log_compliance_event.\"","explanation":"A system-prompt request is followed most of the time, and \"every request\" admits no exceptions."},{"key":"B","text":"Set tool_choice to force that specific tool for that turn.","explanation":"Correct. Forcing tool_choice to log_compliance_event for that turn guarantees the call at the API level rather than relying on the model to comply."},{"key":"C","text":"Give the model only one tool option ever, for every turn of the conversation.","explanation":"Restricting the model to one tool forever breaks every other turn that needs a different tool."},{"key":"D","text":"Add a PostToolUse hook that checks after the fact and complains if it wasn't called.","explanation":"A PostToolUse hook detects the omission after the fact; the requirement is that the call happens, not that misses are reported."}],"correct":"B","tiebreaker":"Domain 2 core concept: force tool_choice for guaranteed single-tool execution.","rationale":"Forcing tool_choice to a specific tool is the deterministic way to guarantee that exact tool gets called on that turn. Asking nicely is probabilistic; a single-tool-forever restriction breaks other turns that need different tools; catching it after the fact doesn't prevent the problem.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.3 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Define tools (descriptions, tool_choice)","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools","type":"docs"}],"note":"Answer per the exam guide. The current docs list several newer models that reject tool_choice any and named-tool with a 400 error; the documented alternative there is auto with strict: true.","corroborated":[]},
{"id":"REF-030","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.2"],"objectives":[],"stem":"A create_ticket tool's input schema marks \"priority\" as optional. In practice, tickets created without a priority cause downstream failures. What's the cleanest fix at the tool-design level?","options":[{"key":"A","text":"Add a note in the system prompt gently asking the model to \"always include priority\" going forward.","explanation":"A prompt note leaves the field optional in the schema, so a valid call can still omit it and break downstream."},{"key":"B","text":"Mark \"priority\" as a required field in the schema, with a description of valid values.","explanation":"Correct. Marking priority required puts the requirement in the tool's contract, where the model reads it on every call, instead of in a prompt note it may not weigh."},{"key":"C","text":"Default every missing field to \"low\" silently, without surfacing it downstream.","explanation":"Silently defaulting to \"low\" hides missing data and mislabels genuinely urgent tickets."},{"key":"D","text":"Remove the priority field from the schema entirely, since it keeps causing friction.","explanation":"Removing the field deletes information downstream depends on, trading one failure for another."}],"correct":"B","tiebreaker":"Domain 2 core concept: input schema requiredness enforces call correctness structurally.","rationale":"Marking a field required in the schema states the requirement structurally, at the point where the model builds the call. A prompt note is weaker and easier to miss; silently defaulting masks a real problem instead of preventing it.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.2 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Strict tool use","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/strict-tool-use","type":"docs"}],"note":"Answer per the exam guide. In the current API a tool's input is only guaranteed to match its input_schema when the tool sets strict: true; without it Claude can return a wrong type or omit a required field.","corroborated":[]},
{"id":"REF-031","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d2"],"taskStatements":["2.4"],"objectives":["O34","O35"],"stem":"An MCP server author wants to expose a pre-written, reusable prompt template (with placeholders) that a client application can invoke to kick off a specific workflow. Which MCP primitive is designed for this?","options":[{"key":"A","text":"Tools.","explanation":"Tools are actions the model invokes. A reusable prompt template isn't an action — it's prewritten text the client surfaces."},{"key":"B","text":"Resources.","explanation":"Resources supply context the model reads. They aren't parameterized or invoked to start a workflow."},{"key":"C","text":"Prompts.","explanation":"Correct. Prompts are MCP's primitive for reusable, templated interactions with placeholders that a client can surface and invoke."},{"key":"D","text":"Sampling.","explanation":"Sampling is the reverse direction: a server asking the client's model for a completion. It isn't a way to publish a template."}],"correct":"C","tiebreaker":"Domain 2 core concept: MCP's three primitives — Tools, Resources, Prompts.","rationale":"Prompts are exactly this: reusable templated interactions a client can surface and invoke, distinct from Tools (actions) and Resources (context data). Sampling refers to servers requesting completions from the client's model, a different MCP capability entirely.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.4 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-032","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.1"],"objectives":["O36"],"stem":"An agent has get_record(id) described only as \"Gets record data\" and get_history(id) described only as \"Gets history data.\" Both descriptions are technically accurate but nearly identical in scope, and the model frequently picks the wrong one. What's the fix?","options":[{"key":"A","text":"Rewrite both descriptions with specific, non-overlapping trigger conditions and a short example each.","explanation":"Correct. \"Gets record data\" and \"Gets history data\" overlap at the point of decision; concrete non-overlapping triggers plus an example each give the model a basis to choose."},{"key":"B","text":"Rename the tools to more distinctive, memorable identifiers so the model stops conflating the two.","explanation":"A distinctive name doesn't say when to use the tool. The model picks on meaning, and both descriptions still claim the same ground."},{"key":"C","text":"Remove one of the two tools entirely, eliminating the ambiguity the overlap was creating.","explanation":"Removing a tool removes a capability the agent needs; the two do different jobs and both are used."},{"key":"D","text":"Add a system-prompt reminder listing which tool applies in which situation, reinforced each turn.","explanation":"A system-prompt reminder restates at session start what the description could say at decision time — weaker, and easy to miss in a long context."}],"correct":"A","tiebreaker":"First Step Trap: Tool misrouting → improve tool descriptions.","rationale":"The fix is always sharper, non-overlapping descriptions with concrete trigger conditions — not renaming, removing capability, or hoping a prompt reminder covers every case. A prompt reminder is a weaker, probabilistic version of the same idea — descriptions the model sees at decision time beat instructions it has to recall.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.1 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Define tools (descriptions, tool_choice)","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-033","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.1"],"objectives":["O36"],"stem":"As a team keeps adding tools to an agent (now at 40), overall tool-selection accuracy has been declining, even for tools that existed from the start and are well-described. What's the most likely contributing factor?","options":[{"key":"A","text":"Too many overlapping options increase ambiguity, making each selection harder for the model.","explanation":"Correct. More options means more ways to confuse one tool for another; the practical fix is scoping which tools each agent sees rather than exposing all forty."},{"key":"B","text":"The model needs a larger context window to hold all forty tool descriptions at once without loss.","explanation":"Capacity isn't the constraint — forty descriptions fit comfortably. The difficulty is choosing between them."},{"key":"C","text":"Tool count should never exceed ten, since beyond that selection accuracy collapses entirely.","explanation":"There is no hard cliff at ten. Accuracy declines gradually and depends on how distinct the tools are."},{"key":"D","text":"The older tool definitions have gone stale and need to be re-registered with the current schema.","explanation":"Nothing goes stale in a tool definition; the well-described older tools are unchanged, and only the surrounding choice has grown harder."}],"correct":"A","tiebreaker":"Domain 1/2 crossover: large tool sets benefit from routing to scope relevant tools per agent.","rationale":"Large tool counts genuinely increase selection difficulty — the practical fix is scoping which tools each agent/subagent actually sees, often via routing. A bigger window misdiagnoses this as a capacity issue rather than a choice-complexity issue; an arbitrary hard cap isn't an accurate rule either.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.1 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-034","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.1"],"objectives":["O36"],"stem":"A tool's description is a single vague line: \"Updates a record.\" The model frequently calls it incorrectly. A developer responds by writing an extremely long, exhaustive description covering every edge case in dense paragraphs. Does this fully solve the problem?","options":[{"key":"A","text":"Yes — the longer and more exhaustive the description, the better, with no real downside to consider.","explanation":"Length has real downsides: a dense wall of text buries the trigger conditions and costs tokens on every request."},{"key":"B","text":"Better, but not automatic — clarity and specificity about usage matter more than raw description length.","explanation":"Correct. What drives correct selection is clear, specific usage conditions. An exhaustive description helps only insofar as it makes those conditions easier to find."},{"key":"C","text":"No — tool descriptions have no measurable effect on which tool the model selects at runtime.","explanation":"Descriptions are a primary input to tool selection — the original vague line is exactly why the model chose wrongly."},{"key":"D","text":"No — only the tool's name influences selection, and the description is effectively ignored.","explanation":"The name is one signal among several; the description carries the usage conditions the model relies on."}],"correct":"B","tiebreaker":"Domain 2 core concept: tool description clarity and specificity, not just length.","rationale":"The goal is clarity and specificity about usage conditions, not raw length — a dense wall of text can be just as unhelpful as a vague one-liner. The other options are inaccurate about what drives tool selection.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.1 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Define tools (descriptions, tool_choice)","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-035","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.1"],"objectives":["O36"],"stem":"A database lookup tool returns its entire raw record — tens of thousands of tokens — every time it's called, even when only two fields are actually relevant to the current question. What's the best fix at the tool-design level?","options":[{"key":"A","text":"Have the tool return only the relevant, requested fields, rather than the entire raw record every time.","explanation":"Correct. Returning only the requested fields cuts the noise and the cost at source, so nothing downstream has to cope with tens of thousands of irrelevant tokens."},{"key":"B","text":"Increase the model's context window so it can comfortably hold the full record dump.","explanation":"A larger window accommodates the waste instead of removing it, and you still pay for every token on every call."},{"key":"C","text":"Ask the model to ignore the irrelevant portions of the record it receives before reasoning over it.","explanation":"The tokens are already in context and already billed; asking the model to disregard them saves nothing and adds a reliability risk."},{"key":"D","text":"Cache the full record dump so at least repeated lookups return faster and cost less each time.","explanation":"Caching makes repeat dumps cheaper but still floods context with fields the question never needed."}],"correct":"A","tiebreaker":"Domain 2 core concept: design tool outputs for relevance, not raw completeness.","rationale":"Designing the tool to return only what's relevant (or parameterized to select fields) is the right fix — it reduces noise and cost at the source. A bigger window repeats the Usually Wrong instinct about size; asking the model to ignore parts is unreliable and doesn't reduce cost.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.1 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-036","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.1"],"objectives":["O13","O16"],"family":"personal-claude-md","stem":"A team of 8 engineers onboards a new developer. After their first week, Claude Code isn't following the project's coding standards — no linting rules, no test requirements, none of the architectural constraints the rest of the team sees enforced. The team lead confirms their own setup works perfectly. No changes have been made to the repo recently. What is the most likely root cause?","options":[{"key":"A","text":"The project's .claude/commands/ directory was never committed, so it is missing from the clone.","explanation":"A missing .claude/commands/ directory would cost shortcuts, not coding standards — and the stem says the repo is unchanged."},{"key":"B","text":"The new developer's Claude Code version is outdated and does not support the current CLAUDE.md syntax.","explanation":"A version gap would affect the lead's machine too once they updated, and CLAUDE.md syntax changes don't silently drop every rule."},{"key":"C","text":"The coding standards are defined in the team lead's ~/.claude/CLAUDE.md (user-level), which is not shared via git.","explanation":"Correct. ~/.claude/CLAUDE.md is user-level and machine-local, so it never travels through git — which is exactly why it works for the lead and nobody else. Team standards belong in the project-level CLAUDE.md, committed to the repo."},{"key":"D","text":"The new developer needs to run /memory to sync the project instructions into their local session.","explanation":"/memory doesn't fetch instructions from a teammate's machine; there is nothing in the repo for it to sync."}],"correct":"C","tiebreaker":"First Step Trap: Team instructions not applied → check CLAUDE.md is at project-level.","rationale":"The standards live in the lead's ~/.claude/CLAUDE.md — user-level, machine-specific, never committed to git. Team-wide standards belong in the project-level CLAUDE.md, checked into the repo so every teammate inherits them automatically. The other options describe plausible-sounding but incorrect mechanisms — none explain why it works for the lead and no one else.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.1 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code memory (CLAUDE.md and .claude/rules/)","url":"https://code.claude.com/docs/en/memory","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-037","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"ci","scenario":"Claude Code for Continuous Integration","scenarioContext":null,"domains":["d3"],"taskStatements":["3.6"],"objectives":["O11","O13","O15","O30"],"family":"ci-print-flag","stem":"A team adds a Claude Code step to CI to auto-generate release notes. Locally, running `claude` and typing prompts works fine. In CI, the job never completes and eventually times out. What's the most likely fix?","options":[{"key":"A","text":"Increase the CI job's timeout so the process has enough time to finish before the runner kills it.","explanation":"A longer timeout lets the process wait longer for input that will never arrive — the same hang, later."},{"key":"B","text":"Add the -p flag for non-interactive/print mode, so it stops waiting on input CI can never provide.","explanation":"Correct. Without -p, the CLI starts an interactive session and blocks on stdin. Print mode runs the prompt and exits, which is what CI needs."},{"key":"C","text":"Install Claude Code globally on the runner rather than as a project-local dependency.","explanation":"Install location doesn't change whether the process waits for input; it would fail the same way either way."},{"key":"D","text":"Move the CI job to a runner with more memory so the process is not starved mid-execution.","explanation":"The job is blocked, not starved. A hang that ends in a timeout with no memory pressure points at input, not resources."}],"correct":"B","tiebreaker":"First Step Trap: CI job hangs → -p flag, essentially every time.","rationale":"CI hangs are almost always an interactive-mode problem — the process is waiting for input it will never get. -p is the CLI flag question you should recognize instantly the moment you see 'CI job hangs.' A longer timeout just delays the failure; the other options don't address why it's hanging.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.6 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Run Claude Code programmatically (headless)","url":"https://code.claude.com/docs/en/headless","type":"docs"},{"title":"Claude Code CLI reference","url":"https://code.claude.com/docs/en/cli-reference","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-038","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.1"],"objectives":["O13","O16"],"stem":"A team wants three things: (1) persistent project context loaded automatically every session, (2) a reusable shortcut a developer can invoke on demand for a repeatable task, and (3) a packaged set of expert instructions (with scripts/resources) Claude loads only when relevant. Which mechanisms map to (1), (2), (3) respectively?","options":[{"key":"A","text":"CLAUDE.md, Commands, Skills.","explanation":"Correct. CLAUDE.md loads automatically every session, Commands are on-demand shortcuts for repeatable tasks, and Skills are packaged instructions with resources that load only when relevant."},{"key":"B","text":"Skills, CLAUDE.md, Commands.","explanation":"This puts Skills in the always-loaded slot and CLAUDE.md in the on-demand one, inverting how both work."},{"key":"C","text":"Commands, Skills, CLAUDE.md.","explanation":"Commands don't load automatically, and CLAUDE.md isn't a conditionally-loaded package of expert instructions."},{"key":"D","text":"CLAUDE.md, Skills, Commands.","explanation":"The first slot is right, but Skills and Commands are swapped: the on-demand shortcut is a Command, and the conditionally-loaded package is a Skill."}],"correct":"A","tiebreaker":"Domain 3 core concept: CLAUDE.md vs Commands vs Skills.","rationale":"CLAUDE.md is the always-loaded persistent context; Commands are on-demand shortcuts for repeatable tasks; Skills are packaged, conditionally-loaded expert instructions with their own resources. Each of the other options swaps at least one mechanism into the wrong slot.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.1 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code skills","url":"https://code.claude.com/docs/en/skills","type":"docs"}],"note":"Answer per the exam guide. In current Claude Code, custom commands have been merged into skills: a file in .claude/commands/ and a skill in .claude/skills/ both create a /name command, and skills can additionally load automatically when relevant.","corroborated":[]},
{"id":"REF-039","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.4"],"objectives":["O08"],"stem":"A developer asks Claude Code to refactor a shared authentication module used by twelve other services. Which approach better fits the risk level?","options":[{"key":"A","text":"Direct execution, so the refactor lands in a single uninterrupted pass.","explanation":"A single uninterrupted pass across a module twelve services depend on is where the risk is — there's no checkpoint before changes land."},{"key":"B","text":"Plan mode, so the approach is proposed and approved before any code changes.","explanation":"Correct. Plan mode surfaces the approach for review before any edit, which is the right trade when a mistake propagates to twelve consumers."},{"key":"C","text":"Direct execution, repeated twice so the results can be compared afterward.","explanation":"Running it twice produces two unreviewed refactors and a comparison after the fact, when the damage is already done."},{"key":"D","text":"Direct execution with a longer prompt describing all twelve dependent services.","explanation":"A longer prompt may improve the attempt but still commits changes with no approval step."}],"correct":"B","tiebreaker":"Domain 3 core concept: plan mode for higher-risk changes, direct execution for routine ones.","rationale":"Plan mode is exactly for higher-risk or exploratory changes — propose first, approve, then execute — versus direct execution for routine, low-risk tasks. Running it twice or writing a longer prompt doesn't add the review step that actually reduces risk.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.4 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code permission modes (plan mode)","url":"https://code.claude.com/docs/en/permission-modes","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-040","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.1"],"objectives":["O13","O16"],"stem":"A team wants a rule like 'never modify files under /legacy/ without explicit approval' applied consistently across every Claude Code session on this repo, without anyone needing to type it each time. Where does this belong?","options":[{"key":"A","text":"In each individual prompt, restated by every developer at the start of every working session.","explanation":"Relying on every developer to restate the rule every session guarantees it is eventually forgotten."},{"key":"B","text":"In project-level configuration (CLAUDE.md / project rules), loaded automatically for the repo.","explanation":"Correct. Project-level configuration lives in the repo and loads automatically, so the constraint applies to every session without anyone typing it."},{"key":"C","text":"In a pinned team chat message that developers consult and apply themselves when relevant.","explanation":"A pinned message never reaches a session; nothing loads it into Claude's context."},{"key":"D","text":"In each developer's personal shell profile, applied whenever they start work.","explanation":"A personal shell profile is per-developer and per-machine, so it neither travels with the repo nor covers the team."}],"correct":"B","tiebreaker":"Domain 3 core concept: project-level config for repo-wide standing rules.","rationale":"Persistent, repo-wide constraints belong in project-level configuration that loads automatically — exactly the problem CLAUDE.md/project rules solve. Repeating it in every prompt is error-prone; a Slack reminder isn't enforcement at all.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.1 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code memory (CLAUDE.md and .claude/rules/)","url":"https://code.claude.com/docs/en/memory","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-041","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.1"],"objectives":["O13","O16"],"stem":"A team wants to configure a PreToolUse hook that blocks a specific tool under certain conditions. Where is this hook defined?","options":[{"key":"A","text":"Inside the CLAUDE.md file as a written instruction the model reads at the start of every session.","explanation":"Text in CLAUDE.md is an instruction the model may follow. A hook's point is that it fires regardless of what the model decides."},{"key":"B","text":"In the project's settings.json configuration, as a structured hook definition.","explanation":"Correct. Hooks are declared as structured configuration in settings.json, which is what makes them deterministic rather than advisory."},{"key":"C","text":"As a comment in the source code near the relevant function, where the constraint is most visible.","explanation":"A source comment is read by people, and possibly by the model as context; it configures nothing."},{"key":"D","text":"Through a live chat message to Claude at the start of each session that needs the constraint.","explanation":"A chat message lasts for that session and is still only an instruction."}],"correct":"B","tiebreaker":"Domain 3 core concept: hooks are configured in settings.json, not CLAUDE.md.","rationale":"Hooks are configured structurally in settings.json — that's what makes them deterministic/programmatic rather than prompted. Putting it in CLAUDE.md would just be another instruction, not enforcement; the other options aren't real configuration mechanisms for hooks.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.1 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code hooks reference","url":"https://code.claude.com/docs/en/hooks","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-042","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.1"],"objectives":["O13","O16"],"stem":"You're setting up Claude Code for a junior developer's sandboxed task and want to guarantee it can read and edit files but cannot execute shell commands, no matter what the model decides. What's the right layer to enforce this?","options":[{"key":"A","text":"A strongly worded instruction telling the model to never use shell commands under any circumstance.","explanation":"A strongly worded instruction is still advisory — \"no matter what the model decides\" is precisely what prompting cannot promise."},{"key":"B","text":"Tool/permission configuration that scopes exactly which tools are available or allowed in that session.","explanation":"Correct. Scoping the available tools at the permission layer means shell execution isn't offered at all, so no model decision can reach it."},{"key":"C","text":"Rely on the model inferring from the task context that shell execution would be inappropriate here.","explanation":"Inference from context is the weakest form of all; the requirement is a guarantee."},{"key":"D","text":"A prominent comment at the top of every source file warning against running shell commands.","explanation":"Comments in source files don't restrict capabilities, and the model may never read them."}],"correct":"B","tiebreaker":"Domain 3 core concept: scope capability at the permission/config layer, not the prompt layer.","rationale":"Permission/tool scoping at the configuration level is a structural guarantee; instructions are advisory and can be worked around or simply not followed. The other options are all prompt-level or non-mechanisms — none actually prevent the capability.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.1 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code permissions","url":"https://code.claude.com/docs/en/permissions","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-043","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.2"],"objectives":["O14","O16"],"stem":"A team wants a shortcut where typing /deploy-checklist triggers the same repeatable pre-deploy review steps every time, without re-explaining them. What's this?","options":[{"key":"A","text":"A Skill — packaged expert instructions that load conditionally when relevant.","explanation":"Skills load when Claude judges them relevant. The stem describes something the developer explicitly triggers by typing it."},{"key":"B","text":"A Command — a user-invoked shortcut that runs the same repeatable steps on demand.","explanation":"Correct. A slash-invoked shortcut that replays the same steps on demand is exactly what a Command is."},{"key":"C","text":"A hook — deterministic enforcement that fires around tool execution.","explanation":"Hooks fire around tool execution as enforcement; nobody invokes one by typing /deploy-checklist."},{"key":"D","text":"A Resource — read-only content the model can reference from an MCP server.","explanation":"A Resource is read-only content from an MCP server, not an action a developer triggers."}],"correct":"B","tiebreaker":"Domain 3 core concept: Commands are user-invoked, on-demand shortcuts.","rationale":"This is precisely what Commands are for: on-demand, developer-invoked shortcuts for repeatable tasks. Skills are more about conditionally-loaded expert instructions/resources than an explicit slash-invoked shortcut; hooks are enforcement, not a user-triggered shortcut.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.2 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code skills","url":"https://code.claude.com/docs/en/skills","type":"docs"}],"note":"Answer per the exam guide. In current Claude Code, custom commands have been merged into skills: a file in .claude/commands/ and a skill in .claude/skills/ both create a /name command, and skills can additionally load automatically when relevant.","corroborated":[]},
{"id":"REF-044","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.1"],"objectives":["O13","O16"],"stem":"A facilitator builds a SKILL.md file containing instructions (and helper scripts) for generating exam-style practice questions on demand, which Claude loads only when the task calls for it. What mechanism is this?","options":[{"key":"A","text":"A Skill — packaged expert instructions that load conditionally when relevant.","explanation":"Correct. A SKILL.md bundling instructions plus helper scripts, loaded only when the task calls for it, is the definition of a Skill."},{"key":"B","text":"A Command — a user-invoked shortcut that runs the same repeatable steps on demand.","explanation":"A Command is invoked explicitly by the developer; this loads on relevance, without anyone typing it."},{"key":"C","text":"A hook — deterministic enforcement that fires around tool execution.","explanation":"Hooks enforce behaviour around tool calls. They don't package instructions or scripts for a task."},{"key":"D","text":"CLAUDE.md content — standing project context loaded automatically every session.","explanation":"CLAUDE.md is loaded every session regardless of relevance, which is the opposite of the conditional loading described."}],"correct":"A","tiebreaker":"Domain 3 core concept: Skills are conditionally-loaded, packaged expert instructions.","rationale":"This is exactly a Skill: packaged, reusable instructions (often with resources/scripts) that load conditionally, based on relevance to the task. It's not always-loaded like CLAUDE.md, not a slash-invoked shortcut like a Command, and not enforcement like a hook.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.1 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code skills","url":"https://code.claude.com/docs/en/skills","type":"docs"}],"note":"Answer per the exam guide. In current Claude Code, custom commands have been merged into skills: a file in .claude/commands/ and a skill in .claude/skills/ both create a /name command, and skills can additionally load automatically when relevant.","corroborated":[]},
{"id":"REF-045","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.1"],"objectives":["O13","O16"],"stem":"A project's CLAUDE.md has grown over time to roughly 3,000 lines covering everything from coding style to historical decisions to unrelated trivia. Compliance with the actually-important rules has gotten worse, not better. What's the most likely issue?","options":[{"key":"A","text":"CLAUDE.md files have a hard line limit that's been exceeded and is silently truncating.","explanation":"There is no silent truncation limit at work here; the whole file is being read, which is part of the problem."},{"key":"B","text":"Bloated, low-signal CLAUDE.md content dilutes attention to the rules that actually matter.","explanation":"Correct. Three thousand lines of mixed-signal content competes for attention, so the rules that matter are diluted by trivia and history."},{"key":"C","text":"The file needs to be converted into a Skill so it loads conditionally rather than on every session.","explanation":"Converting wholesale to a Skill moves the bloat rather than reducing it; the fix is cutting low-signal content and keeping standing rules concise."},{"key":"D","text":"Nothing is wrong — more documented context is reliably better, and the model will weight what matters.","explanation":"Compliance got worse as the file grew, which is direct evidence against \"more context is reliably better.\""}],"correct":"B","tiebreaker":"Domain 3/5 crossover: attention dilution applies to CLAUDE.md content, not just conversation length.","rationale":"This is the same attention-dilution principle as long conversations — a bloated, low-signal CLAUDE.md competes for attention with the rules that matter most. 'More content is always better' is the Usually Wrong instinct here; there's no accurate mechanism pointing to a silent truncation limit.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.1 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code memory (CLAUDE.md and .claude/rules/)","url":"https://code.claude.com/docs/en/memory","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-046","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.6"],"objectives":["O11","O13","O15","O30"],"stem":"A nightly cron job runs Claude Code non-interactively to generate a dependency changelog and commit it. Which configuration considerations matter most here, versus an interactive developer session?","options":[{"key":"A","text":"Identical configuration to an interactive session, with no automation-specific changes.","explanation":"Identical configuration is what causes unattended runs to hang or overreach — there is no human to answer a prompt or stop a bad action."},{"key":"B","text":"Non-interactive print mode, scoped tool permissions, and no prompts expecting a human reply.","explanation":"Correct. An unattended run needs print/non-interactive mode so nothing blocks on input, and tightly scoped permissions because no one is watching what it does."},{"key":"C","text":"A longer system prompt with more encouragement to complete the task correctly.","explanation":"Encouragement doesn't address either operational risk: blocking on input, or acting beyond its remit."},{"key":"D","text":"A larger context window setting so the unattended run has more room to work.","explanation":"Window size has no bearing on whether the job can run without a human present."}],"correct":"B","tiebreaker":"Domain 3 core concept: automated/CI contexts require non-interactive mode + scoped permissions.","rationale":"Automated/non-interactive runs need explicit non-interactive mode and tightly scoped permissions — there's no human present to respond to prompts or catch overreach in the moment. Assuming identical configuration ignores real operational differences; neither prompt length nor window size addresses the actual automation requirements.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.6 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Run Claude Code programmatically (headless)","url":"https://code.claude.com/docs/en/headless","type":"docs"},{"title":"Claude Code CLI reference","url":"https://code.claude.com/docs/en/cli-reference","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-047","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["1.5"],"objectives":["O16"],"stem":"A team wants a PreToolUse hook that only triggers for a single specific tool (delete_record), not for every tool call in the session. Is this possible?","options":[{"key":"A","text":"No — hooks always apply to every tool call in the session without exception.","explanation":"Blanket application would make hooks impractical; scoping is a core part of their design."},{"key":"B","text":"Yes — hooks support matchers that scope them to specific tools such as delete_record.","explanation":"Correct. Hooks take matchers, so a PreToolUse hook can be scoped to fire only for delete_record and leave every other call untouched."},{"key":"C","text":"No — scoping requires renaming the tool to carry a special reserved prefix.","explanation":"No reserved prefix is involved; the matcher does the scoping without renaming anything."},{"key":"D","text":"Only partly — PostToolUse hooks can be scoped, but PreToolUse always applies globally.","explanation":"Both PreToolUse and PostToolUse support matchers — there is no such asymmetry."}],"correct":"B","tiebreaker":"Domain 3 core concept: hooks can be scoped to specific tools, not only global.","rationale":"Hooks can be scoped to specific tools or matchers, not just applied blanket-wide — that's part of what makes them a practical enforcement tool. The other options all overstate limitations that aren't accurate.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.2 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code hooks reference","url":"https://code.claude.com/docs/en/hooks","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-048","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.1"],"objectives":["O13","O16"],"stem":"A developer has a user-level ~/.claude/CLAUDE.md saying 'prefer verbose comments' and the project's CLAUDE.md says 'minimal comments, rely on tests.' Both are loaded. What should you expect?","options":[{"key":"A","text":"The user-level file always overrides the project-level file, since personal configuration is more specific.","explanation":"User-level files don't override project files; the files are concatenated rather than ranked."},{"key":"B","text":"Both load as context and neither overrides the other, so a real conflict should be reconciled deliberately.","explanation":"Correct. Discovered CLAUDE.md files are concatenated into context rather than ranked, and when two instructions contradict, Claude may follow either — so a conflict like this is worth resolving deliberately rather than leaving to chance."},{"key":"C","text":"Only the project-level file loads, and the user-level file is ignored whenever a project file exists.","explanation":"The user-level file isn't discarded when a project file exists; both contribute context."},{"key":"D","text":"Claude Code halts and reports the conflict, requiring resolution before the session can continue.","explanation":"Claude Code doesn't halt on contradictory guidance — which is exactly why an unnoticed conflict can persist."}],"correct":"B","tiebreaker":"Domain 3 core concept: user-level and project-level CLAUDE.md both load; a conflict is not settled by precedence.","rationale":"Both layers load as context and are concatenated rather than ranked, so a contradiction between them is not resolved by a precedence rule — Claude may follow either. The project file is the team's agreed standard, so the conflict should be reconciled explicitly. The other options assert an override, an exclusion or a blocking behaviour that doesn't exist.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.1 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code memory (CLAUDE.md and .claude/rules/)","url":"https://code.claude.com/docs/en/memory","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-049","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.1"],"objectives":["O13","O16"],"stem":"A CLAUDE.md file states \"never commit directly to main branch.\" The team also has branch protection configured at the repository/platform level that technically blocks direct commits to main. Which layer is actually providing the real guarantee?","options":[{"key":"A","text":"The CLAUDE.md instruction alone is already sufficient; the branch protection rule is redundant.","explanation":"An instruction in CLAUDE.md is advisory. Calling the platform rule redundant mistakes guidance for enforcement."},{"key":"B","text":"The repository-level branch protection is the real guarantee; CLAUDE.md is a helpful, non-binding reinforcement.","explanation":"Correct. Branch protection is enforced by the platform on every push regardless of client or intent; CLAUDE.md usefully states the same rule but cannot guarantee it."},{"key":"C","text":"Neither applies, since Claude Code cannot push commits to a protected repository branch at all.","explanation":"Claude Code can push like any other client — it is the protection rule, not an inability, that stops a direct commit to main."},{"key":"D","text":"Only the CLAUDE.md instruction matters; platform-level protections don't apply to AI-driven commits.","explanation":"Platform protections apply to every commit path; the origin of the commit makes no difference."}],"correct":"B","tiebreaker":"Domain 3 core concept: real guarantees come from structural enforcement, not written instructions alone.","rationale":"Repository-level branch protection is a structural, always-enforced guarantee; a written instruction is helpful context but not a hard guarantee on its own. Options A and D mistake the instruction for the enforcement mechanism, and C invents a limitation.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.1 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-050","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.1"],"objectives":["O13","O16"],"stem":"A monorepo has a root-level CLAUDE.md with general conventions, and a more specific CLAUDE.md inside a subdirectory for a particular service with its own conventions. When working inside that subdirectory, what should you expect?","options":[{"key":"A","text":"Only the root-level file is ever loaded, no matter which working directory you're in.","explanation":"Ignoring the nearer file would make per-service conventions impossible to express in a monorepo."},{"key":"B","text":"Both can apply — the closer, more specific file layers local context onto the broader root conventions.","explanation":"Correct. The broader root conventions still apply and the closer file layers service-specific context on top, which is the point of nesting."},{"key":"C","text":"The subdirectory file completely replaces the root file everywhere, even outside that subdirectory.","explanation":"The subdirectory file applies within its own area, not across the whole repository."},{"key":"D","text":"Nested CLAUDE.md files are not supported, so only a single root-level file is ever recognized.","explanation":"Nested CLAUDE.md files are supported; that is what makes monorepo configuration workable."}],"correct":"B","tiebreaker":"Domain 3 core concept: nested CLAUDE.md files layer specific context alongside broader conventions.","rationale":"Nested, more specific configuration layered alongside broader conventions is the useful pattern for large monorepos — not an either/or replacement. The other options either understate what's actually supported or overstate the subdirectory file's scope beyond its own area.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.1 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code memory (CLAUDE.md and .claude/rules/)","url":"https://code.claude.com/docs/en/memory","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-051","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.2"],"objectives":["O24","O29"],"stem":"You prompt Claude to generate a structured weekly status report from raw notes. The instructions describe the desired sections in prose. Across ten runs, section ordering, headers, and formatting vary noticeably. What should you do first?","options":[{"key":"A","text":"Lower the temperature to 0 to force deterministic sampling, removing run-to-run variation in the format.","explanation":"Temperature 0 makes sampling deterministic for identical input, but the format was never specified precisely — so it locks in an arbitrary shape, and ordering can still differ as notes change."},{"key":"B","text":"Add 2–3 few-shot examples showing the exact desired output format.","explanation":"Correct. The instructions describe the format in prose; two or three examples show it exactly, which is far more reliable for pinning section order and headers."},{"key":"C","text":"Split the task into multiple smaller prompts, one per section, so each has a single formatting concern.","explanation":"Splitting per section adds orchestration and still leaves each section's formatting unspecified."},{"key":"D","text":"Switch to a larger model with stronger instruction-following to hold the format more consistently.","explanation":"A stronger model follows an underspecified format more consistently at best; it still has to guess what you meant."}],"correct":"B","tiebreaker":"First Step Trap: Output inconsistency → add few-shot examples.","rationale":"Output inconsistency is the signature case for few-shot examples — showing the format is far more reliable than describing it in prose. Temperature affects word choice, not adherence to a format that was never precisely specified; the other options don't address why the model was never shown what 'correct' looks like.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.2 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Prompting best practices","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-052","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.3"],"objectives":["O25","O26","O27","O29","O37"],"family":"json-preamble","stem":"You're extracting structured fields from documents and expect strict JSON back. Most responses are clean, but occasionally the model adds a sentence like \"Here's the extracted data:\" before the JSON, breaking your parser. What's the most reliable fix?","options":[{"key":"A","text":"Add a stronger instruction saying \"Respond with ONLY valid JSON, and nothing else, ever.\"","explanation":"A stronger instruction lowers the rate of stray prose without eliminating it — and \"occasionally\" is already what near-compliance looks like."},{"key":"B","text":"Force tool_choice onto a single extraction tool whose input_schema defines the exact fields you need.","explanation":"Correct. A forced tool call returns arguments matching the input_schema, so there is no free-text channel for a preamble to appear in at all."},{"key":"C","text":"Post-process every response with a regex script that strips any prose preceding the JSON payload.","explanation":"Regex stripping patches the output after the fact and breaks on the next unanticipated shape, such as prose after the JSON or a fenced block."},{"key":"D","text":"Lower the temperature to zero so the model stops varying how it opens each of its responses.","explanation":"Temperature 0 reduces variation but doesn't forbid a preamble; if the opener is likely, deterministic sampling can make it appear every time."}],"correct":"B","tiebreaker":"Domain 4 core concept: forced tool_choice for structured output.","rationale":"Forcing tool_choice is the reliable, structural fix — it removes the possibility of stray prose entirely, rather than hoping the model complies with an instruction. A stronger instruction is still probabilistic; regex stripping treats a symptom and will break in new ways.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.3 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Strict tool use","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/strict-tool-use","type":"docs"}],"note":"Answer per the exam guide. In the current API a tool's input is only guaranteed to match its input_schema when the tool sets strict: true; without it Claude can return a wrong type or omit a required field. The current docs also list several newer models that reject tool_choice any and named-tool with a 400 error; the documented alternative there is auto with strict: true.","corroborated":[]},
{"id":"REF-053","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.1"],"objectives":[],"stem":"A team pastes the same 400-word company policy into the user message at the start of every single request, verbatim, every time. Where should this content actually live?","options":[{"key":"A","text":"In the user message, since that is where the model reads context most reliably each turn.","explanation":"Repeating 400 identical words in every user turn mixes standing policy with the turn's actual task and re-sends it each time."},{"key":"B","text":"In the system message, since it is standing context for the whole conversation rather than one turn.","explanation":"Correct. Standing context that governs the whole conversation belongs in the system message, leaving the user message for that turn's task — and a stable system prefix is also what caches well."},{"key":"C","text":"Split evenly across the system message and every user message for redundancy.","explanation":"Duplicating it in both places doubles the tokens and adds no reliability."},{"key":"D","text":"Removed entirely and replaced with a shorter reminder repeated on each request.","explanation":"Shortening to a reminder discards policy content the model needs to apply."}],"correct":"B","tiebreaker":"Domain 4 core concept: system message = standing context, user message = the task.","rationale":"Standing context and behavioral rules belong in the system message; the user message should carry the actual task for that turn. This also sets up a caching opportunity, since a stable system message is exactly the kind of static content that caches well.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.1 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Prompt caching","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-caching","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-054","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.2"],"objectives":["O24","O29"],"stem":"An agent solving multi-step word problems gets the final numeric answer wrong noticeably more often than expected, even though each individual fact it's given is correct. What technique most directly helps here?","options":[{"key":"A","text":"Chain-of-thought — the model works through intermediate steps before answering.","explanation":"Correct. Errors that appear only in the final answer while every input fact is right point at skipped reasoning steps, which is what chain-of-thought addresses."},{"key":"B","text":"Prefilling — the assistant turn is started with the desired answer format.","explanation":"Prefilling constrains how the answer starts, not whether the arithmetic and logic along the way are sound."},{"key":"C","text":"A larger context window — more room to hold the full problem statement.","explanation":"The problem statement already fits; nothing is being dropped for lack of room."},{"key":"D","text":"Temperature at zero — randomness in token selection is minimized.","explanation":"Temperature 0 makes a flawed reasoning path repeatable rather than correct."}],"correct":"A","tiebreaker":"Domain 4 core concept: chain-of-thought for multi-step reasoning accuracy.","rationale":"Chain-of-thought is specifically effective for multi-step reasoning accuracy — working through steps reduces the chance of skipping logic and landing on a wrong final answer. Prefilling and temperature don't address reasoning quality; a bigger window is unrelated to this failure mode.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.2 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-055","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.3"],"objectives":["O25","O26","O27","O29","O37"],"stem":"A prompt pastes instructions, a long document to summarize, and two formatting examples together in one continuous block of text. The model sometimes treats part of the document as an instruction, or an example as part of the source content. What's the most direct fix?","options":[{"key":"A","text":"Wrap each section in clear XML tags (<instructions>, <document>, <examples>) so the model can tell them apart.","explanation":"Correct. Explicit tags give each block an unambiguous boundary and role, so a sentence in the document can't read as an instruction."},{"key":"B","text":"Make the whole prompt noticeably shorter overall, trimming detail out of every section.","explanation":"Trimming makes the prompt shorter but no clearer about which text is which — the categories are still run together."},{"key":"C","text":"Move the document into a separate API call, away from the instructions entirely.","explanation":"A separate call splits the document from the instructions that interpret it, so neither call has what it needs."},{"key":"D","text":"Add the word \"IMPORTANT\" before the instructions section so the model prioritizes them over the document.","explanation":"\"IMPORTANT\" adds emphasis without drawing a boundary; the model still has to guess where the document ends."}],"correct":"A","tiebreaker":"Domain 4 core concept: XML tags separate instructions, context, and examples.","rationale":"XML tags are exactly for this — cleanly separating instructions, context, and examples so the model doesn't confuse categories of content. Simply shortening the prompt removes information; adding emphasis words is a weak trick that doesn't solve structural confusion.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.3 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Prompting best practices","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-056","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.2"],"objectives":["O24","O29"],"family":"json-preamble","stem":"You need JSON-only output, but the model reliably starts its response with a sentence of preamble before the JSON, even with clear instructions not to. What technique steers past this specific failure point?","options":[{"key":"A","text":"Prefill the assistant's turn with the opening character (e.g. \"{\") so it continues straight into JSON.","explanation":"Correct. Prefilling the assistant turn with \"{\" starts the response past the point where the preamble would go, so continuation into JSON is the only natural path."},{"key":"B","text":"Repeat the same instruction three separate times in the prompt so the requirement is impossible to overlook.","explanation":"An instruction that is already being ignored doesn't become binding by being repeated three times."},{"key":"C","text":"Increase max_tokens so there is more room for the response to unfold without being cut short mid-structure.","explanation":"max_tokens affects length, not whether a sentence appears before the JSON."},{"key":"D","text":"Switch to a larger model whose stronger instruction-following should eliminate the stray opening text.","explanation":"A stronger model reduces the rate but keeps the same free-text channel open; the preamble remains possible."}],"correct":"A","tiebreaker":"Domain 4 core concept: prefilling steers past a likely-wrong first token/move.","rationale":"Prefilling starts the assistant's turn past the likely-wrong first move, steering it directly into the desired continuation. Repeating an instruction that's already not working rarely helps; max_tokens and switching models don't address the actual failure point.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.2 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":"Answer per the exam guide. Starting with Claude 4.6 models, a prefilled last assistant turn is no longer supported and returns a 400 error; earlier models still accept prefills.","corroborated":[]},
{"id":"REF-057","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.1"],"objectives":[],"stem":"A team enables prompt caching but includes the user's constantly-changing query as part of the cached block, expecting savings on every request. Why don't they see the expected benefit?","options":[{"key":"A","text":"Caching only pays off on a static prefix repeated identically across requests.","explanation":"Correct. The cache matches on an identical prefix, so putting a per-request query inside the cached block invalidates it every time and nothing is reused."},{"key":"B","text":"Caching doesn't actually save any cost, regardless of how it is set up.","explanation":"Caching does save cost and latency — but only on the stable prefix, which this setup never achieves."},{"key":"C","text":"Caching only works with Haiku models, not with the other model families.","explanation":"Prompt caching is not restricted to one model."},{"key":"D","text":"They also need to cache the changing query manually on the server side.","explanation":"There is no manual server-side step; the fix is to move the changing query out of the cached prefix."}],"correct":"A","tiebreaker":"Domain 4 core concept: caching benefits static, repeated prefix content only.","rationale":"Caching benefits static prefix content that's genuinely identical across calls — a per-request-changing query defeats the purpose since it invalidates that part of the cache every time. The other options are either factually incorrect or not how caching is designed to work.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.1 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Prompt caching","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-caching","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-058","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.3"],"objectives":["O25","O26","O27","O29","O37"],"stem":"A forced-tool extraction returns syntactically valid JSON, but nested fields (e.g., an address object) are sometimes flattened into the wrong level, or a required nested field is missing. What's the most direct fix?","options":[{"key":"A","text":"Ask the model, in prose, to \"be more careful with nested fields.\"","explanation":"Asking for care in prose reintroduces exactly the probabilistic compliance the forced tool call was there to avoid."},{"key":"B","text":"Tighten the input_schema itself","explanation":"Correct. The schema is the enforcement point: declaring nested objects with required, typed fields makes the wrong shape invalid rather than merely discouraged."},{"key":"C","text":"Post-process the output with a script that guesses the right shape.","explanation":"Guessing the intended shape after the fact can silently place a value under the wrong key, which is worse than a visible failure."},{"key":"D","text":"Switch from forced tool_choice back to free-text prompting.","explanation":"Free-text prompting gives up the structural guarantee entirely and reopens malformed and prose-wrapped output."}],"correct":"B","tiebreaker":"Domain 4 core concept: schema strictness, not just forcing, guarantees exact output shape.","rationale":"The schema itself is the enforcement mechanism — tightening required/typed nested fields structurally prevents the wrong shape, rather than hoping the model self-corrects. Reverting to free-text prompting removes the very guarantee forced tool_choice was providing in the first place.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.3 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Strict tool use","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/strict-tool-use","type":"docs"}],"note":"Answer per the exam guide. In the current API a tool's input is only guaranteed to match its input_schema when the tool sets strict: true; without it Claude can return a wrong type or omit a required field. The current docs also list several newer models that reject tool_choice any and named-tool with a 400 error; the documented alternative there is auto with strict: true.","corroborated":[]},
{"id":"REF-059","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.2"],"objectives":["O24","O29"],"stem":"You've added a few-shot example of the correct output format, but the model still occasionally makes one specific recurring mistake (e.g., including a trailing disclaimer sentence it shouldn't). What additional technique often helps here?","options":[{"key":"A","text":"Add a counter-example showing the specific mistake and why it's wrong, next to the positive example.","explanation":"Correct. A counter-example naming the specific recurring mistake, shown beside the positive example, targets that error directly rather than restating the general shape."},{"key":"B","text":"Remove every example entirely and rely purely on written instructions instead.","explanation":"The examples are already helping; removing them loses the format anchor and leaves only the prose that was insufficient."},{"key":"C","text":"Increase the temperature setting so the model varies its output more randomly.","explanation":"Higher temperature increases variation, making an occasional unwanted sentence more likely, not less."},{"key":"D","text":"Repeat the same positive example several more times so the correct pattern dominates the context.","explanation":"More copies of an example that never showed the mistake doesn't tell the model what to avoid."}],"correct":"A","tiebreaker":"Domain 4 core concept: counter-examples reinforce what to avoid, not just what to do.","rationale":"A well-chosen negative/counter-example that shows exactly the mistake to avoid is often more effective than more positive examples alone, especially for a specific recurring error. Removing examples takes away what was already helping; the other options don't target the specific recurring mistake.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.2 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-060","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.1"],"objectives":["O30","O31"],"stem":"A system prompt opens with \"You are a senior security auditor with 20 years of experience.\" Is this persona framing, by itself, sufficient to guarantee expert-level security analysis?","options":[{"key":"A","text":"Yes — persona framing alone reliably produces expert-level depth and accuracy every time.","explanation":"A persona sets stance and vocabulary; it supplies no audit criteria, no threat model and no standard of depth."},{"key":"B","text":"No — persona framing sets tone, but real depth still comes from guidance, criteria, and examples.","explanation":"Correct. Persona framing shapes tone, but depth and accuracy come from explicit guidance, criteria and examples of what a good audit covers."},{"key":"C","text":"No — persona framing has no measurable effect on the depth or accuracy of the resulting output.","explanation":"Persona framing does measurably affect register and emphasis — the claim of no effect is too strong in the other direction."},{"key":"D","text":"Yes — provided the persona is restated at the beginning of every user message in the conversation.","explanation":"Restating the persona every turn repeats a label; it still adds no criteria."}],"correct":"B","tiebreaker":"Domain 4 core concept: persona framing shapes tone, not a substitute for real guidance/examples.","rationale":"Persona framing can shape tone and stance, but real depth and accuracy still come from specific guidance, criteria, and examples — not the persona label alone. Claiming persona framing alone is sufficient overstates its effect; claiming it has zero effect understates it.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.1 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-061","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.2"],"objectives":["O24","O29"],"stem":"A prompt has accumulated 40 separate prose rules describing the exact desired output format, and compliance is still inconsistent across runs. What's likely to help more than rule #41?","options":[{"key":"A","text":"Replace most of the prose rules with 2-3 concrete few-shot examples showing the format directly.","explanation":"Correct. Forty prose rules have already failed to pin the format down; two or three concrete examples show it directly and replace most of that prose."},{"key":"B","text":"Add ten more prose rules to the prompt, covering every edge case you can think of.","explanation":"Ten more rules extends an approach that is visibly not working and lengthens the prompt further."},{"key":"C","text":"Repeat the five most critical rules twice each so they carry more weight than the surrounding prose.","explanation":"Repetition emphasises rules without making the target format any more concrete."},{"key":"D","text":"Move all forty rules from the system message into the user message where they sit closer to the task.","explanation":"Relocating the same rules changes where they sit, not whether prose can specify a format precisely."}],"correct":"A","tiebreaker":"First Step Trap: Output inconsistency → add few-shot examples (applies even after many prose rules already exist).","rationale":"This is the same core principle as the output-inconsistency pattern: examples anchor format more reliably than accumulating more prose rules. Adding or repeating more rules just adds more of what's already not working; moving rules between messages doesn't address the actual issue.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.2 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Prompting best practices","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-062","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.3"],"objectives":["O25","O26","O27","O29","O37"],"stem":"You need a response that is always exactly \"true\" or \"false\", nothing else. Option one: instruct \"respond with only true or false.\" Option two: force tool_choice to a tool whose schema only accepts a boolean field. Which is actually guaranteed?","options":[{"key":"A","text":"The prose instruction, since a clear enough instruction reliably constrains the output.","explanation":"A clear instruction is followed most of the time; \"always exactly\" is a guarantee prose cannot give."},{"key":"B","text":"The forced tool_choice, since the schema structurally cannot accept anything but a boolean.","explanation":"Correct. With a forced tool call the output is tool arguments shaped by the schema, so there is no free-text channel for \"maybe\" or a sentence."},{"key":"C","text":"Neither, since both approaches can still return unexpected values in some runs.","explanation":"Option two genuinely is a structural guarantee, so \"neither\" is too pessimistic."},{"key":"D","text":"Both equally, provided temperature is also set to zero for each of them.","explanation":"Temperature 0 makes output repeatable, not schema-conformant; it doesn't lift the instruction to a guarantee."}],"correct":"B","tiebreaker":"Domain 4 core concept: schema-enforced output is guaranteed; instructions are probabilistic.","rationale":"Schema-enforced output via forced tool_choice is structurally guaranteed by the schema; prose instructions can still be deviated from. Claiming instructions are equally reliable overstates them; claiming neither/both are unreliable is inaccurate — option two is a genuine guarantee.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.3 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Strict tool use","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/strict-tool-use","type":"docs"}],"note":"Answer per the exam guide. In the current API a tool's input is only guaranteed to match its input_schema when the tool sets strict: true; without it Claude can return a wrong type or omit a required field. The current docs also list several newer models that reject tool_choice any and named-tool with a 400 error; the documented alternative there is auto with strict: true.","corroborated":[]},
{"id":"REF-063","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.2"],"objectives":["O24","O29"],"stem":"A developer believes that setting temperature to 0 is the primary way to guarantee consistent output structure across runs. Is this the right mental model?","options":[{"key":"A","text":"Yes — temperature at zero is the primary guarantee of consistent output structure.","explanation":"Temperature 0 gives repeatability for identical input, which is not the same as a structure that holds as the input changes."},{"key":"B","text":"Not quite — temperature reduces word-choice randomness, but structure is anchored by examples or schema.","explanation":"Correct. Temperature governs randomness in token choice; structural consistency comes from showing the format with examples or enforcing it with a schema."},{"key":"C","text":"No — temperature has no measurable effect on output structure or word choice in practice.","explanation":"Temperature clearly affects word choice and variability, so \"no measurable effect\" is wrong."},{"key":"D","text":"Yes — provided a sufficiently detailed system prompt accompanies the temperature setting.","explanation":"A detailed prompt helps, but the mental model in the stem is still mistaken about what temperature controls."}],"correct":"B","tiebreaker":"Domain 4 core concept: temperature ≠ structural consistency guarantee.","rationale":"Temperature reduces randomness in word choice, not structural adherence — format consistency needs to be anchored by examples or schema, not just a lower temperature. Claiming temperature alone guarantees consistency overstates it; claiming it has no effect understates it.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.2 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-064","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.2"],"objectives":["O24","O29"],"stem":"A team is deciding how to supply few-shot examples: as several separate prior user/assistant turns in the conversation, or as inline examples within a single system or user message. Is one approach definitively required?","options":[{"key":"A","text":"Yes — few-shot examples only take effect when supplied as separate prior conversation turns.","explanation":"Prior turns are one effective placement, not a requirement; inline examples work too."},{"key":"B","text":"No — both placements work; inline examples in one message are often simpler for single-turn tasks.","explanation":"Correct. Both placements work. Inline examples are often simpler for single-turn tasks, while separate turns can suit ongoing dialogue."},{"key":"C","text":"Yes — examples only work when embedded directly inside the system prompt, never elsewhere.","explanation":"Examples are not restricted to the system prompt; they're effective in a user message too."},{"key":"D","text":"No — few-shot examples have no measurable influence on the model's behavior either way.","explanation":"Few-shot examples demonstrably influence output format — that is why they're the standard fix for format drift."}],"correct":"B","tiebreaker":"Domain 4 core concept: few-shot examples can be placed inline or as turns — both are valid.","rationale":"Both placements are legitimate; inline examples in one message are frequently simpler for single-turn, stateless tasks, while conversation-turn examples can suit ongoing dialogues. The other options impose an unnecessary hard rule or are simply factually wrong about whether examples influence behavior.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.2 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Prompting best practices","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-065","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.5"],"objectives":["O23"],"family":"batch-vs-sync","stem":"A team wants to cut API costs, so they route their live customer-facing chat widget's requests through the Batch API for the discount. Users now wait unpredictably long for replies. What's the architectural error?","options":[{"key":"A","text":"The Batch API should never be used for blocking, real-time, user-facing requests.","explanation":"Correct. The Batch API trades turnaround time for a discount, which is fine for offline bulk work and never fine for a user waiting on a live reply."},{"key":"B","text":"The batch size is too large; smaller batches would respond faster.","explanation":"Batch turnaround isn't a function of batch size; smaller batches don't make it a real-time path."},{"key":"C","text":"They should have used prompt caching instead to reduce cost with no latency penalty.","explanation":"Caching is a sound cost lever and would help here generally, but it isn't what makes routing live chat through batch processing wrong."},{"key":"D","text":"They need to increase max_tokens so responses complete in fewer round-trips.","explanation":"max_tokens affects response length, not when the batch is processed."}],"correct":"A","tiebreaker":"Always Wrong: Batch API for blocking tasks.","rationale":"Batch API for blocking tasks is Always Wrong, no exceptions — it trades latency guarantees for a cost discount, fine for offline bulk work, never fine for a live user. Batch size tuning doesn't change the fundamental turnaround-time model of the Batch API; caching is a reasonable cost lever in general but doesn't correct this specific architectural mismatch.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.5 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Batch processing","url":"https://platform.claude.com/docs/en/build-with-claude/batch-processing","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-066","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"ci","scenario":"Claude Code for Continuous Integration","scenarioContext":null,"domains":["d4"],"taskStatements":["4.6"],"objectives":["O24","O28"],"family":"review-pass-split","stem":"You ask Claude Code to review a 14-file pull request for style and security issues in a single pass. The review flags issues in some files but misses similar issues in others, and severity language isn't consistent across the report. What should you change?","options":[{"key":"A","text":"Ask for a stricter system prompt with the full standards list enumerated inside it for every file.","explanation":"Enumerating the full standards list still asks one pass to hold fourteen files to a consistent bar, which is the thing that degraded."},{"key":"B","text":"Run one review pass per file, then a separate integration pass that checks cross-file consistency.","explanation":"Correct. A pass per file keeps attention on one file's code, and a separate integration pass is where cross-file consistency and severity wording get normalised."},{"key":"C","text":"Reduce the PR to fewer files per review run so a single pass can hold all of them consistently.","explanation":"Shrinking the PR sidesteps the problem rather than solving it; real pull requests are this size."},{"key":"D","text":"Increase max_tokens so the single pass has enough room to treat all fourteen files thoroughly.","explanation":"Room to write was never the constraint — the inconsistency is in coverage and judgement, not output length."}],"correct":"B","tiebreaker":"First Step Trap: Large multi-file review inconsistency → per-file passes + integration pass.","rationale":"Large multi-file reviews degrade in a single pass — per-file passes plus an integration pass is the documented fix, not more instructions or more tokens. Adding rules or tokens tries to brute-force a structural problem with more of the same approach; reducing the PR avoids the problem instead of solving it for realistic sizes.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.6 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-067","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d5"],"taskStatements":["5.3"],"objectives":[],"stem":"A search tool legitimately returns zero matching records for a query. The agent proceeds to tell the user \"Done — found your record,\" treating the empty result as if it were a successful lookup. What's the correct handling?","options":[{"key":"A","text":"Treat the empty result as success, since the call itself didn't error.","explanation":"A call that succeeds technically and a call that found nothing are different outcomes; conflating them is how \"found your record\" gets said about no record."},{"key":"B","text":"Check explicitly for the zero-result case and report it as an outcome distinct from success.","explanation":"Correct. Zero results is a third case alongside data and error, and handling it explicitly is what lets the agent say nothing matched instead of inventing success."},{"key":"C","text":"Retry the same query immediately, on the assumption the empty result was a transient lookup failure.","explanation":"The stem says the empty result is legitimate, so an immediate retry returns the same nothing at extra cost."},{"key":"D","text":"Fall back to the most recent cached result so the agent still has something usable to work with.","explanation":"Substituting a cached record answers about a different record entirely — a confidently wrong answer."}],"correct":"B","tiebreaker":"Always Wrong: return empty as success.","rationale":"Empty is a distinct outcome from both success-with-data and error — it needs its own explicit handling, not folded into 'success.' Treating empty as success is Always Wrong on this exam; retrying blindly or silently substituting stale data doesn't help and can mislead.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.3 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-068","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d5"],"taskStatements":["5.2"],"objectives":[],"stem":"A downstream API is intermittently flaky. An agent hits a transient error and retries the same call over and over with no limit, burning time and cost. What should the retry logic include?","options":[{"key":"A","text":"Unbounded retries, repeating the call until the flaky downstream service eventually responds.","explanation":"Unbounded retries against a flaky service burn time and cost with no point at which anyone is told."},{"key":"B","text":"Bounded retries with backoff, plus an explicit fallback or escalation once the limit is hit.","explanation":"Correct. A bounded count with backoff gives a transient fault room to clear without hammering the service, and the fallback defines what happens when it doesn't."},{"key":"C","text":"No retries at all, surfacing the failure immediately the first time the call does not succeed.","explanation":"Failing on the first error throws away the easy win: transient faults usually clear on the next attempt."},{"key":"D","text":"Immediate tool substitution, switching to a different tool after a single failure.","explanation":"Switching tools after one failure abandons the right tool for a momentary blip, and the substitute may not do the same job."}],"correct":"B","tiebreaker":"Domain 5 core concept: bounded retry + backoff + explicit fallback, not infinite retry.","rationale":"Bounded retries with backoff, plus a defined fallback once exhausted, is the reliable pattern — neither infinite retry nor zero retry serves a genuinely transient failure well. Retrying forever wastes resources indefinitely; giving up immediately is too brittle for a transient (not permanent) failure.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.2 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-069","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d5"],"taskStatements":["5.1"],"objectives":["O18","O21"],"stem":"A team pastes their entire 800-page product documentation into the context of every request, hoping the model will find the relevant section. Responses are slow, expensive, and sometimes miss the right section anyway. What's the better context strategy?","options":[{"key":"A","text":"Retrieval — only the passages relevant to each query are pulled into context.","explanation":"Correct. Retrieval sends only the passages relevant to the query, which cuts cost and latency and improves the odds the right section is actually attended to."},{"key":"B","text":"A larger context window — the full 800 pages are kept, with more room to hold them.","explanation":"A larger window accommodates the 800 pages rather than fixing the cost, the latency, or the misses caused by burying the relevant section."},{"key":"C","text":"Whitespace compression — the same documentation is pasted after stripping formatting.","explanation":"Stripping formatting trims a little volume and leaves the fundamental problem — nearly all the content is irrelevant to any one query."},{"key":"D","text":"Model-side skimming — the whole document is sent with an instruction to skip to what matters.","explanation":"Instructing the model to skim still sends and pays for everything, and relies on the same attention that is already missing sections."}],"correct":"A","tiebreaker":"Domain 5 core concept: retrieval over full-context stuffing for large corpora.","rationale":"Retrieval — pulling in only what's relevant per query — is the right strategy for large corpora, rather than stuffing everything in every time. A bigger window repeats the Usually Wrong 'bigger window fixes it' instinct; the other options don't meaningfully address the retrieval problem.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.1 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-070","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d5"],"taskStatements":["5.4"],"objectives":["O09","O17","O20"],"family":"exploration-drift","stem":"A long-running coding agent task spans many hours and many tool calls. Partway through, it starts making decisions that contradict choices it made earlier in the same run. What context strategy directly helps here?","options":[{"key":"A","text":"A larger context window so the full run history stays available and nothing needs summarizing at all.","explanation":"A larger window keeps more history available but doesn't make the earlier decisions salient; they're still buried under hours of tool output."},{"key":"B","text":"A scratchpad file where the agent records key decisions and progress, and re-reads as it continues.","explanation":"Correct. An explicit scratchpad the agent writes decisions to and re-reads keeps those commitments in front of it, independent of how long the transcript grows."},{"key":"C","text":"Periodic restarts from a clean slate, so accumulated drift never has a chance to compound over hours.","explanation":"Restarting clean discards the progress and the decisions, so the contradictions get worse rather than better."},{"key":"D","text":"A reduced tool-call budget, so less intermediate output accumulates and crowds out earlier decisions.","explanation":"Fewer tool calls slows the accumulation slightly but offers no mechanism for remembering what was already decided."}],"correct":"B","tiebreaker":"Domain 5 core concept: note-taking/scratchpad as a context strategy for long-running tasks.","rationale":"An explicit scratchpad/notes file the agent maintains and re-reads is a direct fix for losing track of earlier decisions over a long run. A bigger window is the familiar Usually Wrong instinct; restarting loses all progress, and limiting tool calls doesn't address the memory issue at all.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.4 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-071","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d5"],"taskStatements":["5.1"],"objectives":["O18","O21"],"stem":"A developer is nervous that a 40,000-token request will overwhelm the model, given a 200K token context window. Is this concern well-founded on token count alone?","options":[{"key":"A","text":"Yes — at 40,000 tokens the request is large enough that quality degrades on token count alone.","explanation":"40K of 200K is well inside the window; the number alone doesn't predict degradation."},{"key":"B","text":"Not on token count alone — 40K sits comfortably inside 200K; relevance and structure matter more.","explanation":"Correct. 40K sits comfortably within 200K, so what matters is whether that content is relevant and well-organised, not the raw count."},{"key":"C","text":"Yes — context windows above 32,000 tokens are unreliable across all current models.","explanation":"There is no general reliability cliff at 32K across current models."},{"key":"D","text":"No — request size has no bearing on output quality as long as it fits inside the context window.","explanation":"Size isn't irrelevant either — irrelevant bulk does dilute attention, which is why the answer is about relevance and structure rather than \"never matters.\""}],"correct":"B","tiebreaker":"Domain 5 core concept: 200K context window — size alone isn't usually the real risk factor.","rationale":"40K tokens is comfortably within a 200K window — the real risk factors are how well-organized and relevant that content is, not the raw count relative to the ceiling. The other options state incorrect numeric thresholds or overcorrect into 'size never matters,' which isn't accurate either.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.1 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-072","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.2"],"objectives":[],"stem":"An agent is designed to skip human review whenever it reports being above 90% confident in its own answer. In practice, it reports high confidence on answers that turn out to be wrong almost as often as ones that turn out right. What does this suggest?","options":[{"key":"A","text":"The confidence threshold should be raised from 90% to 99% so only near-certain answers skip review.","explanation":"Raising the bar on a signal that doesn't track correctness just moves where the miscalibration bites."},{"key":"B","text":"Self-reported confidence is a poorly-calibrated signal and shouldn't be the basis for skipping review.","explanation":"Correct. Confidence that is high almost as often when wrong as when right carries no information, so it can't be the gate for skipping review."},{"key":"C","text":"The model should be instructed to report its confidence more conservatively and honestly.","explanation":"Asking for more honest confidence assumes the model can introspect its own accuracy, which is the capability in question."},{"key":"D","text":"Confidence reporting is working as intended; the review process itself is what needs redesigning.","explanation":"Confidence is not working as intended: the stem reports it failing to discriminate right answers from wrong ones."}],"correct":"B","tiebreaker":"Usually Wrong: self-reported confidence — poorly calibrated.","rationale":"Self-reported confidence is on the Usually Wrong list specifically because it's poorly calibrated — raising the threshold doesn't fix a fundamentally unreliable signal. Just moving the dial or asking for more honesty doesn't address the calibration problem itself.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.2 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-073","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d5"],"taskStatements":["5.4"],"objectives":["O09","O17","O20"],"stem":"A long support conversation is approaching a length where quality is starting to degrade, but the early parts contain decisions that still matter later. What's a better strategy than simply truncating the oldest messages?","options":[{"key":"A","text":"Compaction — older context is condensed so its substance survives in shorter form.","explanation":"Correct. Compaction condenses the older turns so the decisions that still matter survive in shorter form, instead of being thrown away."},{"key":"B","text":"Truncation — the oldest half of the conversation is deleted outright.","explanation":"Deleting the oldest half discards exactly the early decisions the stem says still matter."},{"key":"C","text":"Model switching — the conversation moves mid-stream to a larger-window model.","explanation":"A larger window defers the same problem and doesn't condense anything; the conversation keeps growing."},{"key":"D","text":"Restarting — the user opens a new conversation and re-supplies the earlier details.","explanation":"Restarting puts the burden on the user to re-supply context the system should have retained."}],"correct":"A","tiebreaker":"Domain 5 core concept: compaction/summarization preserves key context better than truncation.","rationale":"Compaction preserves the substance of older context in condensed form, rather than losing it outright or dodging the problem. Deleting the oldest half risks losing decisions that still matter; switching models or restarting doesn't solve the underlying context-management problem.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.4 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-074","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d5"],"taskStatements":["5.2"],"objectives":[],"stem":"Your logistics tracking agent occasionally hits a genuinely ambiguous shipment that no amount of retrying will resolve — it's a judgment call, not a transient error. What should distinguish this from a retryable failure?","options":[{"key":"A","text":"Both kinds of failure should just be retried the same way, up to the same fixed limit.","explanation":"One retry loop for both treats a judgment call as a technical blip: it retries what can never succeed and escalates nothing."},{"key":"B","text":"An explicit criterion separating \"transient, retry it\" from \"needs human judgment, escalate it.\"","explanation":"Correct. The two failures need different paths, so the design needs a stated test for which one it is — retry the transient, escalate the judgment call."},{"key":"C","text":"Always escalate first, and only retry afterward if a human explicitly says to.","explanation":"Escalating first sends every transient blip to a human, which wastes their time on faults that clear by themselves."},{"key":"D","text":"Always retry first, and only escalate once every possible retry has failed, regardless of the failure's nature.","explanation":"Exhausting retries first delays every genuine judgment call by the full retry budget before a human ever sees it."}],"correct":"B","tiebreaker":"Domain 5 core concept: distinguish retryable failures from judgment-call escalations explicitly.","rationale":"Transient technical failures and genuine judgment calls are different problems and need different explicit handling — collapsing them into one retry loop under-serves both. The other options impose a rigid universal order that ignores what kind of failure actually occurred.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.2 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-075","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.3"],"objectives":[],"stem":"An agent's workflow depends on a third-party enrichment tool that's temporarily unavailable. The rest of the task doesn't strictly require that enrichment to produce a useful (if less complete) result. What's the better reliability design?","options":[{"key":"A","text":"Fail the entire task immediately whenever any single tool is unavailable, regardless of whether it's essential.","explanation":"Failing the whole task for a non-essential dependency denies the user a result that would have been useful."},{"key":"B","text":"Design for graceful degradation, returning the partial result with the gap flagged.","explanation":"Correct. Graceful degradation returns the useful part and flags what's missing, which beats all-or-nothing when the absent piece isn't essential."},{"key":"C","text":"Retry the unavailable tool indefinitely until it comes back.","explanation":"Indefinite retries hold the whole task hostage to an enrichment step it doesn't strictly need."},{"key":"D","text":"Silently substitute fabricated data for the missing enrichment so the output looks complete.","explanation":"Fabricating the missing data is the worst outcome: the output looks complete and is quietly wrong."}],"correct":"B","tiebreaker":"Domain 5 core concept: graceful degradation for non-essential dependency failures.","rationale":"Graceful degradation — proceeding with a flagged, partial result — serves users better than an all-or-nothing failure when the missing piece isn't strictly essential. Retrying indefinitely wastes time on a non-essential dependency; fabricating data is far worse than failing, since it produces misleading output.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.3 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-076","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d5"],"taskStatements":["5.3"],"objectives":[],"stem":"A downstream service has been failing on every call for the last five minutes straight. The agent keeps calling it at the same rate as if nothing were wrong, adding load to an already-struggling service. What pattern addresses this?","options":[{"key":"A","text":"A circuit breaker — calls stop after repeated failures, then retry after a cool-down.","explanation":"Correct. A circuit breaker opens after repeated failures so calls stop, fail fast or fall back, and resume only after a cool-down lets the service recover."},{"key":"B","text":"Retry acceleration — the call rate increases so a success lands sooner on recovery.","explanation":"Calling faster adds load to a service that is already failing, making recovery less likely."},{"key":"C","text":"Permanent failover — the agent switches to a different tool and never returns.","explanation":"Never returning abandons the dependency permanently over an outage that may last minutes."},{"key":"D","text":"Passive continuation — calls proceed at the same rate until the service recovers.","explanation":"Continuing at the same rate is the behaviour described in the stem — it's the problem, not the fix."}],"correct":"A","tiebreaker":"Domain 5 core concept: circuit breaker pattern for repeated downstream failures.","rationale":"A circuit breaker is exactly the pattern for this: stop hammering a clearly-failing dependency, fail fast or fall back, and check again after a cool-down. Increasing retry rate makes the problem worse by adding load; ignoring it passively harms the already-struggling service further.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.3 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-077","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d1"],"taskStatements":["1.4"],"objectives":["O08"],"stem":"Telemetry shows that in roughly one in eight conversations, the agent calls lookup_order directly from a stated customer name, bypassing get_customer entirely. A few of these cases have resulted in refunds issued against the wrong account. What change would most reliably close this gap?","options":[{"key":"A","text":"Add a programmatic prerequisite that blocks lookup_order and process_refund until get_customer has returned a verified customer ID.","explanation":"Correct. A programmatic prerequisite makes the sequence structural: without a verified customer ID, lookup_order and process_refund cannot run, so the skip path no longer exists."},{"key":"B","text":"Update the system prompt to state that identity verification is mandatory before any order tool call.","explanation":"A mandatory-sounding system prompt is still an instruction, and one in eight is what a high-but-imperfect compliance rate looks like."},{"key":"C","text":"Add few-shot examples showing the agent always verifying identity first, even when the customer offers order details unprompted.","explanation":"Few-shot examples shift the odds without closing the path; money moving against the wrong account needs a guarantee."},{"key":"D","text":"Add a routing classifier that decides which tools are available for a given request type before the agent starts.","explanation":"A routing classifier controls which tools are available for a request, not the order in which they must be called within one."}],"correct":"A","tiebreaker":"Official Exam Guide: deterministic prerequisite gates for identity-sensitive sequencing (Task 1.4).","rationale":"A hard prerequisite gate guarantees the sequence — no prompt-based approach can promise that, since compliance stays probabilistic. The prompt and few-shot options reduce but don't eliminate the skip rate; a routing classifier controls which tools exist, not the order they must be called in.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.4 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-078","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.1"],"objectives":["O36"],"stem":"get_customer and lookup_order both have minimal one-line descriptions and accept similar identifier formats. When users ask things like 'check my order #12345,' the agent frequently calls get_customer instead of lookup_order. What's the most effective first step to fix this?","options":[{"key":"A","text":"Add 5-8 few-shot examples to the system prompt showing order-related phrasing routed to lookup_order.","explanation":"Examples help the model generalise, but they're compensating for descriptions that never stated each tool's scope — more tokens, same ambiguity at the root."},{"key":"B","text":"Rewrite each tool's description to include input formats, example queries, edge cases, and clear boundaries versus similar tools.","explanation":"Correct. Descriptions are the model's primary signal at selection time; stating input formats, example queries and the boundary against the similar tool is what makes the choice decidable."},{"key":"C","text":"Add a pre-processing routing layer that inspects the message for keywords and pre-selects the tool before the model runs.","explanation":"A keyword router replaces the model's reasoning with brittle string matching and is over-engineered as a first step."},{"key":"D","text":"Merge both tools into a single generic lookup tool that infers the correct backend from the query itself.","explanation":"Merging two genuinely distinct lookups makes one vague tool and pushes the same disambiguation problem inside it."}],"correct":"B","tiebreaker":"Official Exam Guide: tool description quality is the primary tool-selection signal (Task 2.1).","rationale":"Tool descriptions are the model's primary signal for tool selection — thin descriptions on similar tools are close to a coin flip. Few-shot examples add tokens without fixing the root cause; a keyword router bypasses the model's own reasoning and is over-engineered for a first step; merging tools is more invasive than a first move calls for.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.1 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Define tools (descriptions, tool_choice)","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-079","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d5"],"taskStatements":["5.2"],"objectives":[],"stem":"First-contact resolution sits at 55% against an 80% target. Reviewing transcripts, the agent escalates straightforward damage-replacement requests that already have photo evidence, while attempting to resolve cases that actually require a policy exception on its own. What's the most effective way to fix the escalation calibration?","options":[{"key":"A","text":"Add explicit escalation criteria to the system prompt, with few-shot examples for borderline cases.","explanation":"Correct. The agent is mis-drawing the line between routine and exception, so stating the criteria and showing borderline cases fixes the boundary itself, with no new infrastructure."},{"key":"B","text":"Have the agent self-report a 1–10 confidence score and escalate automatically below a set threshold.","explanation":"A self-reported score is least reliable exactly on the ambiguous cases that drive this gap."},{"key":"C","text":"Train a separate classifier on historical tickets to pre-screen which requests need escalation.","explanation":"A trained classifier is substantial infrastructure for a boundary that has never been written down clearly."},{"key":"D","text":"Add sentiment analysis and escalate automatically once detected frustration crosses a threshold.","explanation":"Frustration doesn't track policy complexity — a calm request can need an exception and an irate one can be routine."}],"correct":"A","tiebreaker":"Official Exam Guide: explicit escalation criteria + few-shot beats self-confidence, sentiment, or a bolted-on classifier (Task 5.2).","rationale":"Explicit, concrete criteria plus examples is the proportionate first fix for unclear decision boundaries — no new infrastructure required. Self-reported confidence is poorly calibrated precisely on the hard cases where it matters most; a separate classifier is real infrastructure for a problem prompt design hasn't been given a chance to fix yet; sentiment doesn't track policy complexity, which is the actual issue.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.2 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-080","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.2"],"objectives":["O14","O16"],"stem":"You're building a custom /review slash command that runs your team's standard review checklist, and you want it available to every developer automatically when they clone or pull the repository. Where should the command file live?","options":[{"key":"A","text":".claude/commands/ inside the project repository.","explanation":"Correct. Commands in .claude/commands/ are committed with the repo, so every developer has /review as soon as they clone or pull."},{"key":"B","text":"~/.claude/commands/ in each developer's home directory.","explanation":"The home-directory path is personal and never travels through git, so only that one developer gets it."},{"key":"C","text":"Inside the project's CLAUDE.md file.","explanation":"CLAUDE.md carries context and instructions; it isn't where command definitions live."},{"key":"D","text":"A .claude/config.json commands array.","explanation":"There is no commands array in .claude/config.json for this."}],"correct":"A","tiebreaker":"Official Exam Guide: project-scoped .claude/commands/ for team-wide, version-controlled shortcuts (Task 3.2).","rationale":"Project-scoped commands in .claude/commands/ are version-controlled and ship automatically with the repo — exactly the 'everyone gets it on clone' requirement. The user-level path is personal and never shared via git; CLAUDE.md holds context/instructions, not command definitions; there's no such config.json commands mechanism.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.2 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code skills","url":"https://code.claude.com/docs/en/skills","type":"docs"}],"note":"Answer per the exam guide. In current Claude Code, custom commands have been merged into skills: a file in .claude/commands/ and a skill in .claude/skills/ both create a /name command, and skills can additionally load automatically when relevant.","corroborated":[]},
{"id":"REF-081","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d3"],"taskStatements":["3.4"],"objectives":["O08"],"stem":"You've been asked to restructure a monolithic application into microservices, which will span dozens of files and require decisions about service boundaries and module dependencies. What's the right approach?","options":[{"key":"A","text":"Enter plan mode to explore the codebase and propose an approach before any changes are made.","explanation":"Correct. Service boundaries and module dependencies across dozens of files are decisions worth reviewing before any code moves — which is what plan mode is for."},{"key":"B","text":"Start with direct execution and let the natural service boundaries emerge as you go.","explanation":"Letting boundaries emerge mid-execution means discovering a wrong split after files have already been restructured around it."},{"key":"C","text":"Use direct execution, but write extremely detailed upfront instructions covering exactly how to structure each service.","explanation":"Exhaustive upfront instructions assume you already know the right structure; determining it is the actual task."},{"key":"D","text":"Start in direct execution and only switch to plan mode if unexpected complexity shows up.","explanation":"The complexity isn't unexpected — it's stated in the request, so there's nothing to wait for."}],"correct":"A","tiebreaker":"Official Exam Guide: plan mode for multi-file, architecturally-significant work (Task 3.4).","rationale":"Large-scale, multi-file, architecturally-significant work is exactly what plan mode exists for — propose and review before committing to changes across dozens of files. Letting boundaries 'emerge' during direct execution risks expensive rework once dependencies surface; exhaustive upfront instructions assume you already know the right structure; waiting for 'unexpected' complexity ignores that the complexity is already known from the request itself.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.4 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code permission modes (plan mode)","url":"https://code.claude.com/docs/en/permission-modes","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-082","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.1"],"objectives":["O13","O16"],"family":"rules-glob-scattered","stem":"Different areas of your codebase already follow different conventions (functional React components, async/await API handlers, repository-pattern database models), and test files are interspersed throughout rather than centralized. You want Claude to automatically apply the right convention based on what it's editing, without manual invocation. What's the most maintainable setup?","options":[{"key":"A","text":".claude/rules/ files with YAML frontmatter glob patterns that scope each convention to matching file paths.","explanation":"Correct. Glob-scoped rules match on the path of the file being edited, so the right convention applies automatically even with test files scattered across directories."},{"key":"B","text":"One root CLAUDE.md with a section per area, trusting Claude to infer which section applies.","explanation":"One root file leaves the model to infer which section applies, which is the manual judgement the requirement rules out."},{"key":"C","text":"A skill per code area, with each area's conventions written into its own SKILL.md and loaded on demand.","explanation":"Skills load on relevance rather than on which file is being edited, so the match is looser than a path glob."},{"key":"D","text":"A separate CLAUDE.md placed in every subdirectory that needs its own distinct set of conventions.","explanation":"Directory-bound files can't follow conventions that apply to files interspersed throughout the tree."}],"correct":"A","tiebreaker":"Official Exam Guide: .claude/rules/ glob-pattern scoping for conventions that cut across directory structure (Task 3.3).","rationale":"Glob-scoped rules apply automatically based on the file being touched, regardless of which directory it lives in — exactly what scattered test files need. A single root file relies on inference rather than explicit matching; skills load on relevance to the task rather than on the path of the file being edited; directory-bound CLAUDE.md files can't reach files spread across many directories.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.1 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code memory (CLAUDE.md and .claude/rules/)","url":"https://code.claude.com/docs/en/memory","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-083","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.2"],"objectives":["O04","O10"],"family":"decomposition-gap","stem":"A multi-agent research run on 'the impact of AI on creative industries' completes without errors: web search, document analysis, and synthesis all report success. But the final report covers only visual arts — no music, writing, or film. The coordinator's logs show it split the topic into three subtasks: AI in digital art, AI in graphic design, and AI in photography. What's the most likely root cause?","options":[{"key":"A","text":"The synthesis agent has no instructions for detecting coverage gaps in the material it receives.","explanation":"Synthesis can only combine what was gathered; no instruction to detect gaps conjures music or film research nobody did."},{"key":"B","text":"The coordinator's task decomposition was too narrow, so no subagent was ever assigned the other creative domains.","explanation":"Correct. The logs show all three subtasks were visual-arts topics, so every agent succeeded at its brief and the omission was built into the split."},{"key":"C","text":"The web search agent's queries need broadening to reach more of the creative sector's coverage.","explanation":"Broader queries would help if an agent had been assigned those domains — none was."},{"key":"D","text":"The document analysis agent's relevance filtering is excluding non-visual sources too aggressively.","explanation":"Over-aggressive filtering would discard gathered sources; here the other domains were never searched for."}],"correct":"B","tiebreaker":"Official Exam Guide: coverage gaps in multi-agent output trace to coordinator decomposition (Task 1.2).","rationale":"The logs show the actual assignments — three visual-arts subtasks and nothing else. Every subagent did exactly what it was told; the gap is in what it was told, not in how it executed. Blaming search queries or relevance filtering assumes those agents received a broader mandate they didn't get; synthesis can't cover ground that was never gathered.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.2 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-084","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.3"],"objectives":[],"stem":"The web search subagent times out mid-task. You need to decide how that failure gets reported back to the coordinator so it can recover intelligently. Which approach is best?","options":[{"key":"A","text":"Return structured error context: failure type, the query that was attempted, any partial results gathered, and possible alternative approaches.","explanation":"Correct. Naming the failure type, the attempted query, any partial results and viable alternatives gives the coordinator what it needs to retry differently, route elsewhere or proceed partially."},{"key":"B","text":"Retry with backoff inside the subagent, and only report a generic \"search unavailable\" status once retries are exhausted.","explanation":"Silent retries followed by \"search unavailable\" discard the detail that would inform recovery."},{"key":"C","text":"Catch the timeout and return an empty result set marked successful, so the downstream pipeline continues without stalling.","explanation":"Reporting an empty result as success turns a known failure into a silent coverage gap downstream."},{"key":"D","text":"Let the timeout propagate to a top-level handler that terminates the run and reports the failure upward.","explanation":"Killing the whole run over one subagent's timeout throws away the work the other agents completed."}],"correct":"A","tiebreaker":"Official Exam Guide: structured error context enables coordinator recovery; generic status, false success, and full termination are anti-patterns (Task 5.3).","rationale":"Structured context — what failed, what was tried, what's already in hand, what else could work — is what actually lets the coordinator make a good recovery decision. A generic status after silent retries throws away exactly the detail that would help; marking empty as success hides a real failure; terminating the whole run over one subagent's timeout discards otherwise-usable partial work.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.3 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-085","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d2"],"taskStatements":["2.3"],"objectives":["O05","O27","O33","O37"],"stem":"The synthesis agent frequently needs to verify small facts while combining findings, and today that means bouncing back to the coordinator, which invokes the web search agent, then re-invokes synthesis — 2-3 extra round trips per task, adding real latency. Evaluation shows 85% of these are simple lookups (dates, names, numbers) and 15% genuinely need deeper research. What's the best fix?","options":[{"key":"A","text":"Give the synthesis agent a narrowly-scoped verify_fact tool for simple lookups, keeping the harder 15% routed through the coordinator.","explanation":"Correct. A narrow verify_fact tool makes the common 85% a single local call while the genuinely hard 15% still goes through the coordinator, so the fast path gets faster without loosening role boundaries."},{"key":"B","text":"Have synthesis batch every verification need and send them to the coordinator as a single consolidated request at the end of its pass.","explanation":"Batching at the end breaks down when one verification determines whether another is needed."},{"key":"C","text":"Give the synthesis agent full access to the web search agent's toolset so it never has to round-trip through the coordinator at all.","explanation":"Handing synthesis the full search toolkit dissolves the role separation for the sake of a minority of cases."},{"key":"D","text":"Have the web search agent proactively over-fetch context on every source up front, anticipating what synthesis might later need to check.","explanation":"Speculative over-fetching pays to gather context that mostly goes unused and still misses what wasn't anticipated."}],"correct":"A","tiebreaker":"Official Exam Guide: a narrowly-scoped tool for the high-frequency simple case, coordinator still owns the hard cases (Task 2.3).","rationale":"A scoped tool for the common, simple case keeps the fast path fast while preserving the existing, safer coordination pattern for the genuinely hard 15%. Batching creates ordering problems when later verifications depend on earlier ones; giving synthesis the full search toolkit blurs role boundaries it doesn't need; pre-fetching everything speculatively can't reliably predict what will actually be needed.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.3 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-086","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.6"],"objectives":["O11","O13","O15","O30"],"family":"ci-print-flag","stem":"A pipeline step runs Claude Code with a security-review prompt, and the job hangs indefinitely — logs show it's waiting on interactive input. What's the correct way to run Claude Code in an automated, non-interactive pipeline?","options":[{"key":"A","text":"Add the -p (print) flag, which runs the prompt non-interactively and exits after printing the result.","explanation":"Correct. -p / --print runs the prompt non-interactively and exits, which is precisely what an automated pipeline needs."},{"key":"B","text":"Set a CLAUDE_HEADLESS=true environment variable before running the Claude Code command.","explanation":"There is no CLAUDE_HEADLESS environment variable."},{"key":"C","text":"Redirect stdin from /dev/null when invoking the Claude Code command in the pipeline.","explanation":"Redirecting stdin may make the process fail rather than hang, but it doesn't put the CLI in a mode designed for unattended use."},{"key":"D","text":"Add a --batch flag so the command runs in batch mode and exits without waiting for interaction.","explanation":"There is no --batch flag on Claude Code."}],"correct":"A","tiebreaker":"Official Exam Guide: -p / --print flag for non-interactive Claude Code runs; watch for fake-sounding distractor flags (Task 3.6).","rationale":"-p / --print is the documented non-interactive mode — it runs the prompt, prints the result, and exits without waiting on input, exactly the CI requirement. There's no CLAUDE_HEADLESS environment variable or --batch flag in Claude Code, and redirecting stdin is a Unix workaround that doesn't properly address the actual interactive-mode behavior.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.6 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Run Claude Code programmatically (headless)","url":"https://code.claude.com/docs/en/headless","type":"docs"},{"title":"Claude Code CLI reference","url":"https://code.claude.com/docs/en/cli-reference","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-087","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.5"],"objectives":["O23"],"family":"batch-vs-sync","stem":"Two workflows currently run on real-time Claude calls: a blocking pre-merge check developers wait on, and an overnight technical-debt report reviewed the next morning. Your manager proposes moving both to the Message Batches API for its 50% cost savings. How should you evaluate this?","options":[{"key":"A","text":"Move the overnight report to Batch; keep the pre-merge check on real-time calls.","explanation":"Correct. The overnight report has no one waiting on it, so the batch window is free savings; the pre-merge check blocks a developer, so it needs the latency guarantee real-time calls give."},{"key":"B","text":"Move both to Batch, and add status polling so each workflow knows when its results are ready.","explanation":"Polling reports when results arrive but doesn't make them arrive sooner — the developer still waits an unbounded time."},{"key":"C","text":"Keep both on real-time calls, since Batch result ordering would be too unpredictable either way.","explanation":"Result correlation is handled by custom_id, so ordering isn't the obstacle; the overnight report is a good fit for batch."},{"key":"D","text":"Move both to Batch, with a fallback to real-time calls if a batch takes too long.","explanation":"A real-time fallback rebuilds the real-time path anyway, with extra complexity, when routing each workflow correctly up front is simpler."}],"correct":"A","tiebreaker":"Official Exam Guide: Batch API for latency-tolerant, non-blocking workloads only (Task 4.5).","rationale":"Batch trades cost for a processing window up to 24 hours with no latency guarantee — fine for a report nobody's waiting on live, wrong for a check that blocks a developer's merge. Polling doesn't change the lack of a latency guarantee; result correlation is handled by custom_id, so ordering isn't the real risk; a real-time fallback adds complexity where matching each workflow to the right API in the first place is simpler.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.5 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Batch processing","url":"https://platform.claude.com/docs/en/build-with-claude/batch-processing","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-088","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"ci","scenario":"Claude Code for Continuous Integration","scenarioContext":null,"domains":["d4"],"taskStatements":["4.6"],"objectives":["O24","O28"],"family":"review-pass-split","stem":"A 14-file pull request reviewed in a single pass comes back inconsistent: some files get detailed feedback, others get superficial comments, and the same pattern is flagged as a problem in one file but approved in another. How should the review be restructured?","options":[{"key":"A","text":"Run a focused pass per file for local issues, then a separate integration pass that specifically looks at cross-file data flow.","explanation":"Correct. Per-file passes keep attention on one file at a time, and a dedicated integration pass is where cross-file data flow and consistent severity wording get handled deliberately."},{"key":"B","text":"Require developers to split any large PR into review batches of three to four files before the automated review runs at all.","explanation":"Pushing the split onto developers works around the review system instead of fixing it."},{"key":"C","text":"Move to a higher-tier model with a bigger context window so all 14 files get equal attention in one pass.","explanation":"A bigger window gives more room, not more even attention; the same dilution recurs."},{"key":"D","text":"Run the full-PR review three times and only keep findings that show up in at least two of the three runs.","explanation":"Keeping only findings that recur in two of three runs discards real issues that surface intermittently — the very inconsistency being complained about."}],"correct":"A","tiebreaker":"Official Exam Guide: per-file + integration pass for large multi-file reviews; bigger models/context don't solve attention dilution (Task 4.6).","rationale":"Splitting into per-file passes plus a dedicated integration pass directly targets the actual cause — attention dilution across many files at once — while still catching cross-file issues on purpose. Pushing PR size limits onto developers doesn't fix the review system itself; a bigger context window doesn't fix attention quality; requiring 2-of-3 consensus would suppress real findings that only show up intermittently.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.6 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-089","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O06"],"family":"coordinator-spawn-tool","stem":"A coordinator agent is designed to delegate to subagents via the Task tool, but every attempt silently fails to spawn anything. The subagent definitions themselves are configured correctly. What's the most likely misconfiguration?","options":[{"key":"A","text":"The coordinator's allowedTools list doesn't include \"Task\", so it can't spawn subagents at all.","explanation":"Correct. Task is the tool that spawns subagents, so if it isn't in the coordinator's allowedTools the capability simply isn't available and attempts go nowhere."},{"key":"B","text":"The subagents themselves must list \"Task\" in their own allowedTools before delegation can occur.","explanation":"A subagent needs Task only if it spawns further subagents; it isn't required to be spawned."},{"key":"C","text":"fork_session has to be called explicitly before any Task invocation will be accepted.","explanation":"fork_session is unrelated to Task delegation and isn't a prerequisite for it."},{"key":"D","text":"AgentDefinition requires a system prompt above a minimum length before the agent activates.","explanation":"There is no minimum system-prompt length gating agent activation."}],"correct":"A","tiebreaker":"Official concept: allowedTools must include \"Task\" for a coordinator to spawn subagents.","rationale":"Task is the mechanism for spawning subagents, and it has to be explicitly present in the coordinator's own allowedTools — without it, delegation isn't available to that agent. Subagents don't need Task in their own list unless they in turn spawn further subagents; fork_session and prompt length aren't related to this failure.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.3 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code subagents","url":"https://code.claude.com/docs/en/sub-agents","type":"docs"},{"title":"Agent SDK: subagents (AgentDefinition)","url":"https://code.claude.com/docs/en/agent-sdk/subagents","type":"docs"}],"note":"Claude Code renamed the Task tool to Agent in version 2.1.63. Existing Task(...) references still work as aliases, so the mechanism this question tests is unchanged; the current name is Agent. In the current Agent SDK, allowedTools is the list of auto-approved tools, and its examples include Agent there so the coordinator can delegate.","corroborated":[]},
{"id":"REF-090","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O05"],"stem":"You want one subagent restricted to read-only file exploration with a narrow system prompt, and another with broader tool access and a different persona. Where does this per-subagent configuration live?","options":[{"key":"A","text":"A single shared CLAUDE.md that every subagent reads identically.","explanation":"A single shared file read identically by every subagent cannot express different tool restrictions per subagent."},{"key":"B","text":"Each subagent's own AgentDefinition, configured separately for each one.","explanation":"Correct. AgentDefinition is the per-subagent surface for description, system prompt and tool restrictions, which is exactly what differs between these two."},{"key":"C","text":"The coordinator's own system prompt, describing every subagent's rules in one place.","explanation":"Describing the rules in the coordinator's prompt states intentions; it doesn't restrict what each subagent can actually do."},{"key":"D","text":"Environment variables set before the session starts.","explanation":"Environment variables are process-wide and aren't the mechanism for per-subagent configuration."}],"correct":"B","tiebreaker":"Official concept: AgentDefinition holds each subagent's description, system prompt, and tool restrictions.","rationale":"AgentDefinition is exactly the per-subagent configuration surface — description, system prompt, and tool restrictions defined individually for each subagent type. A shared CLAUDE.md or one coordinator prompt can't express genuinely different restrictions per subagent as cleanly, and environment variables aren't the mechanism for this.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.3 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code subagents","url":"https://code.claude.com/docs/en/sub-agents","type":"docs"},{"title":"Agent SDK: subagents (AgentDefinition)","url":"https://code.claude.com/docs/en/agent-sdk/subagents","type":"docs"}],"note":"AgentDefinition is the Agent SDK's per-subagent type: description, prompt (the system prompt) and tools (the allowlist), with disallowedTools as a denylist. In Claude Code the same fields are YAML frontmatter in a Markdown file under .claude/agents/. In the current SDK, allowedTools is a session option that auto-approves tools; a subagent's own restriction is its tools field.","corroborated":[]},
{"id":"REF-091","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d1"],"taskStatements":["1.7"],"objectives":["O02","O09"],"stem":"You want to compare two different refactoring strategies starting from the same already-completed codebase analysis, without either exploration affecting the other. Separately, in another project, several files have changed since your last session and the old tool results are now stale. What should you do in each case, respectively?","options":[{"key":"A","text":"fork_session for the comparison case; a fresh session with an injected summary for the stale-results case.","explanation":"Correct. Forking gives both refactoring strategies the same analysis as a baseline without cross-contamination, while stale tool results are better replaced by a fresh session seeded with a summary than carried forward."},{"key":"B","text":"Use --resume in both cases, continuing the original session so all prior context stays available throughout.","explanation":"Resuming the second case keeps the outdated tool results in context, which is the specific problem to avoid."},{"key":"C","text":"Use fork_session in both cases, branching from the same baseline so neither run contaminates the other.","explanation":"Forking the stale case branches the stale results too — the fork inherits exactly what needs discarding."},{"key":"D","text":"Start fresh with no summary in either case, guaranteeing that no stale tool results can mislead the run.","explanation":"Starting fresh with no summary in the first case throws away the completed analysis both strategies are meant to share."}],"correct":"A","tiebreaker":"Official concept: fork_session for divergent exploration from a shared baseline; fresh session + summary beats resuming stale results.","rationale":"Forking is exactly for exploring divergent approaches from one shared baseline; when prior tool results are stale, a fresh session seeded with a structured summary is more reliable than resuming and trusting outdated results. Resuming both would carry stale results into the second case; forking both misapplies forking to a situation that isn't about parallel exploration; starting with zero summary throws away still-useful context.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.7 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Agent SDK: sessions (resume and fork)","url":"https://code.claude.com/docs/en/agent-sdk/sessions","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-092","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d1"],"taskStatements":["1.4"],"objectives":["O08"],"stem":"Your legal contract review agent escalates a contract to a human agent who has zero visibility into the conversation that led there. What should the structured handoff contain so the human can act immediately?","options":[{"key":"A","text":"The customer's full message history, passed through verbatim so the human loses no detail of what was said.","explanation":"Verbatim history makes the human reconstruct the case themselves, which is the work the handoff was supposed to do."},{"key":"B","text":"A root-cause analysis of what the agent couldn't resolve, paired with a recommended next action for the human.","explanation":"Correct. Stating what blocked resolution and what to do next lets the human act immediately instead of reading back through the conversation."},{"key":"C","text":"The model's internal confidence score for its attempted resolution, so the human knows how certain it was.","explanation":"An internal confidence number says nothing about the customer's situation or what the human should do."},{"key":"D","text":"A generic summary of the company policy that applies, so the human starts from the correct rulebook.","explanation":"A generic policy summary is reference material the human already has; it omits this case entirely."}],"correct":"B","tiebreaker":"Official concept: structured handoffs need customer details, root-cause analysis, and a recommended action, not a raw transcript dump.","rationale":"Root cause and a recommended action are exactly what let a human agent act without reconstructing the whole conversation themselves. Raw verbatim history without synthesis defeats the purpose of a handoff summary; an internal confidence score isn't customer- or case-relevant information for a human picking up the case.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.4 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-093","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.2"],"objectives":[],"stem":"Which category of MCP tool failure is the classic candidate for an automatic retry, without any change to the input or a different action?","options":[{"key":"A","text":"transient (timeout/service unavailable)","explanation":"Correct. A timeout or unavailable service says nothing is wrong with the request, so repeating the identical call is often enough."},{"key":"B","text":"validation (malformed input rejected by schema)","explanation":"A schema rejection repeats identically until the input is corrected."},{"key":"C","text":"business (request violates a policy rule)","explanation":"A policy violation is a decision, not a blip; retrying asks the same forbidden thing again."},{"key":"D","text":"permission (caller lacks required access)","explanation":"Missing access persists across attempts — it needs different credentials or an escalation, not a retry."}],"correct":"A","tiebreaker":"Official concept: transient errors are the retry case; validation/business/permission failures need a different response.","rationale":"Transient failures are about momentary unavailability, not anything wrong with the request itself — retrying the same call again is often exactly right. Validation errors need the input fixed first; business and permission failures need a different decision entirely (escalation, alternate path), not more attempts at the same call.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.2 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-094","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d2"],"taskStatements":["2.4"],"objectives":["O34","O35"],"stem":"A team debates whether to expose their documentation hierarchy as an MCP Resource or leave the agent to discover it via exploratory tool calls. What is the primary benefit of exposing it as a Resource?","options":[{"key":"A","text":"It gives the model upfront visibility into available content, cutting down on exploratory tool calls it would otherwise need.","explanation":"Correct. A Resource makes the documentation hierarchy visible up front, so the model can reference what it needs instead of discovering it through exploratory calls."},{"key":"B","text":"It allows the model to modify the underlying documentation directly, keeping the catalog current as it works.","explanation":"Resources are read-only context; they aren't a write path to the documentation."},{"key":"C","text":"It removes the need for any Tools in the same MCP server, since Resources can cover every interaction.","explanation":"Resources supply context and Tools perform actions — a server commonly needs both."},{"key":"D","text":"It requires deprecating the associated Tools once the Resource is added, to avoid duplicate access paths.","explanation":"Adding a Resource doesn't deprecate anything; Resources and Tools serve different purposes side by side."}],"correct":"A","tiebreaker":"Official concept: Resources reduce exploratory tool calls and give upfront visibility into available content.","rationale":"Resources expose content the model can see and reference directly, cutting down on exploratory tool calls and giving upfront visibility into what's available. Resources are read-only context, not a mechanism for modification; a server can and often does mix Resources and Tools — one doesn't replace the need for the other.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.4 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code MCP documentation (scopes, .mcp.json, ${VAR} expansion, @ resources, /mcp)","url":"https://code.claude.com/docs/en/mcp","type":"docs"}],"note":"Answer per the exam guide. How a resource reaches the model depends on the client: in Claude Code, resources are attached when referenced with an @ mention, and Claude can otherwise list and read them through built-in resource tools.","corroborated":[]},
{"id":"REF-095","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.3"],"objectives":["O05","O27","O33","O37"],"stem":"Your pipeline must always run extract_metadata before any enrichment tools touch a document, but you don't want to prevent enrichment tools from being called in later turns. What's the right approach?","options":[{"key":"A","text":"Force tool_choice to extract_metadata for the first turn, then let subsequent turns use auto or any for the enrichment steps.","explanation":"Correct. Forcing the tool only on the turn where the ordering matters gives the guarantee, and relaxing afterwards leaves enrichment free to run in later turns."},{"key":"B","text":"Force tool_choice to extract_metadata on every turn, guaranteeing the ordering constraint always holds.","explanation":"Forcing extract_metadata on every turn means enrichment never gets a turn at all."},{"key":"C","text":"Set tool_choice to \"any\" for the whole conversation and rely on the model to sequence extraction before enrichment correctly.","explanation":"\"any\" requires some tool, not a particular order, so enrichment could still go first."},{"key":"D","text":"Remove the enrichment tools until extract_metadata has been called once, then add them back manually.","explanation":"Adding and removing tools mid-conversation is far more fragile than setting tool_choice per turn."}],"correct":"A","tiebreaker":"Official concept: force a specific tool for one turn to guarantee order, then relax tool_choice afterward.","rationale":"Forcing the specific tool on the turn where order matters, then relaxing tool_choice for later turns, gets the guarantee where it's needed without permanently restricting the conversation. Forcing it every turn would block enrichment from ever running; \"any\" for the whole conversation doesn't guarantee order; manually adding/removing tools mid-conversation is far more fragile than changing tool_choice per turn.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.3 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Define tools (descriptions, tool_choice)","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools","type":"docs"}],"note":"Answer per the exam guide. The current docs list several newer models that reject tool_choice any and named-tool with a 400 error; the documented alternative there is auto with strict: true.","corroborated":[]},
{"id":"REF-096","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.1"],"objectives":["O13","O16"],"stem":"A monorepo has package-specific standards files (api-standards.md, frontend-standards.md, etc.), and you want each package's CLAUDE.md to selectively pull in just the standards relevant to its own domain, without duplicating content. What feature supports this?","options":[{"key":"A","text":"The @import syntax, referencing specific external files from within CLAUDE.md.","explanation":"Correct. @import references an external file from CLAUDE.md, so each package pulls in exactly the standards it needs with the content living in one place."},{"key":"B","text":".claude/rules/ glob patterns, scoping each package's conventions to its matching file paths.","explanation":"Glob rules scope by the path of the file being edited rather than composing shared files into a package's configuration."},{"key":"C","text":"A Skill with context: fork, so each package's standards load in an isolated execution context.","explanation":"context: fork isolates a skill's execution; it doesn't assemble configuration from shared documents."},{"key":"D","text":"The /memory command, used to load each package's conventions on demand as work moves between them.","explanation":"/memory inspects what's loaded; it isn't an authoring or composition mechanism."}],"correct":"A","tiebreaker":"Official concept: @import keeps CLAUDE.md modular by referencing external standards files.","rationale":"@import is specifically for referencing external files from CLAUDE.md, letting each package pull in just the standards relevant to it without duplicating content. Glob-pattern rules scope by file path being edited, not by explicit reference; a forked skill isolates execution context, it doesn't compose configuration files; /memory is a diagnostic command, not an authoring mechanism.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.1 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code memory (CLAUDE.md and .claude/rules/)","url":"https://code.claude.com/docs/en/memory","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-097","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.1"],"objectives":["O13","O16"],"stem":"Two developers on the same project see Claude Code behave inconsistently, and you suspect different memory files are being loaded for each of them. What command lets you directly verify which memory files are actually in effect?","options":[{"key":"A","text":"/memory","explanation":"Correct. /memory reports which memory files are actually in effect, which is what distinguishes two developers' differing setups."},{"key":"B","text":"/compact","explanation":"/compact reduces context usage and says nothing about which files were loaded."},{"key":"C","text":"/rules","explanation":"There is no /rules command in Claude Code, so this inspects nothing at all."},{"key":"D","text":"--resume","explanation":"--resume continues a prior session rather than inspecting configuration."}],"correct":"A","tiebreaker":"Official concept: /memory verifies which memory files are loaded, for diagnosing cross-session inconsistency.","rationale":"/memory is the diagnostic command specifically for checking which memory files are currently loaded — exactly what you'd reach for to debug this kind of inconsistency. /compact reduces context usage, not a memory-file diagnostic; there's no /rules command; --resume continues a session, it doesn't inspect configuration.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.1 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code memory (CLAUDE.md and .claude/rules/)","url":"https://code.claude.com/docs/en/memory","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-098","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d3"],"taskStatements":["3.2"],"objectives":["O14","O16"],"family":"skill-fork-verbose","stem":"A skill performs a verbose codebase analysis as an intermediate step, and you only want its final summary in the main conversation — not the exploratory reasoning that got it there. What frontmatter option isolates this?","options":[{"key":"A","text":"context: fork — the skill runs in an isolated context and returns only its result.","explanation":"Correct. context: fork runs the skill in an isolated context, so only what it returns reaches the main conversation and the verbose exploration stays out."},{"key":"B","text":"allowed-tools — the skill's available tools are restricted to read-only operations.","explanation":"allowed-tools limits what the skill may do, not how much of its working output is visible."},{"key":"C","text":"argument-hint — the expected parameters for the skill are described up front.","explanation":"argument-hint describes expected parameters and has no bearing on context isolation."},{"key":"D","text":"A longer SKILL.md — the instructions explicitly ask for a summary only.","explanation":"Asking for a summary in the instructions is probabilistic, and the intermediate reasoning still passes through the main context."}],"correct":"A","tiebreaker":"Official concept: context: fork isolates a skill's execution so its output doesn't pollute the main conversation.","rationale":"context: fork runs the skill in its own isolated context, so only what it explicitly returns reaches the main conversation. allowed-tools restricts capability, not context visibility; argument-hint is about parameter prompting; asking nicely for a summary is still probabilistic and doesn't structurally prevent pollution.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.2 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code skills","url":"https://code.claude.com/docs/en/skills","type":"docs"}],"note":"The exam guide describes allowed-tools as restricting a skill's tools. In current Claude Code it pre-approves the listed tools for the turn and does not remove any others.","corroborated":[]},
{"id":"REF-099","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d3"],"taskStatements":["5.4"],"objectives":["O20"],"stem":"You're running a multi-phase investigation of an unfamiliar codebase before implementing a change, and verbose discovery output threatens to exhaust the context window before you reach the implementation phase. What's designed to isolate this?","options":[{"key":"A","text":"The Explore subagent — discovery runs in a subagent that hands back a summary.","explanation":"Correct. The Explore subagent absorbs verbose discovery in its own context and returns a summary, which protects the main conversation's budget for the implementation phase."},{"key":"B","text":"A larger context window — more room so discovery output fits alongside implementation.","explanation":"A larger window postpones exhaustion rather than keeping discovery output out of the main context."},{"key":"C","text":"Continuous /compact — the context is compacted repeatedly throughout exploration.","explanation":"Repeated compaction is a workaround that loses detail progressively and still routes everything through the main context first."},{"key":"D","text":"Plan mode — the entire investigation runs under propose-then-approve.","explanation":"Plan mode governs approval before changes; it doesn't isolate the context discovery consumes."}],"correct":"A","tiebreaker":"Official concept: the Explore subagent isolates verbose discovery output to preserve main-conversation context.","rationale":"The Explore subagent exists specifically to absorb verbose discovery work and hand back a summary, protecting the main conversation's context budget. A bigger window is the familiar Usually-Wrong instinct; running /compact continuously is a workaround, not the purpose-built tool; plan mode governs approval before changes, not context isolation during discovery.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.4 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code subagents","url":"https://code.claude.com/docs/en/sub-agents","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-100","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"ci","scenario":"Claude Code for Continuous Integration","scenarioContext":null,"domains":["d3"],"taskStatements":["3.6"],"objectives":["O11","O13","O15","O30"],"stem":"You're running Claude Code in CI to produce code-review findings that get posted automatically as inline pull-request comments. Beyond the -p flag for non-interactive mode, what else do you need for reliably machine-parseable output?","options":[{"key":"A","text":"--output-format json paired with --json-schema to enforce the exact structure your script expects.","explanation":"Correct. --output-format json with --json-schema makes the CLI emit output conforming to the structure your script expects, rather than hoping free text parses."},{"key":"B","text":"A longer system prompt simply asking the model for \"clean JSON only,\" nothing more.","explanation":"A prompt asking for clean JSON is probabilistic and will eventually emit a stray line that breaks the pipeline."},{"key":"C","text":"Post-process the plain-text output with a regex parser that extracts findings into the required shape.","explanation":"Regex-parsing free text is brittle and breaks whenever the phrasing shifts."},{"key":"D","text":"Run the command twice and diff the outputs, keeping only findings that appear in both runs.","explanation":"Running twice and diffing compares two unstructured outputs and still yields nothing machine-parseable."}],"correct":"A","tiebreaker":"Official concept: --output-format json + --json-schema for machine-parseable CI output.","rationale":"--output-format json with --json-schema is the documented, structural way to get schema-compliant output straight from the CLI, exactly for automated contexts like this. Asking nicely in the prompt is still probabilistic; regex-parsing free text is fragile; running twice and diffing doesn't produce structured output at all.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.6 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Run Claude Code programmatically (headless)","url":"https://code.claude.com/docs/en/headless","type":"docs"},{"title":"Claude Code CLI reference","url":"https://code.claude.com/docs/en/cli-reference","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-101","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.3"],"objectives":["O26","O29"],"stem":"An extraction schema marks \"contract_end_date\" as required, but a meaningful fraction of source contracts never state an end date at all (they're open-ended). What happens, and what should you change?","options":[{"key":"A","text":"The model will tend to fabricate a plausible date to satisfy the required field; make the field nullable.","explanation":"Correct. A required field with no source value pressures the model to supply something plausible; making the field nullable lets \"not stated\" be recorded truthfully."},{"key":"B","text":"Nothing changes; required fields are simply always present in every document.","explanation":"Real contracts vary, and the stem says a meaningful fraction genuinely have no end date."},{"key":"C","text":"Add a few-shot example showing a fabricated date, so the model has a consistent pattern to follow.","explanation":"An example of a fabricated date teaches the model to fabricate consistently, which is worse."},{"key":"D","text":"Increase the model's temperature so it's more creative about inferring likely dates.","explanation":"Higher temperature increases invention — the opposite of what's needed."}],"correct":"A","tiebreaker":"Official concept: nullable/optional schema fields prevent the model from fabricating values to satisfy required fields.","rationale":"A required field with no source data pressures the model to invent something plausible rather than admit absence — making the field nullable lets 'not stated' be represented truthfully. Assuming required fields are always present ignores real document variation; the other two options actively encourage fabrication instead of preventing it.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.2 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-102","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.3"],"objectives":["O25","O26","O27","O29","O37"],"stem":"A document-type classification field is a strict enum of five known categories, but roughly 8% of real documents don't cleanly fit any of them. What schema pattern handles this gracefully without breaking strict validation?","options":[{"key":"A","text":"An \"other\" enum value paired with a free-text detail field describing what it actually is.","explanation":"Correct. An explicit \"other\" value with a free-text detail field keeps validation strict while representing the 8% honestly."},{"key":"B","text":"Make the field a free-text string instead of an enum, abandoning strict typing.","explanation":"Dropping to free text abandons the validation that made the enum worthwhile."},{"key":"C","text":"Force every document into the closest of the five categories, even if it's a poor fit.","explanation":"Forcing a poor fit silently corrupts the data for 8% of documents."},{"key":"D","text":"Reject and skip any document that doesn't match one of the five categories.","explanation":"Skipping those documents discards information that could have been captured accurately."}],"correct":"A","tiebreaker":"Official concept: enum + \"other\" + detail-string pattern for extensible categorization without sacrificing strict validation.","rationale":"\"Other\" plus a detail string keeps the field strictly typed and validated while still honestly capturing cases outside the known categories. Dropping strict typing loses the validation benefit entirely; forcing a poor-fit category corrupts your data; skipping documents outright loses information you could otherwise capture.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.3 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-103","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.4"],"objectives":[],"stem":"An extraction fails validation twice in a row for the same field. In one case, the model returned a string where a number was expected. In another, the field's value genuinely never appears anywhere in the source document. Should you retry both the same way?","options":[{"key":"A","text":"No — retry the type-mismatch case with the validation error included, but treat the missing-information case as not retry-fixable.","explanation":"Correct. A type mismatch is correctable, so retrying with the validation error quoted usually fixes it; a value that appears nowhere in the document cannot be produced by trying again."},{"key":"B","text":"Yes — retry both identically up to the same fixed limit, since retries eventually resolve validation failures.","explanation":"Retrying the missing-value case identically spends the whole budget on something no attempt can satisfy."},{"key":"C","text":"No — abandon both immediately with no retry, since a schema validation failure indicates a malformed request.","explanation":"Abandoning both gives up on the type mismatch, which a single corrective retry typically resolves."},{"key":"D","text":"Yes — retry both, but only after switching the extraction over to a larger model with stronger schema adherence.","explanation":"A larger model still cannot extract a date the document never states, and the type error is cheaper to fix with feedback."}],"correct":"A","tiebreaker":"Official concept: retry-with-error-feedback fixes format/structural errors; it can't fix information genuinely absent from the source.","rationale":"A structural/format mismatch is genuinely fixable by pointing out the specific error and retrying; if the information simply isn't in the source, no number of retries will produce it. Treating both the same way either wastes retries on an unfixable case or gives up too early on a genuinely fixable one; switching models doesn't address either underlying issue.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.4 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-104","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d5"],"taskStatements":["5.5"],"objectives":["O22"],"stem":"Your extraction pipeline could route low-confidence results to human review two different ways: (1) the model casually self-reporting how sure it feels about its overall answer, or (2) field-level confidence scores calibrated against a labeled validation set. Which statement is accurate?","options":[{"key":"A","text":"Casual self-reporting is poorly calibrated for routing, while validation-calibrated field scores can inform it.","explanation":"Correct. A casual self-report isn't calibrated against outcomes, whereas field-level scores checked against a labelled set have a measured relationship to accuracy and can justify routing."},{"key":"B","text":"Both approaches are equally unreliable, so neither should be used to route work to human review.","explanation":"They aren't equally unreliable — calibration against real outcomes is exactly the difference between them."},{"key":"C","text":"Calibration is unnecessary, since any confidence score means the same thing regardless of source.","explanation":"A score means only what its calibration shows; an uncalibrated number and a validated one are not interchangeable."},{"key":"D","text":"Confidence of any kind, calibrated or not, should be excluded from routing work to human review.","explanation":"Too absolute: field-level scores calibrated against a labelled set have a measured relationship to accuracy and are a legitimate routing signal."}],"correct":"A","tiebreaker":"Official concept: distinguish poorly-calibrated self-reported confidence from validated, field-level confidence scoring (Task 5.5).","rationale":"Uncalibrated self-report is the Usually-Wrong pattern; calibrating field-level scores against labeled data is the legitimate version of confidence-based routing. The two are not equally unreliable — calibration against real outcomes is what makes the difference; skipping calibration throws away the thing that makes a score trustworthy.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.2 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-105","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d5"],"taskStatements":["5.5"],"objectives":["O22"],"stem":"Your extraction pipeline reports 97% aggregate accuracy, and the team wants to reduce human review to save cost. What should you verify before doing that?","options":[{"key":"A","text":"No further verification — 97% aggregate accuracy is a sufficient basis on its own.","explanation":"A single aggregate can hide a document type or field performing far below the mean, which is precisely the risk when cutting review."},{"key":"B","text":"Stratified random sampling by document type and field, checking the 3% isn't concentrated.","explanation":"Correct. Sampling stratified by document type and field shows whether the 3% is spread evenly or concentrated in one segment that would then go unreviewed."},{"key":"C","text":"Review of the single lowest-volume document type, assumed to be the likely outlier.","explanation":"Checking the lowest-volume type assumes where the problem is; the weak segment could be a high-volume one."},{"key":"D","text":"Self-reported model confidence across a handful of manually spot-checked examples.","explanation":"Informal spot checks plus self-reported confidence is neither structured sampling nor a calibrated signal."}],"correct":"B","tiebreaker":"Official concept: stratified random sampling by document type/field verifies real accuracy before automating away human review (Task 5.5).","rationale":"A single aggregate number can hide a segment performing far worse than the average — stratified sampling by document type and field is what verifies uniform performance before pulling back review. Reducing review on the aggregate alone risks exactly the hidden-segment problem; checking only one type doesn't rule out others; informal spot-checking isn't structured sampling.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.5 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-106","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.6"],"objectives":["O18","O19"],"family":"conflict-attribution","stem":"Two credible sources report different figures for the same statistic in your research pipeline. How should the synthesis output handle this?","options":[{"key":"A","text":"Include both values with clear source attribution, explicitly annotating the conflict rather than picking one.","explanation":"Correct. Carrying both figures with attribution and naming the conflict lets the reader judge it, instead of hiding a disagreement behind a single number."},{"key":"B","text":"Use whichever source was published more recently, on the basis that newer data supersedes older data.","explanation":"Recency alone doesn't settle which figure is right; methodology and scope often explain the gap."},{"key":"C","text":"Average the two conflicting values and report the midpoint as a reasonable consensus figure.","explanation":"An average reports a number neither source published and conceals that they disagreed."},{"key":"D","text":"Omit the statistic entirely rather than presenting the reader with an unresolved contradiction.","explanation":"Dropping the statistic removes information the reader needs rather than presenting it honestly."}],"correct":"A","tiebreaker":"Official concept: annotate conflicting source statistics with attribution rather than arbitrarily resolving them (Task 5.6).","rationale":"Preserving both values with attribution and flagging the conflict gives the reader the real picture; silently picking, averaging, or dropping the statistic all destroy information the reader needed. Recency isn't a reliable tiebreaker on its own; averaging invents a number neither source reported; omitting it loses the statistic instead of handling the disagreement honestly.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.6 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-107","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.6"],"objectives":["O18","O19"],"family":"dated-figures","stem":"A synthesis report flags two sources as contradicting each other on a market growth rate, but the values were published five years apart, and the metric has genuinely changed over that time. What should have prevented this false contradiction?","options":[{"key":"A","text":"Requiring subagents to cite only sources published within the same calendar year, ensuring comparability.","explanation":"Restricting to a single calendar year discards legitimate historical context and still wouldn't explain the difference."},{"key":"B","text":"Requiring subagents to include publication dates, so synthesis reads differences as change over time.","explanation":"Correct. With publication dates attached, synthesis can see the five-year gap and read the difference as change over time rather than as a contradiction."},{"key":"C","text":"Instructing the synthesis agent to always trust whichever source happens to be more recent.","explanation":"Always trusting the newer figure hides the trend, which is the genuinely interesting finding here."},{"key":"D","text":"Discarding older sources as soon as a newer figure is available, so the report reflects current data.","explanation":"Discarding older sources loses the earlier data point that makes the change measurable."}],"correct":"B","tiebreaker":"Official concept: require publication/collection dates to correctly interpret temporal differences (Task 5.6).","rationale":"Publication/collection dates let synthesis correctly read a difference over time as change, not contradiction — that's the missing information here. Restricting to one calendar year would discard valid historical context; silently trusting the newer source erases what changed and by how much; discarding older sources loses real trend information.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.6 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-108","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d5"],"taskStatements":["5.1"],"objectives":["O18","O21"],"family":"case-facts-block","stem":"In a long customer support conversation, progressive summarization is condensing older turns to save context. A specific dollar amount stated early in the conversation is later referenced incorrectly, having drifted during summarization. What pattern directly prevents this?","options":[{"key":"A","text":"Summarize the conversation more aggressively so less content needs to be tracked at all.","explanation":"More aggressive summarization increases the chance a precise figure is lost or altered."},{"key":"B","text":"Extract transactional facts into a persistent \"case facts\" block kept outside the summarized history.","explanation":"Correct. Holding transactional facts in a persistent block outside the summarized history means the dollar amount is never rewritten by a summarizer."},{"key":"C","text":"Increase max_tokens so there is more room to restate the transactional details accurately each turn.","explanation":"max_tokens governs response length and doesn't protect a figure from drifting during summarization."},{"key":"D","text":"Ask the model to re-verify its own figures against the conversation before every single response.","explanation":"Self-verification checks against a history whose earlier turns have already been condensed, so the original figure may no longer be there."}],"correct":"B","tiebreaker":"Official concept: a persistent case-facts block preserves exact transactional details outside progressive summarization (Task 5.1).","rationale":"Pulling hard facts out into their own persistent, unsummarized block protects specific numbers from drifting during progressive summarization of everything else. More aggressive summarization makes the drift risk worse; max_tokens and self-checking don't address where the number actually got lost.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.1 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-109","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.4"],"objectives":["O09","O17","O20"],"family":"crash-recovery","stem":"A long multi-agent codebase exploration needs to survive a crash partway through without losing all prior progress. What design supports this?","options":[{"key":"A","text":"Each agent exports state to a known location; the coordinator loads a manifest of it back into prompts on resume.","explanation":"Correct. Agents writing state to known locations plus a coordinator-loaded manifest gives a single source of truth for what is already done, so a resume continues rather than repeats."},{"key":"B","text":"Restart the entire exploration from scratch after any crash, guaranteeing a fully consistent final state.","explanation":"Restarting from scratch is the outcome crash recovery is meant to avoid."},{"key":"C","text":"Keep all state in memory only, since disk persistence adds complexity and its own failure modes.","explanation":"In-memory state is gone precisely when the crash happens, so nothing survives to resume from."},{"key":"D","text":"Have each agent independently decide whether to resume or restart, with no shared coordination.","explanation":"Agents deciding independently with no shared record produces inconsistent resumption and duplicated work."}],"correct":"A","tiebreaker":"Official concept: structured state exports + a coordinator-loaded manifest enable crash recovery in multi-agent exploration (Task 5.4).","rationale":"Structured state exports plus a coordinator-loaded manifest is the crash-recovery pattern — known locations to read from, and a single source of truth for what's already done. Restarting from scratch defeats the purpose of recovery; memory-only state is lost on crash by definition; uncoordinated independent decisions per agent risk exactly the inconsistency a shared manifest prevents.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.4 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-110","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.2"],"objectives":[],"stem":"Your travel booking agent's tools return errors for very different reasons: a downstream timeout, a malformed input field, a policy limit being exceeded, and an expired access token. What should the structured error response include so the agent can react correctly to each?","options":[{"key":"A","text":"A category (transient/validation/business/permission) plus an isRetryable flag, so the agent knows whether retrying could help.","explanation":"Correct. A category plus an isRetryable flag maps each cause to the right behaviour: back off and retry, fix the input, explain or escalate the policy limit, or re-authenticate."},{"key":"B","text":"A single unified \"error\" boolean value, leaving the agent to guess at what actually went wrong before deciding what to do.","explanation":"One boolean collapses four distinct causes into \"something failed\" and leaves the agent guessing."},{"key":"C","text":"The raw HTTP status code by itself, on the assumption the agent can reliably infer the right response from the number alone.","explanation":"A raw status code is ambiguous in practice and still needs interpreting into retryable or not."},{"key":"D","text":"A human-readable message written for a support engineer to read later, with nothing structured for the agent to act on now.","explanation":"Prose written for an engineer to read later gives the agent nothing structured to branch on now."}],"correct":"A","tiebreaker":"Official concept: structured errors need errorCategory + isRetryable, not a generic pass/fail signal.","rationale":"A category plus isRetryable tells the agent whether to retry with backoff (transient), fix the input and retry (validation), explain the policy or escalate (business), or re-authenticate or escalate (permission) — four different correct behaviors from four different causes. A bare boolean or status code collapses those four cases into one signal, and a human-facing message alone doesn't give the agent anything machine-actionable to decide on.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.2 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-111","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d2"],"taskStatements":["2.2"],"objectives":[],"stem":"Your retail inventory agent's search tool can return in two ways: a 200 response with an empty array (the query ran fine, nothing matched), or a timeout (the query never ran at all). What should the agent tell the user in each case, respectively?","options":[{"key":"A","text":"\"I didn't find anything matching that\" for the empty case; \"I wasn't able to search right now, let me try again\" for the timeout.","explanation":"Correct. The empty result is a real answer — the search ran and nothing matched — while the timeout means no search happened, so only one of the two warrants a retry."},{"key":"B","text":"\"I didn't find anything matching that\" for both cases, since the end result shown to the user looks identical either way.","explanation":"Reporting \"nothing matched\" after a timeout asserts something the agent never established."},{"key":"C","text":"\"I wasn't able to search right now\" for both cases, staying non-committal regardless of what actually happened underneath.","explanation":"Saying the search failed when it ran successfully withholds a genuine finding from the user."},{"key":"D","text":"Silently retry before responding in both cases, on the assumption a second attempt resolves whatever ambiguity exists.","explanation":"Retrying a successful empty search costs a call and returns the same empty result."}],"correct":"A","tiebreaker":"Official concept: never retry a valid empty result, and never present a real failure as \"no results.\"","rationale":"A valid empty result is information (the search ran, nothing matched); a timeout is a failure (the search never executed). Collapsing them into the same message tells the user something untrue in one of the two cases. Retrying a genuinely empty, successfully-executed search wastes a call and won't change the outcome — retrying only makes sense for the failure case.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.2 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-112","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d2"],"taskStatements":["2.5"],"objectives":["O17","O32"],"stem":"Your agent needs to find every file that calls a deprecated utility function across a large codebase, then update each call site — but some of the surrounding code is nearly identical across files, so a unique-text match isn't guaranteed everywhere. Which built-in tools fit each step?","options":[{"key":"A","text":"Grep to locate every caller by content match; Read + Write as the fallback wherever Edit can't find a unique anchor.","explanation":"Correct. Grep finds callers by content, and where surrounding code is near-identical Edit has no unique anchor, so Read plus Write is the safe fallback."},{"key":"B","text":"Glob to locate every caller by content match; Edit exclusively, since it never requires a unique anchor.","explanation":"Glob matches paths, not file contents, so it can't find call sites — and Edit does need a unique match."},{"key":"C","text":"Bash to scan the filesystem directly, then Edit for every replacement regardless of match uniqueness.","explanation":"Bash can scan, but forcing Edit everywhere runs straight into the non-unique matches the stem warns about."},{"key":"D","text":"Read every file in the repository upfront, then Write each one back with replacements already applied.","explanation":"Reading and rewriting every file in a large repository is wasteful and risks rewriting files that needed no change."}],"correct":"A","tiebreaker":"Official concept: Grep for content search, Glob for path patterns, Read+Write as Edit's fallback on non-unique matches.","rationale":"Grep searches file contents for patterns like function calls; Edit needs a unique text match to target a change safely, so Read + Write is the documented fallback when that uniqueness can't be guaranteed. Glob matches file paths, not content, so it can't locate callers by usage; forcing Edit everywhere ignores exactly the non-unique-match cases it can't handle.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.5 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code tools reference","url":"https://code.claude.com/docs/en/tools-reference","type":"docs"}],"note":"Answer per the exam guide. In current Claude Code on macOS, Linux and WSL, Glob and Grep are left out of the default tool set and Claude searches with find and grep through Bash; the two tools are available when named in --tools or --allowedTools, or in a subagent's tools list.","corroborated":[]},
{"id":"REF-113","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.3"],"objectives":["O16"],"family":"rules-glob-scattered","stem":"Your Terraform files mostly live in a top-level terraform/ directory, but individual service folders also contain scattered *.tf override files. You want Terraform-specific conventions to load automatically whenever any .tf file is being edited, regardless of which directory it's in. What's the right mechanism?","options":[{"key":"A","text":"A .claude/rules/ file with YAML frontmatter paths: [\"**/*.tf\"], so it loads whenever a matching file is edited, anywhere in the repo.","explanation":"Correct. A rules file globbing **/*.tf loads on the path of the file being edited, so it covers both the terraform/ directory and the scattered overrides."},{"key":"B","text":"A CLAUDE.md file placed only in the terraform/ directory, accepting that scattered override files elsewhere won't get the conventions.","explanation":"A CLAUDE.md inside terraform/ never applies to .tf files sitting in service folders."},{"key":"C","text":"The Terraform conventions added to the root CLAUDE.md, relying on Claude to infer when they're relevant.","explanation":"Root-level conventions rely on inference about relevance rather than matching the file actually being edited."},{"key":"D","text":"A skill in .claude/skills/ that must be manually invoked each time a .tf file happens to be edited.","explanation":"A manually invoked skill isn't automatic, and it will be forgotten on exactly the scattered files that need it."}],"correct":"A","tiebreaker":"Official concept: .claude/rules/ with YAML frontmatter glob patterns for path-scoped, location-independent convention loading.","rationale":"Glob-pattern rules in .claude/rules/ apply based on file path patterns regardless of directory location — exactly what's needed when matching files are scattered across the codebase. A directory-bound CLAUDE.md misses files outside that directory, and relying on inference or manual invocation isn't the deterministic, path-based loading the guide describes.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.3 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code memory (CLAUDE.md and .claude/rules/)","url":"https://code.claude.com/docs/en/memory","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-114","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d3"],"taskStatements":["3.5"],"objectives":["O12"],"stem":"You ask Claude to write a function that normalizes phone numbers, describing the expected transformation in a paragraph of prose. The results are inconsistent from run to run — sometimes country codes get stripped, sometimes they don't, sometimes formatting varies. What's the most effective fix?","options":[{"key":"A","text":"Provide 2-3 concrete input/output example pairs showing exactly which transformations are expected.","explanation":"Correct. Two or three input/output pairs pin down exactly what happens to country codes and formatting, which prose evidently left open to interpretation."},{"key":"B","text":"Rewrite the same prose description using more emphatic language and additional adjectives.","explanation":"Emphatic wording doesn't resolve the ambiguity about what the transformation should actually do."},{"key":"C","text":"Lower the temperature setting so the model interprets the existing prose more literally.","explanation":"Lower temperature makes one interpretation more consistent without establishing that it's the intended one."},{"key":"D","text":"Repeat the same prose description twice within the same message for reinforcement.","explanation":"Repeating an ambiguous description twice leaves it just as ambiguous."}],"correct":"A","tiebreaker":"Official concept: concrete input/output examples are the most effective way to fix inconsistent output when prose alone produces varied results.","rationale":"Concrete input/output examples are the most effective way to communicate an expected transformation when prose descriptions alone are being interpreted inconsistently. Rephrasing, repeating, or adjusting sampling parameters don't resolve genuine ambiguity in what the transformation should do — only concrete examples pin down the exact expected behavior.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.5 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Prompting best practices","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-115","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.2"],"objectives":["O04","O10"],"stem":"You need a system that gathers pricing data from twelve independent supplier APIs, then produces one reconciled report. Each supplier call is independent and slow (2-4s), but the reconciliation step needs all twelve results before it can run. Which orchestration pattern fits, and why?","options":[{"key":"A","text":"Parallel execution for the twelve supplier calls, followed by a single sequential reconciliation step once all results return.","explanation":"Correct. The twelve calls are independent, so running them concurrently collapses 24-48s of latency into roughly one call's time, and reconciliation genuinely needs all twelve, so it runs once afterwards."},{"key":"B","text":"A strict sequential pipeline calling each supplier one at a time, then reconciling as each result arrives.","explanation":"Sequential calls serialise 2-4s twelve times for no reason, and reconciling as results arrive works on incomplete data."},{"key":"C","text":"A coordinator-worker pattern where each worker independently decides when to hand off to reconciliation.","explanation":"Workers deciding individually when to hand off risks reconciliation starting before all twelve have returned."},{"key":"D","text":"Twelve separate sequential pipelines running end-to-end in isolation, merged only at final output.","explanation":"Twelve isolated end-to-end pipelines duplicate the reconciliation context and still merge only at the very end."}],"correct":"A","tiebreaker":"Official concept: select coordinator-worker, parallel, or sequential based on whether subtasks are independent and whether downstream steps need all outputs.","rationale":"The twelve calls have no dependency on each other, so running them in parallel minimizes total latency; reconciliation genuinely needs all twelve, so it correctly waits and runs once as a single step. A sequential pipeline wastes the 2-4s per call needlessly since nothing prevents concurrency; letting workers decide handoff individually risks reconciling on incomplete data.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.2 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-116","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O01"],"family":"parallel-subagents","stem":"Your coordinator needs to spawn three independent subagents — web search, document analysis, and a fact-checker — none of which depend on each other's output. Currently the coordinator calls Task once, waits for that subagent to finish, then calls Task again for the next one. What change reduces total round-trip latency the most?","options":[{"key":"A","text":"Emit all three Task tool calls within a single coordinator response turn, so they execute concurrently.","explanation":"Correct. Three Task calls emitted in one response run concurrently, so the total wait is roughly the slowest subagent instead of the sum of all three."},{"key":"B","text":"Increase the coordinator's max_tokens so it can describe all three tasks in more detail per call.","explanation":"More output tokens let the coordinator describe tasks at greater length; it doesn't change that they execute one after another."},{"key":"C","text":"Merge all three subagents into a single agent with three system prompts loaded simultaneously.","explanation":"Merging the three defeats the role separation and gives one agent three conflicting mandates."},{"key":"D","text":"Reduce the number of subagents to two, since three concurrent Task calls exceed a hard platform limit.","explanation":"No such hard limit forces a reduction to two, and dropping a subagent loses its work entirely."}],"correct":"A","tiebreaker":"Official concept: parallel subagent execution means multiple Task calls emitted in one coordinator turn, not spread across separate turns.","rationale":"Emitting multiple Task tool calls within one response turn lets independent subagents run in parallel rather than one after another — this is exactly what removes the sequential wait between calls. More tokens per call doesn't change execution order, merging agents defeats the purpose of separating their roles, and there's no such hard limit forcing a reduction to two.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.3 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code subagents","url":"https://code.claude.com/docs/en/sub-agents","type":"docs"},{"title":"Agent SDK: subagents (AgentDefinition)","url":"https://code.claude.com/docs/en/agent-sdk/subagents","type":"docs"}],"note":"Claude Code renamed the Task tool to Agent in version 2.1.63. Existing Task(...) references still work as aliases, so the mechanism this question tests is unchanged; the current name is Agent. In the current Agent SDK, allowedTools is the list of auto-approved tools, and its examples include Agent there so the coordinator can delegate.","corroborated":[]},
{"id":"REF-117","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3"],"objectives":["O05","O33"],"stem":"Your coordinator spawns a billing-lookup subagent and a general-research subagent. Both currently receive the same AgentDefinition: full tool access and an identical system prompt. The billing subagent has started attempting web searches when it can't find an answer locally. What should change?","options":[{"key":"A","text":"Give each subagent its own AgentDefinition, restricting allowedTools and system prompt to what its specific role actually requires.","explanation":"Correct. A per-subagent AgentDefinition that narrows allowedTools to what billing actually needs removes web search as an option, rather than asking the model not to use it."},{"key":"B","text":"Leave tool access shared, but add a system-prompt line asking the billing subagent to \"stay focused on billing.\"","explanation":"\"Stay focused on billing\" is a request against a capability the subagent still has, so it will sometimes wander again."},{"key":"C","text":"Remove Task from the coordinator's allowedTools so subagents can no longer be spawned at all.","explanation":"Removing Task from the coordinator disables delegation altogether, losing both subagents."},{"key":"D","text":"Give both subagents access to every tool in the system, on the theory that more capability means fewer failures.","explanation":"Universal tool access is what allowed the drift in the first place; widening it makes the problem worse."}],"correct":"A","tiebreaker":"Official concept: constrain each subagent invocation with tool restrictions, context scoping, and a system prompt matched to its designated role.","rationale":"Scoping each subagent's AgentDefinition — its tools, context, and system prompt — to its designated role is what structurally prevents a billing subagent from wandering into web search; a prompt request alone is a probabilistic ask, not a guarantee. Removing Task disables the whole pattern, and granting universal tool access to both subagents is the opposite of the fix — it's what caused the problem.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.3 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code subagents","url":"https://code.claude.com/docs/en/sub-agents","type":"docs"},{"title":"Agent SDK: subagents (AgentDefinition)","url":"https://code.claude.com/docs/en/agent-sdk/subagents","type":"docs"}],"note":"AgentDefinition is the Agent SDK's per-subagent type: description, prompt (the system prompt) and tools (the allowlist), with disallowedTools as a denylist. In Claude Code the same fields are YAML frontmatter in a Markdown file under .claude/agents/. In the current SDK, allowedTools is a session option that auto-approves tools; a subagent's own restriction is its tools field.","corroborated":[]},
{"id":"REF-118","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.6"],"objectives":["O07","O10"],"stem":"You're building an agent to investigate a production incident. You initially planned three fixed subtasks: check logs, check recent deploys, check database metrics. Partway through, the logs reveal the issue started right after a specific config change — a lead the fixed plan has no step for following. What approach handles this well?","options":[{"key":"A","text":"Dynamic decomposition: generate new subtasks based on what's discovered at each step, rather than executing the original fixed sequence regardless of findings.","explanation":"Correct. Generating new subtasks from what each step uncovers lets the investigation follow the config-change lead, which a plan fixed in advance has no step for."},{"key":"B","text":"Continue executing the three original subtasks exactly as planned, then note the config-change lead for a separate follow-up investigation later.","explanation":"Finishing the original three and filing the lead for later ignores the most informative finding while the incident is live."},{"key":"C","text":"Restart the investigation from scratch with the config change as the only subtask, discarding the other three entirely.","explanation":"Discarding the other subtasks throws away context that may corroborate or rule out the config change."},{"key":"D","text":"Run all three original subtasks in parallel to finish faster, without changing what each one investigates.","explanation":"Running the original three in parallel arrives faster at the same three answers, none of which covers the lead."}],"correct":"A","tiebreaker":"Official concept: dynamic decomposition adapts subtasks to intermediate findings, versus a fixed sequence that ignores what's discovered along the way.","rationale":"Dynamic, adaptive decomposition generates new subtasks as findings emerge, letting the investigation actually follow the config-change lead instead of ignoring it because it wasn't in the original plan. Sticking to the fixed plan wastes the most useful lead found so far; discarding the other subtasks throws away potentially relevant context; parallelizing the original three doesn't help since none of them cover the actual lead.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 1.6 — Agentic Architecture & Orchestration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-119","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d2"],"taskStatements":["2.5"],"objectives":["O17","O32"],"family":"glob-then-grep","stem":"You need to (1) find every file whose name matches *.config.ts anywhere in the repo, and (2) then check the content of each match for a specific deprecated setting name. Which built-in tools fit steps 1 and 2, respectively?","options":[{"key":"A","text":"Glob for step 1 (path pattern matching); Grep for step 2 (content search within those files).","explanation":"Correct. Glob matches paths like *.config.ts, and Grep then searches inside those files for the deprecated setting — each tool used for what it does."},{"key":"B","text":"Grep for step 1 (path pattern matching); Glob for step 2 (content search within those files).","explanation":"This reverses them: Grep doesn't match file names and Glob doesn't read content."},{"key":"C","text":"Bash for both steps, since shell commands can handle any file discovery and content search task.","explanation":"Bash could do both, but the built-in tools are purpose-made here and avoid shell quoting and portability issues."},{"key":"D","text":"Read for step 1, loading every file in the repo first, then Grep to search the loaded content.","explanation":"Reading every file in the repository first is far more expensive than globbing to the handful that match."}],"correct":"A","tiebreaker":"Official concept: Glob for file path pattern matching, Grep for content search — selecting the wrong one wastes the whole exploration step.","rationale":"Glob matches file paths by pattern (like *.config.ts) regardless of content; Grep searches file contents for patterns like a specific setting name — exactly the two-step job here. Reversing them doesn't work: Grep doesn't match on file names, and Glob doesn't inspect content. Reading every file upfront is far less efficient than targeted discovery first.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 2.5 — Tool Design & MCP Integration","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code tools reference","url":"https://code.claude.com/docs/en/tools-reference","type":"docs"}],"note":"Answer per the exam guide. In current Claude Code on macOS, Linux and WSL, Glob and Grep are left out of the default tool set and Claude searches with find and grep through Bash; the two tools are available when named in --tools or --allowedTools, or in a subagent's tools list.","corroborated":[]},
{"id":"REF-120","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.1"],"objectives":["O13","O16"],"stem":"Your team needs: (1) universal coding standards loaded every session, (2) conventions that apply only when editing files under terraform/**, and (3) a guaranteed, non-negotiable block on any tool call that would delete a database table. Which mechanisms fit each, respectively?","options":[{"key":"A","text":"CLAUDE.md for (1); .claude/rules/ with a path glob for (2); a hook that inspects and blocks the call for (3).","explanation":"Correct. CLAUDE.md covers the always-loaded standards, a path-scoped rules glob applies conventions only under terraform/**, and a hook inspects each tool call and blocks a destructive one regardless of what the model decides."},{"key":"B","text":"CLAUDE.md for all three, since it's the single always-loaded source of context for the whole project.","explanation":"CLAUDE.md can't scope itself to terraform/** by path, and as text it guarantees nothing about a delete."},{"key":"C","text":".claude/rules/ for (1) and (2); a Skill for (3), invoked whenever a destructive operation is attempted.","explanation":"A Skill loads on relevance rather than enforcing; it can't guarantee a block on a destructive tool call."},{"key":"D","text":"A Skill for (1); CLAUDE.md for (2); settings permissions for (3), since permissions are prompt-based guidance.","explanation":"This misassigns (1) and (2), and settings permissions aren't prompt-based guidance — deny rules are enforced. For (3), a hook is still the better fit because it can inspect the whole call rather than match a command pattern."}],"correct":"A","tiebreaker":"Official concept: CLAUDE.md = always-loaded, .claude/rules/ = path-scoped, Skills = on-demand, hooks = deterministic enforcement, settings = permission scoping.","rationale":"CLAUDE.md is the always-loaded universal standard; .claude/rules/ with glob-pattern frontmatter applies conventions only when matching files are being edited; a hook gives a deterministic block that can inspect the call itself. CLAUDE.md alone can't scope to terraform/**, and a Skill is on-demand guidance, not a guarantee. Settings deny rules are deterministic too, but option D mislabels them as prompt-based and misassigns the other two; matching every table-deleting call by command pattern is also fragile, which is why the hook is the fit here.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.1 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code permissions","url":"https://code.claude.com/docs/en/permissions","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-121","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d3"],"taskStatements":["3.2"],"objectives":["O14","O16"],"family":"skill-fork-verbose","stem":"You have a /analyze-deps skill that traces a package's full dependency tree and returns pages of exploratory output. Every time a developer runs it, that entire output stays in the main conversation, crowding out everything else. What frontmatter change fixes this?","options":[{"key":"A","text":"Add context: fork to the skill's frontmatter, so it runs in an isolated context and only its final result returns to the main conversation.","explanation":"Correct. context: fork runs the skill in an isolated context, so pages of dependency-tree exploration stay there and only the final result returns."},{"key":"B","text":"Add allowed-tools: [] to the skill's frontmatter, blocking it from using any tools at all during its execution.","explanation":"Blocking all tools stops the skill tracing anything at all."},{"key":"C","text":"Add argument-hint to the skill's frontmatter, prompting the developer for missing parameters before the skill runs.","explanation":"argument-hint prompts for missing parameters and has nothing to do with output volume."},{"key":"D","text":"Move the skill from .claude/skills/ to .claude/commands/, on the assumption commands don't retain their output.","explanation":"Moving the file to .claude/commands/ changes how it's invoked, not whether its output lands in the conversation."}],"correct":"A","tiebreaker":"Official concept: context: fork isolates a skill's execution to prevent its output from polluting the main session.","rationale":"context: fork runs the skill in an isolated sub-agent context, so its verbose exploratory output never pollutes the main conversation — only the final result comes back. Blocking all tools would break the skill's ability to function at all, argument-hint solves a different problem (missing parameters), and moving directories doesn't change how output is retained.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.2 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code skills","url":"https://code.claude.com/docs/en/skills","type":"docs"}],"note":"Answer per the exam guide. In current Claude Code, custom commands have been merged into skills: a file in .claude/commands/ and a skill in .claude/skills/ both create a /name command, and skills can additionally load automatically when relevant. The exam guide describes allowed-tools as restricting a skill's tools. In current Claude Code it pre-approves the listed tools for the turn and does not remove any others.","corroborated":[]},
{"id":"REF-122","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.4"],"objectives":["O08"],"stem":"You're migrating a shared authentication library used by twelve services. The migration needs (a) upfront exploration of every call site, (b) an approved design before any code changes, and (c) implementation that a human can review in stages rather than all at once. Which approach fits?","options":[{"key":"A","text":"A multi-phase workflow: plan mode for exploration and approval, then staged direct execution with checkpoints between stages.","explanation":"Correct. The requirements name all three pieces: exploration and approval before changes (plan mode), then implementation in reviewable stages with checkpoints between them."},{"key":"B","text":"Jump straight into direct execution, since twelve services is still a well-defined, bounded scope with no real ambiguity.","explanation":"Twelve dependent services is exactly the ambiguity the required exploration step exists to resolve."},{"key":"C","text":"Run plan mode across the whole migration end to end, including every service's actual code changes inside the plan itself.","explanation":"Plan mode is for design and approval; putting every service's actual code changes inside the plan misuses it."},{"key":"D","text":"Use direct execution guided by one exhaustive upfront prompt describing every service's required change in complete detail.","explanation":"One exhaustive prompt skips the approval gate and delivers the whole migration in a single unreviewable pass."}],"correct":"A","tiebreaker":"Official concept: select the review architecture (plan mode, direct execution, or multi-phase) based on task scope, risk, and human approval requirements — not just task size alone.","rationale":"This scenario explicitly needs upfront exploration and approval (plan mode's role) plus staged, reviewable implementation afterward — that combination is a multi-phase workflow, not a single mode alone. Jumping straight to direct execution skips the required exploration and approval step; trying to fit all twelve services' actual code changes inside plan mode itself misunderstands what plan mode is for (design, not implementation).","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 3.4 — Claude Code Configuration & Workflows","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Claude Code permission modes (plan mode)","url":"https://code.claude.com/docs/en/permission-modes","type":"docs"}],"note":null,"corroborated":[]},
{"id":"REF-123","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.3"],"objectives":["O25","O26","O27","O29","O37"],"stem":"Your insurance claims pipeline needs extracted data to strictly conform to a JSON schema every single time — a downstream system rejects the entire batch on any schema violation. Which approach should you use, and why?","options":[{"key":"A","text":"tool_use with the schema defined as the tool's input parameters, since this is the only method that structurally guarantees schema-compliant output.","explanation":"Correct. With the schema as the tool's input parameters, the output is tool arguments shaped by that schema, which is the only option here that enforces structure rather than asking for it."},{"key":"B","text":"Prompt-based formatting, describing the exact JSON shape in detailed, carefully-worded natural-language instructions.","explanation":"Carefully worded instructions reduce violations without preventing them, and one violation rejects the whole batch."},{"key":"C","text":"Prefilled responses, seeding the assistant's turn with an opening brace and trusting it to complete the structure correctly.","explanation":"Prefilling an opening brace steers the start and leaves the rest of the structure to chance."},{"key":"D","text":"Any of the three approaches works equally well, provided the schema is described clearly enough within the prompt itself.","explanation":"They are not equivalent: only the schema-enforced path turns \"almost always valid\" into a guarantee."}],"correct":"A","tiebreaker":"Official concept: tool_use with JSON schema is the most reliable structured-output method when strict schema compliance is required.","rationale":"tool_use with a JSON schema as the tool's input is the most reliable method because it structurally enforces schema compliance — the model literally cannot return a syntactically non-conforming shape. Prompt-based formatting and prefilling both reduce errors but remain probabilistic; when the requirement is a hard guarantee against a strict downstream schema, only tool_use provides that.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.3 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"},{"title":"Strict tool use","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/strict-tool-use","type":"docs"}],"note":"Answer per the exam guide. In the current API a tool's input is only guaranteed to match its input_schema when the tool sets strict: true; without it Claude can return a wrong type or omit a required field.","corroborated":[]},
{"id":"REF-124","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.6"],"objectives":["O28"],"family":"truncation-split","stem":"You're running a structured code review across a large pull request, and the response keeps hitting a truncation point before the full set of findings is returned. Your first instinct is to raise max_tokens further. What's the better fix, and why?","options":[{"key":"A","text":"Split the review into smaller, scoped API calls and merge the resulting structured findings, instead of pushing max_tokens further.","explanation":"Correct. Scoped calls merged afterwards scale with the size of the pull request, and each call keeps enough attention on its slice to find the findings at all."},{"key":"B","text":"Keep raising max_tokens indefinitely until the full response comfortably fits inside one single API call.","explanation":"Raising max_tokens has practical limits, and quality degrades across a very long single response well before truncation."},{"key":"C","text":"Switch the review from structured JSON to plain prose output instead, since prose doesn't hit the same truncation point.","explanation":"Prose avoids the truncation point by abandoning the structured output the pipeline depends on."},{"key":"D","text":"Reduce the number of files under review until it happens to fit inside whatever max_tokens value is already set.","explanation":"Shrinking the review until it fits treats the token budget as the design constraint and leaves files unreviewed."}],"correct":"A","tiebreaker":"Official concept: resolve truncation by splitting into smaller scoped calls and merging results, not by increasing max_tokens past practical limits.","rationale":"Splitting a large task into smaller scoped calls and merging the results scales cleanly and avoids the underlying problem — trying to force an ever-larger single response into one call has practical limits and degrades quality well before truncation. Endlessly raising max_tokens doesn't scale and doesn't address why the task doesn't fit; switching to unstructured prose sacrifices exactly the structured-output requirement the task presumably needs; shrinking scope to fit a token budget treats the workaround as the design.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.3 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-125","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.6"],"objectives":["O24","O28"],"stem":"Your automated PR review prompt currently asks Claude to flag security vulnerabilities, business logic errors, and API design inconsistencies all in a single pass with one set of few-shot examples. Reviewers report it catches some of each category but misses obvious issues in every category. What's the most effective restructuring?","options":[{"key":"A","text":"Split into separate, focused review passes — one per concern — each with its own dedicated few-shot examples.","explanation":"Correct. One pass per concern, each with examples for that concern, stops security, business logic and API design competing for the same attention."},{"key":"B","text":"Add more few-shot examples to the existing single pass, covering all three concerns more thoroughly within it.","explanation":"More examples in an already-crowded pass adds to the competition rather than resolving it."},{"key":"C","text":"Run the exact same single-pass prompt twice, then merge whichever findings happen to appear in both runs.","explanation":"Running the same prompt twice reproduces the same trade-off and keeps only findings that happened to recur."},{"key":"D","text":"Remove business logic and API design from scope entirely, leaving only security as the review pass's sole focus.","explanation":"Dropping two concerns removes the misses by removing the coverage."}],"correct":"A","tiebreaker":"Official concept: separate competing concerns into focused prompts with dedicated few-shot examples, rather than one prompt covering all of them.","rationale":"Separating concerns into focused passes with dedicated examples prevents the recall trade-off that happens when one prompt tries to hold attention across three unrelated concern types at once. Adding more examples to the same crowded pass doesn't fix the underlying attention-splitting problem; running the same prompt twice just repeats the same trade-off; dropping two of three concerns loses coverage rather than fixing it.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 4.6 — Prompt Engineering & Structured Output","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-126","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d5"],"taskStatements":["5.1"],"objectives":["O18","O21"],"family":"case-facts-block","stem":"A long customer-support conversation is approaching its practical context limit. Early details (order numbers, dates, prior commitments) are at risk of being pushed out or blurred by everything that's accumulated since. Which technique most directly protects that specific risk?","options":[{"key":"A","text":"A structured state object — a persistent block of extracted key facts, kept outside the summarized history and included in every prompt.","explanation":"Correct. Extracted facts held in a persistent block outside the summarized history are included verbatim in every prompt, so order numbers and commitments can't be blurred or dropped."},{"key":"B","text":"A sliding window that simply drops the oldest turns once some fixed token threshold has been reached.","explanation":"A sliding window drops the oldest turns, which is exactly where the early order numbers and dates live."},{"key":"C","text":"Aggressive summarization that condenses the entire conversation down into a single short paragraph before continuing.","explanation":"Condensing everything into one paragraph is the mechanism that turns specific figures into vague language."},{"key":"D","text":"Selective retention that keeps only the five most recent turns, discarding every earlier turn outright.","explanation":"Keeping only the five most recent turns discards the early commitments outright."}],"correct":"A","tiebreaker":"Official concept: structured state objects preserve specific facts through compression better than summarization, sliding windows, or simple retention cutoffs.","rationale":"A structured state object built from extracted key facts survives compression intact because it's outside the summarized history entirely — the exact protection needed against early details being blurred or dropped. A sliding window and selective retention both risk dropping the early details outright, and aggressive summarization is precisely the mechanism that blurs numbers and commitments into vague language.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.1 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-127","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.4"],"objectives":["O09","O17","O20"],"family":"crash-recovery","stem":"Your multi-agent research pipeline writes a manifest when it starts, listing each subtask and the subagent assigned to it. After a crash four hours in, the resumed run reads the manifest and dispatches every subtask again, including dozens that had finished, because the manifest cannot tell finished work from work that was only assigned. What should the manifest record?","options":[{"key":"A","text":"Each subtask's completion, written when it finishes, with the location of its output for a resumed run.","explanation":"Correct. Completion recorded at the moment work finishes, with where its output lives, lets a resumed run load finished results and dispatch only what remains."},{"key":"B","text":"The full prompt sent to each subagent, so a resumed run can dispatch the same work exactly as before.","explanation":"Dispatching the same prompts again is the redundant work the resume is meant to avoid."},{"key":"C","text":"A timestamp for when each subtask was assigned, so a resumed run can skip the oldest assignments.","explanation":"Being assigned early says nothing about finishing; the oldest assignments may be the ones that crashed."},{"key":"D","text":"Nothing more; on resume, treat any subtask with an output file on disk as finished and skip it.","explanation":"A file on disk can be a partial write from the moment of the crash; its existence is a guess at completion, not a record of it."}],"correct":"A","tiebreaker":"Checking for output files is the runner-up, but a half-written file from the crash passes that check.","rationale":"Reliable resumption needs state that tells finished work from assigned work: record each completion when it happens, with where its output was written, and have the coordinator load those results and dispatch only what remains.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.4 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"REF-128","exam":"CCAR-F","set":"reference_mock_v6","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d5"],"taskStatements":["5.4"],"objectives":["O09","O17","O20"],"family":"exploration-drift","stem":"An agent has been exploring a large, unfamiliar codebase for over an hour. It starts giving inconsistent answers about class structures it examined earlier, occasionally referencing \"typical patterns\" instead of the specific classes it actually found. What combination of techniques addresses this directly?","options":[{"key":"A","text":"Subagent delegation for verbose discovery phases, plus a scratchpad file recording key findings that gets referenced for later questions.","explanation":"Correct. Delegating verbose discovery keeps the main context focused, and a scratchpad of specific findings gives later questions something concrete to consult instead of recalled generalities."},{"key":"B","text":"Rely on a larger context window alone, on the assumption that more room automatically prevents inconsistency from emerging.","explanation":"A larger window delays degradation over a long session; it doesn't prevent specifics fading into \"typical patterns\"."},{"key":"C","text":"Restart the exploration from a clean slate every twenty minutes, to prevent degradation from ever accumulating.","explanation":"Restarting every twenty minutes discards the exploration already done, repeatedly."},{"key":"D","text":"Add a single system-prompt instruction asking the agent to be more careful and specific about earlier findings.","explanation":"An instruction to be careful doesn't restore details that are no longer reliably in context."}],"correct":"A","tiebreaker":"Official concept: subagent delegation plus scratchpad files counteract context degradation in extended codebase exploration sessions.","rationale":"Delegating verbose exploration to subagents keeps the main agent's context focused on coordination, while a scratchpad file preserves specific findings across context boundaries — directly countering the context-degradation pattern described. A larger window alone doesn't stop degradation over a long enough session, restarting repeatedly throws away real progress, and a single prompt instruction doesn't structurally prevent the model from losing track of earlier specifics.","sources":[{"title":"CCAR-F Exam Guide v1.0 (July 2026), Task 5.4 — Context Management & Reliability","url":"https://anthropic-partners.skilljar.com/page/partner-certifications","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"S6-001","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4"],"taskStatements":["4.3","4.4"],"objectives":["O26"],"stem":"The accounts payable team processes about 13,000 vendor invoices a month, roughly 18% of which are non-PO bills such as utilities and software subscriptions. Today the extraction schema treats the purchase order number as a required string, and the ERP runs three-way matching on whatever value comes back. Accuracy on PO-backed invoices sits at 98.7%. The team wants non-PO invoices to flow into the ERP's separate non-PO approval path without being mistaken for PO-backed invoices. Which approach should they take?","options":[{"key":"A","text":"Add a system prompt instruction telling the model to output the string 'NONE' whenever an invoice has no PO number, and have the ERP treat 'NONE' as non-PO.","explanation":"Workable but probabilistic: the schema still demands a value, so the model will sometimes fabricate a PO anyway, and a sentinel string pollutes a field downstream systems read as data."},{"key":"B","text":"Make the PO field nullable, have the model return null when no PO appears, and route nulls to the non-PO path.","explanation":"A required field pressures the model to invent a value. A nullable field gives it a legitimate way to say 'not present', removing the cause of fabrication, and null is trivially routable in code."},{"key":"C","text":"Maintain a list of known non-PO vendors and skip PO extraction for invoices from those vendors.","explanation":"Depends on a vendor list that will never be complete and does nothing about the schema forcing fabrication for everyone else."},{"key":"D","text":"Validate every extracted PO number against the ERP and retry extraction with the error appended when no match is found.","explanation":"Retries can't recover information that isn't in the document; they cost money and may just produce a different fabricated value."}],"correct":"B","tiebreaker":"Guaranteed beats likely","rationale":"Design the schema so absence is representable. Nullable fields prevent fabrication when source documents lack the information. The 98.7% figure is a distractor.","sources":[{"title":"Task 4.3: designing optional (nullable) schema fields to prevent fabrication","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Tool use with Claude","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/overview","type":"docs"}],"note":null,"corroborated":["GUIDE","ACG","PAL","LEAN"]},
{"id":"S6-002","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4","d5"],"taskStatements":["4.4","4.3","5.5"],"objectives":["O26"],"stem":"The legal operations team extracts about 4,000 contracts a month and already runs a validation-retry loop with two retries. They want to cut the roughly $1,900 a month spent on retries while keeping the automatic fixes they get today. About 62% of first-pass failures are effective dates written in prose, which retries fix 93% of the time, and the other 38% are empty governing law fields, which retries fix 3% of the time; legal has confirmed most of those contracts simply have no governing law clause. What should the team do?","options":[{"key":"A","text":"Keep retries for date format failures, make governing law nullable without retries, and flag missing clauses for legal.","explanation":"Retries work for format errors and fail for absent information. Keeping them where they work and routing genuinely missing data to humans cuts cost without losing the automatic fixes."},{"key":"B","text":"Add few-shot examples showing governing law clauses written in a variety of phrasings, so the first pass finds them more often.","explanation":"Few-shot helps find information that is present but unusually phrased. Legal confirmed it is mostly absent, so this targets the wrong cause."},{"key":"C","text":"Remove the retry loop and send every validation failure straight to human review.","explanation":"Throws away a loop that fixes 93% of date failures automatically, breaking the 'keep automatic fixes' goal."},{"key":"D","text":"Lower the maximum retries from two to one across all failures, which roughly halves what the team spends on retries.","explanation":"Reduces cost bluntly, cutting useful retries along with useless ones, and still wastes a retry on every absent clause."}],"correct":"A","tiebreaker":"Root cause","rationale":"Distinguish format or structural failures (retry with error feedback is effective) from missing-information failures (retries are ineffective).","sources":[{"title":"Task 4.4: identifying when retries will be ineffective (missing information) vs effective (format mismatches)","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":["GUIDE","NEU","CSK"]},
{"id":"S6-003","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4"],"taskStatements":["4.3","4.4"],"objectives":["O25"],"stem":"The finance team recently moved the invoice pipeline from JSON-in-text prompting to tool use with a strict JSON schema, and parse failures went from 6.1% to zero. They now want the pipeline to catch invoices where line items don't add up to the total or where tax has landed in the shipping field, which together affect about 4.6% of invoices, before the data reaches the ERP. Which approach should they choose?","options":[{"key":"A","text":"Add calculated_total and conflict_detected fields, check them in code, and retry mismatches with the specific error.","explanation":"Strict schemas remove syntax errors, not semantic ones. Deterministic checks in code catch every mismatch, and retry with the specific error gives the model what it needs to correct it."},{"key":"B","text":"Tighten the schema with minimum and maximum values and stricter numeric types on every one of the invoice's amount fields.","explanation":"A valid number in the wrong field, or line items that don't sum, still passes any type or range constraint."},{"key":"C","text":"Add an instruction asking the model to check that the line items add up to the total before it calls the tool.","explanation":"May reduce errors somewhat but is probabilistic and gives no way to detect what still slips through."},{"key":"D","text":"Have a second Claude instance review every extraction and flag any that look inconsistent.","explanation":"Heavier and costlier than needed; simple arithmetic in code checks this deterministically."}],"correct":"A","tiebreaker":"Guaranteed beats likely","rationale":"Strict tool use guarantees schema-valid output, not semantically correct output. Add self-check fields and validate them programmatically.","sources":[{"title":"Task 4.3 (schemas don't prevent semantic errors) and Task 4.4 (calculated_total vs stated_total, conflict_detected)","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Tool use with Claude","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/overview","type":"docs"}],"note":"Answer per the exam guide. In the current API a tool's input is only guaranteed to match its input_schema when the tool sets strict: true; without it Claude can return a wrong type or omit a required field.","corroborated":["GUIDE","ACG","LEAN","NEU"]},
{"id":"S6-004","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d2","d4"],"taskStatements":["2.3","4.3"],"objectives":["O27"],"stem":"The mailroom team handles a mix of about 65% invoices and 35% receipts, and gives Claude two tools, extract_invoice and extract_receipt, so it can choose the right schema for each document. They want every document to produce structured output, because their parser discards plain-text replies and they currently lose about 950 documents a week that way. How should they configure the request?","options":[{"key":"A","text":"Add a system prompt instruction requiring the model to always respond by calling one of the extraction tools.","explanation":"Reduces text replies but can't guarantee zero; the API setting enforces it deterministically."},{"key":"B","text":"Force extract_invoice with a named tool choice, since invoices are the majority of volume.","explanation":"Guarantees a tool call but forces 35% of documents into the wrong schema."},{"key":"C","text":"Set tool_choice to 'any', so the model must call one of the two tools but still picks the schema.","explanation":"'any' requires the model to call some tool while still letting it pick the right schema per document."},{"key":"D","text":"Add a fallback parser that extracts fields from text replies with regular expressions.","explanation":"Builds a brittle, unvalidated second extraction path instead of preventing text replies."}],"correct":"C","tiebreaker":"Built-in feature over workaround","rationale":"tool_choice 'auto' may return text; 'any' must call a tool; a named tool forces one specific tool.","sources":[{"title":"Task 4.3: setting tool_choice 'any' to guarantee structured output when multiple schemas exist","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Define tools: forcing tool use","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools#forcing-tool-use","type":"docs"},{"title":"Tool use with Claude","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/overview","type":"docs"}],"note":"Answer per the exam guide. The current docs list several newer models that reject tool_choice any and named-tool with a 400 error; the documented alternative there is auto with strict: true.","corroborated":["GUIDE","ACG","DOCS"]},
{"id":"S6-005","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d5"],"taskStatements":["5.5"],"objectives":["O22"],"stem":"Every extraction is currently reviewed by a team of 14 people. On a 12,000-document labeled validation set made up of 81% typed invoices, 11% credit memos and 8% handwritten delivery receipts, the pipeline scores 97.2% field-level accuracy overall. Leadership wants to auto-approve high-confidence extractions and shrink the review team to three people without letting accuracy drop for any document type. What should the team do before switching on auto-approval?","options":[{"key":"A","text":"Draw a random sample of 1,000 high-confidence extractions and confirm accuracy holds at about 97%.","explanation":"Still a single blended number, and it contains only about 80 handwritten receipts, so a weak segment stays hidden."},{"key":"B","text":"Set a conservative confidence threshold of 0.95 instead of the proposed 0.90 to build in a margin.","explanation":"A stricter number chosen without calibration is still arbitrary and says nothing about per-type accuracy."},{"key":"C","text":"Have the model explain its confidence for each field and have reviewers check only fields where the explanation looks weak.","explanation":"Relies on self-reported reasoning, which is least reliable on exactly the hard cases."},{"key":"D","text":"Measure accuracy by document type and by field, and calibrate confidence thresholds per segment against the labeled set.","explanation":"Aggregate accuracy can mask a weak low-volume segment. Segment-level measurement plus calibrated thresholds directly meets the 'no type drops' goal."}],"correct":"D","tiebreaker":"Root cause","rationale":"Validate accuracy by document type and field before automating, and calibrate confidence thresholds using labeled data.","sources":[{"title":"Task 5.5: aggregate metrics can mask poor performance; analyze by document type and field; calibrate with labeled validation sets","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":["GUIDE","NEU"]},
{"id":"S6-006","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d5"],"taskStatements":["5.5","4.6"],"objectives":["O22"],"stem":"Three months after launch, the pipeline processes about 42,000 documents a week, 89% of them auto-approved at calibrated thresholds, and downstream teams have reported no problems. The review team has capacity for about 600 extra reviews a week. The team wants an ongoing, trustworthy measure of the error rate in auto-approved output and early warning when something new goes wrong, such as a vendor changing its invoice template. How should they use that capacity?","options":[{"key":"A","text":"Review the auto-approved extractions whose confidence scores sit just above the threshold.","explanation":"Biased toward borderline cases; misses confidently wrong output, such as a new template handled wrongly with high confidence."},{"key":"B","text":"Review a stratified random sample of auto-approved extractions spread across document types and fields.","explanation":"Gives an unbiased error-rate estimate per segment and can surface new error patterns anywhere in the distribution."},{"key":"C","text":"Run a second Claude instance over all auto-approved documents and have humans review only the disagreements.","explanation":"Model agreement isn't ground truth (shared blind spots), doubles cost and doesn't yield a measured error rate."},{"key":"D","text":"Review a random sample of auto-approved documents from the highest-volume vendors.","explanation":"Random within a slice but ignores low-volume segments, where new problems often appear."}],"correct":"B","tiebreaker":"The option that meets every stated goal","rationale":"Stratified random sampling of high-confidence extractions measures ongoing error rates and detects novel error patterns.","sources":[{"title":"Task 5.5: stratified random sampling of high-confidence extractions for error rate measurement and novel pattern detection","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":["GUIDE"]},
{"id":"S6-007","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4"],"taskStatements":["4.5"],"objectives":["O23"],"stem":"The company runs two extraction workloads: a supplier onboarding portal where about 400 users a day upload a W-9 and wait on screen for a pre-filled form, and a nightly ingest of about 60,000 archived contracts whose data must be available within 30 hours of upload. Finance wants to capture the Message Batches API's 50% discount wherever it won't hurt the business. What should the team do?","options":[{"key":"A","text":"Move both workloads to batch, and have the portal show a processing message and email users when results are ready.","explanation":"Batch can take up to 24 hours, which breaks the on-screen experience the portal exists for."},{"key":"B","text":"Keep both workloads synchronous, since the Batches API offers no latency guarantee.","explanation":"True that there's no latency guarantee, but the archive's 30-hour window can absorb the 24-hour maximum, so this leaves savings on the table."},{"key":"C","text":"Move the archive ingest to batch, submitted often enough to meet the 30-hour SLA, and keep the portal synchronous.","explanation":"Matches each workload to its latency need: batch for latency-tolerant work, synchronous for blocking user interactions."},{"key":"D","text":"Move the portal to batch during off-peak hours only and keep the archive ingest synchronous.","explanation":"Backwards: puts the blocking workload on batch and pays full price for the tolerant one."}],"correct":"C","tiebreaker":"Match the tool to the latency requirement","rationale":"Message Batches API: 50% cost savings, up to 24-hour processing, no latency SLA. Use it for non-blocking workloads and size submission frequency to the SLA.","sources":[{"title":"Task 4.5: matching API approach to latency requirements; calculating submission frequency from SLA","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Batch processing","url":"https://platform.claude.com/docs/en/build-with-claude/batch-processing","type":"docs"},{"title":"Message Batches API reference (custom_id, results out of order, up to 24 hours)","url":"https://platform.claude.com/docs/en/api/messages/batches","type":"docs"}],"note":null,"corroborated":["GUIDE","DOCS"]},
{"id":"S6-008","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4"],"taskStatements":["4.5"],"objectives":["O23"],"stem":"A weekly batch of 20,000 insurance claim forms finished with 690 errors: 450 exceeded the context limit because attachments had been merged into 400-plus-page PDFs, and 240 hit a transient server error. The team wants to get every claim processed this week at the lowest extra cost. What should they do?","options":[{"key":"A","text":"Resubmit the entire 20,000-request batch so every result comes from the same run and the records are easy to track.","explanation":"Reprocesses 19,310 successful requests for nothing, and the oversized documents still fail."},{"key":"B","text":"Resubmit all 690 failed requests unchanged in a new batch.","explanation":"Right instinct to resubmit only failures, but the 450 oversized documents will fail again unchanged."},{"key":"C","text":"Process the 690 failed claims synchronously so they finish quickly.","explanation":"Pays full price and still doesn't fix the oversized documents."},{"key":"D","text":"Use custom_id to find the failures; resubmit the 240 transient ones as-is and split the 450 oversized documents.","explanation":"custom_id correlates results so only failures are resubmitted, and inputs that caused the failure are modified first."}],"correct":"D","tiebreaker":"Smallest thing that works","rationale":"Handle batch failures by resubmitting only failed requests, identified by custom_id, with modifications where the input caused the failure.","sources":[{"title":"Task 4.5: resubmit only failed documents (identified by custom_id) with modifications","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Batch processing","url":"https://platform.claude.com/docs/en/build-with-claude/batch-processing","type":"docs"},{"title":"Message Batches API reference (custom_id, results out of order, up to 24 hours)","url":"https://platform.claude.com/docs/en/api/messages/batches","type":"docs"}],"note":null,"corroborated":["GUIDE","DOCS"]},
{"id":"S6-009","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4","d1"],"taskStatements":["4.5","1.1"],"objectives":["O37"],"stem":"The procurement team wants to move purchase order extraction onto the Message Batches API. The current synchronous design has Claude read each purchase order, call lookup_vendor to get a canonical vendor ID from a 48,000-entry vendor master, and then call submit_extraction. The team wants every batched request to produce a complete extraction with a valid vendor ID. How should they design it?","options":[{"key":"A","text":"Include the full vendor master in each request's prompt so Claude can pick the vendor ID without making a tool call.","explanation":"Removes the tool loop but bloats every request with 48,000 entries and buries the answer mid-context."},{"key":"B","text":"Extract the vendor name in one forced submit_extraction call per request, then resolve the vendor ID in code.","explanation":"A batch request is a single turn, so nothing returns the lookup result. One extraction call plus a deterministic lookup in code fits the batch model."},{"key":"C","text":"Keep the two-tool design and set tool_choice to 'any' so both calls are made.","explanation":"tool_choice can't create a second turn; the request still stops after the first tool call."},{"key":"D","text":"Keep the two-tool design and raise max_tokens so the model has room to complete both calls.","explanation":"Token limits aren't the issue; the missing tool result is."}],"correct":"B","tiebreaker":"Root cause","rationale":"The Batches API does not support multi-turn tool calling within a single request. Move multi-step lookups into application code.","sources":[{"title":"Task 4.5: Batch API does not support multi-turn tool calling within a single request","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Batch processing","url":"https://platform.claude.com/docs/en/build-with-claude/batch-processing","type":"docs"}],"note":"Forcing a named tool may be rejected on the newest models (see S6-004 note); the design point, keeping lookups out of the batch request, is unaffected.","corroborated":["GUIDE"]},
{"id":"S6-010","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d5","d4"],"taskStatements":["5.1","4.6"],"objectives":["O28"],"stem":"The lending team wants to extract 25 covenant terms from 180-page commercial loan agreements, about 110,000 tokens each, and needs consistently high recall no matter where in the agreement a covenant appears. In testing, a single call over the whole document missed 3% of covenants on the first 40 and last 30 pages but 23% of those in the middle. Which design should they adopt?","options":[{"key":"A","text":"Run section-level passes that record page numbers, then a consolidation pass that merges results and flags conflicts.","explanation":"Shorter passes remove the long middle where attention drops, and page metadata preserves provenance for consolidation."},{"key":"B","text":"Keep the single call over the whole document, but repeat the extraction instructions at both the very start and the end.","explanation":"Helps the model remember what to do, not attend to content buried in the middle."},{"key":"C","text":"Keep the single call and add an instruction to pay particular attention to the middle sections.","explanation":"A vague nudge that doesn't change the underlying position effect."},{"key":"D","text":"Move to a model with a larger context window.","explanation":"The document already fits; a bigger window doesn't fix lost-in-the-middle."}],"correct":"A","tiebreaker":"Root cause","rationale":"Lost in the middle: models process the start and end of long inputs more reliably than the middle. Split into focused passes plus an integration pass.","sources":[{"title":"Task 5.1: lost-in-the-middle effect; Task 4.6: multi-pass architectures","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":["GUIDE","DOCS"]},
{"id":"S6-011","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4"],"taskStatements":["4.2","4.3"],"objectives":["O29"],"stem":"The logistics team extracts length in meters and weight in kilograms from handwritten bills of lading, where drivers write values like 'approx 2 and a half meters', 8'6\", '1.2 t' and '2400 lbs'. Today a paragraph of prose explains the conversion rules, and the team wants the model to normalize these informal values reliably while still returning null when a value is genuinely missing. What should they do?","options":[{"key":"A","text":"Replace the prose with a full conversion table covering every unit and abbreviation that drivers might plausibly use.","explanation":"Better than prose but still describes the transformation instead of demonstrating it, and doesn't teach when null is right."},{"key":"B","text":"Make both fields required so the model always produces a value.","explanation":"Turns genuinely missing values into fabricated ones, breaking the null requirement."},{"key":"C","text":"Add three or four few-shot examples of informal inputs and their normalized outputs, including a genuinely absent value.","explanation":"Few-shot examples are the most effective way to handle varied informal formats, and the absent case teaches when null is correct."},{"key":"D","text":"Preprocess the text with regular expressions that convert units before sending it to Claude.","explanation":"Regex can't reliably handle phrasing like '2 and a half meters' or every driver's shorthand."}],"correct":"C","tiebreaker":"Built-in technique that targets the problem","rationale":"Use 2 to 4 targeted few-shot examples for varied formats; include an empty or null case to prevent fabrication.","sources":[{"title":"Task 4.2: few-shot for informal measurements and varied formats, addressing empty/null fields","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Prompting best practices: use examples","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":["GUIDE","CCAP","DOCS"]},
{"id":"S6-012","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d5"],"taskStatements":["5.6","4.4","5.5"],"objectives":["O19","O22"],"stem":"Accounts payable schedules supplier payments automatically from the extracted payment terms. About 6% of contracts state one set of terms in the main body and different terms in an amended schedule, and legal says which one governs depends on amendment language that varies from contract to contract. The team wants automatic scheduling to continue for clean contracts while never paying on the wrong terms. Which approach should they take?","options":[{"key":"A","text":"Instruct the model to always prefer the terms in the latest schedule or amendment.","explanation":"A clean deterministic rule, but legal says it doesn't hold for every contract, so some payments would go out on the wrong terms."},{"key":"B","text":"Extract both values with their locations, flag the conflict, and route flagged contracts to human review.","explanation":"Preserves both values with attribution and surfaces the conflict for a human, while clean contracts keep flowing automatically."},{"key":"C","text":"Ask the model for a confidence score on the payment terms and auto-schedule only when it exceeds 0.9.","explanation":"Self-reported confidence doesn't resolve a genuine conflict in the source document."},{"key":"D","text":"Have the model read the amendment clause and decide which terms govern, recording its reasoning in a notes field.","explanation":"Asks the model to make the exact case-by-case legal judgment legal says varies, then acts on it automatically."}],"correct":"B","tiebreaker":"The option that meets every stated goal","rationale":"When sources conflict, annotate both values with attribution rather than arbitrarily picking one, and route ambiguous or contradictory documents to human review.","sources":[{"title":"Task 5.6: annotate conflicting values with source attribution; Task 5.5: route contradictory source documents to human review","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Reduce hallucinations","url":"https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/reduce-hallucinations","type":"docs"}],"note":null,"corroborated":["GUIDE","NEU"]},
{"id":"S6-013","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4"],"taskStatements":["4.3"],"objectives":["O26"],"stem":"A records team classifies scanned documents with a document_type enum of six values: invoice, receipt, contract, purchase order, credit memo and statement. About 9% of incoming documents are types outside that list, such as pro forma invoices and packing slips, and about 2% are torn or illegible scans. Today the model forces all of these into the nearest category, and they land in the wrong processing queues. The team wants every document to reach a queue that fits it and wants new document types to be identifiable for future schema updates, without maintaining a sprawling enum. What should they change?","options":[{"key":"A","text":"Expand the enum so it covers every document type the team has ever received, roughly 25 values in all.","explanation":"Helps today, but the next new type is still forced into a wrong category, illegible scans still have nowhere to go, and the enum keeps growing."},{"key":"B","text":"Change document_type to a free-text string so the model can describe any document it receives.","explanation":"Captures anything but loses the fixed values that routing depends on."},{"key":"C","text":"Add an 'other' value with a detail string and an 'unclear' value, and route both to a triage queue.","explanation":"'other' plus a detail string makes the category extensible and records what new types look like; 'unclear' gives illegible scans an honest answer instead of a forced guess."},{"key":"D","text":"Add an instruction telling the model to choose the closest category carefully.","explanation":"The schema still offers no correct answer for these documents, so careful choice still means a wrong choice."}],"correct":"C","tiebreaker":"Root cause","rationale":"Enums without an escape hatch force misclassification. Add 'other' plus a detail field and 'unclear' for extensible, honest categorisation.","sources":[{"title":"Task 4.3: adding 'unclear' and 'other' enum values with detail fields for extensible categorization","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Tool use with Claude","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/overview","type":"docs"}],"note":null,"corroborated":["GUIDE","ACG"]},
{"id":"S6-014","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4"],"taskStatements":["4.3"],"objectives":["O29"],"stem":"The ERP requires invoice dates in ISO 8601. The extraction schema already defines invoice_date as a string, but source documents write dates as '03/04/25', '4 March 2025' or '2025-03-04'. About 11% of extracted dates come back in their source format, and about 1.5% are posted with day and month swapped because vendors in different countries write dates differently. The team wants consistent ISO dates with the correct day and month order, and wants to keep the existing schema. What should they do?","options":[{"key":"A","text":"Add normalisation rules to the prompt: output ISO 8601, use the vendor's country to resolve day and month order, null if unsure.","explanation":"The schema enforces structure; the prompt sets formatting rules, and only the model reading the document can use context like vendor country to resolve ambiguity."},{"key":"B","text":"Convert whatever date strings come back using a date-parsing library in post-processing, before the ERP import runs.","explanation":"Fixes the format but can't tell whether 03/04/25 means March or April, so the swapped dates remain."},{"key":"C","text":"Add a pattern constraint to the schema's date field so that it only accepts values written as YYYY-MM-DD.","explanation":"Forces the shape, but the model still has to guess day/month order with no rule to follow, so swaps continue in valid-looking form."},{"key":"D","text":"Add a retry loop that re-asks whenever the returned date isn't in ISO format.","explanation":"Pays for extra calls to fix format and does nothing about swapped day and month."}],"correct":"A","tiebreaker":"Root cause","rationale":"Include format normalisation rules in prompts alongside strict output schemas; schemas constrain structure, not interpretation.","sources":[{"title":"Task 4.3: including format normalization rules in prompts alongside strict output schemas","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Prompting best practices: be clear and direct","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":["GUIDE","ACG"]},
{"id":"S6-015","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4","d2"],"taskStatements":["4.3","2.3"],"objectives":["O37"],"stem":"A pipeline must run extract_metadata, which returns document type, language and page count, before it chooses which detailed extraction tool to use. With tool_choice set to 'any' and all tools offered, about 7% of requests call a detail tool such as extract_invoice_details first, skipping metadata, and downstream routing breaks for those documents. The team wants metadata extracted first on every document, followed by the normal flexible choice of detail tool. How should they configure the requests?","options":[{"key":"A","text":"Keep tool_choice 'any' and list extract_metadata first in the tools array.","explanation":"Tool order in the array doesn't enforce which tool is called first."},{"key":"B","text":"Add a system prompt instruction to always call extract_metadata first, before calling any of the detail extraction tools.","explanation":"Likely to improve the 7% but can't guarantee it, and routing breaks whenever it slips."},{"key":"C","text":"Offer only extract_metadata in the first request, with tool_choice left on 'auto', then the detail tools next.","explanation":"Close, but 'auto' still allows a plain-text reply instead of the metadata call."},{"key":"D","text":"Force extract_metadata by name on the first request, then send the detail tools with tool_choice 'any' on the next.","explanation":"Forcing the named tool guarantees the mandatory first step; switching back to 'any' restores flexible schema choice for the next step."}],"correct":"D","tiebreaker":"Guaranteed beats likely","rationale":"Use forced tool selection to make a specific tool run first in a pipeline; tool_choice applies per request.","sources":[{"title":"Task 4.3: forcing a specific tool with tool_choice {'type': 'tool', 'name': 'extract_metadata'} for pipeline ordering","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Define tools: forcing tool use","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools#forcing-tool-use","type":"docs"}],"note":"Answer per the exam guide. On the newest models the docs report forced tool_choice returns a 400 error; the documented alternative there is 'auto' with strict: true.","corroborated":["GUIDE","ACG","DOCS"]},
{"id":"S6-016","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4"],"taskStatements":["4.4"],"objectives":[],"stem":"An extraction pipeline's validation-retry loop currently sends a follow-up message that says only 'Your previous answer failed validation, please try again.' Retries fix 41% of failures. The team wants a much higher fix rate on retries without adding human review. What should they change?","options":[{"key":"A","text":"Increase the maximum number of retries from two to four so that more of the failures get another chance to pass.","explanation":"More attempts with the same missing information mostly repeat the same mistakes at higher cost."},{"key":"B","text":"Include the original document, the failed extraction and the specific validation errors in the retry request.","explanation":"Specific error feedback tells the model exactly what to fix, which is what makes retries effective."},{"key":"C","text":"Route retries to a larger model.","explanation":"May help a little, but the larger model still doesn't know what failed."},{"key":"D","text":"Lower the temperature on retry requests.","explanation":"Makes output more deterministic, which tends to reproduce the same error."}],"correct":"B","tiebreaker":"Root cause","rationale":"Retry-with-error-feedback: include the original document, the failed extraction and the specific validation errors.","sources":[{"title":"Task 4.4: follow-up requests that include the original document, the failed extraction and specific validation errors","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":["GUIDE","NEU","CSK"]},
{"id":"S6-017","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4"],"taskStatements":["4.4"],"objectives":["O30"],"stem":"The extraction pipeline raises anomaly flags such as 'possible duplicate invoice' and 'unusual amount' for accounts payable reviewers, and reviewers dismiss 62% of them. The team wants to find out which kinds of flags are mostly false positives so they can fix the right rules, without reducing the amount of review. What should they add?","options":[{"key":"A","text":"A free-text comment box that reviewers fill in whenever they dismiss a flag, explaining their reasons in their own words.","explanation":"Captures some context, but free text is inconsistent and hard to aggregate across thousands of dismissals."},{"key":"B","text":"A higher confidence threshold before any flag is raised.","explanation":"Cuts flags across the board without showing which rules are wrong, and reduces coverage the team wanted to keep."},{"key":"C","text":"A detected_pattern field on each flag, recording which rule triggered it so dismissals can be grouped by rule.","explanation":"A structured pattern field makes dismissal rates measurable per rule, pointing directly at the rules that need fixing."},{"key":"D","text":"A second Claude instance that re-reviews every dismissed flag.","explanation":"Adds cost and a second opinion, but still doesn't tell the team which rules produce the false positives."}],"correct":"C","tiebreaker":"Root cause","rationale":"Add a detected_pattern field to findings to enable systematic analysis of dismissal and false-positive patterns.","sources":[{"title":"Task 4.4: detected_pattern field in findings to enable systematic analysis of dismissal patterns","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":["GUIDE"]},
{"id":"S6-018","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4"],"taskStatements":["4.5"],"objectives":["O23"],"stem":"The team is about to batch-process 400,000 historical contracts as a one-time migration. The extraction prompt was developed and tested on 20 hand-picked contracts. The team wants to avoid paying for a full run that then has to be redone. What should they do first?","options":[{"key":"A","text":"Run the prompt on a few hundred representative contracts, fix the issues found, then submit the full batch.","explanation":"Refining on a sample catches problems at a fraction of the cost before committing the full volume."},{"key":"B","text":"Submit the full batch now, since the 50% batch discount makes a rerun affordable.","explanation":"A rerun still doubles the cost of 400,000 requests, and the discount doesn't change that."},{"key":"C","text":"Process the full set synchronously so problems can be spotted and stopped early.","explanation":"Pays full price on every request to get early visibility a sample would give far more cheaply."},{"key":"D","text":"Split the job into 40 batches of 10,000 and refine the prompt between batches as problems show up in results.","explanation":"Works, but early batches run on a flawed prompt and results are inconsistent across the migration."}],"correct":"A","tiebreaker":"Smallest thing that works","rationale":"Use prompt refinement on a representative sample set before batch-processing large volumes.","sources":[{"title":"Task 4.5: using prompt refinement on a sample set before batch-processing large volumes","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Batch processing","url":"https://platform.claude.com/docs/en/build-with-claude/batch-processing","type":"docs"}],"note":null,"corroborated":["GUIDE"]},
{"id":"S6-019","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4"],"taskStatements":["4.5"],"objectives":["O23"],"stem":"Supplier documents arrive continuously throughout the day, and extracted data must be available within 30 hours of a document's arrival. The Message Batches API can take up to 24 hours to process a batch. The team wants the batch discount with as few submissions as possible while still meeting the SLA for every document. How often should they submit batches?","options":[{"key":"A","text":"Once every 24 hours.","explanation":"A document arriving just after a submission waits up to 24 hours, then up to 24 more to process: 48 hours."},{"key":"B","text":"Once every 12 hours.","explanation":"Fewer submissions, but the worst case is 12 hours waiting plus 24 processing, or 36 hours, over the SLA."},{"key":"C","text":"Never; process synchronously, because batch can't guarantee any SLA.","explanation":"The worst case can be bounded by submission frequency, so this gives up the discount unnecessarily."},{"key":"D","text":"Once every 4 hours.","explanation":"Worst case is 4 hours waiting plus 24 processing, or 28 hours, inside the 30-hour SLA with some margin."}],"correct":"D","tiebreaker":"The option that meets every stated goal","rationale":"Worst-case latency equals the submission interval plus the 24-hour processing window; size the interval so the sum stays inside the SLA.","sources":[{"title":"Task 4.5: calculating batch submission frequency based on SLA constraints (e.g., 4-hour windows for 30-hour SLA)","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Batch processing","url":"https://platform.claude.com/docs/en/build-with-claude/batch-processing","type":"docs"},{"title":"Message Batches API reference (custom_id, results out of order, up to 24 hours)","url":"https://platform.claude.com/docs/en/api/messages/batches","type":"docs"}],"note":null,"corroborated":["GUIDE","DOCS"]},
{"id":"S6-020","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4"],"taskStatements":["4.6"],"objectives":[],"stem":"Extracted terms from contracts worth more than $1 million get a second check before the data is used. Today, the same conversation that produced the extraction is asked to 'review your extraction for errors', and in testing it caught only 12% of deliberately seeded errors. The team wants a second check that catches subtle mistakes. Which design should they use?","options":[{"key":"A","text":"Keep the self-review but add an instruction to be highly critical.","explanation":"The reviewer still carries the reasoning that produced the errors, which makes it unlikely to question them."},{"key":"B","text":"Run a separate Claude instance that gets only the document and extracted JSON, without the original reasoning.","explanation":"An independent instance has no stake in the original reasoning, so it is more likely to catch subtle errors."},{"key":"C","text":"Run the extraction three times and take a majority vote on each field.","explanation":"Helps surface inconsistent outputs but triples cost, and errors the model makes consistently still win the vote."},{"key":"D","text":"Have the same instance re-extract from scratch later in the same conversation, and compare the two sets of results.","explanation":"The earlier reasoning is still in context, so the re-extraction tends to repeat it."}],"correct":"B","tiebreaker":"Root cause","rationale":"Self-review retains generation context; an independent instance without that context is more effective at catching subtle issues.","sources":[{"title":"Task 4.6: using a second independent Claude instance to review without the generator's reasoning context","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":["GUIDE"]},
{"id":"S6-021","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d5"],"taskStatements":["5.5"],"objectives":["O22"],"stem":"The pipeline extracts about 9,000 documents a day, and reviewers can handle about 900. Today each document gets one document-level confidence score, and any flagged document is reviewed in full, so reviewers spend most of their time re-checking fields that were already correct. The team wants reviewer time spent where errors actually are, within that capacity. What should they implement?","options":[{"key":"A","text":"Field-level confidence, calibrated per field on a labeled set, routing low-confidence fields and conflicting sources to review.","explanation":"Field-level, calibrated confidence points reviewers at the specific fields likely to be wrong, which is how limited capacity is prioritised."},{"key":"B","text":"Keep the document-level score but tune its threshold so exactly 900 documents, the reviewers' capacity, are flagged daily.","explanation":"Fits capacity, but reviewers still re-check whole documents and the threshold isn't calibrated to accuracy."},{"key":"C","text":"Send the longest documents to review, since longer documents tend to contain more errors.","explanation":"A proxy that ignores where errors actually occur."},{"key":"D","text":"Ask the model to list in free text any fields it feels unsure about.","explanation":"Uncalibrated self-reporting, and free text is hard to route reliably."}],"correct":"A","tiebreaker":"Root cause","rationale":"Use field-level confidence calibrated with labeled validation sets to route review attention, prioritising limited reviewer capacity.","sources":[{"title":"Task 5.5: field-level confidence scores calibrated using labeled validation sets for routing review attention","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":["GUIDE","NEU"]},
{"id":"S6-022","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d5","d1"],"taskStatements":["5.1","1.5"],"objectives":["O21"],"stem":"An extraction agent calls lookup_vendor for every invoice it processes, and each call returns about 45 fields of vendor data, including bank details, contacts and payment history. Only five fields matter for extraction: vendor ID, name, tax ID, payment terms and status. After about 60 invoices in one session the context is nearly full and extraction accuracy starts to slip. The team wants accuracy to stay steady through long sessions. What should they do?","options":[{"key":"A","text":"Move the extraction agent to a model with a larger context window so that long sessions fit comfortably.","explanation":"Postpones the problem; irrelevant data still accumulates and competes for attention."},{"key":"B","text":"Summarise the conversation every 20 invoices so older vendor data is compressed and context space is freed up again.","explanation":"Frees space but risks condensing exact values like amounts and IDs into vague summaries."},{"key":"C","text":"Trim lookup_vendor results to the five relevant fields before they enter the context, for example in a hook.","explanation":"Removes the irrelevant bulk at its source, so context holds only what the extraction needs."},{"key":"D","text":"Instruct the model to ignore vendor fields it doesn't need.","explanation":"The fields still occupy context; the instruction only asks the model not to use them."}],"correct":"C","tiebreaker":"Root cause","rationale":"Tool results accumulate in context disproportionately to their relevance; trim verbose tool outputs to relevant fields before they accumulate.","sources":[{"title":"Task 5.1: trimming verbose tool outputs to only relevant fields before they accumulate in context","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":["GUIDE"]},
{"id":"S6-023","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d5"],"taskStatements":["5.6","1.3"],"objectives":["O18"],"stem":"The audit team needs every value extracted from loan files to be traceable to where it came from, so auditors can verify it quickly. Today the pipeline returns values only, and auditors spend about 20 minutes per file finding where each value appears. The team wants auditors to verify a value in seconds. What should they change?","options":[{"key":"A","text":"Ask the model to add a closing paragraph to each extraction summarising where the key values came from in the file.","explanation":"A prose summary loses the link between each specific value and its location."},{"key":"B","text":"Store the full source document alongside each extraction so auditors always have the original right next to it.","explanation":"Necessary, but auditors still have to hunt for each value."},{"key":"C","text":"Have reviewers record sources manually for files that get flagged.","explanation":"Slow, partial and only covers flagged files."},{"key":"D","text":"Extend the schema so each field carries its value, source page and a verbatim excerpt, kept through later merging.","explanation":"Structured value-to-source mapping makes every value verifiable at a glance and survives later processing."}],"correct":"D","tiebreaker":"Root cause","rationale":"Preserve claim-source mappings in structured output, separating content from metadata such as page numbers and excerpts.","sources":[{"title":"Task 5.6: structured claim-source mappings preserved through synthesis; Task 1.3: structured formats separating content from metadata","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Reduce hallucinations","url":"https://platform.claude.com/docs/en/test-and-evaluate/strengthen-guardrails/reduce-hallucinations","type":"docs"}],"note":null,"corroborated":["GUIDE","DOCS"]},
{"id":"S6-024","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d5"],"taskStatements":["5.6"],"objectives":["O19"],"family":"dated-figures","stem":"The pipeline extracts unit prices from supplier documents. One supplier's January price list says $4.10 per unit and its June amendment says $4.45. Downstream checks flag any differing prices for the same item as contradictions, and 18% of suppliers get flagged, though reviewers find most are simply price changes over time. The team wants to cut these false conflicts while still catching genuine contradictions. What should they do?","options":[{"key":"A","text":"Keep only the most recently extracted price for each item and drop older values, so there is never a conflict to flag.","explanation":"Simple, but the most recently processed document isn't necessarily the latest in effect, history is lost, and genuine same-period contradictions disappear."},{"key":"B","text":"Require an effective date with every extracted price, so downstream flags only disagreements within the same period.","explanation":"Dates let downstream tell an update from a contradiction, which removes the false flags without hiding real ones."},{"key":"C","text":"Only flag price differences larger than 10%.","explanation":"Hides small genuine contradictions and still flags large legitimate updates."},{"key":"D","text":"Instruct the model to resolve price conflicts itself before outputting.","explanation":"Pushes a judgment into the extraction step without the date information needed to make it."}],"correct":"B","tiebreaker":"Root cause","rationale":"Require publication or collection dates in structured outputs so temporal differences aren't misread as contradictions.","sources":[{"title":"Task 5.6: requiring publication or data collection dates in structured outputs to enable correct temporal interpretation","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":["GUIDE"]},
{"id":"S6-025","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4"],"taskStatements":["4.2"],"objectives":["O29"],"stem":"Invoices list line items in a table about 70% of the time, in prose in the body about 20% of the time (for example, 'plus installation, two hours at $95'), and in an attached schedule about 10% of the time. Line items written in prose are missed 31% of the time. The team wants line items captured whatever the layout. What should they do?","options":[{"key":"A","text":"Add three or four few-shot examples showing correct line-item extraction from each layout, prose and schedule included.","explanation":"Examples showing each structure teach the model where line items can hide and how to extract them, which instructions alone convey poorly."},{"key":"B","text":"Add an instruction telling the model to look for line items anywhere in the document, not only inside tables.","explanation":"A reasonable nudge, but describing the requirement is less reliable than demonstrating the varied cases."},{"key":"C","text":"Preprocess documents to convert prose descriptions of charges into tables before the extraction step runs.","explanation":"Converting prose to tables is itself the hard extraction problem, moved to a less capable step."},{"key":"D","text":"Make line_items required with at least one item.","explanation":"Ensures something is returned but not that prose items are found, and invites fabrication."}],"correct":"A","tiebreaker":"Built-in technique that targets the problem","rationale":"Few-shot examples are effective for varied document structures and reduce misses and hallucination in extraction.","sources":[{"title":"Task 4.2: few-shot examples for varied document structures","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Prompting best practices: use examples","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":["GUIDE","CCAP","DOCS"]},
{"id":"S6-026","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4"],"taskStatements":["4.1"],"objectives":["O31"],"stem":"The pipeline flags 'suspicious' invoices for fraud review using a prompt that says 'only flag invoices you are highly confident are suspicious.' About 70% of flags are false positives, mostly round amounts and first invoices from new vendors, and reviewers have started ignoring the queue; two real fraud cases were missed last quarter. The team wants reviewers to trust the queue again while still catching real fraud. What should they change?","options":[{"key":"A","text":"Reword the instruction to 'be very conservative and only flag clear-cut cases', keeping the rest of the prompt unchanged.","explanation":"Another vague instruction, which the guide notes fails compared to specific criteria."},{"key":"B","text":"Ask for a confidence score on every flag and only surface the flags that score above 0.9 to reviewers.","explanation":"Self-reported confidence is poorly calibrated, so false positives can still score high."},{"key":"C","text":"Stop flagging invoices entirely until a dedicated fraud-detection model has been built and tested.","explanation":"Restores nothing and guarantees real fraud is missed in the meantime."},{"key":"D","text":"Replace it with explicit criteria: flag mismatched bank details, duplicates and over-PO amounts; skip round amounts and new vendors.","explanation":"Specific categorical criteria cut the known false positives while keeping the signals that matter."}],"correct":"D","tiebreaker":"Root cause","rationale":"Explicit, categorical criteria beat vague instructions like 'be conservative'; high false-positive rates undermine trust in accurate findings.","sources":[{"title":"Task 4.1: explicit criteria over vague instructions to reduce false positives","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Prompting best practices: be clear and direct","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":["GUIDE"]},
{"id":"S6-027","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d5"],"taskStatements":["5.2"],"objectives":[],"stem":"When the extracted vendor name is 'Acme Supply', the vendor lookup returns three matching records in different cities. Today the pipeline picks the most recently used record, and about 8% of those invoices are posted to the wrong vendor. The team wants invoices posted to the correct vendor without guessing. What should they do?","options":[{"key":"A","text":"Pick the matching vendor record with the most invoices already on file, since it's the most likely to be the right supplier.","explanation":"Still a heuristic guess, just a different one."},{"key":"B","text":"Use fuzzy matching on the vendor name to pick whichever of the matching records is the closest overall.","explanation":"All three names already match; fuzzy matching can't separate them."},{"key":"C","text":"Match on other identifiers on the invoice, such as tax ID and remit-to address, and send still-ambiguous ones to review.","explanation":"Additional identifiers resolve most multi-matches deterministically, and review handles the rest instead of a guess."},{"key":"D","text":"Send every invoice whose vendor name matches more than one record to human review, whatever else the invoice shows.","explanation":"Safe, but sends cases the invoice itself could resolve to people."}],"correct":"C","tiebreaker":"Smallest thing that works","rationale":"Multiple matches require clarification with additional identifiers rather than heuristic selection.","sources":[{"title":"Task 5.2: multiple matches require additional identifiers rather than heuristic selection","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":["GUIDE"]},
{"id":"S6-028","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4"],"taskStatements":["4.5"],"objectives":["O23"],"stem":"The team joins Message Batches API results back to their source documents by position in the results file. After one run, about 3% of extractions were attached to the wrong document. The team wants every result reliably matched to its source document. What should they do?","options":[{"key":"A","text":"Sort results by completion timestamp before joining them to documents.","explanation":"Completion order has nothing to do with request order."},{"key":"B","text":"Set each request's custom_id to its document ID and join results on custom_id.","explanation":"custom_id exists to correlate results with requests, because results may be returned out of request order."},{"key":"C","text":"Submit smaller batches so results come back in order.","explanation":"Batch size doesn't guarantee ordering."},{"key":"D","text":"Put the document ID in each prompt and ask the model to echo it in its output.","explanation":"Usually works, but depends on the model copying the ID correctly every time."}],"correct":"B","tiebreaker":"Built-in feature over workaround","rationale":"Use custom_id fields to correlate batch request and response pairs.","sources":[{"title":"Task 4.5: custom_id fields for correlating batch request/response pairs","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Message Batches API reference (custom_id, results out of order, up to 24 hours)","url":"https://platform.claude.com/docs/en/api/messages/batches","type":"docs"}],"note":null,"corroborated":["GUIDE","DOCS"]},
{"id":"S6-029","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d2","d5"],"taskStatements":["2.2","5.3"],"objectives":[],"stem":"An extraction agent calls an OCR tool that returns 'OCR failed' for every kind of failure, and the agent retries each failure three times. About 60% of failures are pages that can never be read, while 40% are timeouts that succeed on retry. The team wants to stop wasting retries while still recovering the timeouts. What should they change?","options":[{"key":"A","text":"Return structured errors with a category (transient or unreadable) and an isRetryable flag; retry only transient ones.","explanation":"Structured error metadata lets the agent make the right recovery decision for each failure type."},{"key":"B","text":"Remove retries entirely.","explanation":"Stops the waste but loses the timeouts that would have succeeded."},{"key":"C","text":"Retry every failure with exponential backoff, so that timeouts have time to clear before each further attempt is made.","explanation":"Handles timeouts better, but still wastes retries on pages that can never succeed."},{"key":"D","text":"Add an instruction telling the agent not to retry OCR failures more than once.","explanation":"Still retries unreadable pages once and may give up on a timeout that needed a second try."}],"correct":"A","tiebreaker":"Root cause","rationale":"Uniform error responses prevent appropriate recovery; structured errorCategory and isRetryable metadata prevent wasted retries.","sources":[{"title":"Task 2.2: structured error metadata (errorCategory, isRetryable) and retryable vs non-retryable errors","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":["GUIDE","CCAP"]},
{"id":"S6-030","exam":"CCAR-F","set":"scenario6_core","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":"You are building a structured data extraction system using Claude. It extracts information from unstructured business documents such as invoices, contracts, receipts, shipping paperwork and claim forms, validates the output against JSON schemas, and feeds downstream systems including an ERP and accounts payable. It must maintain high accuracy, handle edge cases gracefully and integrate cleanly with downstream systems.","domains":["d4"],"taskStatements":["4.6"],"objectives":["O28"],"stem":"A loan packet contains 14 documents, including an application, pay stubs, bank statements and tax returns. One call extracts everything and checks consistency across documents, such as whether stated income matches the pay stubs. The cross-document checks are inconsistent: some mismatches are caught and others are missed on identical packets. The team wants reliable cross-document reconciliation. Which design should they use?","options":[{"key":"A","text":"Raise max_tokens so the single call has room for every check.","explanation":"Output length isn't the cause; attention spread across 14 documents is."},{"key":"B","text":"Move all of the reconciliation instructions to the end of the prompt, after all 14 of the documents.","explanation":"Placement may help a little but doesn't fix attention dilution across many documents."},{"key":"C","text":"Add a self-review step in the same conversation that re-checks the full reconciliation before the results are returned.","explanation":"Self-review keeps the original reasoning, so it tends to confirm its own misses."},{"key":"D","text":"Extract each document in its own pass into structured output, then run a separate reconciliation pass on the results.","explanation":"Per-document passes give each document full attention; the integration pass compares compact structured data instead of 14 raw documents."}],"correct":"D","tiebreaker":"Root cause","rationale":"Multi-pass review: local per-item passes plus a separate integration pass avoid attention dilution.","sources":[{"title":"Task 4.6: multi-pass review with local passes plus cross-item integration passes","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":["GUIDE"]},
{"id":"W-001","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d1"],"taskStatements":["1.1","1.3"],"objectives":["O01"],"stem":"A platform team runs a custom agent loop that helps engineers understand unfamiliar services. A typical question needs six independent file reads, and logs show the agent makes one Read call per turn, so answers take about 80 seconds across six round trips. The loop code appends each tool_result to the conversation as its own user message. The team wants independent reads to happen together in fewer round trips. What should they change?","options":[{"key":"A","text":"Replace the six reads with one new tool that returns the full contents of a directory, so every file arrives in a single call.","explanation":"Cuts round trips by loading whole directories, which floods context with files the question never needed."},{"key":"B","text":"Return all tool_result blocks from a turn together in one user message, and tell the agent to call independent tools at the same time.","explanation":"Splitting results into separate user messages is the most common reason Claude stops making parallel calls; one message with every result, plus a short prompt nudge, restores them."},{"key":"C","text":"Raise max_tokens so the model has room to request every file it needs in a single response.","explanation":"Output length isn't what limits the calls; the loop's message structure is."},{"key":"D","text":"Set disable_parallel_tool_use to false as a top-level request parameter, so the API is explicitly told to allow several tool calls per response.","explanation":"Parallel calls are already on by default, and the flag lives inside tool_choice, not at the top level; flipping it changes nothing here."}],"correct":"B","tiebreaker":"Root cause","rationale":"Claude can emit several tool_use blocks in one response. Return one tool_result per call, all in the next user message; separate messages per result teach the model to stop parallelising.","sources":[{"title":"Task 1.3: spawning parallel subagents by emitting multiple calls in a single response; Task 1.1: agentic loop lifecycle","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Parallel tool use","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/parallel-tool-use","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-002","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3","1.2"],"objectives":["O01","O10"],"family":"parallel-subagents","stem":"A research coordinator splits each request into four independent subtopics and hands each to a research subagent. Each subagent takes about 2.5 minutes, and because the coordinator spawns one subagent per turn and waits for it, a full report takes over 11 minutes. The team wants reports in under 4 minutes while the coordinator still collects and checks every subagent's findings. What should they do?","options":[{"key":"A","text":"Give one subagent all four subtopics in a single invocation, so the request needs only one delegation and one result to aggregate.","explanation":"One subagent working through four topics is still sequential, and coverage of each topic tends to thin out."},{"key":"B","text":"Cap each subagent at fewer turns so each finishes faster.","explanation":"Shortens each run by cutting research depth, and the four still run one after another."},{"key":"C","text":"Run four separate coordinators in parallel, one per subtopic, and concatenate their four reports into the final answer.","explanation":"Parallel, but no single coordinator checks coverage or resolves overlaps across subtopics."},{"key":"D","text":"Have the coordinator emit all four subagent calls in a single response so they run in parallel, then aggregate the results.","explanation":"Multiple Task calls in one coordinator response run concurrently, cutting wall time to roughly one subagent's duration while the coordinator keeps aggregation."}],"correct":"D","tiebreaker":"The option that meets every stated goal","rationale":"Spawn parallel subagents by emitting multiple calls in a single coordinator response; the coordinator still aggregates and evaluates.","sources":[{"title":"Task 1.3: spawning parallel subagents by emitting multiple Task calls in a single coordinator response","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Parallel tool use","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/parallel-tool-use","type":"docs"},{"title":"Claude Code subagents","url":"https://code.claude.com/docs/en/sub-agents","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-003","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3","1.2"],"objectives":["O04"],"stem":"The coordinator's prompt to its web research subagent is a 12-step procedure: search a fixed query, open the top three results, extract statistics from each, and so on. When the top results are paywalled, the subagent still follows the steps and returns thin findings, and coverage scores have dropped to 61%. The team wants the subagent to adapt when a step doesn't pan out, while the coordinator can still see what was done and what is missing. How should they change the delegation?","options":[{"key":"A","text":"State the research goal, quality bar and definition of done, and require a structured report of findings, sources and gaps.","explanation":"Goal-oriented delegation lets the subagent change tactics; the structured report keeps the coordinator informed and in control."},{"key":"B","text":"Add steps to the procedure that cover paywalled pages, missing statistics and the other failure cases seen so far in production.","explanation":"Patches the known failures but stays brittle; the next unexpected situation hits the same wall."},{"key":"C","text":"Let the research subagent spawn its own subagents whenever it decides the procedure isn't working, and report only final results.","explanation":"Adds adaptivity but moves decisions out of the coordinator's sight, losing the visibility the team wants."},{"key":"D","text":"Have the coordinator run the searches itself and pass only the pages to read to the subagent.","explanation":"Keeps control but drags verbose search work into the coordinator's context and removes the subagent's ability to adapt."}],"correct":"A","tiebreaker":"The option that meets every stated goal","rationale":"Coordinator prompts should specify research goals and quality criteria, not step-by-step procedures; structured outputs preserve coordinator visibility.","sources":[{"title":"Task 1.3: designing coordinator prompts with research goals and quality criteria, not step-by-step procedural instructions","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"W-004","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d1"],"taskStatements":["1.3","1.4"],"objectives":["O04"],"stem":"A support coordinator delegates billing investigations to a subagent with the one-line instruction 'investigate this billing issue'. The subagent sometimes wanders into unrelated account settings, and the coordinator can't tell what it checked, so 23% of cases are re-investigated by a human. The team wants the subagent to keep adapting to each case but stay on task and report back in a way the coordinator can act on. What should they change?","options":[{"key":"A","text":"Replace the goal with a fixed checklist of the eight checks every billing investigation should run, in a set order, and nothing else.","explanation":"Restores visibility but removes the adaptivity cases need; unusual issues fall outside the checklist."},{"key":"B","text":"Keep the goal, add scope limits and success criteria, and require a structured result: what was checked, findings, open questions.","explanation":"Goal-oriented delegation keeps adaptivity; explicit boundaries and a structured report fix both the wandering and the coordinator's blind spot."},{"key":"C","text":"Ask the subagent to end each investigation with a free-text summary of what it looked at and what it concluded.","explanation":"Better than nothing, but prose summaries are hard for the coordinator to act on and do nothing about scope."},{"key":"D","text":"Remove the subagent and have the coordinator handle billing investigations directly.","explanation":"Gains visibility by abandoning delegation and loading investigation detail into the coordinator's context."}],"correct":"B","tiebreaker":"The option that meets every stated goal","rationale":"Goal-oriented instructions need boundaries and quality criteria; structured handoffs keep the coordinator able to evaluate and re-delegate.","sources":[{"title":"Task 1.3: coordinator prompts with goals and quality criteria; Task 1.4: structured handoff protocols","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"W-005","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.4"],"objectives":["O08"],"stem":"A developer needs to move 52 files from a deprecated logging library to its replacement. There are two reasonable approaches, a thin wrapper or direct replacement at every call site, and the tech lead wants to approve the approach before any file changes. What should the developer do in Claude Code?","options":[{"key":"A","text":"Use direct execution, committing after every ten files so that any change is easy to roll back if needed.","explanation":"Rollback is easier, but edits start before the tech lead has approved an approach."},{"key":"B","text":"Use direct execution on one file first, then show that diff to the tech lead as the proposed approach for all 52.","explanation":"Shows one approach in practice but never compares the two or examines dependencies across the codebase."},{"key":"C","text":"Use plan mode to explore the call sites and dependencies, propose an approach for approval, then implement.","explanation":"Plan mode suits multi-file changes with several valid approaches: explore safely, get approval, then execute."},{"key":"D","text":"Spawn parallel subagents to migrate different directories at once to finish quickly.","explanation":"Fast, but makes changes before an approach is chosen and risks the halves of the codebase diverging."}],"correct":"C","tiebreaker":"Match the tool to the requirement","rationale":"Plan mode for large-scale or multi-file changes with multiple valid approaches and approval needs; direct execution for well-scoped changes.","sources":[{"title":"Task 3.4: plan mode vs direct execution","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code permission modes (plan mode)","url":"https://code.claude.com/docs/en/permission-modes","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-006","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.4"],"objectives":["O08"],"stem":"A failing unit test points to a missing null check in one function in a single file. The fix is about three lines, the expected behaviour is clear from the test, and no one needs to review an approach first. Which way of working fits best?","options":[{"key":"A","text":"Enter plan mode so Claude can explore the codebase and propose a fix for review before editing.","explanation":"Plan mode adds an approval loop the task doesn't need."},{"key":"B","text":"Direct execution: ask Claude to add the null check and re-run the test.","explanation":"A single-file fix with a clear scope and an objective check is exactly what direct execution is for."},{"key":"C","text":"A multi-phase workflow with a design review, an implementation pass and an independent review pass.","explanation":"Heavy process for a three-line, test-verified change."},{"key":"D","text":"Spawn an Explore subagent to map every caller of the function before changing anything.","explanation":"Useful for unclear scope, but here the scope is already known from the failing test."}],"correct":"B","tiebreaker":"Smallest thing that works","rationale":"Direct execution for simple, well-scoped changes such as a single-file bug fix.","sources":[{"title":"Task 3.4: selecting direct execution for well-understood changes with clear scope","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code permission modes (plan mode)","url":"https://code.claude.com/docs/en/permission-modes","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-007","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3","d1"],"taskStatements":["3.4","1.4","4.6"],"objectives":["O08"],"stem":"A team must change how session tokens are validated across three services. Compliance requires a named engineer to sign off on the design before work starts and on the final diff before merge, and a past change in this area caused an outage. The team wants Claude Code to do most of the work within those controls. Which approach fits?","options":[{"key":"A","text":"Direct execution in each of the three services, with the named engineer reviewing the combined pull request before it merges.","explanation":"Meets the final sign-off but skips design approval, and the work proceeds on an unapproved approach."},{"key":"B","text":"Plan mode to produce a design the engineer approves, then direct execution across the three services through to merge.","explanation":"Covers design approval but misses the required sign-off on the final diff."},{"key":"C","text":"Run three parallel subagents, one per service, and merge their changes automatically when tests pass.","explanation":"Fast, but removes both human checkpoints from a high-risk change."},{"key":"D","text":"A multi-phase workflow: plan mode for design, human approval, implementation, an independent review pass, then sign-off before merge.","explanation":"Scope, risk and two approval gates call for distinct phases with human checkpoints and an independent review."}],"correct":"D","tiebreaker":"The option that meets every stated goal","rationale":"Choose the review architecture by scope, risk and approval requirements; high-risk multi-service work with two sign-offs needs phases with human gates.","sources":[{"title":"Task 3.4: plan mode for investigation combined with execution; Task 1.4: programmatic gates; Task 4.6: independent review","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code permission modes (plan mode)","url":"https://code.claude.com/docs/en/permission-modes","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-008","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"ci","scenario":"Claude Code for CI/CD","scenarioContext":null,"domains":["d3"],"taskStatements":["3.6"],"objectives":["O11"],"stem":"A nightly CI job runs Claude Code non-interactively to generate missing tests. Last week one run kept going for 340 turns and about $410 before the 6-hour job timeout killed it, leaving no usable output. The team wants every run to stop well before that point without anyone watching. What should they add to the invocation?","options":[{"key":"A","text":"A CLAUDE.md instruction asking Claude to finish efficiently and stop when coverage is adequate.","explanation":"Guidance the model may or may not follow; it puts no hard ceiling on turns or spend."},{"key":"B","text":"A shorter CI job timeout, such as 30 minutes.","explanation":"A useful backstop, but it kills runs mid-work with no clean result and doesn't bound spend per run inside the window."},{"key":"C","text":"A turn limit with --max-turns and a spend cap with --max-budget-usd, sized from typical successful runs.","explanation":"Turn and cost limits on the invocation stop runaway executions deterministically, at a size that still lets normal runs finish."},{"key":"D","text":"Moving the job to the Message Batches API to halve the cost of each turn.","explanation":"Halves the price of a runaway, but doesn't stop it, and batch requests don't support multi-turn tool loops."}],"correct":"C","tiebreaker":"Guaranteed beats likely","rationale":"Configure non-interactive CI invocations with turn and cost limits that prevent runaway executions.","sources":[{"title":"Task 3.6: running Claude Code in CI; exam objective on cost and turn limits","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code CLI reference","url":"https://code.claude.com/docs/en/cli-reference","type":"docs"},{"title":"Run Claude Code programmatically (headless)","url":"https://code.claude.com/docs/en/headless","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-009","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"ci","scenario":"Claude Code for CI/CD","scenarioContext":null,"domains":["d3"],"taskStatements":["3.6"],"objectives":["O11","O13"],"stem":"A pull-request review step runs `claude \"review this PR\"` in CI. Some runs hang until the job times out, and in two runs Claude edited files in the workspace. The team wants the step to finish on its own every time and never modify the repository. How should they invoke Claude Code?","options":[{"key":"A","text":"Use -p for non-interactive mode and limit --tools to read-only tools such as Read, Grep and Glob.","explanation":"-p runs once and exits without waiting for input; --tools restricts the available set, so editing is not possible. (--allowedTools is the auto-approve flag, not the restricting one.)"},{"key":"B","text":"Use --permission-mode bypassPermissions so the run never pauses to wait for approval of any action it takes.","explanation":"Stops the waiting, but also lets every edit and command through, the opposite of what the team wants."},{"key":"C","text":"Pipe a stream of 'yes' answers into stdin so any prompt is answered automatically.","explanation":"Answers prompts by approving them, including edits, and is fragile besides."},{"key":"D","text":"Keep the command as it is, and add a CLAUDE.md rule stating that reviews must never edit any files.","explanation":"Doesn't fix the hang, and a written rule is weaker than removing the edit tools."}],"correct":"A","tiebreaker":"Guaranteed beats likely","rationale":"Run Claude Code in CI with -p to avoid interactive hangs, and use --tools to restrict the available set to what the job needs.","sources":[{"title":"Task 3.6: -p flag for non-interactive pipelines; Task 3.2/3.6: restricting tool access","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code CLI reference","url":"https://code.claude.com/docs/en/cli-reference","type":"docs"},{"title":"Run Claude Code programmatically (headless)","url":"https://code.claude.com/docs/en/headless","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-010","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.5"],"objectives":["O12"],"stem":"A developer asks Claude Code for a function that converts legacy order codes such as 'EU-0042/B' into a new format. After three rounds of prose corrections, the output still mishandles codes without a suffix and codes with two-letter regions. The developer wants the function right with as little back-and-forth as possible. What should they do next?","options":[{"key":"A","text":"Rewrite the prose requirements in much more detail, spelling out every rule for regions, separators and suffixes.","explanation":"More prose is more of what has already been interpreted inconsistently."},{"key":"B","text":"Ask Claude to think through the requirements step by step before writing the function again from scratch.","explanation":"May help reasoning, but doesn't remove the ambiguity in what the output should be."},{"key":"C","text":"Start a fresh session so earlier misunderstandings don't carry over.","explanation":"Clears context but brings back the same ambiguous prose description."},{"key":"D","text":"Provide three concrete input-output pairs, including one with no suffix and one with a two-letter region.","explanation":"Concrete examples are the most effective way to communicate a transformation when prose is read inconsistently, and they target the failing cases."}],"correct":"D","tiebreaker":"Root cause","rationale":"Use 2-3 concrete input-output examples to clarify transformation requirements, especially the edge cases that fail.","sources":[{"title":"Task 3.5: concrete input/output examples when prose is interpreted inconsistently","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Prompting best practices: use examples","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-011","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.5"],"objectives":["O12"],"stem":"After an implementation, five tests fail. Three come from the same shared date parser, and fixing one of them has broken another twice. The other two are unrelated mistakes in separate modules. The developer has been sending one failure per message. They want the parser failures resolved for good and the rest fixed cleanly. How should they give feedback?","options":[{"key":"A","text":"Keep sending one failing test per message, so each fix stays small, focused and easy to review before moving on.","explanation":"Works for independent issues, but interacting parser failures keep undoing each other."},{"key":"B","text":"Paste the entire test log, all five failures included, into one message and ask Claude to make every test pass at once.","explanation":"Batches everything, but buries the interacting failures among unrelated noise without targeted detail."},{"key":"C","text":"Send the three parser failures and their exact outputs together in one message; handle the two unrelated failures separately.","explanation":"Interacting issues need to be seen together for a consistent fix; independent ones are cleaner one at a time."},{"key":"D","text":"Ask Claude to rewrite the date parser from scratch before looking at any failures.","explanation":"Discards working code and the failure details that show what's wrong."}],"correct":"C","tiebreaker":"Root cause","rationale":"Batch interacting problems in a single message with specific failure details; iterate sequentially on independent problems.","sources":[{"title":"Task 3.5: addressing interacting issues in a single message; sequential iteration for independent issues","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"W-012","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"ci","scenario":"Claude Code for CI/CD","scenarioContext":null,"domains":["d3"],"taskStatements":["3.6","3.1"],"objectives":["O13"],"stem":"A CI review job feeds Claude Code's output to a bot that posts inline comments. Reviews ignore the team's coding standards, which live only in a wiki; some runs execute shell commands; and about 20% of outputs are prose the bot can't parse. The team wants reviews that follow their standards, have no side effects and always parse. Which configuration achieves this?","options":[{"key":"A","text":"Paste the wiki standards into each run's prompt, ask Claude to reply in JSON, and post-process any output that fails to parse.","explanation":"Brings the standards in, but JSON on request still fails sometimes and the shell access remains."},{"key":"B","text":"Commit the standards to the project CLAUDE.md, allow only read-only tools, and use --output-format json with --json-schema.","explanation":"Each part addresses one failure: standards loaded every run, no tools with side effects, and schema-constrained output."},{"key":"C","text":"Call the Messages API directly with the diff instead of Claude Code, and parse its prose with regular expressions.","explanation":"Removes side effects, but loses project context and makes parsing more brittle."},{"key":"D","text":"Add the standards and a 'do not run commands' rule to a personal ~/.claude/CLAUDE.md on the CI runner so every run loads them.","explanation":"User-level config isn't in version control, and a written rule doesn't remove shell access."}],"correct":"B","tiebreaker":"Guaranteed beats likely","rationale":"CI review configuration: project CLAUDE.md for standards, restricted tools, and --output-format json with --json-schema for machine-parseable findings.","sources":[{"title":"Task 3.6: CLAUDE.md context for CI and --output-format json / --json-schema; Task 3.1: project-level configuration","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code CLI reference","url":"https://code.claude.com/docs/en/cli-reference","type":"docs"},{"title":"Run Claude Code programmatically (headless)","url":"https://code.claude.com/docs/en/headless","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-013","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"ci","scenario":"Claude Code for CI/CD","scenarioContext":null,"domains":["d3"],"taskStatements":["3.1","3.6"],"objectives":["O13","O16"],"family":"personal-claude-md","stem":"Code reviews follow the team's standards when one senior developer runs Claude Code on her laptop, but the CI review job and other developers get generic feedback. The standards turn out to be in her ~/.claude/CLAUDE.md. The team wants every review, local or CI, to apply the same standards. What is the best fix?","options":[{"key":"A","text":"Copy her ~/.claude directory into the CI runner image.","explanation":"Fixes CI but ties the team's standards to one person's personal config, and other developers still miss them."},{"key":"B","text":"Ask each developer to copy the standards into their own user-level CLAUDE.md, and the CI image too.","explanation":"Spreads the standards by hand, and copies drift as they're edited."},{"key":"C","text":"Move the standards into the project's CLAUDE.md and commit it to the repository.","explanation":"Project-level CLAUDE.md is shared through version control, so every developer and CI run loads the same standards."},{"key":"D","text":"Add the standards to the prompt string in the CI pipeline's configuration.","explanation":"Covers CI only, and the standards now live in two places."}],"correct":"C","tiebreaker":"Root cause","rationale":"User-level CLAUDE.md applies only to that user and isn't shared via version control; shared standards belong at project level.","sources":[{"title":"Task 3.1: diagnosing hierarchy issues (instructions in user-level rather than project-level config)","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code memory (CLAUDE.md and .claude/rules/)","url":"https://code.claude.com/docs/en/memory","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-014","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.1"],"objectives":["O16"],"stem":"A team's CLAUDE.md says never to run 'git push --force' or delete the migrations folder. Over three months Claude Code attempted a force push twice during long sessions. The team wants these actions impossible, not just discouraged. Which mechanism should they use?","options":[{"key":"A","text":"Repeat the rule in capital letters at the top of CLAUDE.md.","explanation":"Still guidance the model may miss in a long session."},{"key":"B","text":"Move the rule into a .claude/rules/ file so it loads with the relevant files.","explanation":"Path-scoped guidance is still guidance, and git commands aren't tied to file paths."},{"key":"C","text":"Deny rules for those commands in the project's settings permissions.","explanation":"Settings permissions enforce what tools and commands are allowed, so the action is blocked rather than advised against."},{"key":"D","text":"A Skill describing safe git practices that developers invoke before pushing.","explanation":"On-demand guidance that only helps when someone remembers to invoke it."}],"correct":"C","tiebreaker":"Guaranteed beats likely","rationale":"Choose the mechanism by guidance type: CLAUDE.md and rules advise; settings permissions and hooks enforce.","sources":[{"title":"Task 3.1-3.3: configuration mechanisms; Task 1.5: deterministic enforcement over prompt guidance","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code permissions","url":"https://code.claude.com/docs/en/permissions","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-015","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3"],"taskStatements":["3.2","3.1"],"objectives":["O16"],"stem":"A three-page database migration checklist sits in the project CLAUDE.md. It's needed roughly twice a month, but it loads into every session and developers complain that unrelated sessions feel cluttered. The team wants the checklist available whenever someone runs a migration and out of the way otherwise. Where should it go?","options":[{"key":"A","text":"A Skill that developers invoke when they start a migration.","explanation":"Skills load on demand, which suits a long procedure needed occasionally; CLAUDE.md is for always-relevant standards."},{"key":"B","text":"A .claude/rules/ file with paths set to the migrations folder.","explanation":"Loads only when migration files are edited, which may be after the planning steps the checklist covers."},{"key":"C","text":"A PostToolUse hook that prints the checklist after every edit.","explanation":"Hooks are for automatic, deterministic actions, not long procedural guidance."},{"key":"D","text":"Keep it in CLAUDE.md but move it to the bottom of the file.","explanation":"Still loads every session; position doesn't change that."}],"correct":"A","tiebreaker":"Match the tool to the requirement","rationale":"Use Skills for on-demand procedures and CLAUDE.md for always-loaded universal standards.","sources":[{"title":"Task 3.2: choosing between skills (on-demand) and CLAUDE.md (always-loaded universal standards)","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code memory (CLAUDE.md and .claude/rules/)","url":"https://code.claude.com/docs/en/memory","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-016","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"codegen","scenario":"Code Generation with Claude Code","scenarioContext":null,"domains":["d3","d1"],"taskStatements":["1.5","3.1"],"objectives":["O16"],"stem":"The team wants the code formatter to run on every file Claude Code edits. CLAUDE.md asks for this, but in practice the formatter is skipped in about one in ten edits, and the formatting check then fails in CI. The team wants formatting applied after every edit without depending on the model to remember. What should they use?","options":[{"key":"A","text":"A stronger CLAUDE.md instruction, with an example of the formatter command.","explanation":"Clearer guidance, but still relies on the model to remember every time."},{"key":"B","text":"A hook that runs the formatter automatically after each file edit.","explanation":"Hooks run deterministically on tool events, so formatting happens on every edit regardless of the model."},{"key":"C","text":"A Skill named /format that developers run before committing.","explanation":"Moves the remembering from the model to the developer."},{"key":"D","text":"A settings permission that blocks commits until files are formatted.","explanation":"Permissions allow or deny tool use; they don't run the formatter."}],"correct":"B","tiebreaker":"Guaranteed beats likely","rationale":"Hooks provide deterministic actions on tool events; prompt guidance is probabilistic.","sources":[{"title":"Task 1.5: hooks provide deterministic guarantees vs prompt instructions; Task 3.1: configuration mechanisms","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code hooks reference","url":"https://code.claude.com/docs/en/hooks","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-017","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"ci","scenario":"Claude Code for CI/CD","scenarioContext":null,"domains":["d4"],"taskStatements":["4.6","4.2"],"objectives":["O24"],"stem":"A single review prompt covers security, business logic and API design. After the team added few-shot examples for API design, API findings improved but security recall dropped from 78% to 61% on their labeled set. The team wants strong recall in all three areas. What should they do?","options":[{"key":"A","text":"Add more few-shot examples for all three concerns to the same prompt, so each concern is equally well represented.","explanation":"Makes the competition for attention worse rather than better."},{"key":"B","text":"Reorder the prompt so the security section and its examples come first.","explanation":"Shifts the trade-off toward security at the cost of the other concerns."},{"key":"C","text":"Run a separate review pass for each concern, each with its own focused prompt and examples, then merge the findings.","explanation":"Separate passes stop the concerns competing in one prompt, so each keeps its recall."},{"key":"D","text":"Switch to a larger, more capable model so that one prompt can handle all three concerns without losing recall.","explanation":"May soften the trade-off but doesn't remove the competition inside a single prompt."}],"correct":"C","tiebreaker":"Root cause","rationale":"Separate concerns into focused review passes with dedicated few-shot examples to avoid recall trade-offs.","sources":[{"title":"Task 4.6: multi-pass review architectures; Task 4.2: targeted few-shot examples","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Prompting best practices: use examples","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-018","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"ci","scenario":"Claude Code for CI/CD","scenarioContext":null,"domains":["d4"],"taskStatements":["4.6","4.2","4.1"],"objectives":["O24","O30"],"stem":"The team is splitting its reviewer into separate security, business logic and API design passes. For the security pass, they want few-shot examples that keep recall high without flagging the team's accepted patterns, such as parameterised queries built by their query helper. Which examples should go into the security pass?","options":[{"key":"A","text":"Two to four security-only examples that contrast real vulnerabilities with the team's accepted patterns, with reasoning.","explanation":"Focused, contrasting examples teach the pass what to flag and what to leave, without diluting it with other concerns."},{"key":"B","text":"Reuse the same mixed set of examples across all three passes, so findings stay consistent from one pass to the next.","explanation":"Consistent, but reintroduces the competing concerns the split was meant to remove."},{"key":"C","text":"Twenty examples of real vulnerabilities drawn from public security reports, to maximise how much the pass recognises.","explanation":"Builds recall but says nothing about accepted patterns, so false positives remain."},{"key":"D","text":"No examples, relying on a detailed list of vulnerability types instead.","explanation":"A list describes categories but doesn't show where the team's boundary lies."}],"correct":"A","tiebreaker":"Root cause","rationale":"Each specialised pass gets dedicated few-shot examples that distinguish acceptable patterns from genuine issues.","sources":[{"title":"Task 4.2: examples distinguishing acceptable code patterns from genuine issues; Task 4.6: multi-pass review","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Prompting best practices: use examples","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-019","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d4","d2"],"taskStatements":["4.3","2.3"],"objectives":["O27"],"stem":"When the support agent escalates, its final step should produce a handoff record (customer ID, issue summary, steps tried, recommended action) that the ticketing system ingests. About 5% of escalations end with a friendly prose message instead, and those tickets arrive empty. The team wants every escalation to produce a valid handoff record. What should they do?","options":[{"key":"A","text":"Ask the model to reply only in JSON matching the ticket fields, and validate every reply before it is sent onward.","explanation":"Prompt-based JSON improves things but has no structural guarantee."},{"key":"B","text":"Define a create_handoff tool with the record as its JSON schema, and force that tool on the escalation request.","explanation":"Tool use with a schema gives structured output, and forcing the tool rules out a prose reply."},{"key":"C","text":"Keep the current flow, and use a second model call to convert any prose reply into the ticket fields.","explanation":"Patches failures afterwards and adds a second place for errors to creep in."},{"key":"D","text":"Define the create_handoff tool, but leave tool_choice on auto and give the tool a clear, detailed description.","explanation":"Auto still allows a text reply, which is exactly the failure."}],"correct":"B","tiebreaker":"Guaranteed beats likely","rationale":"Define the output as a tool schema and configure tool_choice so a conversational reply is impossible where it would break downstream.","sources":[{"title":"Task 4.3: tool_use with JSON schemas; forced tool_choice; Task 1.4: structured handoff protocols","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Define tools: forcing tool use","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools#forcing-tool-use","type":"docs"}],"note":"Answer per the exam guide. Current docs report the newest models reject forced tool_choice with a 400 error; the documented alternative there is auto with strict: true.","corroborated":[]},
{"id":"W-020","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"ci","scenario":"Claude Code for CI/CD","scenarioContext":null,"domains":["d4"],"taskStatements":["4.3"],"objectives":["O27","O25"],"stem":"A CI step classifies each pull request's risk with a single classify_risk tool. tool_choice is auto, and about 4% of runs return text such as 'This PR looks low risk' with no tool call, which fails the pipeline. A teammate suggests prefilling the assistant reply with an opening brace instead. The team wants every run to return the classification object. What should they do?","options":[{"key":"A","text":"Prefill the assistant turn with an opening '{' and parse the rest of the completion as JSON.","explanation":"Prefilling nudges the format but is prompt-based, with no schema guarantee."},{"key":"B","text":"Keep tool_choice on auto, and add a retry whenever a response comes back without a tool call.","explanation":"Recovers most failures at extra cost but doesn't prevent them."},{"key":"C","text":"Add 'always call classify_risk' to the system prompt.","explanation":"Reduces text replies; doesn't eliminate them."},{"key":"D","text":"Force tool_choice to classify_risk so every response is that tool call.","explanation":"A forced tool call guarantees schema-shaped output every time, the strictest of the available methods."}],"correct":"D","tiebreaker":"Guaranteed beats likely","rationale":"Tool use with a JSON schema plus forced tool_choice is more reliable than prompt-based formatting or prefilled responses.","sources":[{"title":"Task 4.3: forcing a specific tool; exam objective on structured output methods","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Define tools: forcing tool use","url":"https://platform.claude.com/docs/en/agents-and-tools/tool-use/define-tools#forcing-tool-use","type":"docs"}],"note":"Answer per the exam guide; see the current-state note on forced tool_choice for the newest models.","corroborated":[]},
{"id":"W-021","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d4"],"taskStatements":["4.2","4.3"],"objectives":["O29","O26"],"stem":"A document analysis subagent extracts sample size and methodology from research papers. Some papers state them in the methods section, some in a table and some only in an appendix. Sample size is wrong or invented in 12% of papers, mostly ones that never report it. The team wants accurate values when present and an honest 'not reported' when absent. What should they do?","options":[{"key":"A","text":"Keep sample_size required, and add an instruction telling the model never to guess a number it can't find in the paper itself.","explanation":"The required field still pressures the model to produce a number."},{"key":"B","text":"Make sample_size nullable, and add few-shot examples: a methods-section case, a table case, and a paper that doesn't report it.","explanation":"Nullable fields remove the pressure to fabricate; examples across structures teach where values hide and when null is right."},{"key":"C","text":"Search the text for numbers next to the letter 'n' before sending it to the model.","explanation":"Brittle across layouts and can't tell sample size from other counts."},{"key":"D","text":"Move the document analysis subagent to a larger model that reads methods sections, tables and appendices more reliably.","explanation":"May improve accuracy but leaves the schema pushing toward invented values."}],"correct":"B","tiebreaker":"Root cause","rationale":"Combine optional or nullable fields with few-shot examples across varied document structures to reduce hallucination.","sources":[{"title":"Task 4.2: few-shot for varied document structures; Task 4.3: nullable fields to prevent fabrication","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Prompting best practices: use examples","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-022","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.3","4.2"],"objectives":["O29"],"stem":"Invoices come from suppliers in several countries, so amounts appear as '$1,234.56', '€1.234,56' and '1 234,56 kr'. The schema defines total_amount as a number, yet about 4% of totals are off by a factor of 100 or 1,000 because the decimal separator was misread. The team wants totals correct regardless of locale. What should they do?","options":[{"key":"A","text":"Change total_amount to a string and convert it to a number in application code after extraction.","explanation":"Moves the same ambiguity into code that has even less context than the model."},{"key":"B","text":"Add a range check that rejects totals above a ceiling and retries them.","explanation":"Catches some errors after the fact but misses mistakes that stay within range."},{"key":"C","text":"Add normalisation rules on separators and currency to the prompt, with examples from each locale.","explanation":"Normalisation instructions plus locale examples tell the model how to read each format; the schema alone only fixes the type."},{"key":"D","text":"Move the extraction step to a larger model, which should read the separators correctly more often.","explanation":"Might reduce errors but gives no rule for resolving the ambiguity."}],"correct":"C","tiebreaker":"Root cause","rationale":"Include format normalisation instructions and few-shot examples alongside strict schemas for consistency across varied formats.","sources":[{"title":"Task 4.3: format normalization rules alongside strict output schemas; Task 4.2: few-shot for varied formats","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Prompting best practices: use examples","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-023","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"ci","scenario":"Claude Code for CI/CD","scenarioContext":null,"domains":["d4","d3"],"taskStatements":["4.1","3.6"],"objectives":["O30"],"stem":"The automated reviewer flags raw SQL in every pull request, but the team's convention allows raw SQL in the migrations folder and in generated reporting queries. Developers dismiss these comments on almost every PR and have started ignoring the reviewer altogether. The team wants these accepted patterns left alone on every review, permanently. What should they do?","options":[{"key":"A","text":"Have each author add a note to the pull request description listing which raw SQL the reviewer should accept in that PR.","explanation":"Relies on every author remembering, PR after PR."},{"key":"B","text":"Filter out any review comment that mentions SQL before the bot posts it to the pull request.","explanation":"Also hides genuine SQL problems elsewhere."},{"key":"C","text":"Lower the severity of raw SQL findings so they appear as optional suggestions rather than issues.","explanation":"The noise remains, just labelled differently."},{"key":"D","text":"Document the accepted patterns and where they apply in the review's persistent project context, such as CLAUDE.md.","explanation":"Conventions and exclusions in persistent context apply on every review, removing the false positives at the source."}],"correct":"D","tiebreaker":"Root cause","rationale":"Supply project-specific conventions, accepted patterns and exclusion criteria as persistent context on every review.","sources":[{"title":"Task 4.1: explicit criteria for what to report vs skip; Task 3.6: CLAUDE.md context for CI reviews","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code memory (CLAUDE.md and .claude/rules/)","url":"https://code.claude.com/docs/en/memory","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-024","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"ci","scenario":"Claude Code for CI/CD","scenarioContext":null,"domains":["d4"],"taskStatements":["4.1"],"objectives":["O30","O31"],"stem":"The reviewer comments on files under vendor/ and generated/, which the team never edits by hand. Those comments are 35% of all review findings and nearly all are dismissed. The team wants reviews to focus on code they own without losing findings there. What should they change?","options":[{"key":"A","text":"Add explicit exclusion criteria to the review's persistent configuration: skip vendor/ and generated/ files.","explanation":"A clear, persistent exclusion boundary removes a whole category of unwanted findings without touching owned code."},{"key":"B","text":"Ask reviewers to ignore comments on those folders.","explanation":"Leaves the noise in place and depends on people filtering it."},{"key":"C","text":"Raise the minimum confidence required for any finding, so low-value comments like these are filtered out automatically.","explanation":"Cuts findings everywhere, including real ones in owned code."},{"key":"D","text":"Add examples of acceptable vendor code to the prompt so the reviewer learns that this code is fine as it is.","explanation":"Indirect and partial; the team doesn't want those files reviewed at all."}],"correct":"A","tiebreaker":"Smallest thing that works","rationale":"Define explicit exclusion boundaries in persistent review context rather than relying on confidence or downstream filtering.","sources":[{"title":"Task 4.1: specific criteria defining which issues to report vs skip","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Prompting best practices: be clear and direct","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-025","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"ci","scenario":"Claude Code for CI/CD","scenarioContext":null,"domains":["d4"],"taskStatements":["4.1"],"objectives":["O31"],"stem":"A review step checks that code comments are accurate, using the instruction 'check that comments are accurate'. About 40% of its findings are about grammar, missing documentation or style, and developers have started ignoring the step. The team wants it to report only comments that are actually wrong. What should they change?","options":[{"key":"A","text":"Change the instruction to 'only report high-confidence findings about comments', keeping everything else the same.","explanation":"Vague instructions like this fail compared with specific criteria."},{"key":"B","text":"Report only when a comment's described behaviour contradicts the code; skip grammar, style and missing documentation.","explanation":"Explicit inclusion and exclusion criteria define the boundary the vague instruction left open."},{"key":"C","text":"Add severity levels to the output so grammar, style and documentation findings are marked as low severity.","explanation":"Keeps the unwanted findings, just ranked lower."},{"key":"D","text":"Disable the comment check until a better model is available.","explanation":"Removes the noise along with the value."}],"correct":"B","tiebreaker":"Root cause","rationale":"Explicit criteria (flag only contradictions between comment and code) beat vague instructions.","sources":[{"title":"Task 4.1: explicit criteria over vague instructions","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Prompting best practices: be clear and direct","url":"https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/claude-prompting-best-practices","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-026","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"extract","scenario":"Structured Data Extraction","scenarioContext":null,"domains":["d4"],"taskStatements":["4.1"],"objectives":["O31"],"stem":"A contract pipeline extracts risk clauses into categories. On a labeled set, termination clauses score 95% accuracy and payment penalties 92%, but indemnification analysis scores 58%, and legal says wrong indemnification output is worse than none. The team wants to keep automating where results are reliable. What should they do?","options":[{"key":"A","text":"Add few-shot examples of tricky indemnification clauses to the prompt, and keep extracting every category as before.","explanation":"Might raise accuracy, but until it's proven reliable the pipeline keeps producing output legal can't trust."},{"key":"B","text":"Keep all categories, but attach the model's own confidence score to every indemnification finding for legal to weigh.","explanation":"Self-reported confidence is poorly calibrated, especially on the hard category."},{"key":"C","text":"Run indemnification extraction twice and keep only results where both runs agree.","explanation":"Agreement isn't accuracy; consistent mistakes still pass."},{"key":"D","text":"Extract only the reliable categories, explicitly excluding indemnification, and route those clauses to legal review.","explanation":"Explicit boundaries stop the model producing findings where performance is unreliable, while reliable categories stay automated."}],"correct":"D","tiebreaker":"The option that meets every stated goal","rationale":"Define explicit inclusion and exclusion boundaries so the model doesn't generate findings in categories where performance is unreliable.","sources":[{"title":"Task 4.1: temporarily disabling high false-positive categories; explicit criteria","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"W-027","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"research","scenario":"Multi-Agent Research System","scenarioContext":null,"domains":["d2"],"taskStatements":["2.3"],"objectives":["O33"],"stem":"The synthesis agent in a research system was given the full set of 16 tools, including web search. It now runs its own searches mid-synthesis, which duplicates the research agents' work and adds about 40% to report time. The team wants synthesis to stick to synthesising, with any new research going through the coordinator. What should they change?","options":[{"key":"A","text":"Add a system prompt instruction telling the synthesis agent not to call web search while it is writing the report.","explanation":"Discourages the behaviour but leaves the tool in reach."},{"key":"B","text":"Improve the web search tool's description to say it's meant for research agents.","explanation":"Descriptions guide selection but don't prevent an agent that has the tool from using it."},{"key":"C","text":"Give the synthesis agent only the tools synthesis needs, and route new research requests back to the coordinator.","explanation":"Scoped tool access prevents out-of-role calls and simplifies the agent's choices."},{"key":"D","text":"Merge the synthesis agent into the research agents so each one writes its own section.","explanation":"Removes the role boundary instead of enforcing it, and loses cross-source synthesis."}],"correct":"C","tiebreaker":"Root cause","rationale":"Give each agent only the tools its role needs; out-of-role tools get misused.","sources":[{"title":"Task 2.3: restricting each subagent's tool set to its role","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"W-028","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"support","scenario":"Customer Support Resolution Agent","scenarioContext":null,"domains":["d2"],"taskStatements":["2.3"],"objectives":["O33","O05"],"stem":"A single support agent has 18 tools covering billing, shipping, account security and returns. Its wrong-tool rate is 11%, even though every tool description was rewritten last month with clear boundaries and examples. The team wants fewer wrong-tool calls. What should they do?","options":[{"key":"A","text":"Rewrite the tool descriptions again, this time with more examples of exactly when each tool applies.","explanation":"Descriptions are already clear; the remaining errors come from too many choices."},{"key":"B","text":"Add a routing step that picks the right tool for the agent before each call it makes.","explanation":"Adds a second decision-maker with the same 18 options to confuse."},{"key":"C","text":"Merge related tools into fewer, broader ones that take a mode parameter instead.","explanation":"Fewer names, but the same decisions now hide inside parameters."},{"key":"D","text":"Split the work into role-specific subagents, each with only the four or five tools it needs.","explanation":"Fewer tools per agent reduces decision complexity, which improves selection when descriptions are already good."}],"correct":"D","tiebreaker":"Root cause","rationale":"Too many tools (18 instead of 4-5) degrades selection reliability; distribute tools by role.","sources":[{"title":"Task 2.3: too many tools degrades tool selection reliability","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"}],"note":null,"corroborated":[]},
{"id":"W-029","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d2"],"taskStatements":["2.4"],"objectives":["O34"],"stem":"An internal MCP server gives the team's agent access to design docs and database schemas. Sessions average about 25 list_* and search_* calls just to discover which docs and tables exist before any real work starts. The team wants fewer exploratory calls. What should they change on the server?","options":[{"key":"A","text":"Add one search_everything tool that returns every document and table matching a keyword the agent supplies.","explanation":"Fewer tool names, but the agent still has to search to discover what exists."},{"key":"B","text":"Expose the document index and schema catalog as MCP resources the agent can see and reference directly.","explanation":"Resources make catalogs visible without exploratory tool calls; tools stay for actions and queries."},{"key":"C","text":"Cache the results of list_* calls so repeated discovery calls in a session return faster.","explanation":"Makes the exploration cheaper but doesn't remove it."},{"key":"D","text":"Paste the full document index and schema list into the system prompt of every session.","explanation":"Gives visibility, but goes stale and spends tokens every session."}],"correct":"B","tiebreaker":"Built-in feature over workaround","rationale":"Expose content catalogs as MCP resources to reduce exploratory tool calls.","sources":[{"title":"Task 2.4: MCP resources as content catalogs to reduce exploratory tool calls","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code MCP documentation (scopes, .mcp.json, ${VAR} expansion, @ resources, /mcp)","url":"https://code.claude.com/docs/en/mcp","type":"docs"}],"note":"Answer per the exam guide. How a resource reaches the model depends on the client: in Claude Code, resources are attached when referenced with an @ mention, and Claude can otherwise list and read them through built-in resource tools.","corroborated":[]},
{"id":"W-030","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d2"],"taskStatements":["2.4"],"objectives":["O34"],"stem":"A team is designing an MCP server for their analytics database. It should let the agent see table schemas, which change a few times a year, and run read-only SQL queries the agent writes. Which design fits MCP best?","options":[{"key":"A","text":"Expose schemas as resources and the SQL query capability as a tool.","explanation":"Schemas are content to read; running a query is an action with inputs. Resources and tools map onto exactly that split."},{"key":"B","text":"Expose both schemas and queries as tools.","explanation":"Works, but turns reading schemas into a stream of exploratory calls."},{"key":"C","text":"Expose both as resources, with each query result published as a resource.","explanation":"Queries take input and run on demand, which is what tools are for."},{"key":"D","text":"Put schemas in the project CLAUDE.md and expose only the query tool.","explanation":"Schema copies in CLAUDE.md drift out of date and load into every session."}],"correct":"A","tiebreaker":"Match the tool to the requirement","rationale":"Resources expose content for the agent to read; tools perform actions. Use each for what it fits.","sources":[{"title":"Task 2.4: MCP resources as content catalogs","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code MCP documentation (scopes, .mcp.json, ${VAR} expansion, @ resources, /mcp)","url":"https://code.claude.com/docs/en/mcp","type":"docs"}],"note":"Answer per the exam guide. How a resource reaches the model depends on the client: in Claude Code, resources are attached when referenced with an @ mention, and Claude can otherwise list and read them through built-in resource tools.","corroborated":[]},
{"id":"W-031","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d2"],"taskStatements":["2.4"],"objectives":["O35"],"stem":"A team wants the GitHub MCP server available to everyone who clones their repository. Each developer has their own GitHub token, and the security team has banned committing tokens. How should the server be configured?","options":[{"key":"A","text":"Add it to each developer's ~/.claude.json, with each person's own token written directly into their personal entry.","explanation":"Keeps tokens out of the repo, but nothing is shared and each person configures it by hand."},{"key":"B","text":"Add it to the project's .mcp.json with the token written in, and make the repository private to limit exposure.","explanation":"Shared, but commits a secret, which security has banned."},{"key":"C","text":"Add it to the project's .mcp.json and reference the token as ${GITHUB_TOKEN}, set in each developer's environment.","explanation":"Project scope shares the server through version control; environment variable expansion keeps each token out of the repo."},{"key":"D","text":"Describe how to install the server in the README and let developers configure it themselves.","explanation":"Documentation instead of configuration, so setups drift."}],"correct":"C","tiebreaker":"The option that meets every stated goal","rationale":"Use project-scoped .mcp.json for shared servers with environment variable expansion for credentials.","sources":[{"title":"Task 2.4: project-level .mcp.json with environment variable expansion","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code MCP documentation (scopes, .mcp.json, ${VAR} expansion, @ resources, /mcp)","url":"https://code.claude.com/docs/en/mcp","type":"docs"}],"note":null,"corroborated":[]},
{"id":"W-032","exam":"CCAR-F","set":"weak_objectives_1","format":"single_select","scn":"devprod","scenario":"Developer Productivity with Claude","scenarioContext":null,"domains":["d2"],"taskStatements":["2.4"],"objectives":["O35"],"stem":"Every developer on the team gets the updated tools from the shared MCP server configured in the project's .mcp.json, except one, whose agent still sees an old tool list. Months ago he added a server with the same name for testing, at the default local scope. He wants to use the team's configuration. What should he do first?","options":[{"key":"A","text":"Reinstall Claude Code to clear any cached configuration.","explanation":"Doesn't remove his own server entry, so the problem comes straight back."},{"key":"B","text":"Remove his same-named local-scope server, then run /mcp to check the team server is connected and its tools listed.","explanation":"Local scope takes precedence over project scope; removing it lets the shared config apply, and /mcp verifies discovery."},{"key":"C","text":"Copy the team's .mcp.json entry into his ~/.claude.json at user scope so it's available in every project.","explanation":"Local scope still wins over user scope, so his old entry keeps taking effect."},{"key":"D","text":"Rename the team's server in .mcp.json so that it no longer shares a name with the server he added for testing months ago.","explanation":"Changes shared config for everyone to work around one person's leftover entry."}],"correct":"B","tiebreaker":"Root cause","rationale":"MCP scope precedence is local over project over user; verify discovery with /mcp.","sources":[{"title":"Task 2.4: project-scoped vs personal server configuration","url":"https://jc-aiwiki.pages.dev/claude-ai/official-exam-guide","type":"exam_guide"},{"title":"Claude Code MCP documentation (scopes, .mcp.json, ${VAR} expansion, @ resources, /mcp)","url":"https://code.claude.com/docs/en/mcp","type":"docs"}],"note":null,"corroborated":[]}
];
